		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.amount = 1;
			break;
		case 'mousedown': {
			// A tap near a cell starts its division early, when there is room
			if (reduced) break;
			let best = -1, bd = 25600;
			for (let i = 0; i < MAX; i++) {
				if (!alive[i] || div[i] > 0 || die[i] > 0) continue;
				const dd = (x[i] - d.x) ** 2 + (y[i] - d.y) ** 2;
				if (dd < bd) { bd = dd; best = i; }
			}
			if (best >= 0) age[best] = Math.max(age[best], cyc[best]);
			break;
		}
	}
};

/**
 * Title: Chongqing Fog City (WebGL)
 * Description: Layered neon towers of a river city drift past in river mist and mirror onto rippling water, dipping and dimming behind the chat while the cursor turns your head.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const PAN_SPEED       = 1;     // how fast the skyline drifts sideways; 0 holds it still (0-3)
const MOTION          = 1;     // speed of the mist, ripples and window flicker (0-2)
const REDUCED_SPEED   = 0.15;  // share of the motion kept when the viewer asks to reduce motion (0-1)
const FOG_DENSITY     = 1;     // river-mist thickness (0-2)
const NEON_BRIGHTNESS = 1;     // glow of the lit windows and signs (0-2)
const WINDOW_DENSITY  = 0.45;  // share of windows that are lit (0-1)
const CITY_HEIGHT     = 1;     // how tall the towers climb (0.5-1.5)
const WATERLINE       = 0.22;  // height of the river's edge, as a share of the screen (0.1-0.4)
const LOOK_AROUND     = 1;     // how far the layers shift as the cursor moves (0-2)
const CENTER_CALM     = 0.8;   // how much the city dips and dims behind the chat column (0-1)
const BAND_WIDTH      = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const RENDER_SCALE    = 0.75;  // resolution of the scene; windows stay crisp at 0.75 (0.35-1)
const MAX_FPS         = 30;    // frame cap; the city moves slowly (15-60)
const FOLLOW_THEME    = true;  // take the colors from the theme's palette
const COLOR_AMBER     = '#ffb857';  // main window color when not following the theme
const COLOR_CYAN      = '#40e6ff';  // second window color
const COLOR_MAGENTA   = '#ff3d80';  // sign and lantern color
const COLOR_HAZE      = '#8a4a6a';  // fog color, where the neon bleeds into the mist
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform float u_pan[5];',
	'uniform vec2 u_look;',
	'uniform vec3 u_c1;',
	'uniform vec3 u_c2;',
	'uniform vec3 u_c3;',
	'uniform vec3 u_haze;',
	'uniform vec3 u_body;',
	'uniform float u_dark;',
	'uniform vec2 u_col;',
	'const float H = ' + WATERLINE.toFixed(3) + ';',
	'float h11(float n) { return fract(sin(mod(n, 1024.0) * 12.9898) * 43758.5453); }',
	'float h21(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }',
	'float noise(vec2 p) {',
	'	vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);',
	'	return mix(mix(h21(i), h21(i + vec2(1.0, 0.0)), u.x), mix(h21(i + vec2(0.0, 1.0)), h21(i + vec2(1.0, 1.0)), u.x), u.y);',
	'}',
	'float fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 4; i++) { v += a * noise(p); p *= 2.03; a *= 0.5; } return v; }',
	'vec3 winColor(float k) { return k < 0.5 ? u_c1 : (k < 0.75 ? u_c2 : (k < 0.92 ? u_c3 : mix(u_c2, vec3(1.0), 0.4))); }',
	'vec4 over(vec4 top, vec4 under) { return top + under * (1.0 - top.a); }',
	// The skyline at point p (in screen heights), premultiplied; calm dims it, dip lowers it
	'vec4 city(vec2 p, float calm, float fog) {',
	'	vec2 colH = u_col / (u_res.y / u_scale);',
	'	float sy = max(p.y - H, 0.0);',
	'	float g = exp(-sy * 3.5) * (0.14 + 0.10 * fog) * mix(0.55, 1.0, calm) * mix(0.6, 1.0, u_dark);',
	'	vec4 acc = vec4(u_haze * g, g) * step(H, p.y);',
	'	for (int i = 0; i < 5; i++) {',
	'		float fi = float(i), depth = fi / 4.0;',
	'		float scale = mix(6.5, 2.3, depth);',
	'		float off = u_pan[i] + u_look.x * (0.4 + depth * 1.4) + fi * 17.0;',
	'		float wx = p.x * scale + off;',
	'		float ci = floor(wx), f = fract(wx);',
	'		float rnd = h11(ci + fi * 57.0), rw = h11(ci * 1.73 + fi * 23.0);',
	'		float bandB = abs((ci + 0.5 - off) / scale - colH.x) / colH.y;',
	'		float dip = 1.0 - 0.5 * ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.4, 1.2, bandB));',
	'		float topH = (mix(0.20, 0.30, depth) + rnd * mix(0.12, 0.34, depth)) * ' + CITY_HEIGHT.toFixed(3) + ' * dip;',
	'		float wB = 0.70 + rw * 0.22, edge = (1.0 - wB) * 0.5;',
	'		float aa = scale / (u_res.y / u_scale);',
	'		float inB = smoothstep(edge - aa, edge, f) * smoothstep(1.0 - edge + aa, 1.0 - edge, f) * step(H, p.y) * smoothstep(H + topH + 0.002, H + topH, p.y);',
	'		float lx = (f - edge) / wB, ly = p.y - H;',
	'		float wCols = floor(5.0 + rw * 6.0), rowH = mix(0.011, 0.016, depth);',
	'		vec2 cell = vec2(floor(lx * wCols), floor(ly / rowH));',
	'		vec2 wf = vec2(fract(lx * wCols), fract(ly / rowH));',
	'		float frame = step(0.22, wf.x) * step(wf.x, 0.78) * step(0.3, wf.y) * step(wf.y, 0.78) * step(ly, topH - 0.012);',
	'		float seed = h21(cell + vec2(mod(ci, 1024.0) * 7.0, fi * 11.0));',
	'		float lit = step(mix(0.80, 0.25, ' + WINDOW_DENSITY.toFixed(3) + '), seed);',
	'		float flick = 0.78 + 0.22 * step(0.5, h21(cell + floor(u_time * (0.12 + seed * 0.3))));',
	'		float emit = lit * frame * flick * (0.45 + 0.55 * h21(cell + 3.7)) * (0.35 + depth * 0.65) * ' + NEON_BRIGHTNESS.toFixed(3) + ' * mix(0.75, 1.0, u_dark);',
	'		float sg = step(0.62, rnd) * step(0.5, depth) * step(0.06, lx) * step(lx, 0.12) * step(0.08, ly) * step(ly, topH * 0.7);',
	'		emit = max(emit, sg * (0.55 + 0.35 * sin(u_time * 0.8 + rnd * 20.0)) * ' + NEON_BRIGHTNESS.toFixed(3) + ');',
	'		vec3 wc = sg > 0.5 ? mix(u_c2, u_c3, step(0.8, rnd)) : winColor(h11(cell.x + cell.y * 3.1 + ci));',
	'		float haze = (1.0 - depth) * (0.35 + 0.3 * fog);',
	'		vec3 body = mix(u_body, u_haze, haze * mix(0.6, 0.15, u_dark));',
	'		float rise = mix(smoothstep(-0.02, 0.16 + 0.08 * fog, ly), 1.0, depth * 0.55);',
	'		float ba = mix(mix(0.22, 0.80, depth), mix(0.10, 0.38, depth), 1.0 - u_dark) * inB * calm * mix(0.35, 1.0, rise);',
	'		float we = emit * inB * calm * calm * mix(1.0 - haze * 0.6, 1.0, depth);',
	'		acc = over(vec4(body * ba + wc * we, max(ba, we)), acc);',
	'		if (i == 2) {',
	'			float mist = fbm(vec2(p.x * 2.4 - u_time * 0.04, p.y * 3.2 + u_time * 0.015));',
	'			float ma = smoothstep(0.35, 0.8, mist) * exp(-abs(p.y - H - 0.06) * 6.0) * 0.45 * fog * mix(0.4, 1.0, calm) * step(H, p.y);',
	'			ma *= mix(0.55, 1.0, u_dark);',
	'			acc = over(vec4(u_haze * ma, ma), acc);',
	'		}',
	'	}',
	'	return acc;',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	vec2 p = px / res.y;',
	'	p.y += u_look.y * 0.02;',
	'	float fog = ' + FOG_DENSITY.toFixed(3) + ';',
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float near = 1.0 - smoothstep(0.5, 1.3, band);',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * near;',
	'	vec4 col;',
	'	if (p.y >= H) {',
	'		col = city(p, calm, fog);',
	'	} else {',
	'		float d = H - p.y;',
	'		vec2 rp = vec2(p.x + sin(p.y * 42.0 + u_time * 1.6) * 0.004 * (1.0 + d * 3.0) + sin(p.y * 11.0 - u_time * 0.7) * 0.01 * d, H + d * 1.1);',
	'		float glint = smoothstep(0.45, 0.9, noise(vec2(p.x * 40.0, p.y * 150.0 - u_time * 1.2)));',
	'		vec4 refl = city(rp, calm, fog) * exp(-d * 5.0) * mix(0.5, 0.7, u_dark) * (0.6 + 0.8 * glint);',
	'		float wa = mix(0.06, 0.32, u_dark) * smoothstep(0.0, 0.05, d) * mix(0.35, 1.0, calm) * smoothstep(0.0, 0.18, p.y + 0.06);',
	'		col = over(refl, vec4(u_body * wa, wa));',
	'	}',
	'	col.a = clamp(col.a, 0.0, 1.0);',
	'	gl_FragColor = vec4(min(col.rgb, vec3(col.a)), col.a);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
const loc = {};
let w = 0, h = 0, dpr = 1;
let last = 0, time = 0, reduced = false, column = null;
const pans = new Float32Array(5);
const mouse = { x: -10000, y: -10000, amount: 0, target: 0, lx: 0, ly: 0 };
const colors = { c1: hexToRgb(COLOR_AMBER), c2: hexToRgb(COLOR_CYAN), c3: hexToRgb(COLOR_MAGENTA), haze: hexToRgb(COLOR_HAZE), body: [0.02, 0.02, 0.035], dark: 1 };

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function mix3(a, b, k) { return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]; }

// Windows in the accents, towers in the theme's structure color, fog between muted and accent2
function applyTheme(t) {
	if (t) colors.dark = t.dark === false ? 0 : 1;
	const own = !FOLLOW_THEME || !t || !t.rgb;
	if (own) {
		colors.c1 = hexToRgb(COLOR_AMBER);
		colors.c2 = hexToRgb(COLOR_CYAN);
		colors.c3 = hexToRgb(COLOR_MAGENTA);
		colors.haze = colors.dark ? hexToRgb(COLOR_HAZE) : [0.96, 0.95, 0.96];
		colors.body = colors.dark ? [0.02, 0.02, 0.035] : [0.36, 0.38, 0.44];
		return;
	}
	colors.c1 = t.rgb.accent;
	colors.c2 = t.rgb.accent3;
	colors.c3 = t.rgb.accent2;
	colors.haze = colors.dark ? mix3(t.rgb.muted, t.rgb.accent2, 0.35) : mix3(t.rgb.background, [1, 1, 1], 0.5);
	colors.body = colors.dark ? mix3(t.rgb.background, [0, 0, 0], 0.75) : t.rgb.muted;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_pan', 'u_look', 'u_c1', 'u_c2', 'u_c3', 'u_haze', 'u_body', 'u_dark', 'u_col'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

// Window grids are line art, so the scene follows the pixel ratio up to 2
function size() {
	const s = RENDER_SCALE * Math.min(dpr, 2);
	canvas.width = Math.max(1, Math.round(w * s));
	canvas.height = Math.max(1, Math.round(h * s));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const k = reduced ? REDUCED_SPEED : 1;
	time = (time + dt * MOTION * k) % 3000;
	for (let i = 0; i < 5; i++) pans[i] = (pans[i] + dt * PAN_SPEED * k * (0.015 + i * 0.02)) % 1024;
	// The head turn eases toward the cursor, then drifts back once it rests
	mouse.target = Math.max(0, mouse.target - dt * 0.35);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 2);
	const tx = w ? (mouse.x / w - 0.5) * mouse.amount * LOOK_AROUND : 0;
	const ty = h ? (0.5 - mouse.y / h) * mouse.amount * LOOK_AROUND : 0;
	const ease = Math.min(1, dt * (reduced ? 0.6 : 2.5));
	mouse.lx += (tx - mouse.lx) * ease;
	mouse.ly += (ty - mouse.ly) * ease;
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform1fv(loc.u_pan, pans);
	gl.uniform2f(loc.u_look, mouse.lx, mouse.ly);
	gl.uniform3fv(loc.u_c1, colors.c1);
	gl.uniform3fv(loc.u_c2, colors.c2);
	gl.uniform3fv(loc.u_c3, colors.c3);
	gl.uniform3fv(loc.u_haze, colors.haze);
	gl.uniform3fv(loc.u_body, colors.body);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	const opts = { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' };
	gl = canvas.getContext('webgl2', opts) || canvas.getContext('webgl', opts);
	if (!gl) {
		console.warn('Chongqing Fog City: WebGL is not available, so the city is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Chongqing Fog City:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Chongqing Fog City:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			dpr = d.dpr || 1;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			for (let i = 0; i < 5; i++) pans[i] = Math.random() * 1024;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			dpr = d.dpr || dpr;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

/**
 * Title: Circuit Board
 * Description: Circuit traces grow along a grid at the sides of the screen, glow at their pads, retire and regrow, and carry signal pulses wherever the cursor passes or taps.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const GRID          = 20;    // grid the traces follow, in px (10-40)
const MAX_TRACES    = 48;    // traces on the board at once (10-80)
const GROW_SPEED    = 120;   // how fast a trace draws itself, in px per second (30-400)
const TRACE_LIFE    = 30;    // average seconds a finished trace stays before it retires (8-120)
const TRACE_ALPHA   = 0.3;   // visibility of finished traces (0.1-0.6)
const PULSE_SPEED   = 180;   // speed of signal pulses, in px per second (60-500)
const MAX_PULSES    = 24;    // signal pulses at once (0-40)
const CURSOR_REACH  = 150;   // how near the cursor must pass a pad to send a pulse, in px (50-300)
const MOTION        = 1;     // overall speed (0.2-2)
const REDUCED_SPEED = 0.3;   // share of the speed kept when the viewer asks to reduce motion (0-1)
const CENTER_CALM   = 0.92;  // how much traces fade behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const TRACE_COLOR   = '#00b4a0';  // finished trace color when not following the theme
const NODE_COLOR    = '#00dcb4';  // pad and growing trace color
const TIP_COLOR     = '#00ffdc';  // growing tip color
const PULSE_COLOR   = '#00ffc8';  // signal pulse color
/* ──────────────────────────────────────────── */

const MAX_PTS = 12;
const DIRS_X = [1, 0, -1, 0], DIRS_Y = [0, 1, 0, -1];
const FREE = 0, GROWING = 1, DONE = 2, FADING = 3;

let canvas, ctx;
let w = 0, h = 0, dpr = 1;
let last = 0, reduced = false, dark = true, spawnWait = 0, pulseWait = 0, column = null, insetL = 0, insetR = 0;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };
const col = { trace: TRACE_COLOR, node: NODE_COLOR, tip: TIP_COLOR, pulse: PULSE_COLOR };
let tipSprite = null, pulseSprite = null;
// Trace pool: points, then per-trace state
const tx = new Float32Array(MAX_TRACES * MAX_PTS), ty = new Float32Array(MAX_TRACES * MAX_PTS);
const tn = new Uint8Array(MAX_TRACES), ts = new Uint8Array(MAX_TRACES), tseg = new Uint8Array(MAX_TRACES);
const tprog = new Float32Array(MAX_TRACES), tlife = new Float32Array(MAX_TRACES);
const talpha = new Float32Array(MAX_TRACES), tfade = new Float32Array(MAX_TRACES);
// Pulse pool: trace, segment, progress in px, life
const pt = new Int16Array(MAX_PULSES).fill(-1), pseg = new Uint8Array(MAX_PULSES);
const pprog = new Float32Array(MAX_PULSES), plife = new Float32Array(MAX_PULSES);

// A soft round glow in one color: the color filled, then masked by a radial falloff
function sprite(color, r) {
	const c = new OffscreenCanvas(r * 2, r * 2), g = c.getContext('2d');
	g.fillStyle = color;
	g.fillRect(0, 0, r * 2, r * 2);
	const grad = g.createRadialGradient(r, r, 0, r, r, r);
	grad.addColorStop(0, 'rgba(255,255,255,1)');
	grad.addColorStop(0.2, 'rgba(255,255,255,0.9)');
	grad.addColorStop(0.45, 'rgba(255,255,255,0.25)');
	grad.addColorStop(1, 'rgba(255,255,255,0)');
	g.globalCompositeOperation = 'destination-in';
	g.fillStyle = grad;
	g.fillRect(0, 0, r * 2, r * 2);
	return c;
}

function applyTheme(t) {
	if (t) {
		dark = t.dark !== false;
		if (FOLLOW_THEME && t.colors) {
			col.trace = t.colors.muted;
			col.node = t.colors.accent;
			col.tip = t.colors.accent2;
			col.pulse = t.colors.accent3;
		}
	}
	tipSprite = sprite(col.tip, 12);
	pulseSprite = sprite(col.pulse, 12);
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function band(x) {
	const b = Math.abs(x - colX()) / colHalf();
	const s = Math.min(1, Math.max(0, (b - 0.55) / 0.7));
	return 1 - CENTER_CALM * (1 - s * s * (3 - 2 * s));
}

// The chat area's edges as insets from the screen's, so a board laid on resize, before the next layout message, still fits the new width
function setArea(width) { insetL = column ? column.left : 0; insetR = column ? Math.max(0, width - column.right) : 0; }

const snap = (v) => Math.round(v / GRID) * GRID;

// Lays a new trace inside one side's region, turning 90 degrees at each joint and never doubling onto itself
function lay(i) {
	// Inside the chat area, which leaves out the sidebar
	const inner = colHalf() * 0.5, cx = colX(), lo = insetL, hi = w - insetR;
	const left = Math.random() < 0.5;
	let x0 = left ? lo + GRID : cx + inner, x1 = left ? cx - inner : hi - GRID;
	if (x1 - x0 < GRID * 4) { x0 = lo + GRID; x1 = hi - GRID; }
	let x = snap(x0 + Math.random() * (x1 - x0)), y = snap(GRID + Math.random() * (h - GRID * 2));
	let dir = Math.floor(Math.random() * 4);
	const o = i * MAX_PTS, want = 4 + Math.floor(Math.random() * (MAX_PTS - 4));
	tx[o] = x; ty[o] = y;
	let n = 1;
	for (let tries = 0; n < want && tries < want * 3; tries++) {
		const len = (2 + Math.floor(Math.random() * 7)) * GRID;
		let nx = x + DIRS_X[dir] * len, ny = y + DIRS_Y[dir] * len;
		// Bounce off the region's edge rather than pile up along it
		if (nx < x0 || nx > x1 || ny < GRID || ny > h - GRID) { nx = x - DIRS_X[dir] * len; ny = y - DIRS_Y[dir] * len; }
		dir = (dir + (Math.random() < 0.5 ? 1 : 3)) % 4;
		if (nx < x0 || nx > x1 || ny < GRID || ny > h - GRID) continue;
		x = snap(nx); y = snap(ny);
		tx[o + n] = x; ty[o + n] = y;
		n++;
	}
	tn[i] = n;
	tseg[i] = 0;
	tprog[i] = 0;
	tfade[i] = 1;
	talpha[i] = TRACE_ALPHA * (0.6 + Math.random() * 0.4) * band(tx[o]);
	tlife[i] = TRACE_LIFE * (0.6 + Math.random() * 0.8);
	ts[i] = n > 1 ? GROWING : FREE;
}

function segLen(i, s) {
	const o = i * MAX_PTS + s;
	return Math.abs(tx[o + 1] - tx[o]) + Math.abs(ty[o + 1] - ty[o]);
}

// A full board at start and after each resize, its traces at staggered ages so they retire one by one
function seed() {
	ts.fill(FREE);
	pt.fill(-1);
	for (let i = 0; i < Math.floor(MAX_TRACES * 0.7); i++) {
		lay(i);
		if (ts[i] === FREE) continue;
		ts[i] = DONE;
		tseg[i] = tn[i] - 1;
		tlife[i] *= Math.random();
	}
}

// After the chat column moves, traces that now cross it or sit outside the chat area retire and regrow beside it
function clearColumn() {
	const a = colX() - colHalf() * 0.5, b = colX() + colHalf() * 0.5, lo = insetL, hi = w - insetR;
	for (let i = 0; i < MAX_TRACES; i++) {
		if (ts[i] !== DONE && ts[i] !== GROWING) continue;
		for (let k = 0, o = i * MAX_PTS; k < tn[i]; k++) {
			if ((tx[o + k] > a && tx[o + k] < b) || tx[o + k] < lo || tx[o + k] > hi) { ts[i] = FADING; break; }
		}
	}
}

function resize(width, height, ratio) {
	w = width;
	h = height;
	dpr = Math.min(ratio || 1, 2);
	if (!canvas) return;
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	seed();
}

// Sends one pulse down the trace with a pad nearest to (x, y), if any is within reach
function pulseNear(x, y) {
	let best = -1, bestD = CURSOR_REACH * CURSOR_REACH;
	for (let i = 0; i < MAX_TRACES; i++) {
		if (ts[i] !== DONE) continue;
		for (let k = 0, o = i * MAX_PTS; k < tn[i]; k++) {
			const dx = tx[o + k] - x, dy = ty[o + k] - y, d = dx * dx + dy * dy;
			if (d < bestD) { bestD = d; best = i; }
		}
	}
	if (best < 0) return;
	for (let p = 0; p < MAX_PULSES; p++) {
		if (pt[p] >= 0) continue;
		pt[p] = best; pseg[p] = 0; pprog[p] = 0; plife[p] = 1;
		return;
	}
}

function update(dt) {
	const speed = dt * MOTION * (reduced ? REDUCED_SPEED : 1);
	let growing = 0, oldest = -1;
	for (let i = 0; i < MAX_TRACES; i++) {
		if (ts[i] === GROWING) {
			growing++;
			tprog[i] += GROW_SPEED * speed;
			while (ts[i] === GROWING && tprog[i] >= segLen(i, tseg[i])) {
				tprog[i] -= segLen(i, tseg[i]);
				if (++tseg[i] >= tn[i] - 1) ts[i] = DONE;
			}
		} else if (ts[i] === DONE) {
			tlife[i] -= speed;
			if (tlife[i] <= 0) ts[i] = FADING;
			if (oldest < 0 || tlife[i] < tlife[oldest]) oldest = i;
		} else if (ts[i] === FADING) {
			tfade[i] -= speed * 0.4;
			if (tfade[i] <= 0) ts[i] = FREE;
		}
	}
	spawnWait -= speed;
	if (spawnWait <= 0 && growing < 3) {
		spawnWait = 0.4 + Math.random() * 0.6;
		const slot = ts.indexOf(FREE);
		if (slot >= 0) lay(slot);
		else if (oldest >= 0) ts[oldest] = FADING; // a full board retires its oldest trace so a new one can grow
	}
	pulseWait -= dt;
	if (mouse.amount > 0.3 && pulseWait <= 0) {
		pulseWait = 0.25;
		pulseNear(mouse.x, mouse.y);
	}
	for (let p = 0; p < MAX_PULSES; p++) {
		const i = pt[p];
		if (i < 0) continue;
		if (ts[i] === FREE) { pt[p] = -1; continue; }
		pprog[p] += PULSE_SPEED * speed;
		while (pt[p] >= 0 && pprog[p] >= segLen(i, pseg[p])) {
			pprog[p] -= segLen(i, pseg[p]);
			if (++pseg[p] >= tn[i] - 1) pt[p] = -1;
		}
		plife[p] -= speed * 0.15;
		if (plife[p] <= 0) pt[p] = -1;
	}
}

// Path of a trace up to its growth point; returns the tip's position through tip[]
const tip = new Float32Array(2);
function path(i) {
	const o = i * MAX_PTS, s = tseg[i];
	ctx.moveTo(tx[o], ty[o]);
	for (let k = 1; k <= s; k++) ctx.lineTo(tx[o + k], ty[o + k]);
	if (ts[i] === GROWING) {
		const len = segLen(i, s) || 1, f = Math.min(1, tprog[i] / len);
		tip[0] = tx[o + s] + (tx[o + s + 1] - tx[o + s]) * f;
		tip[1] = ty[o + s] + (ty[o + s + 1] - ty[o + s]) * f;
		ctx.lineTo(tip[0], tip[1]);
	}
}

function draw() {
	ctx.clearRect(0, 0, w, h);
	const k = dark ? 1 : 0.8;
	ctx.lineWidth = 1.5;
	ctx.lineJoin = 'round';
	for (let i = 0; i < MAX_TRACES; i++) {
		if (ts[i] === FREE) continue;
		const a = talpha[i] * tfade[i] * k;
		ctx.globalAlpha = ts[i] === GROWING ? Math.min(1, a * 1.8) : a;
		ctx.strokeStyle = ts[i] === GROWING ? col.node : col.trace;
		ctx.beginPath();
		path(i);
		ctx.stroke();
		// Pads at each joint, brighter where the cursor is
		ctx.fillStyle = col.node;
		const o = i * MAX_PTS, end = ts[i] === GROWING ? tseg[i] : tn[i] - 1;
		for (let n = 0; n <= end; n++) {
			const dx = tx[o + n] - mouse.x, dy = ty[o + n] - mouse.y;
			const near = Math.max(0, 1 - Math.sqrt(dx * dx + dy * dy) / 120) * mouse.amount;
			ctx.globalAlpha = Math.min(1, a * (1.6 + near * 2.5));
			const r = n === 0 || n === tn[i] - 1 ? 2.5 : 1.75;
			ctx.fillRect(tx[o + n] - r, ty[o + n] - r, r * 2, r * 2);
		}
		if (ts[i] === GROWING) {
			ctx.globalAlpha = Math.min(1, band(tip[0]) * (dark ? 0.9 : 0.7));
			ctx.drawImage(tipSprite, tip[0] - 12, tip[1] - 12);
		}
	}
	for (let p = 0; p < MAX_PULSES; p++) {
		const i = pt[p];
		if (i < 0) continue;
		const o = i * MAX_PTS + pseg[p];
		const f = Math.min(1, pprog[p] / (segLen(i, pseg[p]) || 1));
		const x = tx[o] + (tx[o + 1] - tx[o]) * f, y = ty[o] + (ty[o + 1] - ty[o]) * f;
		ctx.globalAlpha = Math.min(1, plife[p] * 1.5) * tfade[i] * band(x) * (dark ? 0.95 : 0.75);
		ctx.drawImage(pulseSprite, x - 12, y - 12);
	}
	ctx.globalAlpha = 1;
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!ctx) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	mouse.target = Math.max(0, mouse.target - dt * 0.8);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 5);
	update(dt);
	draw();
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			reduced = !!d.reducedMotion;
			column = d.column || null;
			setArea(d.width);
			applyTheme(d.theme);
			resize(d.width, d.height, d.dpr);
			requestAnimationFrame(frame);
			break;
		case 'resize':
			resize(d.width, d.height, d.dpr);
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			setArea(w);
			if (canvas) clearColumn();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
		case 'mousedown':
			// A tap sends a few pulses from the pads around it; one when motion is reduced
			for (let n = reduced ? 1 : 3; n > 0; n--) pulseNear(d.x + (Math.random() - 0.5) * 60, d.y + (Math.random() - 0.5) * 60);
			break;
	}
};

/**
 * Title: Constellation Map
 * Description: Drifting, twinkling stars in your theme's colors link into faint constellations, thin behind the chat, lean gently toward the cursor and light up where you tap.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const STAR_COUNT     = 120;   // number of stars (40-300)
const STAR_SIZE      = 1;     // size of the stars (0.5-2)
const LINK_DIST      = 150;   // longest constellation line, in px (60-260)
const LINK_ALPHA     = 0.3;   // strength of the constellation lines (0-1)
const MAX_LINKS      = 3;     // lines each star may start (1-6)
const DRIFT          = 1;     // drift speed of the stars; 0 holds them still (0-3)
const REDUCED_SPEED  = 0.2;   // share of the drift kept when the viewer asks to reduce motion (0-1)
const TWINKLE        = 1;     // how much the stars twinkle (0-2)
const CENTER_CALM    = 0.7;   // how much the stars and lines fade behind the chat column (0-1)
const BAND_WIDTH     = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const CURSOR_GRAVITY = 1;     // how strongly nearby stars lean toward the cursor (0-3)
const CURSOR_RADIUS  = 250;   // reach of the cursor, in px (100-400)
const MAX_PULL       = 40;    // top speed the cursor can give a star, in px per second (5-120)
const TAP_GLOW       = 1;     // how brightly a tap lights the nearby stars; 0 turns it off (0-2)
const FOLLOW_THEME   = true;  // take the colors from the theme's palette
const STAR_COLOR     = '#dce6ff';  // most stars when not following the theme
const WARM_COLOR     = '#fff0c8';  // warm stars
const BLUE_COLOR     = '#a8c4ff';  // blue stars
const LINE_COLOR     = '#b4c8ff';  // constellation lines
const CURSOR_COLOR   = '#a0c8ff';  // lines to the cursor
/* ──────────────────────────────────────────── */

const MAX_STARS = 300;
const N = Math.max(1, Math.min(MAX_STARS, Math.round(STAR_COUNT)));
const LEVELS = 6;              // line alphas are batched into this many strokes
const CAP = N * 6;             // segments per batch
const SPRITE = 64;             // star sprite size in device px

let canvas, ctx;
let w = 0, h = 0, dpr = 1;
let last = 0, time = 0, reduced = false, dark = true, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };
const tap = { x: -10000, y: -10000, age: 10 };

const sx = new Float32Array(N), sy = new Float32Array(N);
const vx = new Float32Array(N), vy = new Float32Array(N);
const bx = new Float32Array(N), by = new Float32Array(N);
const size = new Float32Array(N), bright = new Float32Array(N);
const twRate = new Float32Array(N), twPhase = new Float32Array(N), twAmt = new Float32Array(N);
const tone = new Uint8Array(N);
const lum = new Float32Array(N);       // brightness this frame, calm included
const segs = new Float32Array(2 * LEVELS * CAP * 4);
const segN = new Int32Array(2 * LEVELS);

let colors = { stars: [STAR_COLOR, WARM_COLOR, BLUE_COLOR].map(hexToRgb), line: hexToRgb(LINE_COLOR), cursor: hexToRgb(CURSOR_COLOR) };
const sprites = [];
const styles = [];                      // [batch] -> stroke color string

function hexToRgb(hex) {
	const n = parseInt(String(hex).slice(1, 7), 16) || 0;
	return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function rgba(c, a) {
	return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a.toFixed(3) + ')';
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function calm(x) {
	const d = Math.abs(x - colX()) / colHalf();
	const s = Math.min(1, Math.max(0, (d - 0.55) / 0.7));
	return 1 - CENTER_CALM * (1 - s * s * (3 - 2 * s));
}

function applyTheme(t) {
	if (!t) return;
	dark = t.dark !== false;
	if (FOLLOW_THEME && t.colors) {
		const c = t.colors;
		colors = {
			// Pale text-colored stars on dark; on light, gray dots would read as dust, so the accents lead
			stars: dark ? [hexToRgb(c.text), hexToRgb(c.accent2), hexToRgb(c.accent)] : [hexToRgb(c.accent), hexToRgb(c.accent2), hexToRgb(c.accent3)],
			line: hexToRgb(dark ? c.text : c.muted),
			cursor: hexToRgb(c.accent),
		};
	}
	build();
}

// Star sprites and line colors, rebuilt on theme change only
function build() {
	for (let k = 0; k < 3; k++) {
		const c = colors.stars[k];
		const sp = sprites[k] || new OffscreenCanvas(SPRITE, SPRITE);
		const g = sp.getContext('2d');
		g.clearRect(0, 0, SPRITE, SPRITE);
		const r = SPRITE / 2;
		const grad = g.createRadialGradient(r, r, 0, r, r, r);
		grad.addColorStop(0, rgba(c, 1));
		grad.addColorStop(0.09, rgba(c, 1));
		grad.addColorStop(0.15, rgba(c, dark ? 0.45 : 0.3));
		grad.addColorStop(0.4, rgba(c, dark ? 0.12 : 0.04));
		grad.addColorStop(1, rgba(c, 0));
		g.fillStyle = grad;
		g.fillRect(0, 0, SPRITE, SPRITE);
		sprites[k] = sp;
	}
	const top = LINK_ALPHA * (dark ? 1.3 : 1.9);
	for (let b = 0; b < LEVELS; b++) {
		styles[b] = rgba(colors.line, top * (b + 1) / LEVELS);
		styles[LEVELS + b] = rgba(colors.cursor, (dark ? 0.45 : 0.4) * (b + 1) / LEVELS);
	}
}

function seed() {
	for (let i = 0; i < N; i++) {
		sx[i] = Math.random() * w;
		sy[i] = Math.random() * h;
		const a = Math.random() * Math.PI * 2, s = 2 + Math.random() * 6;
		bx[i] = vx[i] = Math.cos(a) * s;
		by[i] = vy[i] = Math.sin(a) * s;
		size[i] = 0.8 + Math.random() * 1.8;
		bright[i] = 0.35 + Math.random() * 0.65;
		twRate[i] = 0.8 + Math.random() * 2;
		twPhase[i] = Math.random() * Math.PI * 2;
		twAmt[i] = 0.1 + Math.random() * 0.3;
		const roll = Math.random();
		tone[i] = roll < 0.6 ? 0 : roll < 0.8 ? 1 : 2;
	}
}

function size2d(nw, nh, ndpr) {
	// Keep the sky on a resize: scale the stars to the new size instead of re-rolling them
	if (w && h) {
		for (let i = 0; i < N; i++) { sx[i] *= nw / w; sy[i] *= nh / h; }
	}
	w = nw;
	h = nh;
	dpr = Math.min(2, ndpr || 1);
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}

function addSeg(batch, x1, y1, x2, y2) {
	const n = segN[batch];
	if (n >= CAP) return;
	const o = (batch * CAP + n) * 4;
	segs[o] = x1; segs[o + 1] = y1; segs[o + 2] = x2; segs[o + 3] = y2;
	segN[batch] = n + 1;
}

function update(dt) {
	const speed = DRIFT * (reduced ? REDUCED_SPEED : 1);
	const pull = CURSOR_GRAVITY * mouse.amount * 90;
	const r2 = CURSOR_RADIUS * CURSOR_RADIUS;
	const relax = Math.min(1, dt * 0.8);
	const tw = TWINKLE * (reduced ? 0.4 : 1);
	tap.age += dt;
	const glow = TAP_GLOW * (reduced ? 0.4 : 1) * Math.min(1, tap.age * 6) * Math.max(0, 1 - tap.age / 1.8);
	for (let i = 0; i < N; i++) {
		const dx = mouse.x - sx[i], dy = mouse.y - sy[i];
		const d2 = dx * dx + dy * dy;
		if (pull > 0 && d2 < r2 && d2 > 1) {
			const d = Math.sqrt(d2);
			// Pull toward the cursor, easing to a gentle push inside 45 px so stars hover instead of piling up
			const f = pull * (1 - d / CURSOR_RADIUS) * (d < 45 ? (d - 45) / 45 : 1);
			vx[i] += dx / d * f * dt;
			vy[i] += dy / d * f * dt;
			const ex = vx[i] - bx[i], ey = vy[i] - by[i];
			const e = Math.sqrt(ex * ex + ey * ey);
			if (e > MAX_PULL) { vx[i] = bx[i] + ex / e * MAX_PULL; vy[i] = by[i] + ey / e * MAX_PULL; }
		}
		vx[i] += (bx[i] - vx[i]) * relax;
		vy[i] += (by[i] - vy[i]) * relax;
		sx[i] += vx[i] * dt * speed;
		sy[i] += vy[i] * dt * speed;
		if (sx[i] < -20) sx[i] += w + 40; else if (sx[i] > w + 20) sx[i] -= w + 40;
		if (sy[i] < -20) sy[i] += h + 40; else if (sy[i] > h + 20) sy[i] -= h + 40;
		let b = bright[i] + Math.sin(time * twRate[i] + twPhase[i]) * twAmt[i] * tw;
		if (glow > 0) {
			const tx = sx[i] - tap.x, ty = sy[i] - tap.y;
			b += glow * 0.8 * Math.max(0, 1 - Math.sqrt(tx * tx + ty * ty) / 200);
		}
		lum[i] = Math.max(0.08, Math.min(1, b)) * calm(sx[i]);
	}
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!ctx) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	time += dt * (reduced ? REDUCED_SPEED : 1);
	mouse.target = Math.max(0, mouse.target - dt * 0.5);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 3);
	update(dt);

	ctx.globalAlpha = 1;
	ctx.globalCompositeOperation = 'source-over';
	ctx.clearRect(0, 0, w, h);

	// Gather the lines into a few alpha batches, then stroke each batch once
	segN.fill(0);
	const link2 = LINK_DIST * LINK_DIST;
	for (let i = 0; i < N; i++) {
		let links = 0;
		for (let j = i + 1; j < N && links < MAX_LINKS; j++) {
			const dx = sx[i] - sx[j], dy = sy[i] - sy[j];
			const d2 = dx * dx + dy * dy;
			if (d2 >= link2) continue;
			links++;
			const a = (1 - Math.sqrt(d2) / LINK_DIST) * Math.min(lum[i], lum[j]) * 1.4;
			const b = Math.min(LEVELS - 1, (a * LEVELS) | 0);
			if (a > 0.06) addSeg(b, sx[i], sy[i], sx[j], sy[j]);
		}
	}
	if (mouse.amount > 0.02) {
		const r = CURSOR_RADIUS * 0.6;
		for (let i = 0; i < N; i++) {
			const dx = sx[i] - mouse.x, dy = sy[i] - mouse.y;
			const d2 = dx * dx + dy * dy;
			if (d2 >= r * r) continue;
			const a = (1 - Math.sqrt(d2) / r) * mouse.amount * calm(sx[i]);
			const b = Math.min(LEVELS - 1, (a * LEVELS) | 0);
			if (a > 0.06) addSeg(LEVELS + b, mouse.x, mouse.y, sx[i], sy[i]);
		}
	}
	ctx.lineWidth = dpr > 1 ? 0.7 : 0.8;
	for (let b = 0; b < LEVELS * 2; b++) {
		const n = segN[b];
		if (!n) continue;
		ctx.strokeStyle = styles[b];
		ctx.beginPath();
		for (let k = 0; k < n; k++) {
			const o = (b * CAP + k) * 4;
			ctx.moveTo(segs[o], segs[o + 1]);
			ctx.lineTo(segs[o + 2], segs[o + 3]);
		}
		ctx.stroke();
	}

	// Stars on top, as sprites
	ctx.globalCompositeOperation = dark ? 'lighter' : 'source-over';
	const starA = dark ? 1 : 0.95;
	const grow = STAR_SIZE * (dark ? 12 : 15);
	for (let i = 0; i < N; i++) {
		const s = size[i] * grow;
		ctx.globalAlpha = lum[i] * starA;
		ctx.drawImage(sprites[tone[i]], sx[i] - s * 0.5, sy[i] - s * 0.5, s, s);
	}
	ctx.globalAlpha = 1;
	ctx.globalCompositeOperation = 'source-over';
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
