	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width;
			h = d.height;
			dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			column = d.column || null;
			if (PREVIEW_RATIO > 0) { ratio = target = PREVIEW_RATIO; tokens = (PREVIEW_RATIO * MAX_TOKENS) / GROWTH_SPEED; }
