	const cg = caustic.getContext('2d'), img = cg.createImageData(TW, TH);
	for (let i = 0; i < TW * TH; i++) { img.data[i * 4] = p.light[0]; img.data[i * 4 + 1] = p.light[1]; img.data[i * 4 + 2] = p.light[2]; img.data[i * 4 + 3] = causticField[i] * 255; }
