};

/**
 * Title: Glitch Grid
 * Description: A faint HUD grid with drafting measurements at its edges, where cells, scan lines and blocks glitch now and then in the outer thirds, away from the chat.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const CELL_SIZE     = 40;    // size of a grid cell, in px (20-80)
const GRID_ALPHA    = 0.1;   // visibility of the grid lines (0.03-0.15)
const GLITCH_RATE   = 1;     // how often glitches appear; 0 turns them off (0-3)
const GLITCH_ALPHA  = 0.12;  // peak visibility of a glitched cell (0.03-0.25)
const SCAN_LINES    = true;  // short scan lines sweep the outer thirds
const SHIFT_BLOCKS  = true;  // blocks of the grid briefly slip sideways
const ANNOTATIONS   = true;  // coordinate ticks and labels along the edges
const DIMENSIONS    = 4;     // drafting dimension lines fading in and out at the sides (0-8)
const SECTORS       = 4;     // faint bracketed sector blocks at the sides (0-6)
const MOTION        = 1;     // speed of scan lines and fades (0.2-2)
const CENTER_CALM   = 0.7;   // how much the grid fades behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const CURSOR_GLOW   = 0.6;   // how brightly intersections near the cursor glow (0-1)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const GRID_COLOR    = '#64c8b4';  // grid and label color without the theme
const GLITCH_COLOR  = '#00dcb4';  // glitched cell color
const GLITCH_COLOR2 = '#00c8dc';  // second glitch color
const SCAN_COLOR    = '#c80064';  // scan line fringe color
/* ──────────────────────────────────────────── */

const MAX_CELLS = 24, MAX_SCANS = 4, MAX_BLOCKS = 3, MAX_DIMS = 8;
const DASH = [4, 3], SOLID = [];

let canvas, ctx, cache, cctx;
let w = 0, h = 0, dpr = 1;
let last = 0, reduced = false, dark = true, spawnWait = 0.5, column = null;
let zoneL = 0, zoneR = 0; // widths of the left and right glitch zones, beside the chat column
let zoneA = 0, zoneB = 0; // where the zones start and end: the chat area's edges, which leave out the sidebar
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };
const col = { grid: GRID_COLOR, a: GLITCH_COLOR, b: GLITCH_COLOR2, scan: SCAN_COLOR, font: '10px monospace' };
// Six floats per slot: x, y, life, maxLife, then alpha+color, alpha+speed or width+shift
const cells = new Float32Array(MAX_CELLS * 6);
const scans = new Float32Array(MAX_SCANS * 6);
const blocks = new Float32Array(MAX_BLOCKS * 6);
const sectors = new Float32Array(24); // x, y, width, height of up to six sector marks
const dims = [];
for (let i = 0; i < MAX_DIMS; i++) dims.push({ horiz: true, a: 0, b: 0, at: 0, age: 0, life: 0, label: '' });

function applyTheme(t) {
	if (t) {
		dark = t.dark !== false;
		if (FOLLOW_THEME && t.colors) {
			col.grid = t.colors.muted;
			col.a = t.colors.accent;
			col.b = t.colors.accent3;
			col.scan = t.colors.accent2;
		}
	}
	buildCache();
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function band(x) {
	const b = Math.abs(x - colX()) / colHalf();
	const s = Math.min(1, Math.max(0, (b - 0.55) / 0.7));
	return 1 - CENTER_CALM * (1 - s * s * (3 - 2 * s));
}

function resize(width, height, ratio) {
	w = width;
	h = height;
	dpr = Math.min(ratio || 1, 2);
	if (!canvas) return;
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	cache = new OffscreenCanvas(canvas.width, canvas.height);
	cctx = cache.getContext('2d');
	cells.fill(0); scans.fill(0); blocks.fill(0);
	for (let i = 0; i < MAX_DIMS; i++) dims[i].life = 0;
	layout();
}

// The glitch zones between the chat area's edges and the chat column, and the sector marks in them; rebuilt on resize and layout
function layout() {
	zoneA = column ? column.left : 0; zoneB = column ? column.right : w;
	zoneL = Math.max(CELL_SIZE * 2, Math.min(w / 3, colX() - colHalf() * 0.6 - zoneA));
	zoneR = Math.max(CELL_SIZE * 2, Math.min(w / 3, zoneB - colX() - colHalf() * 0.6));
	for (let i = 0; i < 6; i++) {
		const cw = 2 + Math.floor(Math.random() * 2), ch = 1 + Math.floor(Math.random() * 2);
		const span = Math.max(1, Math.floor((i % 2 ? zoneL : zoneR) / CELL_SIZE) - cw);
		const c = i % 2 ? Math.ceil(zoneA / CELL_SIZE) + Math.floor(Math.random() * span) : Math.floor(zoneB / CELL_SIZE) - cw - Math.floor(Math.random() * span);
		sectors[i * 4] = c * CELL_SIZE;
		sectors[i * 4 + 1] = (1 + Math.floor(Math.random() * Math.max(1, Math.floor(h / CELL_SIZE) - ch - 2))) * CELL_SIZE;
		sectors[i * 4 + 2] = cw * CELL_SIZE;
		sectors[i * 4 + 3] = ch * CELL_SIZE;
	}
	buildCache();
}

// The still grid, sectors and edge labels, drawn into a cache on resize or theme
function buildCache() {
	if (!cctx) return;
	const g = cctx;
	g.setTransform(1, 0, 0, 1, 0, 0);
	g.clearRect(0, 0, cache.width, cache.height);
	g.setTransform(dpr, 0, 0, dpr, 0, 0);
	const a = GRID_ALPHA, off = dpr < 1.5 ? 0.5 : 0, major = CELL_SIZE * 4;
	g.strokeStyle = col.grid;
	g.lineWidth = 1;
	// Minor lines, then every fourth line stronger, like a drafting sheet
	for (let pass = 0; pass < 2; pass++) {
		const step = pass ? major : CELL_SIZE;
		g.globalAlpha = pass ? Math.min(0.15, a * 1.5) : a;
		g.beginPath();
		for (let x = 0; x <= w; x += step) { g.moveTo(x + off, 0); g.lineTo(x + off, h); }
		for (let y = 0; y <= h; y += step) { g.moveTo(0, y + off); g.lineTo(w, y + off); }
		g.stroke();
	}
	// Sector marks: shaded cells with corner brackets, laid out at resize
	g.fillStyle = g.strokeStyle = col.a;
	for (let i = 0; i < SECTORS && i < 6; i++) {
		const x = sectors[i * 4] + off, y = sectors[i * 4 + 1] + off, bw = sectors[i * 4 + 2], bh = sectors[i * 4 + 3];
		g.globalAlpha = 0.08;
		g.fillRect(x, y, bw, bh);
		g.globalAlpha = 0.3;
		g.beginPath();
		g.moveTo(x - 4, y + 6); g.lineTo(x - 4, y - 4); g.lineTo(x + 6, y - 4);
		g.moveTo(x + bw + 4, y + bh - 6); g.lineTo(x + bw + 4, y + bh + 4); g.lineTo(x + bw - 6, y + bh + 4);
		g.stroke();
	}
	if (ANNOTATIONS) {
		g.fillStyle = g.strokeStyle = col.grid;
		g.font = col.font;
		g.globalAlpha = Math.min(0.5, a * 5);
		g.beginPath();
		for (let x = major; x < w; x += major) {
			if (x > zoneA + zoneL && x < zoneB - zoneR) continue;
			g.moveTo(x + off, 0); g.lineTo(x + off, 6);
			g.textAlign = 'center';
			g.fillText(String(x / CELL_SIZE), x, 17);
		}
		for (let y = major; y < h; y += major) {
			g.moveTo(0, y + off); g.lineTo(6, y + off);
			g.moveTo(w, y + off); g.lineTo(w - 6, y + off);
			g.textAlign = 'left';
			g.fillText(String(y / CELL_SIZE), 9, y - 3);
			g.textAlign = 'right';
			g.fillText(String(y / CELL_SIZE), w - 9, y - 3);
		}
		g.stroke();
	}
	// Fade the cache behind the chat column
	g.globalAlpha = 1;
	g.globalCompositeOperation = 'destination-in';
	const mask = g.createLinearGradient(0, 0, w, 0);
	for (let i = 0; i <= 16; i++) mask.addColorStop(i / 16, 'rgba(0,0,0,' + band((i / 16) * w).toFixed(3) + ')');
	g.fillStyle = mask;
	g.fillRect(0, 0, w, h);
	g.globalCompositeOperation = 'source-over';
}

// A random x inside one of the two outer zones, by their widths
function zoneX() {
	const x = Math.random() * (zoneL + zoneR);
	return x < zoneL ? zoneA + x : zoneB - (x - zoneL);
}

function free(pool, n) {
	for (let i = 0; i < n; i++) if (pool[i * 6 + 2] <= 0) return i * 6;
	return -1;
}

function spawn() {
	const near = mouse.amount > 0.2 && ((mouse.x >= zoneA && mouse.x < zoneA + zoneL) || (mouse.x > zoneB - zoneR && mouse.x <= zoneB));
	let k = free(cells, MAX_CELLS);
	if (k >= 0) {
		const x = near && Math.random() < 0.6 ? mouse.x + (Math.random() - 0.5) * 240 : zoneX();
		const y = near && Math.random() < 0.6 ? mouse.y + (Math.random() - 0.5) * 240 : Math.random() * h;
		cells[k] = Math.floor(Math.min(w - 1, Math.max(0, x)) / CELL_SIZE) * CELL_SIZE;
		cells[k + 1] = Math.floor(Math.min(h - 1, Math.max(0, y)) / CELL_SIZE) * CELL_SIZE;
		cells[k + 2] = cells[k + 3] = 0.6 + Math.random() * 0.9;
		cells[k + 4] = GLITCH_ALPHA * (0.4 + Math.random() * 0.6);
		cells[k + 5] = Math.random() < 0.5 ? 0 : 1;
	}
	if (SCAN_LINES && Math.random() < 0.12 && (k = free(scans, MAX_SCANS)) >= 0) {
		scans[k] = Math.random() < 0.5 ? 0 : 1;
		scans[k + 1] = Math.random() * h;
		scans[k + 2] = scans[k + 3] = 1.2 + Math.random() * 1.6;
		scans[k + 4] = 0.05 + Math.random() * 0.07;
		scans[k + 5] = (40 + Math.random() * 90) * (Math.random() < 0.5 ? 1 : -1);
	}
	if (SHIFT_BLOCKS && Math.random() < 0.06 && (k = free(blocks, MAX_BLOCKS)) >= 0) {
		const n = 1 + Math.floor(Math.random() * 3);
		blocks[k] = Math.floor(Math.min(zoneX(), w - n * CELL_SIZE) / CELL_SIZE) * CELL_SIZE;
		blocks[k + 1] = Math.floor((Math.random() * h) / CELL_SIZE) * CELL_SIZE;
		blocks[k + 2] = blocks[k + 3] = 0.35 + Math.random() * 0.4;
		blocks[k + 4] = n;
		blocks[k + 5] = (Math.random() < 0.5 ? -1 : 1) * (3 + Math.random() * 5);
	}
}

// Dimension lines in the outer zones, snapped to the major grid
function placeDim(d) {
	const major = CELL_SIZE * 4, snap = (v) => Math.round(v / major) * major;
	const left = Math.random() < 0.5, zone = left ? zoneL : zoneR;
	const inZone = (len) => snap(major * 0.5 + Math.random() * Math.max(0, zone - len - major));
	d.horiz = Math.random() < 0.5;
	if (d.horiz) {
		const span = Math.max(major, snap(zone * (0.4 + Math.random() * 0.4)));
		d.a = left ? snap(zoneA) + inZone(span) : zoneB - inZone(span) - span;
		d.b = d.a + span;
		d.at = snap(major + Math.random() * Math.max(0, h - major * 2));
	} else {
		d.at = left ? snap(zoneA) + inZone(0) : zoneB - inZone(0);
		d.a = snap(major * 0.5 + Math.random() * h * 0.4);
		d.b = Math.min(h - major * 0.5, d.a + snap(h * (0.2 + Math.random() * 0.3)));
	}
	for (let i = 0; i < MAX_DIMS; i++) {
		const o = dims[i];
		if (o !== d && o.life > 0 && o.horiz === d.horiz && Math.abs(o.at - d.at) < major) { d.life = 0; return; }
	}
	d.label = ((d.b - d.a) / CELL_SIZE).toFixed(1) + ' u';
	d.age = 0;
	d.life = 12 + Math.random() * 14;
}

function drawDims(dt) {
	ctx.strokeStyle = col.grid;
	ctx.fillStyle = col.grid;
	ctx.font = col.font;
	ctx.textAlign = 'center';
	ctx.lineWidth = 1;
	const peak = dark ? 0.32 : 0.28;
	for (let i = 0; i < DIMENSIONS && i < MAX_DIMS; i++) {
		const d = dims[i];
		d.age += dt * MOTION * (reduced ? 0.4 : 1);
		if (d.age >= d.life) { placeDim(d); d.age = -Math.random() * 4; }
		if (d.age < 0 || d.life <= 0) continue;
		const fade = Math.min(1, d.age / 2, (d.life - d.age) / 2);
		const mid = d.horiz ? (d.a + d.b) / 2 : d.at;
		ctx.globalAlpha = peak * fade * band(mid);
		ctx.setLineDash(DASH);
		ctx.beginPath();
		if (d.horiz) { ctx.moveTo(d.a, d.at); ctx.lineTo(d.b, d.at); } else { ctx.moveTo(d.at, d.a); ctx.lineTo(d.at, d.b); }
		ctx.stroke();
		ctx.setLineDash(SOLID);
		ctx.beginPath();
		for (let e = 0; e < 2; e++) {
			const v = e ? d.b : d.a;
			if (d.horiz) { ctx.moveTo(v, d.at - 7); ctx.lineTo(v, d.at + 7); } else { ctx.moveTo(d.at - 7, v); ctx.lineTo(d.at + 7, v); }
		}
		ctx.stroke();
		if (d.horiz) ctx.fillText(d.label, mid, d.at - 9);
		else ctx.fillText(d.label, d.at + (d.at < colX() ? 22 : -22), (d.a + d.b) / 2);
	}
}

// Ages a pooled glitch and returns its fade: a smooth rise and fall, never a flicker
function age(pool, k, dt, rise, fall) {
	pool[k + 2] -= dt * MOTION;
	const t = 1 - pool[k + 2] / pool[k + 3];
	return Math.min(1, t / rise, (1 - t) / fall);
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!ctx) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	mouse.target = Math.max(0, mouse.target - dt * 0.7);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 5);
	ctx.clearRect(0, 0, w, h);
	ctx.setTransform(1, 0, 0, 1, 0, 0);
	ctx.drawImage(cache, 0, 0);
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	if (DIMENSIONS > 0) drawDims(dt);
	const lightK = dark ? 1 : 0.8;

	// Intersections near the cursor glow, fading once it stops
	if (CURSOR_GLOW > 0 && mouse.amount > 0.01) {
		ctx.fillStyle = col.a;
		const range = CELL_SIZE * 3;
		const c0 = Math.max(0, Math.floor((mouse.x - range) / CELL_SIZE)), c1 = Math.floor((mouse.x + range) / CELL_SIZE);
		const r0 = Math.max(0, Math.floor((mouse.y - range) / CELL_SIZE)), r1 = Math.floor((mouse.y + range) / CELL_SIZE);
		for (let c = c0; c <= c1; c++) {
			for (let r = r0; r <= r1; r++) {
				const x = c * CELL_SIZE, y = r * CELL_SIZE;
				const dist = Math.hypot(x - mouse.x, y - mouse.y);
				if (dist >= range) continue;
				ctx.globalAlpha = (1 - dist / range) * 0.7 * CURSOR_GLOW * mouse.amount * band(x) * lightK;
				ctx.fillRect(x - 1.5, y - 1.5, 3, 3);
			}
		}
	}

	if (!reduced && GLITCH_RATE > 0) {
		spawnWait -= dt * GLITCH_RATE * MOTION * (mouse.amount > 0.2 ? 2 : 1);
		if (spawnWait <= 0) { spawn(); spawnWait = 0.25 + Math.random() * 0.35; }
	}
	// Glitched cells
	ctx.lineWidth = 1;
	for (let k = 0; k < MAX_CELLS * 6; k += 6) {
		if (cells[k + 2] <= 0) continue;
		const fade = age(cells, k, dt, 0.2, 0.45);
		if (fade <= 0) continue;
		const a = cells[k + 4] * fade * band(cells[k] + CELL_SIZE / 2) * lightK;
		ctx.fillStyle = ctx.strokeStyle = cells[k + 5] ? col.b : col.a;
		ctx.globalAlpha = a;
		ctx.fillRect(cells[k] + 1, cells[k + 1] + 1, CELL_SIZE - 2, CELL_SIZE - 2);
		ctx.globalAlpha = Math.min(1, a * 1.6);
		ctx.strokeRect(cells[k] + 1.5, cells[k + 1] + 1.5, CELL_SIZE - 3, CELL_SIZE - 3);
	}
	// Scan lines: short sweeps in one outer zone, with a colored fringe
	for (let k = 0; k < MAX_SCANS * 6; k += 6) {
		if (scans[k + 2] <= 0) continue;
		scans[k + 1] += scans[k + 5] * dt * MOTION;
		const fade = age(scans, k, dt, 0.2, 0.3);
		if (fade <= 0 || scans[k + 1] < 0 || scans[k + 1] > h) { scans[k + 2] = 0; continue; }
		const zone = scans[k] ? zoneR : zoneL, x0 = scans[k] ? zoneB - zone : zoneA, y = scans[k + 1];
		ctx.globalAlpha = scans[k + 4] * fade * lightK;
		ctx.fillStyle = col.a;
		ctx.fillRect(x0, y, zone, 1.5);
		ctx.globalAlpha *= 0.5;
		ctx.fillStyle = col.scan;
		ctx.fillRect(x0, y - 1.5, zone, 1);
		ctx.fillStyle = col.b;
		ctx.fillRect(x0, y + 2, zone, 1);
	}
	// Shifted blocks slip sideways and settle back
	for (let k = 0; k < MAX_BLOCKS * 6; k += 6) {
		if (blocks[k + 2] <= 0) continue;
		blocks[k + 2] -= dt * MOTION;
		const t = Math.max(0, blocks[k + 2] / blocks[k + 3]);
		const bw = blocks[k + 4] * CELL_SIZE;
		const sx = blocks[k] + blocks[k + 5] * t;
		ctx.globalAlpha = 0.07 * t * band(blocks[k]) * lightK;
		ctx.fillStyle = col.a;
		ctx.fillRect(sx, blocks[k + 1], bw, CELL_SIZE);
		ctx.globalAlpha = 0.25 * t * band(blocks[k]) * lightK;
		ctx.fillRect(sx, blocks[k + 1] + CELL_SIZE * 0.3, bw, 1);
		ctx.fillRect(sx, blocks[k + 1] + CELL_SIZE * 0.7, bw, 1);
	}
	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			resize(d.width, d.height, d.dpr);
			requestAnimationFrame(frame);
			break;
		case 'resize':
			resize(d.width, d.height, d.dpr);
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas && w) layout();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

/**
 * Title: Ink Bloom
 * Description: Drops of ink in the theme's accent colors bloom and diffuse in the outer thirds of the screen with soft tide-line edges, fading out over the chat column; the cursor stirs them and a tap lets a drop fall.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const MAX_BLOOMS   = 22;     // most blooms at once (4-40)
const BLOOM_EVERY  = 1.4;    // seconds between new drops (0.3-6)
const BLOOM_SIZE   = 170;    // average full-grown radius, in px (60-320)
const GROWTH       = 1;      // how fast a drop spreads; 0 holds the ink still (0-3)
const INK_STRENGTH = 1;      // how dense the ink is (0.2-2)
const TIDE_LINE    = 1;      // darkness of the ring where the ink's edge dries (0-2)
const TENDRILS     = 1;      // how ragged the edges are (0-2)
const CURSOR_BLOOM = 0.35;   // share of drops that fall near a moving cursor (0-1)
const CENTER_CALM  = 0.85;   // how much the ink fades over the chat column (0-1)
const BAND_WIDTH   = 520;    // half-width of the calm band when the page has no chat column, in px (300-900)
const RENDER_SCALE = 0.75;   // resolution of the ink; it is soft, so less is fine (0.5-1)
const MAX_FPS      = 30;     // frame cap; the ink moves slowly (15-60)
const FOLLOW_THEME = true;   // take the colors from the theme's palette
const COLOR_A      = '#3a2ab0'; // first ink when not following the theme
const COLOR_B      = '#b01e3a'; // second ink
const COLOR_C      = '#0e8a5c'; // third ink
const COLOR_D      = '#8a2a7a'; // fourth ink
/* ──────────────────────────────────────────── */

const MAXB = 40, STEPS = 48, HARM = 6, TAU = Math.PI * 2;
const F = (n) => new Float32Array(n);
const bx = F(MAXB), by = F(MAXB), br = F(MAXB), bmax = F(MAXB), brate = F(MAXB), bage = F(MAXB), brot = F(MAXB), bspin = F(MAXB);
const bvx = F(MAXB), bvy = F(MAXB), bu = F(MAXB), bstr = F(MAXB), alive = new Uint8Array(MAXB);
const tPh = F(MAXB * HARM), tAmp = F(MAXB * HARM), prof = F(STEPS);
const LAYER_SCALE = [1, 0.76, 0.52, 0.26], LAYER_ALPHA = [0.4, 0.3, 0.35, 0.5], LAYER_RAG = [1.4, 1, 0.75, 0.5];

let canvas, ctx, w = 0, h = 0, dpr = 1, scale = 1, last = 0, reduced = false, dark = true, wait = 0, mask = null, column = null;
const mouse = { x: -10000, y: -10000, amount: 0 };
const ink = { fill: [], halo: [] };

function rgbOf(hex) { const n = parseInt(hex.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function css(c, a) { return 'rgba(' + (c[0] | 0) + ',' + (c[1] | 0) + ',' + (c[2] | 0) + ',' + (a === undefined ? 1 : a) + ')'; }
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }
function band(x) { const t = Math.min(1, Math.max(0, (Math.abs(x - colX()) / colHalf() - 0.55) / 0.7)); return 1 - t * t * (3 - 2 * t); }

function sprite(c) {
	const s = new OffscreenCanvas(64, 64), g = s.getContext('2d'), gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
	gr.addColorStop(0, css(c, 0.8));
	gr.addColorStop(0.5, css(c, 0.35));
	gr.addColorStop(1, css(c, 0));
	g.fillStyle = gr;
	g.fillRect(0, 0, 64, 64);
	return s;
}

// Ink on a dark page is a glowing dye; on a light page it is darker than the accent, as real ink is
function applyTheme(t) {
	if (t) dark = t.dark !== false;
	const th = FOLLOW_THEME && t && t.colors ? t.colors : null;
	const text = rgbOf(th ? th.text : dark ? '#f2f0f8' : '#1c222b');
	let cs = (th ? [th.accent, th.accent2, th.accent3] : [COLOR_A, COLOR_B, COLOR_C, COLOR_D]).map(rgbOf);
	cs = cs.map((c) => (dark ? (th ? c : mix(c, text, 0.3)) : mix(c, text, th ? 0.15 : 0.1)));
	ink.fill = cs.map((c) => css(c));
	ink.halo = cs.map(sprite);
}

function size() {
	scale = RENDER_SCALE * Math.min(dpr, 1);
	canvas.width = Math.max(1, Math.round(w * scale));
	canvas.height = Math.max(1, Math.round(h * scale));
	ctx.setTransform(scale, 0, 0, scale, 0, 0);
	buildMask();
}

// A horizontal mask that erases ink over the chat column, rebuilt on resize and layout
function buildMask() {
	mask = ctx.createLinearGradient(0, 0, w, 0);
	for (let i = 0; i <= 24; i++) mask.addColorStop(i / 24, 'rgba(0,0,0,' + (CENTER_CALM * band((w * i) / 24)).toFixed(3) + ')');
}

function spawn(x, y, big) {
	for (let i = 0; i < MAXB; i++) {
		if (alive[i]) continue;
		alive[i] = 1;
		bx[i] = x;
		by[i] = y;
		br[i] = 3;
		bmax[i] = BLOOM_SIZE * (0.5 + Math.random() * 0.9) * (big ? 0.8 : 1) * (1 - 0.4 * band(x));
		brate[i] = 30 + Math.random() * 30;
		bage[i] = 0;
		brot[i] = Math.random() * TAU;
		bspin[i] = (Math.random() - 0.5) * 0.06;
		bvx[i] = (Math.random() - 0.5) * 4;
		bvy[i] = (Math.random() - 0.5) * 4;
		bu[i] = Math.random();
		bstr[i] = 0.75 + Math.random() * 0.5;
		for (let k = 0; k < HARM; k++) { tPh[i * HARM + k] = Math.random() * TAU; tAmp[i * HARM + k] = (0.02 + Math.random() * 0.06) * (k < 2 ? 1.4 : 1); }
		return;
	}
}

function spawnSomewhere() {
	if (mouse.amount > 0.3 && Math.random() < CURSOR_BLOOM) {
		spawn(mouse.x + (Math.random() - 0.5) * 220, mouse.y + (Math.random() - 0.5) * 220, false);
		return;
	}
	// Beside the chat column, either side by its room inside the chat area, weighted toward the edges
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const left = Math.max(40, colX() - colHalf() * 0.5 - lo), right = Math.max(40, hi - colX() - colHalf() * 0.5);
	const onLeft = Math.random() * (left + right) < left, e = Math.pow(Math.random(), 1.4) * (onLeft ? left : right);
	spawn(onLeft ? lo + e : hi - e, h * (0.06 + Math.random() * 0.88), false);
}

function drawBloom(i) {
	const p = br[i] / bmax[i];
	const life = (p < 0.1 ? p / 0.1 : p > 0.5 ? 1 - (p - 0.5) / 0.48 : 1) * bstr[i] * INK_STRENGTH;
	if (life <= 0) return;
	const c = Math.min(ink.fill.length - 1, Math.floor(bu[i] * ink.fill.length));
	const base = life * (dark ? 0.3 : 0.3), t = bage[i] * 0.12;
	for (let s = 0; s < STEPS; s++) {
		const a = (s / STEPS) * TAU;
		let v = 1;
		for (let k = 0; k < HARM; k++) v += Math.sin(a * (k + 2) + tPh[i * HARM + k] + t * (k % 2 ? 1 : -1)) * tAmp[i * HARM + k] * TENDRILS;
		prof[s] = v - 1;
	}
	const R = br[i] * 1.25;
	ctx.globalAlpha = base * (dark ? 0.9 : 0.4);
	ctx.drawImage(ink.halo[c], bx[i] - R, by[i] - R, R * 2, R * 2);
	ctx.fillStyle = ink.fill[c];
	ctx.strokeStyle = ink.fill[c];
	for (let l = 0; l < 4; l++) {
		const rad = br[i] * LAYER_SCALE[l], rot = brot[i] + l * 0.9, shift = l * 7, rag = LAYER_RAG[l];
		ctx.beginPath();
		// A smooth closed curve through the midpoints of the profile's points
		let qx = 0, qy = 0;
		for (let s = 0; s <= STEPS + 1; s++) {
			const k = s % STEPS, a = (k / STEPS) * TAU + rot, r = rad * (1 + prof[(k + shift) % STEPS] * rag);
			const px = bx[i] + Math.cos(a) * r, py = by[i] + Math.sin(a) * r;
			if (s === 1) ctx.moveTo((qx + px) / 2, (qy + py) / 2);
			else if (s > 1) ctx.quadraticCurveTo(qx, qy, (qx + px) / 2, (qy + py) / 2);
			qx = px;
			qy = py;
		}
		ctx.globalAlpha = base * LAYER_ALPHA[l];
		ctx.fill();
		if (l === 0 && TIDE_LINE > 0) {
			ctx.globalAlpha = Math.min(1, base * 2 * TIDE_LINE);
			ctx.lineWidth = 1.6;
			ctx.stroke();
		}
	}
}

function frame(now) {
	requestAnimationFrame(frame);
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const g = dt * GROWTH * (reduced ? 0.2 : 1);
	mouse.amount = Math.max(0, mouse.amount - dt * 0.5);
	if (g > 0) {
		wait -= g;
		let n = 0;
		for (let i = 0; i < MAXB; i++) n += alive[i];
		if (wait <= 0 && n < Math.min(MAX_BLOOMS, MAXB)) { spawnSomewhere(); wait = BLOOM_EVERY * (0.6 + Math.random() * 0.8); }
	}
	ctx.globalCompositeOperation = 'source-over';
	ctx.clearRect(0, 0, w, h);
	const stir = reduced ? 0 : mouse.amount;
	for (let i = 0; i < MAXB; i++) {
		if (!alive[i]) continue;
		if (g > 0) {
			br[i] += brate[i] * (1 - br[i] / bmax[i]) * g;
			bage[i] += g;
			brot[i] += bspin[i] * g;
			// A moving cursor stirs the water and nudges the ink away
			const dx = bx[i] - mouse.x, dy = by[i] - mouse.y, d2 = dx * dx + dy * dy, reach = br[i] + 120;
			if (stir > 0 && d2 < reach * reach && d2 > 1) { const d = Math.sqrt(d2); bvx[i] += (dx / d) * stir * 30 * dt; bvy[i] += (dy / d) * stir * 30 * dt; }
			const damp = Math.exp(-dt * 0.8);
			bvx[i] *= damp;
			bvy[i] *= damp;
			bx[i] += bvx[i] * g;
			by[i] += bvy[i] * g;
			if (br[i] >= bmax[i] * 0.98) { alive[i] = 0; continue; }
		}
		drawBloom(i);
	}
	if (CENTER_CALM > 0) {
		ctx.globalCompositeOperation = 'destination-out';
		ctx.globalAlpha = 1;
		ctx.fillStyle = mask;
		ctx.fillRect(0, 0, w, h);
		ctx.globalCompositeOperation = 'source-over';
	}
	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width;
			h = d.height;
			dpr = d.dpr || 1;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			size();
			// Start with a few drops already spreading, at different stages
			for (let k = 0; k < 6; k++) {
				spawnSomewhere();
				const i = k;
				br[i] = bmax[i] * (0.15 + Math.random() * 0.6);
				bage[i] = Math.random() * 10;
			}
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			dpr = d.dpr || 1;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas) buildMask();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.amount = 1;
			break;
		case 'mousedown':
			// A tap lets one drop fall where it landed
			spawn(d.x, d.y, true);
			break;
	}
};

/**
 * Title: Iridescent Liquid Glass (WebGL)
 * Description: Domain-warped veins of thin-film glass in your theme's accents fold slowly at the screen's edges, thin behind the chat, brighten under the cursor and ripple where you tap.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const INTENSITY     = 0.85;  // how strongly the glass shows (0-1)
const FLOW_SPEED    = 0.16;  // how fast the glass churns; 0 holds it still (0-0.6)
const REDUCED_SPEED = 0.15;  // share of the flow kept when the viewer asks to reduce motion (0-1)
const WARP_AMOUNT   = 3.2;   // strength of the domain warp; higher folds more veins (0-6)
const GLASS_SCALE   = 2.8;   // size of the pools and veins; lower is larger (1-5)
const IRIDESCENCE   = 1;     // how far the color shifts across the surface (0-1.5)
const POINTER_LIGHT = 1;     // brightness of the light that follows the cursor (0-2)
const RIPPLE        = 1;     // strength of the ripple a tap sends through the glass (0-2)
const CENTER_CALM   = 0.8;   // how much the glass thins behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const RENDER_SCALE  = 0.5;   // resolution of the glass; it is soft, so half is plenty (0.25-1)
const MAX_FPS       = 30;    // frame cap; the glass flows slowly (15-60)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const COLOR_A       = '#2fd0c8';  // oil-slick teal when not following the theme
const COLOR_B       = '#8a5cf0';  // violet
const COLOR_C       = '#f06aa8';  // rose
/* ──────────────────────────────────────────── */

const MAX_RIPPLES = 6;

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform vec3 u_mouse;',
	'uniform vec3 u_ripples[' + MAX_RIPPLES + '];',
	'uniform vec3 u_c1;',
	'uniform vec3 u_c2;',
	'uniform vec3 u_c3;',
	'uniform float u_dark;',
	'uniform vec2 u_col;',
	'float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }',
	'float noise(vec2 p) {',
	'	vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);',
	'	return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);',
	'}',
	'float fbm(vec2 p) {',
	'	float v = 0.0, a = 0.5;',
	'	for (int i = 0; i < 5; i++) { v += a * noise(p); p = p * 2.02 + vec2(37.1, 11.7); a *= 0.5; }',
	'	return v;',
	'}',
	// Thin film: a smooth loop through the three accents
	'vec3 film(float t) {',
	'	t = fract(t) * 3.0;',
	'	float k = smoothstep(0.0, 1.0, fract(t));',
	'	vec3 c = t < 1.0 ? mix(u_c1, u_c2, k) : (t < 2.0 ? mix(u_c2, u_c3, k) : mix(u_c3, u_c1, k));',
	'	return clamp(mix(vec3(dot(c, vec3(0.299, 0.587, 0.114))), c, 1.45), 0.0, 1.0);',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	vec2 uv = (px - 0.5 * res) / res.y;',
	'	float t = u_time;',
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.55, 1.25, band));',
	'	vec2 disp = vec2(0.0);',
	'	float ringLit = 0.0;',
	'	for (int i = 0; i < ' + MAX_RIPPLES + '; i++) {',
	'		float age = u_ripples[i].z;',
	'		if (age < 0.0) continue;',
	'		vec2 rc = (vec2(u_ripples[i].x, res.y - u_ripples[i].y) - 0.5 * res) / res.y;',
	'		vec2 to = uv - rc;',
	'		float dr = length(to);',
	'		float ring = dr - age * 0.32;',
	'		float env = exp(-age * 0.9) * exp(-ring * ring * 60.0) * smoothstep(0.0, 0.3, age);',
	'		disp += to / (dr + 1e-4) * sin(ring * 40.0) * env * 0.04 * ' + RIPPLE.toFixed(3) + ';',
	'		ringLit += env;',
	'	}',
	'	vec2 p = uv * ' + GLASS_SCALE.toFixed(3) + ' + disp;',
	'	vec2 q = vec2(fbm(p + vec2(0.0, t)), fbm(p + vec2(5.2, -t * 0.8)));',
	'	vec2 r = vec2(fbm(p + ' + WARP_AMOUNT.toFixed(3) + ' * q + vec2(1.7, 9.2) + t * 0.5), fbm(p + ' + WARP_AMOUNT.toFixed(3) + ' * q + vec2(8.3, 2.8) - t * 0.4));',
	'	float f = fbm(p + ' + WARP_AMOUNT.toFixed(3) + ' * r);',
	'	float sheet = 0.35 + 0.65 * smoothstep(0.25, 0.7, f);',
	'	float vein = clamp(exp(-abs(f - 0.50) * 22.0) + 0.7 * exp(-abs(f - 0.63) * 30.0), 0.0, 1.0);',
	'	float depth = f + 0.35 * length(r) - 0.2 * length(q);',
	'	float hue = depth * 2.6 * ' + IRIDESCENCE.toFixed(3) + ' + 0.12 * t;',
	'	vec3 col = film(hue);',
	'	vec3 vcol = film(hue + 0.33);',
	'	float shine = pow(vein, 4.0) * smoothstep(0.5, 1.0, length(r));',
	'	vec2 m = (vec2(u_mouse.x, res.y - u_mouse.y) - 0.5 * res) / res.y;',
	'	float glow = exp(-length(uv - m) * 4.0) * u_mouse.z * ' + POINTER_LIGHT.toFixed(3) + ';',
	'	float edge = 0.5 + 0.5 * smoothstep(0.1, 0.7, length(px / res - 0.5));',
	'	float shape = calm * edge * ' + INTENSITY.toFixed(3) + ';',
	'	float lift = 1.0 + glow * 1.2 + ringLit * 0.8 * ' + RIPPLE.toFixed(3) + ';',
	'	float ba = sheet * mix(0.2, 0.24, u_dark) * shape * min(lift, 1.5);',
	'	float va = vein * mix(0.62, 0.75, u_dark) * shape * min(lift, 1.4);',
	'	float sa = shine * mix(0.0, 0.55, u_dark) * shape * lift;',
	'	vec4 o = vec4(col * mix(0.95, 0.75, u_dark) * ba, ba);',
	'	o = vec4(vcol * mix(0.8, 1.0, u_dark) * va, va) + o * (1.0 - va);',
	'	o = vec4(mix(vcol, vec3(1.0), 0.7) * sa, sa) + o * (1.0 - sa);',
	'	o = clamp(o, 0.0, 1.0);',
	'	gl_FragColor = vec4(min(o.rgb, vec3(o.a)), o.a);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
const loc = {};
let w = 0, h = 0;
let last = 0, time = 0, reduced = false, column = null, rippleHead = 0;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0, sx: -10000, sy: -10000 };
const ripples = new Float32Array(MAX_RIPPLES * 3).fill(-1);
const colors = { c1: hexToRgb(COLOR_A), c2: hexToRgb(COLOR_B), c3: hexToRgb(COLOR_C), dark: 1 };

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function applyTheme(t) {
	if (!t) return;
	colors.dark = t.dark === false ? 0 : 1;
	if (!FOLLOW_THEME || !t.rgb) return;
	colors.c1 = t.rgb.accent3;
	colors.c2 = t.rgb.accent;
	colors.c3 = t.rgb.accent2;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_mouse', 'u_ripples', 'u_c1', 'u_c2', 'u_c3', 'u_dark', 'u_col'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

function size() {
	canvas.width = Math.max(1, Math.round(w * RENDER_SCALE));
	canvas.height = Math.max(1, Math.round(h * RENDER_SCALE));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

// A tap drops one ripple into a fixed ring of six; reduced motion skips them
function addRipple(x, y) {
	if (reduced || RIPPLE <= 0) return;
	ripples[rippleHead * 3] = x;
	ripples[rippleHead * 3 + 1] = y;
	ripples[rippleHead * 3 + 2] = 0;
	rippleHead = (rippleHead + 1) % MAX_RIPPLES;
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	time = (time + dt * FLOW_SPEED * (reduced ? REDUCED_SPEED : 1)) % 1000;
	mouse.target = Math.max(0, mouse.target - dt * 0.5);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 3);
	const ease = Math.min(1, dt * 6);
	mouse.sx += (mouse.x - mouse.sx) * ease;
	mouse.sy += (mouse.y - mouse.sy) * ease;
	for (let i = 0; i < MAX_RIPPLES; i++) {
		const a = i * 3 + 2;
		if (ripples[a] >= 0) ripples[a] = ripples[a] + dt > 5 ? -1 : ripples[a] + dt;
	}
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform3f(loc.u_mouse, mouse.sx, mouse.sy, mouse.amount);
	gl.uniform3fv(loc.u_ripples, ripples);
	gl.uniform3fv(loc.u_c1, colors.c1);
	gl.uniform3fv(loc.u_c2, colors.c2);
	gl.uniform3fv(loc.u_c3, colors.c3);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	const opts = { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' };
	gl = canvas.getContext('webgl2', opts) || canvas.getContext('webgl', opts);
	if (!gl) {
		console.warn('Iridescent Liquid Glass: WebGL is not available, so the glass is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Iridescent Liquid Glass:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Iridescent Liquid Glass:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			time = Math.random() * 100;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			if (mouse.amount < 0.02) { mouse.sx = d.x; mouse.sy = d.y; }
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
		case 'mousedown':
			addRipple(d.x, d.y);
			break;
	}
};

/**
 * Title: Koi Pond (WebGL)
 * Description: A clear pond seen from above, tinted by your theme, where koi glide along its edges under lily pads and caustic light, follow a nearby cursor, scatter from a tap's ripple and now and then kiss the surface.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const FISH_COUNT       = 5;      // number of koi (1-9)
const FISH_SIZE        = 46;     // koi half-length in px, tail not counted (24-90)
const SPEED            = 1;      // pace of the koi and the water; 0 holds the pond still (0-2)
const REDUCED_SPEED    = 0.3;    // share of the pace kept when the viewer asks to reduce motion (0-1)
const CENTER_CALM      = 0.8;    // how much the water, light and koi quiet down behind the chat column (0-1)
const BAND_WIDTH       = 520;    // half-width of the calm band when the page has no chat column, in px (300-900)
const WATER_TINT       = 0.6;    // strength of the water wash over the theme background (0-1)
const CAUSTICS         = 0.6;    // brightness of the dancing light webs (0-1)
const REFRACTION       = 1;      // how much the surface wobbles everything below it (0-2)
const CURIOSITY        = 1;      // how far koi notice and follow the cursor (0-2)
const STARTLE          = 1;      // how hard a tap's ripple scatters nearby koi; 0 turns taps off (0-2)
const KISS_EVERY       = 10;     // average seconds between surface kisses; 0 turns them off (0-60)
const LILY_PADS        = 4;      // lily pads floating in the corners (0-6)
const RENDER_SCALE     = 0.7;    // resolution of the pond; koi edges stay crisp from about 0.6 (0.4-1)
const MAX_FPS          = 30;     // frame cap; koi move slowly (15-60)
const FOLLOW_THEME     = true;   // tint the water from the theme's palette
const KOI_FOLLOW_THEME = false;  // also color the koi patches from the theme's accents
const WATER_DEEP       = '#0b3940';  // deep water when not following the theme
const WATER_SHALLOW    = '#2b8a83';  // shallow water when not following the theme
const KOI_CREAM        = '#f3ebdd';  // koi base color
const KOI_ORANGE       = '#f26a1b';  // koi patch color
/* ──────────────────────────────────────────── */


const N = Math.max(1, Math.min(9, Math.round(FISH_COUNT)));
const P = Math.max(0, Math.min(6, Math.round(LILY_PADS)));
const RN = 6;
const VARIETY = [0, 1, 2, 0, 3, 4, 0, 1, 2]; // orange-cream, kohaku, ogon, sanke, tancho
const PADS = [0.06, 0.15, 0.95, 0.86, 0.93, 0.11, 0.08, 0.9, 0.03, 0.55, 0.97, 0.47];
const n3 = (v) => v.toFixed(3);

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = `#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform vec2 u_res, u_col;
uniform float u_scale, u_time, u_dark;
uniform vec4 u_fa[${N}], u_fb[${N}], u_rip[${RN}], u_pad[${Math.max(1, P)}];
uniform vec3 u_c[9]; // deep, shallow, light, shadow, pad, cream, orange, red, gold
const float FL = ${n3(FISH_SIZE)};
float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
float noise(vec2 p) {
	vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);
	return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 4; i++) { v += a * noise(p); p = mat2(1.6, 1.2, -1.2, 1.6) * p; a *= 0.5; } return v; }
vec2 rot(vec2 p, float a) { return vec2(cos(a) * p.x + sin(a) * p.y, cos(a) * p.y - sin(a) * p.x); }
vec4 over(vec4 d, vec3 c, float a) { a = clamp(a, 0.0, 1.0); return vec4(c * a + d.rgb * (1.0 - a), a + d.a * (1.0 - a)); }
float ell(vec2 p, vec2 c, vec2 r, float a, float e) { return smoothstep(1.0 + e, 1.0 - e, length(rot(p - c, a) / r)); }
float caustic(vec2 uv, float t) {
	vec2 p = mod(uv * 6.2832, 6.2832) - 250.0, i = p; float c = 1.0;
	for (int n = 0; n < 5; n++) {
		float s = t * (1.0 - 3.5 / float(n + 1));
		i = p + vec2(cos(s - i.x) + sin(s + i.y), sin(s - i.y) + cos(s + i.x));
		c += 1.0 / length(p / vec2(sin(i.x + s), cos(i.y + s)) / 200.0);
	}
	return pow(abs(1.17 - pow(c / 5.0, 1.4)), 8.0);
}
// A koi in body units (nose +1, tail tips -1.9): returns the body, fins go to fin
float koi(vec2 p, vec4 a, vec4 b, float e, out vec2 l, out float sh, out float fin) {
	l = rot(p - a.xy, a.z) / FL; sh = 0.0; fin = 0.0;
	if (l.x > 1.2 || l.x < -2.1 || abs(l.y) > 1.0) return 0.0;
	float g = fract(b.w), y = abs(l.y - sin(l.x * 2.6 + a.w) * 0.17 * g * (0.15 + smoothstep(0.7, -1.7, l.x)) - b.z * l.x * l.x * 0.12);
	float u = l.x > 0.25 ? (l.x - 0.25) / 0.8 : (0.25 - l.x) / 1.25, k = sqrt(max(0.0, 1.0 - u * u));
	float bw = l.x > 0.25 ? 0.33 * k : 0.05 + 0.28 * k;
	float body = smoothstep(e, -e, y - bw) * step(u, 1.0);
	sh = clamp(1.0 - y / max(bw, 0.02), 0.0, 1.0);
	float tail = ell(vec2(l.x, y), vec2(-1.4, 0.16), vec2(0.5, 0.17), -0.36 - 0.1 * g, e * 4.0) * (0.45 + 0.55 * smoothstep(-2.0, -1.1, l.x)) * (0.85 + 0.15 * sin(atan(y, l.x + 0.9) * 26.0));
	float pec = ell(vec2(l.x, abs(l.y)), vec2(0.22, 0.36), vec2(0.21, 0.085), -0.55 - 0.3 * sin(a.w * 0.5), e * 4.0);
	fin = max(tail, pec * 0.85) * (1.0 - body);
	return body;
}
float petal(float a, float r) { return r * (0.5 + 0.5 * pow(abs(cos(a * 4.0)), 0.7)); }
float pad(vec2 d, vec4 pd, float e) {
	vec2 q = rot(d, pd.w);
	return smoothstep(pd.z + e, pd.z - e, length(q)) * (q.x > 0.0 ? smoothstep(-e, e, abs(q.y) - q.x * 0.3) : 1.0);
}
void main() {
	vec2 px = vec2(gl_FragCoord.x, u_res.y - gl_FragCoord.y) / u_scale, res = u_res / u_scale;
	float t = u_time, ep = 1.0 / u_scale, dk = u_dark;
	float band = 1.0 - smoothstep(0.45, 1.2, abs(px.x - u_col.x) / u_col.y);
	// Ripples: a travelling wave packet that bends the view and catches the light
	vec2 off = vec2(0.0); float rl = 0.0;
	for (int i = 0; i < ${RN}; i++) {
		vec4 r = u_rip[i];
		if (r.z >= 0.0) {
			vec2 d = px - r.xy; float x = length(d) - r.z * 90.0, wd = 10.0 + r.z * 14.0;
			float env = r.w * exp(-r.z * 1.2 - x * x / (wd * wd)) * smoothstep(0.0, 0.25, r.z);
			off += normalize(d + 0.001) * sin(x * 0.18) * env * 4.0; rl += cos(x * 0.18) * env;
		}
	}
	vec2 q = px + off;
	vec2 wq = q + (vec2(noise(q * 0.011 + t * 0.21), noise(q * 0.011 + 7.3 - t * 0.17)) - 0.5) * ${n3(9 * REFRACTION)};
