}

function start() {
	const opts = { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' };
	gl = canvas.getContext('webgl2', opts) || canvas.getContext('webgl', opts);
	if (!gl) {
		console.warn('Liquid Chrome: WebGL is not available, so the chrome is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Liquid Chrome:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Liquid Chrome:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

/**
 * Title: Living Sky
 * Description: Follows your local time: the sun or a phase-correct moon rides an arc in an outer third over layered mountains, with horizon glow, drifting clouds, night stars and a theme tint.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const PREVIEW_CYCLE  = 0;     // seconds per preview day; 0 follows the clock (0-600)
const THEME_TINT     = 0.35;  // how far the sky leans toward the theme (0-1)
const ARC_X          = 0.84;  // where the sun and moon ride, share of the width; with a chat column, the same side and distance from it (0-1)
const BODY_SIZE      = 22;    // sun and moon radius, in px (10-50)
const CLOUD_AMOUNT   = 1;     // how many clouds drift by (0-2)
const CLOUD_SPEED    = 10;    // cloud drift, in px per second (0-60)
const REDUCED_SPEED  = 0.2;   // drift kept under reduced motion (0-1)
const STAR_DENSITY   = 1;     // night stars, dark themes only (0-2)
const SHOOTING_EVERY = 45;    // average seconds between shooting stars; 0 off (0-300)
const TERRAIN_HEIGHT = 0.17;  // mountain height, share of the screen (0.05-0.2)
const PARALLAX       = 10;    // mountain shift with the cursor, in px (0-40)
const GLOW           = 1;     // horizon and zenith glow (0-2)
const CENTER_CALM    = 0.8;   // how much the sky quiets behind the chat (0-1)
const BAND_WIDTH     = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME   = true;  // lean the palette toward the theme
/* ──────────────────────────────────────────── */

const MAX_STARS = 260, MAX_CLOUDS = 12, PUFFS = 6, TAU = Math.PI * 2;

let canvas, ctx, w = 0, h = 0, last = 0, reduced = false, dark = true, column = null;
let theme = null, hour = 12, clock = 0, refreshAt = 0, elapsed = 0;
let glowCache, glowG, sunSprite, moonSprite, moonHalo, haloSprite, twiSprite, cloudSprite, layers = [], layerG = [];
let starStyle = '', day = 1, twilight = 0, night = 0;
const F = (n) => new Float32Array(n);
const sx = F(MAX_STARS), sy = F(MAX_STARS), sp = F(MAX_STARS), sph = F(MAX_STARS);
const cx = F(MAX_CLOUDS), cy = F(MAX_CLOUDS), cs = F(MAX_CLOUDS), cv = F(MAX_CLOUDS);
const pox = F(MAX_CLOUDS * PUFFS), poy = F(MAX_CLOUDS * PUFFS), pr = F(MAX_CLOUDS * PUFFS);
let stars = 0, clouds = 0;
const shoot = { age: 9, x: 0, y: 0, vx: 0, vy: 120, wait: 20 };
const mouse = { x: 0, amount: 0, off: 0 };

// Atmosphere colors (0-1) for the analytic sky model
const NIGHT_ZEN = [0.015, 0.03, 0.08], NIGHT_HOR = [0.05, 0.06, 0.14];
const DAY_ZEN = [0.2, 0.45, 0.85], DAY_HOR = [0.65, 0.82, 1];
const TWI_ZEN = [0.28, 0.16, 0.38], TWI_HOR = [0.95, 0.45, 0.32];

function hex(c) { const n = parseInt(c.slice(1), 16); return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255]; }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function rgba(c, a) { return 'rgba(' + Math.round(c[0] * 255) + ',' + Math.round(c[1] * 255) + ',' + Math.round(c[2] * 255) + ',' + a.toFixed(3) + ')'; }
function smooth(a, b, x) { const t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); }
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }
function band(x) { return 1 - smooth(0.55, 1.25, Math.abs(x - colX()) / colHalf()); }
// The arc's center: on ARC_X's side of the chat column at a matching distance, mirrored when it would leave the chat area
function arcX() {
	if (!column) return ARC_X * w;
	const lo = column.left, hi = column.right;
	const off = Math.abs(ARC_X - 0.5) / 0.34 * colHalf() * 0.94, s = ARC_X < 0.5 ? -1 : 1, a = colX() + s * off, b = colX() - s * off;
	return a >= lo + 60 && a <= hi - 60 ? a : b >= lo + 60 && b <= hi - 60 ? b : Math.min(hi - 60, Math.max(lo + 60, a));
}
function calm(x) { return 1 - CENTER_CALM * band(x); }
function ridge(v) { const r = 1 - Math.abs(Math.sin(v)); return r * r; }

function sprite(size, col, a0, a1, disc) {
	const c = new OffscreenCanvas(size, size), g = c.getContext('2d'), r = size / 2;
	const grad = g.createRadialGradient(r, r, 0, r, r, r);
	grad.addColorStop(0, rgba(col, a0));
	grad.addColorStop(disc ? 0.86 : 0.35, rgba(col, a1));
	grad.addColorStop(1, rgba(col, 0));
	g.fillStyle = grad;
	g.fillRect(0, 0, size, size);
	return c;
}

function currentHour() {
	if (PREVIEW_CYCLE) return (elapsed / PREVIEW_CYCLE * 24 + 6) % 24;
	const d = new Date();
	return d.getHours() + d.getMinutes() / 60 + d.getSeconds() / 3600;
}

// Moon phase: 0 new, 0.5 full
function moonPhase() {
	return (Date.now() - Date.UTC(2000, 0, 6, 18, 14)) / 86400000 % 29.530588 / 29.530588;
}

// ── Palette: rebuilt as the hour moves on, and on theme or size changes ──
function refresh() {
	const sunH = Math.sin((hour - 6) / 12 * Math.PI);
	day = smooth(-0.12, 0.18, sunH);
	twilight = Math.exp(-Math.pow(sunH * 3.5, 2));
	night = 1 - smooth(-0.2, 0.05, sunH);
	let zen = mix(mix(NIGHT_ZEN, DAY_ZEN, day), TWI_ZEN, twilight * 0.55);
	let hor = mix(mix(NIGHT_HOR, DAY_HOR, day), TWI_HOR, twilight * 0.85);
	let cloud = mix(mix([0.55, 0.58, 0.68], [1, 0.96, 0.92], day), TWI_HOR, twilight * 0.6);
	let sun = mix([1, 0.5, 0.2], [1, 0.88, 0.6], day);
	let ink = dark ? [0.02, 0.02, 0.04] : [0.15, 0.17, 0.2];
	if (FOLLOW_THEME && theme && theme.colors) {
		const c = theme.colors, k = THEME_TINT;
		zen = mix(zen, hex(c.accent3), k);
		hor = mix(hor, hex(c.accent), k * 0.8);
		cloud = mix(cloud, hex(dark ? c.text : c.muted), k);
		sun = mix(sun, hex(c.accent2), k * 0.4);
		ink = mix(hex(c.background), dark ? [0, 0, 0] : hex(c.text), dark ? 0.55 : 0.7);
	}
	const a = dark ? 1 : 0.6;
	sunSprite = sprite(64, dark ? mix(sun, [1, 1, 1], 0.2) : mix(sun, [1, 0.55, 0.15], 0.45), 1, 0.95, true);
	haloSprite = sprite(128, sun, 0.6 * a, 0.16 * a);
	moonHalo = sprite(64, dark ? [0.75, 0.82, 1] : [0.45, 0.5, 0.62], 0.4 * a, 0.1 * a);
	twiSprite = sprite(128, TWI_HOR, 0.55 * a, 0.2 * a);
	cloudSprite = sprite(96, dark ? cloud : mix(hor, ink, 0.3), (dark ? 0.32 : 0.16) * (0.4 + 0.6 * day + 0.4 * twilight), dark ? 0.12 : 0.06);
	starStyle = rgba(mix([1, 1, 1], hor, 0.25), 1);
	buildMoon();

	// Horizon and zenith glow, at quarter size since it is soft
	const gw = glowCache.width, gh = glowCache.height;
	glowG.globalCompositeOperation = 'source-over';
	glowG.clearRect(0, 0, gw, gh);
	const ga = GLOW * (dark ? 0.42 : 0.24);
	const hy = gh * (1 - TERRAIN_HEIGHT * 0.45);
	let grad = glowG.createLinearGradient(0, hy, 0, gh * 0.35);
	grad.addColorStop(0, rgba(hor, Math.min(1, ga)));
	grad.addColorStop(0.3, rgba(hor, Math.min(1, ga * 0.5)));
	grad.addColorStop(1, rgba(hor, 0));
	glowG.fillStyle = grad;
	glowG.fillRect(0, gh * 0.35, gw, gh * 0.65);
	grad = glowG.createLinearGradient(0, 0, 0, gh * 0.28);
	grad.addColorStop(0, rgba(zen, Math.min(1, ga * (0.4 + 0.5 * day))));
	grad.addColorStop(1, rgba(zen, 0));
	glowG.fillStyle = grad;
	glowG.fillRect(0, 0, gw, gh * 0.28);
	glowG.globalCompositeOperation = 'destination-out';
	grad = glowG.createLinearGradient(0, 0, gw, 0);
	const s = gw / Math.max(1, w), mid = colX() * s;
	const inner = colHalf() * 0.55 * s, outer = colHalf() * 1.25 * s;
	const cut = rgba([0, 0, 0], CENTER_CALM * 0.75), none = 'rgba(0,0,0,0)';
	grad.addColorStop(Math.max(0, (mid - outer) / gw), none);
	grad.addColorStop(Math.max(0, (mid - inner) / gw), cut);
	grad.addColorStop(Math.min(1, (mid + inner) / gw), cut);
	grad.addColorStop(Math.min(1, (mid + outer) / gw), none);
	glowG.fillStyle = grad;
	glowG.fillRect(0, 0, gw, gh);

	// Mountains: three ridges, hazier toward the back, lower behind the column
	for (let l = 0; l < 3; l++) {
		const g = layerG[l], lw = layers[l].width;
		g.clearRect(0, 0, lw, h);
		const depth = l / 2;
		g.fillStyle = rgba(mix(hor, ink, dark ? 0.55 + depth * 0.4 : 0.35 + depth * 0.4), 1);
		g.globalAlpha = dark ? 0.7 + depth * 0.3 : 0.22 + depth * 0.2;
		const top = h * TERRAIN_HEIGHT * (1 - depth * 0.45);
		g.beginPath();
		g.moveTo(0, h);
		for (let x = 0; x <= lw; x += 6) {
			const u = x / (230 - l * 50) + l * 7.3;
			const n = ridge(u) * 0.6 + ridge(u * 2.2 + 1.7) * 0.3 + ridge(u * 4.7 + 3) * 0.1;
			const env = 0.55 + 0.45 * Math.sin(x / 410 + l * 2.1);
			const sag = 1 - 0.7 * CENTER_CALM * band(x - PARALLAX * 2);
			g.lineTo(x, h - top * (0.4 + 1.1 * n * env) * sag);
		}
		g.lineTo(lw, h);
		g.closePath();
		g.fill();
	}
}

function buildMoon() {
	const size = 64, r = 26, m = 32;
	moonSprite = new OffscreenCanvas(size, size);
	const g = moonSprite.getContext('2d');
	const lit = dark ? [0.93, 0.93, 0.88] : [0.55, 0.58, 0.65];
	g.fillStyle = rgba(lit, 0.16);
	g.beginPath(); g.arc(m, m, r, 0, TAU); g.fill();
	const p = moonPhase(), off = r * 2 * Math.min(1, Math.abs(p - 0.5) * 2);
	const lc = new OffscreenCanvas(size, size), lg = lc.getContext('2d');
	lg.fillStyle = rgba(lit, 0.95);
	lg.beginPath(); lg.arc(m, m, r, 0, TAU); lg.fill();
	lg.globalCompositeOperation = 'destination-out';
	lg.beginPath(); lg.arc(m + (p < 0.5 ? -1 : 1) * (r * 2 - off), m, r * 1.02, 0, TAU); lg.fill();
	g.drawImage(lc, 0, 0);
}

function size() {
	const px = (v) => Math.max(1, Math.round(v));
	canvas.width = px(w);
	canvas.height = px(h);
	glowCache = new OffscreenCanvas(px(w / 4), px(h / 4));
	glowG = glowCache.getContext('2d');
	for (let l = 0; l < 3; l++) {
		layers[l] = new OffscreenCanvas(px(w + PARALLAX * 4), px(h));
		layerG[l] = layers[l].getContext('2d');
	}
	stars = Math.min(MAX_STARS, Math.round(w * h / 6000 * STAR_DENSITY));
	for (let i = 0; i < stars; i++) {
		sx[i] = Math.random() * w; sy[i] = Math.pow(Math.random(), 1.3) * h * 0.72;
		sp[i] = 0.4 + Math.random() * 1.4; sph[i] = Math.random() * TAU;
	}
	clouds = Math.min(MAX_CLOUDS, Math.round(7 * CLOUD_AMOUNT * Math.max(0.6, w / 1440)));
	for (let i = 0; i < clouds; i++) {
		cx[i] = Math.random() * (w + 600) - 300; cy[i] = h * (0.06 + Math.random() * 0.34);
		cs[i] = 0.6 + Math.random() * 0.8; cv[i] = 0.6 + Math.random() * 0.8;
		for (let j = 0; j < PUFFS; j++) {
			const k = i * PUFFS + j, q = j / (PUFFS - 1), hump = Math.sin(q * Math.PI);
			pox[k] = (q - 0.5) * 180 + (Math.random() - 0.5) * 40;
			poy[k] = (Math.random() - 0.5) * 18 - hump * 14;
			pr[k] = 34 + Math.random() * 26 + hump * 22;
		}
	}
	refresh();
}

function body(f, haloA, halo, hr, disc, dr, discA) {
	const hz = h * (1 - TERRAIN_HEIGHT * 0.55);
	const x = arcX() + (f - 0.5) * 2 * Math.min(w * 0.11, 180);
	const y = hz - Math.sin(Math.min(1, Math.max(0, f)) * Math.PI) * (hz - h * 0.12);
	ctx.globalCompositeOperation = dark ? 'lighter' : 'source-over';
	ctx.globalAlpha = haloA;
	ctx.drawImage(halo, x - hr, y - hr, hr * 2, hr * 2);
	ctx.globalCompositeOperation = 'source-over';
	ctx.globalAlpha = discA;
	ctx.drawImage(disc, x - dr, y - dr, dr * 2, dr * 2);
	return x;
}

function frame(now) {
	requestAnimationFrame(frame);
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	if (!w || !h) return;
	const motion = reduced ? REDUCED_SPEED : 1;
	elapsed += dt * motion;
	clock -= dt;
	if (clock <= 0) {
		const step = PREVIEW_CYCLE ? 0.05 : 1;
		clock = step; hour = currentHour(); refreshAt -= step;
		if (refreshAt <= 0) { refresh(); refreshAt = PREVIEW_CYCLE ? 0.25 : 60; }
	}
	const t = now / 1000;
	ctx.clearRect(0, 0, w, h);
	ctx.globalCompositeOperation = 'source-over';
	ctx.globalAlpha = 1;
	ctx.drawImage(glowCache, 0, 0, w, h);

	const horizon = h * (1 - TERRAIN_HEIGHT * 0.55);

	// Stars, dark themes only, fading with daylight
	if (dark && night > 0.02) {
		ctx.fillStyle = starStyle;
		for (let i = 0; i < stars; i++) {
			const tw = 0.55 + 0.45 * Math.sin(t * sp[i] * (reduced ? 0.3 : 1) + sph[i]);
			ctx.globalAlpha = night * tw * 0.75 * calm(sx[i]) * (1 - sy[i] / h);
			ctx.fillRect(sx[i], sy[i], i % 8 ? 1 : 2, i % 8 ? 1 : 2);
		}
		if (SHOOTING_EVERY > 0 && !reduced) {
			shoot.wait -= dt;
			if (shoot.wait <= 0 && night > 0.6) {
				let side = Math.random() < 0.5 ? -1 : 1;
				if ((side > 0 ? (column ? column.right : w) - colX() : colX() - (column ? column.left : 0)) - colHalf() < 80) side = -side;
				shoot.x = colX() + side * (colHalf() + Math.random() * w * 0.2); shoot.y = h * (0.05 + Math.random() * 0.25);
				shoot.vx = side * (260 + Math.random() * 200); shoot.vy = 120;
				shoot.age = 0; shoot.wait = SHOOTING_EVERY * (0.5 + Math.random());
			}
			if (shoot.age < 0.9) {
				shoot.age += dt;
				shoot.x += shoot.vx * dt; shoot.y += shoot.vy * dt;
				ctx.globalAlpha = Math.sin(Math.PI * shoot.age / 0.9) * 0.7 * night * calm(shoot.x);
				ctx.strokeStyle = starStyle;
				ctx.beginPath(); ctx.moveTo(shoot.x, shoot.y); ctx.lineTo(shoot.x - shoot.vx * 0.12, shoot.y - shoot.vy * 0.12); ctx.stroke();
			}
		}
	}

	// Sun, or the moon at night, on an arc inside the outer third
	const sunF = (hour - 6) / 12, moonF = ((hour < 12 ? hour + 24 : hour) - 18) / 12;
	const sunVis = smooth(-0.04, 0.04, sunF) * smooth(1.04, 0.96, sunF);
	const moonVis = smooth(-0.04, 0.06, moonF) * smooth(1.04, 0.94, moonF) * (1 - day * 0.8);
	if (sunVis > 0) {
		const x = body(sunF, sunVis * (0.6 + 0.4 * twilight), haloSprite, BODY_SIZE * 10, sunSprite, BODY_SIZE, sunVis * (dark ? 0.95 : 0.85));
		ctx.globalCompositeOperation = dark ? 'lighter' : 'source-over';
		ctx.globalAlpha = twilight * sunVis;
		ctx.drawImage(twiSprite, x - w * 0.22, horizon - h * 0.12, w * 0.44, h * 0.24);
		ctx.globalCompositeOperation = 'source-over';
	}
	if (moonVis > 0) body(moonF, moonVis * 0.6, moonHalo, BODY_SIZE * 4.5, moonSprite, BODY_SIZE * 1.1, moonVis);

	// Clouds: sprite puffs, thinner over the column
	const drift = CLOUD_SPEED * motion * dt;
	for (let i = 0; i < clouds; i++) {
		cx[i] += drift * cv[i];
		if (cx[i] > w + 300) { cx[i] = -300; cy[i] = h * (0.06 + Math.random() * 0.34); }
		const s = cs[i];
		for (let j = 0; j < PUFFS; j++) {
			const k = i * PUFFS + j, x = cx[i] + pox[k] * s, r = pr[k] * s;
			ctx.globalAlpha = calm(x);
			ctx.drawImage(cloudSprite, x - r * 1.3, cy[i] + poy[k] * s - r * 0.7, r * 2.6, r * 1.4);
		}
	}

	// Mountains, with a parallax that settles when the cursor stops
	mouse.amount = Math.max(0, mouse.amount - dt * 0.35);
	const target = (mouse.x / Math.max(1, w) - 0.5) * 2 * mouse.amount * (reduced ? 0.3 : 1);
	mouse.off += (target - mouse.off) * Math.min(1, dt * 2);
	ctx.globalAlpha = 1;
	for (let l = 0; l < 3; l++) ctx.drawImage(layers[l], -PARALLAX * 2 - mouse.off * PARALLAX * (0.4 + l * 0.6), 0);
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			theme = d.theme;
			dark = !theme || theme.dark !== false;
			hour = currentHour();
			size();
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width; h = d.height;
			if (canvas) size();
			break;
		case 'theme':
			theme = d;
			dark = d.dark !== false;
			if (glowCache) refresh();
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (glowCache) refresh();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.amount = 1;
			break;
	}
};

/**
 * Title: Matrix Rain
 * Description: Classic digital rain of Latin, katakana or mixed glyphs in your theme's accent, with glowing heads, fading trails, a calm chat column, and faster streams near the cursor.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const CHARSET       = 2;     // glyphs: 0 Latin letters and digits, 1 katakana, 2 mixed (0-2)
const FONT_SIZE     = 16;    // glyph size and column width, in px (10-28)
const SPEED         = 1;     // fall speed; 0 holds the rain still (0-3)
const REDUCED_SPEED = 0.15;  // share of the speed kept when the viewer asks to reduce motion (0-1)
const DENSITY       = 0.8;   // share of columns raining at once (0.1-1)
const TRAIL         = 1;     // trail length (0.3-2)
const BRIGHTNESS    = 0.9;   // overall strength of the glyphs (0.2-1)
const MUTATE        = 1;     // how often trail glyphs flicker to a new symbol (0-3)
const CENTER_CALM   = 0.85;  // how much quieter the rain is behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const CURSOR_BOOST  = 1.5;   // extra speed for columns near the cursor (0-3)
const MIRROR        = true;  // mirror the katakana, as in the film
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const HEAD_COLOR    = '#c8ffd0';  // leading glyph when not following the theme
const TRAIL_COLOR   = '#22e05a';  // trail glyphs
const DIM_COLOR     = '#11803a';  // older trail glyphs
/* ──────────────────────────────────────────── */

const LATIN = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
let KANA = '';
for (let c = 0xff66; c <= 0xff9d; c++) KANA += String.fromCharCode(c);
const GLYPHS = CHARSET === 0 ? LATIN : CHARSET === 1 ? KANA : KANA + '0123456789' + 'ZXCVTHEMRA';
const G = GLYPHS.length;
const MAX_COLS = 400;

let canvas, ctx, atlas;
let w = 0, h = 0, dpr = 1, rows = 0, cols = 0;
let last = 0, reduced = false, dark = true, column = null;
let cw = 1, chh = 1;                  // atlas cell in device px
const mouse = { x: -10000, amount: 0, target: 0 };

const head = new Float32Array(MAX_COLS);   // head position, in rows
const speed = new Float32Array(MAX_COLS);  // rows per second
const len = new Float32Array(MAX_COLS);    // trail length, in rows
const wait = new Float32Array(MAX_COLS);   // seconds before the column rains again
const calmF = new Float32Array(MAX_COLS);  // alpha factor for the chat column
const lastRow = new Int32Array(MAX_COLS);
const glyph = new Uint16Array(MAX_COLS);

let palette = [HEAD_COLOR, TRAIL_COLOR, DIM_COLOR];

function hexToRgb(hex) {
	const n = parseInt(String(hex).slice(1, 7), 16) || 0;
	return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function mixHex(a, b, t) {
	const x = hexToRgb(a), y = hexToRgb(b);
	return 'rgb(' + Math.round(x[0] + (y[0] - x[0]) * t) + ',' + Math.round(x[1] + (y[1] - x[1]) * t) + ',' + Math.round(x[2] + (y[2] - x[2]) * t) + ')';
}

function applyTheme(t) {
	if (!t) return;
	dark = t.dark !== false;
	if (FOLLOW_THEME && t.colors) {
		const c = t.colors;
		palette = dark
			? [mixHex(c.accent, c.text, 0.55), c.accent, mixHex(c.accent, c.muted, 0.5)]
			: [mixHex(c.accent, c.text, 0.45), c.accent, mixHex(c.accent, c.muted, 0.25)];
	}
	buildAtlas();
}

// Every glyph pre-rendered in three tones (glowing head, bright trail, dim trail), so the loop only blits
function buildAtlas() {
	if (!ctx) return;
	cw = Math.ceil(FONT_SIZE * dpr);
	chh = cw; // glow stays inside the cell, so clearing a cell leaves nothing behind
	atlas = atlas || new OffscreenCanvas(1, 1);
	atlas.width = cw * G;
	atlas.height = chh * 3;
	const a = atlas.getContext('2d');
	a.clearRect(0, 0, atlas.width, atlas.height);
	a.font = '600 ' + Math.round(FONT_SIZE * 0.92 * dpr) + 'px monospace';
	a.textAlign = 'center';
	a.textBaseline = 'middle';
	for (let tone = 0; tone < 3; tone++) {
		a.fillStyle = palette[tone];
		a.shadowColor = palette[tone];
		a.shadowBlur = tone === 0 ? FONT_SIZE * 0.45 * dpr : 0;
		for (let i = 0; i < G; i++) {
			const ch = GLYPHS[i];
			const cx = i * cw + cw / 2, cy = tone * chh + chh / 2;
			a.save();
			a.beginPath();
			a.rect(i * cw, tone * chh, cw, chh);
			a.clip();
			const flip = MIRROR && ch.charCodeAt(0) > 0xff00;
			a.translate(cx, cy);
			if (flip) a.scale(-1, 1);
			a.fillText(ch, 0, 0);
			if (tone === 0) { a.shadowBlur = 0; a.fillText(ch, 0, 0); a.shadowBlur = FONT_SIZE * 0.45 * dpr; }
			a.restore();
		}
	}
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function band(x) {
	const d = Math.abs(x - colX()) / colHalf();
	const s = Math.min(1, Math.max(0, (d - 0.55) / 0.7));
	return 1 - s * s * (3 - 2 * s);
}

// Each rain column's alpha factor, rebuilt on resize and layout
function buildCalm() {
	for (let i = 0; i < cols; i++) calmF[i] = 1 - CENTER_CALM * band((i + 0.5) * FONT_SIZE);
}

function restart(i, first) {
	const b = band((i + 0.5) * FONT_SIZE) * CENTER_CALM;
	speed[i] = 8 + Math.random() * 14;
	len[i] = (12 + Math.random() * 26) * TRAIL;
	head[i] = first ? Math.random() * rows * 1.2 - rows * 0.2 : -Math.random() * 4;
	lastRow[i] = Math.floor(head[i]) - 1;
	glyph[i] = (Math.random() * G) | 0;
	// Fewer streams behind the chat: columns there rest longer between runs
	const rest = (1 - DENSITY) / Math.max(0.1, DENSITY) * 4;
	wait[i] = first && Math.random() > b * 0.8 ? 0 : (0.3 + Math.random() * rest) * (1 + b * 6);
}

function size(nw, nh, ndpr) {
	w = nw;
	h = nh;
	dpr = Math.min(2, ndpr || 1);
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	rows = Math.ceil(h / FONT_SIZE);
	cols = Math.min(MAX_COLS, Math.ceil(w / FONT_SIZE));
	buildAtlas();
	// Seed the columns mid-run, trails already drawn, so the rain looks settled at once
	const base = BRIGHTNESS * (dark ? 1 : 0.9);
	buildCalm();
	for (let i = 0; i < cols; i++) {
		restart(i, true);
		if (wait[i] > 0) continue;
		const top = Math.floor(head[i]);
		for (let n = Math.ceil(len[i]); n >= 0; n--) {
			const r = top - n;
			if (r < 0 || r >= rows) continue;
			blit(n === 0 ? 0 : n < 3 ? 1 : 2, (Math.random() * G) | 0, i * FONT_SIZE, r, base * calmF[i] * Math.exp(-2.5 * n / len[i]));
		}
		lastRow[i] = top;
	}
	ctx.globalAlpha = 1;
}

function blit(tone, g, x, row, alpha) {
	ctx.globalAlpha = alpha;
	ctx.drawImage(atlas, g * cw, tone * chh, cw, chh, x, row * FONT_SIZE, FONT_SIZE, FONT_SIZE);
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!ctx || !atlas) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const pace = SPEED * (reduced ? REDUCED_SPEED : 1);
	mouse.target = Math.max(0, mouse.target - dt * 0.6);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 3);
	const base = BRIGHTNESS * (dark ? 1 : 0.9);
	const fs = FONT_SIZE;

	for (let i = 0; i < cols; i++) {
		const x = i * fs;
		if (wait[i] > 0) {
			wait[i] -= dt * (pace > 0 ? 1 : 0);
			continue;
		}
		const dx = Math.abs(x + fs * 0.5 - mouse.x);
		const boost = reduced ? 1 : 1 + CURSOR_BOOST * mouse.amount * Math.max(0, 1 - dx / 200);
		const v = speed[i] * pace * boost;
		head[i] += v * dt;
		const a = base * calmF[i];

		// Fade this column's strip toward transparency, timed so the trail lasts about `len` rows
		const k = speed[i] / len[i] * 2.5;
		ctx.globalCompositeOperation = 'destination-out';
		ctx.globalAlpha = 1 - Math.exp(-k * pace * boost * dt);
		ctx.fillRect(x, 0, fs, h);
		ctx.globalCompositeOperation = 'source-over';

		const row = Math.floor(head[i]);
		while (lastRow[i] < row) {
			const prev = lastRow[i];
			lastRow[i] = prev + 1;
			// Old head becomes a bright trail glyph; a fresh head glows one row down
			if (prev >= 0 && prev < rows) {
				ctx.clearRect(x, prev * fs, fs, fs);
				blit(1, glyph[i], x, prev, a);
			}
			glyph[i] = (Math.random() * G) | 0;
			const r = prev + 1;
			if (r >= 0 && r < rows) {
				ctx.clearRect(x, r * fs, fs, fs);
				blit(0, glyph[i], x, r, Math.min(1, a * 1.25));
			}
			// Wipe the cell the trail has left, so no faint residue builds up over hours
			const tail = r - Math.ceil(len[i]) - 1;
			if (tail >= 0 && tail < rows) ctx.clearRect(x, tail * fs, fs, fs);
		}

		// Flicker: a glyph in the trail changes, drawn at the brightness the fade has left it
		if (MUTATE > 0 && !reduced && Math.random() < MUTATE * dt * 4) {
			const back = 2 + ((Math.random() * (len[i] - 2)) | 0);
			const r = row - back;
			if (r >= 0 && r < rows) {
				ctx.clearRect(x, r * fs, fs, fs);
				blit(2, (Math.random() * G) | 0, x, r, a * 0.9 * Math.exp(-k * back / speed[i]));
			}
		}

		if (row - len[i] - 2 > rows) restart(i, false);
	}
	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			reduced = !!d.reducedMotion;
			column = d.column || null;
			if (d.theme) applyTheme(d.theme);
			size(d.width, d.height, d.dpr);
			requestAnimationFrame(frame);
			break;
		case 'resize':
			if (ctx) size(d.width, d.height, d.dpr);
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			buildCalm();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.target = 1;
			break;
		case 'mousedown': {
			// A tap starts a resting stream nearby from the tapped row
			if (reduced) break;
			const c = Math.floor(d.x / FONT_SIZE);
			for (let o = 0; o < 5; o++) {
				const i = c + (o & 1 ? -1 : 1) * ((o + 1) >> 1);
				if (i < 0 || i >= cols || wait[i] <= 0) continue;
				restart(i, false);
				head[i] = Math.floor(d.y / FONT_SIZE);
				lastRow[i] = head[i] - 1;
				wait[i] = 0;
				break;
			}
			break;
		}
	}
};

/**
 * Title: Molten Forge (WebGL)
 * Description: Domain-warped lava rivers glow through cracked crust along the screen's sides and floor with rising embers, cooling to faint cracks behind the chat while the cursor stokes the heat and leans the flow.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const FLOW_SPEED    = 1;     // how fast the lava churns; 0 holds it still (0-3)
const REDUCED_SPEED = 0.15;  // share of the flow kept when the viewer asks to reduce motion (0-1)
const NOISE_SCALE   = 2.4;   // lava structure frequency; higher is finer (1-5)
const HEAT          = 1;     // how brightly the lava glows (0-2)
const FORGE_HEIGHT  = 0.3;   // how far the hot floor reaches up the screen, as a share (0-0.6)
const EMBER_AMOUNT  = 1;     // brightness of the rising embers; 0 turns them off (0-2)
const SHIMMER       = 1;     // heat-haze distortion strength (0-2)
const CURSOR_HEAT   = 1;     // how much the cursor stokes and steers the lava (0-2)
const CENTER_CALM   = 0.85;  // how much the lava cools behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const RENDER_SCALE  = 0.5;   // resolution of the lava; it is soft, so half is plenty (0.25-1)
const MAX_FPS       = 30;    // frame cap; lava moves slowly (15-60)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const COLOR_DEEP    = '#7a1600';  // cooling lava when not following the theme
const COLOR_HOT     = '#ff7a0a';  // running lava and cracks
const COLOR_CORE    = '#ffd890';  // white-hot core and embers
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform float u_drift;',
	'uniform vec3 u_mouse;',
	'uniform vec3 u_deep;',
	'uniform vec3 u_hot;',
	'uniform vec3 u_core;',
	'uniform vec3 u_rock;',
	'uniform float u_dark;',
	'uniform vec2 u_col;',
	'float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }',
	'vec2 hash2(vec2 p) { return vec2(hash(p), hash(p + 17.31)); }',
	'float noise(vec2 p) {',
	'	vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);',
	'	return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);',
	'}',
	'float fbm(vec2 p) {',
	'	float v = 0.0, a = 0.5;',
	'	mat2 m = mat2(1.6, 1.2, -1.2, 1.6);',
	'	for (int i = 0; i < 5; i++) { v += a * noise(p); p = m * p; a *= 0.5; }',
	'	return v;',
	'}',
	// Two layers of embers rising through cells, each lit cell holding one spark
	'float embers(vec2 p, float t) {',
	'	float acc = 0.0;',
	'	for (int i = 0; i < 2; i++) {',
	'		float fi = float(i);',
	'		vec2 ep = vec2(p.x * (14.0 + fi * 8.0) + sin(t * 0.4 + fi * 2.0 + p.y * 3.0) * 0.4, p.y * 9.0 - t * (0.9 + fi * 0.5));',
	'		vec2 id = floor(ep), f = fract(ep);',
	'		float d = length(f - (0.2 + 0.6 * hash2(id)));',
	'		float tw = 0.6 + 0.4 * sin(t * 1.6 + hash(id) * 40.0);',
	'		acc += smoothstep(0.11, 0.0, d) * tw * step(0.82, hash(id + 2.7)) * (1.2 - fi * 0.4);',
	'	}',
	'	return acc;',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	vec2 p0 = px / res.y;',
	'	float t = u_time;',
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.55, 1.25, band));',
	'	float side = smoothstep(0.75, 1.6, band);',
	'	float floorHeat = 1.0 - smoothstep(0.0, ' + Math.max(0.05, FORGE_HEIGHT).toFixed(3) + ', px.y / res.y);',
	'	vec2 m = vec2(u_mouse.x, res.y - u_mouse.y);',
	'	float stoke = exp(-length(px - m) / 200.0) * u_mouse.z * ' + CURSOR_HEAT.toFixed(3) + ';',
	'	float mask = clamp(max(side, floorHeat * 0.9) + stoke * 0.7, 0.0, 1.0);',
	'	vec2 p = p0 + (vec2(noise(p0 * 24.0 + t * 2.2), noise(p0 * 24.0 + 9.1 + t * 2.0)) - 0.5) * 0.006 * ' + SHIMMER.toFixed(3) + ' * (0.3 + mask);',
	'	float K = ' + NOISE_SCALE.toFixed(3) + ';',
	'	float q1 = fbm(p * K * 1.15 + vec2(u_drift, -t * 0.02));',
	'	float q2 = fbm(p * K * 1.15 + vec2(4.4, 1.3) - vec2(u_drift * 0.6, 0.0));',
	'	float hgt = fbm(p * K + 2.3 * vec2(q1, q2));',
	'	float channel = 1.0 - smoothstep(0.0, mix(0.018, 0.06, mask), abs(hgt - 0.47 + 0.03 * q1));',
	'	float lake = mix(0.10, 0.30, mask);',
	'	float skin = smoothstep(0.25, 0.75, noise(p * 9.0 + vec2(q1, q2) * 3.0 + t * 0.05));',
	'	float pool = (1.0 - smoothstep(lake - 0.07, lake, hgt)) * mix(0.35, 1.0, skin);',
	'	float heat = max(channel * mix(0.45, 1.0, mask), pool * mask);',
	'	float pulse = 0.85 + 0.15 * sin(t * 0.9 + q1 * 6.0);',
	'	float ridged = 1.0 - abs(2.0 * noise(p * 7.0 + vec2(q2, q1) * 2.0) - 1.0);',
	'	float cracks = pow(ridged, 9.0) * (1.0 - heat) * mix(0.08, 1.0, mask);',
	'	float hm = ' + HEAT.toFixed(3) + ' * (1.0 + stoke * 0.5) * mix(0.8, 1.0, u_dark);',
	'	vec3 lava = mix(mix(u_deep, u_hot, pow(heat, 1.4)), u_core, pow(heat, 6.0) * pulse * 0.55 * u_dark);',
	'	float la = smoothstep(0.0, 0.6, heat) * mix(0.18, 1.0, mask) * calm * min(1.0, hm * pulse) * mix(0.7, 0.92, u_dark);',
	'	float ra = (1.0 - heat) * mask * calm * (0.55 + 0.5 * noise(p * 11.0)) * mix(0.10, 0.30, u_dark);',
	'	float ca = cracks * calm * min(1.0, 0.9 * hm * pulse) * mix(0.7, 1.0, u_dark);',
	'	float ga = heat * mask * calm * 0.25 * hm;',
	'	float ea = embers(p0, t) * max(side, floorHeat * 0.6) * calm * calm * ' + EMBER_AMOUNT.toFixed(3) + ' * smoothstep(1.0, 0.7, px.y / res.y) * mix(0.7, 1.0, u_dark);',
	'	vec4 o = vec4(u_rock * ra, ra);',
	'	o = vec4(u_hot * ga, ga) + o * (1.0 - ga);',
	'	o = vec4(min(lava, vec3(1.0)) * la, la) + o * (1.0 - la);',
	'	o = vec4(u_hot * ca, ca) + o * (1.0 - ca);',
	'	o = vec4(mix(u_hot, u_core, 0.6) * ea, ea) + o * (1.0 - ea);',
	'	o = clamp(o, 0.0, 1.0);',
	'	gl_FragColor = vec4(min(o.rgb, vec3(o.a)), o.a);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
const loc = {};
let w = 0, h = 0;
let last = 0, time = 0, drift = 0, reduced = false, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0, sx: -10000, sy: -10000, lean: 0 };
const colors = { deep: hexToRgb(COLOR_DEEP), hot: hexToRgb(COLOR_HOT), core: hexToRgb(COLOR_CORE), rock: [0, 0, 0], dark: 1 };

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function mix3(a, b, k) { return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]; }

// Running lava takes accent, cooling lava accent2, the core leans toward white on dark themes
function applyTheme(t) {
	if (t) colors.dark = t.dark === false ? 0 : 1;
	const dark = colors.dark === 1;
	if (!FOLLOW_THEME || !t || !t.rgb) {
		colors.deep = hexToRgb(COLOR_DEEP);
		colors.hot = dark ? hexToRgb(COLOR_HOT) : mix3(hexToRgb(COLOR_HOT), hexToRgb(COLOR_DEEP), 0.25);
		colors.core = hexToRgb(COLOR_CORE);
		colors.rock = dark ? [0, 0, 0] : [0.35, 0.3, 0.28];
		return;
	}
	colors.deep = dark ? mix3(t.rgb.accent2, [0, 0, 0], 0.4) : t.rgb.accent2;
	colors.hot = t.rgb.accent;
	colors.core = dark ? mix3(t.rgb.accent, [1, 1, 1], 0.6) : t.rgb.accent3;
	colors.rock = dark ? mix3(t.rgb.background, [0, 0, 0], 0.7) : t.rgb.muted;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_drift', 'u_mouse', 'u_deep', 'u_hot', 'u_core', 'u_rock', 'u_dark', 'u_col'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

function size() {
	canvas.width = Math.max(1, Math.round(w * RENDER_SCALE));
	canvas.height = Math.max(1, Math.round(h * RENDER_SCALE));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const k = dt * FLOW_SPEED * (reduced ? REDUCED_SPEED : 1);
	time = (time + k) % 2000;
	// The cursor leans the flow toward its side of the screen, easing back once it rests
	mouse.target = Math.max(0, mouse.target - dt * 0.4);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 2);
	const want = w ? (mouse.x / w - 0.5) * 2 * mouse.amount * CURSOR_HEAT : 0;
	mouse.lean += (want - mouse.lean) * Math.min(1, dt * 0.8);
	drift = (drift + k * (0.02 + mouse.lean * 0.06)) % 1000;
	const ease = Math.min(1, dt * 4);
	mouse.sx += (mouse.x - mouse.sx) * ease;
	mouse.sy += (mouse.y - mouse.sy) * ease;
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform1f(loc.u_drift, drift);
	gl.uniform3f(loc.u_mouse, mouse.sx, mouse.sy, mouse.amount);
	gl.uniform3fv(loc.u_deep, colors.deep);
	gl.uniform3fv(loc.u_hot, colors.hot);
	gl.uniform3fv(loc.u_core, colors.core);
	gl.uniform3fv(loc.u_rock, colors.rock);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	const opts = { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' };
	gl = canvas.getContext('webgl2', opts) || canvas.getContext('webgl', opts);
	if (!gl) {
		console.warn('Molten Forge: WebGL is not available, so the lava is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Molten Forge:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Molten Forge:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			time = Math.random() * 200;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			if (mouse.amount < 0.02) { mouse.sx = d.x; mouse.sy = d.y; }
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

/**
 * Title: Aether Nebula (WebGL)
 * Description: Domain-warped nebula gas in your theme's accent colors that gathers at the screen's edges, thins behind the chat, parts around the cursor and now and then blooms.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const INTENSITY     = 0.85;  // how strongly the gas shows (0-1)
const MOTION        = 1;     // drift speed; 0 holds the nebula still and stops blooms (0-2)
const REDUCED_SPEED = 0.15;  // share of the drift kept when the viewer asks to reduce motion (0-1)
const CENTER_CALM   = 0.75;  // how much the gas thins behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const GAS_SCALE     = 1.6;   // size of the cloud structures; lower is larger (0.6-4)
const WARP          = 3;     // how swirled the gas is (0-6)
const STAR_DENSITY  = 0.5;   // faint stars behind the gas, dark themes only (0-1)
const CURSOR_PUSH   = 1;     // how far the gas parts around the cursor (0-3)
const BLOOM_EVERY   = 70;    // average seconds between stellar blooms; 0 turns them off (0-300)
const RENDER_SCALE  = 0.5;   // resolution of the gas; it is soft, so half is plenty (0.25-1)
const MAX_FPS       = 30;    // frame cap; the gas moves slowly (15-60)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const COLOR_A       = '#6f8cff';  // gas color when not following the theme
const COLOR_B       = '#a46cf0';  // second gas color
const COLOR_C       = '#4fd2e6';  // highlight and bloom color
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform vec3 u_mouse;',
	'uniform vec3 u_c1;',
	'uniform vec3 u_c2;',
	'uniform vec3 u_c3;',
	'uniform float u_dark;',
	'uniform vec4 u_bloom;',
	'uniform vec2 u_col;',
	'float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }',
	'float noise(vec2 p) {',
	'	vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);',
	'	return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);',
	'}',
	'float fbm(vec2 p) {',
	'	float v = 0.0, a = 0.5;',
	'	mat2 m = mat2(1.6, 1.2, -1.2, 1.6);',
	'	for (int i = 0; i < 5; i++) { v += a * noise(p); p = m * p; a *= 0.5; }',
	'	return v;',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	float t = u_time;',
	'	vec2 m = vec2(u_mouse.x, res.y - u_mouse.y);',
	'	vec2 dm = px - m;',
	'	float md = length(dm);',
	'	vec2 push = u_mouse.z * ' + CURSOR_PUSH.toFixed(3) + ' * dm / (md + 1.0) * exp(-md / 240.0) * 0.08;',
	'	vec2 p = px / res.y * ' + GAS_SCALE.toFixed(3) + ' + push;',
	'	vec2 q = vec2(fbm(p + vec2(0.0, t * 0.012)), fbm(p + vec2(5.2, 1.3) - t * 0.010));',
	'	vec2 r = vec2(fbm(p + ' + WARP.toFixed(3) + ' * q + vec2(1.7, 9.2) + t * 0.015), fbm(p + ' + WARP.toFixed(3) + ' * q + vec2(8.3, 2.8) - t * 0.013));',
	'	float f = fbm(p + ' + WARP.toFixed(3) + ' * r);',
	'	float dens = smoothstep(0.38, 0.95, f) * 0.85 + smoothstep(0.62, 0.95, length(r)) * 0.3;',
	'	vec3 col = mix(u_c1, u_c2, clamp(q.x * 1.4 - 0.2, 0.0, 1.0));',
	'	col = mix(col, u_c3, clamp(r.y * r.y * 1.4, 0.0, 1.0));',
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.55, 1.25, band));',
	'	float edge = 0.7 + 0.3 * smoothstep(0.1, 0.75, length(px / res - 0.5));',
	'	float a = dens * calm * edge * ' + INTENSITY.toFixed(3) + ' * mix(0.65, 0.9, u_dark);',
	'	vec2 cell = floor(px / 90.0);',
	'	vec2 sp = (cell + vec2(hash(cell), hash(cell + 7.1))) * 90.0;',
	'	float lit = step(1.0 - ' + STAR_DENSITY.toFixed(3) + ' * 0.55, hash(cell + 3.3));',
	'	float tw = 0.55 + 0.45 * sin(t * (0.6 + hash(cell + 1.9) * 1.6) + hash(cell) * 6.283);',
	'	float s = lit * tw * smoothstep(2.4, 0.0, length(px - sp)) * u_dark * mix(0.35, 1.0, calm) * 0.8;',
	'	vec2 b = vec2(u_bloom.x, res.y - u_bloom.y);',
	'	float life = u_bloom.z;',
	'	float env = smoothstep(0.0, 2.5, life) * (1.0 - smoothstep(3.5, 10.0, life));',
	'	float ba = u_bloom.w * env * exp(-length(px - b) / 170.0) * (0.35 + 0.65 * smoothstep(0.3, 0.8, f));',
	'	vec3 bloomCol = mix(u_c3, vec3(1.0), 0.35 * u_dark);',
	'	vec3 starCol = mix(vec3(1.0), u_c1, 0.3);',
	'	float outA = clamp(a + s + ba * 0.8, 0.0, 1.0);',
	'	gl_FragColor = vec4(min(col * a + starCol * s + bloomCol * ba * 0.8, vec3(outA)), outA);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
let loc = {};
let w = 0, h = 0;
let last = 0, time = 0, reduced = false, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };
const bloom = { x: 0, y: 0, age: 1000, strength: 0, wait: BLOOM_EVERY * 0.5 };
const colors = { c1: hexToRgb(COLOR_A), c2: hexToRgb(COLOR_B), c3: hexToRgb(COLOR_C), dark: 1 };

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function applyTheme(t) {
	if (!t) return;
	colors.dark = t.dark === false ? 0 : 1;
	if (!FOLLOW_THEME || !t.rgb) return;
	colors.c1 = t.rgb.accent;
	colors.c2 = t.rgb.accent2;
	colors.c3 = t.rgb.accent3;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_mouse', 'u_c1', 'u_c2', 'u_c3', 'u_dark', 'u_bloom', 'u_col'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

function size() {
	canvas.width = Math.max(1, Math.round(w * RENDER_SCALE));
	canvas.height = Math.max(1, Math.round(h * RENDER_SCALE));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

// ── Blooms: a slow swell of light beside the chat column, never over it ──
function updateBloom(dt) {
	bloom.age += dt;
	if (BLOOM_EVERY <= 0 || MOTION <= 0 || reduced || bloom.age < 10) return;
	bloom.wait -= dt;
	if (bloom.wait > 0) return;
	// The margins beside the column, inside the chat area so the sidebar can't cover a bloom
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const left = Math.max(0, colX() - colHalf() - lo), right = Math.max(0, hi - colX() - colHalf());
	if (left + right < 80) return;
	const r = Math.random() * (left + right);
	bloom.x = r < left ? lo + r * 0.85 : hi - (r - left) * 0.85;
	bloom.y = h * (0.15 + Math.random() * 0.7);
	bloom.strength = 0.5 + Math.random() * 0.5;
	bloom.age = 0;
	bloom.wait = BLOOM_EVERY * (0.6 + Math.random() * 0.8);
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	time = (time + dt * MOTION * (reduced ? REDUCED_SPEED : 1)) % 3000;
	mouse.target = Math.max(0, mouse.target - dt * 0.4);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 3);
	updateBloom(dt);
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform3f(loc.u_mouse, mouse.x, mouse.y, mouse.amount);
	gl.uniform3fv(loc.u_c1, colors.c1);
	gl.uniform3fv(loc.u_c2, colors.c2);
	gl.uniform3fv(loc.u_c3, colors.c3);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform4f(loc.u_bloom, bloom.x, bloom.y, bloom.age, bloom.strength);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	gl = canvas.getContext('webgl2', { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' })
		|| canvas.getContext('webgl', { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' });
	if (!gl) {
		console.warn('Aether Nebula: WebGL is not available, so the nebula is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Aether Nebula:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Aether Nebula:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

/**
 * Title: Neural Network
 * Description: Layers of drifting nodes linked by faint connections, with pulses of light that travel between them and set off cascades, sent by the cursor and by a tap.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const LAYERS        = 6;     // layers of nodes across the screen (3-9)
const NODE_RADIUS   = 4;     // size of a node, in px (2-8)
const LINK_ALPHA    = 0.26;  // visibility of the connections (0.05-0.5)
const MAX_PULSES    = 80;    // pulses in flight at once (10-150)
const PULSE_SPEED   = 0.9;   // how fast pulses travel, in connections per second (0.2-3)
const FIRE_EVERY    = 0.6;   // average seconds between spontaneous firings; 0 turns them off (0-10)
const CASCADE       = 0.35;  // chance an arriving pulse fires onward along each link (0-0.8)
const DRIFT         = 18;    // how far nodes wander from their place, in px (0-60)
const MOTION        = 1;     // overall speed (0.2-2)
const REDUCED_SPEED = 0.3;   // share of the speed kept when the viewer asks to reduce motion (0-1)
const CURSOR_REACH  = 200;   // how near the cursor must come to wake a node, in px (60-400)
const CENTER_CALM   = 0.8;   // how much the network fades behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const LINK_COLOR    = '#64a0ff';  // connection color when not following the theme
const NODE_COLOR    = '#78b4ff';  // node and pulse color
const GLOW_COLOR    = '#64b4ff';  // halo around energized nodes
const CORE_COLOR    = '#c8e6ff';  // bright center of energized nodes
/* ──────────────────────────────────────────── */

const MAX_NODES = 90, MAX_LINKS = 300;

let canvas, ctx;
let w = 0, h = 0, dpr = 1;
let last = 0, reduced = false, dark = true, fireWait = 1, wakeWait = 0, column = null;
let nodeCount = 0, linkCount = 0, firstOfLast = 0, inputs = 1;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };
const col = { link: LINK_COLOR, node: NODE_COLOR, glow: GLOW_COLOR, core: CORE_COLOR };
let pulseSprite = null, haloSprite = null;
// Nodes: position, home, wander target, phase, energy, calm
const nx = new Float32Array(MAX_NODES), ny = new Float32Array(MAX_NODES);
const hx = new Float32Array(MAX_NODES), hy = new Float32Array(MAX_NODES);
const gx = new Float32Array(MAX_NODES), gy = new Float32Array(MAX_NODES);
const wait = new Float32Array(MAX_NODES), energy = new Float32Array(MAX_NODES), ncalm = new Float32Array(MAX_NODES);
// Links: from, to, weight; outgoing links of a node are contiguous (start index and count)
const lf = new Int16Array(MAX_LINKS), lt = new Int16Array(MAX_LINKS), lw = new Float32Array(MAX_LINKS), lc = new Float32Array(MAX_LINKS);
const outStart = new Int16Array(MAX_NODES), outCount = new Uint8Array(MAX_NODES);
// Pulses: link, progress 0-1, speed, brightness
const pl = new Int16Array(MAX_PULSES).fill(-1), pp = new Float32Array(MAX_PULSES);
const ps = new Float32Array(MAX_PULSES), pb = new Float32Array(MAX_PULSES);

// A soft round glow in one color: the color filled, then masked by a radial falloff
function sprite(color, r) {
	const c = new OffscreenCanvas(r * 2, r * 2), g = c.getContext('2d');
	g.fillStyle = color;
	g.fillRect(0, 0, r * 2, r * 2);
	const grad = g.createRadialGradient(r, r, 0, r, r, r);
	grad.addColorStop(0, 'rgba(255,255,255,1)');
	grad.addColorStop(0.2, 'rgba(255,255,255,0.8)');
	grad.addColorStop(0.5, 'rgba(255,255,255,0.2)');
	grad.addColorStop(1, 'rgba(255,255,255,0)');
	g.globalCompositeOperation = 'destination-in';
	g.fillStyle = grad;
	g.fillRect(0, 0, r * 2, r * 2);
	return c;
}

// Links take the muted color, nodes and pulses the accent, halos accent2, cores the text color
function applyTheme(t) {
	if (t) {
		dark = t.dark !== false;
		if (FOLLOW_THEME && t.colors) {
			col.link = t.colors.muted;
			col.node = t.colors.accent;
			col.glow = t.colors.accent2;
			col.core = dark ? t.colors.text : t.colors.accent3;
		}
	}
	pulseSprite = sprite(col.node, 12);
	haloSprite = sprite(col.glow, 16);
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function band(x) {
	const b = Math.abs(x - colX()) / colHalf();
	const s = Math.min(1, Math.max(0, (b - 0.55) / 0.7));
	return 1 - CENTER_CALM * (1 - s * s * (3 - 2 * s));
}

function build() {
	nodeCount = linkCount = 0;
	pl.fill(-1);
	const layers = Math.max(2, Math.min(9, LAYERS));
	let prevStart = 0, prevCount = 0;
	// Free space left and right of the calm band inside the chat area, each at least an eighth of the screen wide (reaching into the band's fade when short)
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const m = w * 0.05, room = Math.max(80, w * 0.125), l0 = lo + m, l1 = Math.max(l0 + room, colX() - colHalf()), r1 = hi - m, r0 = Math.min(r1 - room, colX() + colHalf());
	for (let l = 0; l < layers; l++) {
		const edge = l === 0 || l === layers - 1;
		const count = Math.min(MAX_NODES - nodeCount, edge ? 3 + Math.floor(Math.random() * 3) : 5 + Math.floor(Math.random() * 5));
		const start = nodeCount;
		// Layers gather on either side of the chat column; long faint links bridge it from a middle layer
		const u = l / (layers - 1);
		const x = u < 0.5 ? l0 + (l1 - l0) * u * 1.7 : u > 0.5 ? r1 - (r1 - r0) * (1 - u) * 1.7 : colX();
		for (let n = 0; n < count; n++) {
			const i = nodeCount++;
			hx[i] = gx[i] = nx[i] = x + (Math.random() - 0.5) * 30;
			hy[i] = gy[i] = ny[i] = (h / (count + 1)) * (n + 1) + (Math.random() - 0.5) * 20;
			wait[i] = Math.random() * 10;
			energy[i] = 0;
			ncalm[i] = band(x);
		}
		// Sparse wiring from the previous layer: one to three links per node, to its neighbours across
		for (let p = prevStart; p < prevStart + prevCount && l > 0; p++) {
			outStart[p] = linkCount;
			const links = 1 + Math.floor(Math.random() * Math.min(3, count));
			const across = ((p - prevStart) / Math.max(1, prevCount - 1)) * (count - 1);
			const first = Math.round(across - (links - 1) / 2 + (Math.random() - 0.5) * 1.5);
			for (let k = 0; k < links && linkCount < MAX_LINKS; k++) {
				lf[linkCount] = p;
				lt[linkCount] = start + Math.min(count - 1, Math.max(0, first + k));
				lw[linkCount] = 0.3 + Math.random() * 0.7;
				lc[linkCount] = Math.min(ncalm[p], ncalm[lt[linkCount]], band((hx[p] + hx[lt[linkCount]]) / 2));
				linkCount++;
			}
			outCount[p] = linkCount - outStart[p];
		}
		if (l === 0) inputs = count;
		prevStart = start;
		prevCount = count;
	}
	firstOfLast = prevStart;
	for (let p = prevStart; p < nodeCount; p++) outCount[p] = 0;
}

function resize(width, height, ratio) {
	w = width;
	h = height;
	dpr = Math.min(ratio || 1, 2);
	if (!canvas) return;
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	build();
}

function fire(node, brightness, chance) {
	energy[node] = Math.min(1, energy[node] + 0.4 * brightness);
	for (let k = outStart[node], end = k + outCount[node]; k < end; k++) {
		if (Math.random() >= chance) continue;
		for (let p = 0; p < MAX_PULSES; p++) {
			if (pl[p] >= 0) continue;
			pl[p] = k; pp[p] = 0; ps[p] = PULSE_SPEED * (0.7 + Math.random() * 0.6); pb[p] = brightness;
			break;
		}
	}
}

function nearest(x, y, reach) {
	let best = -1, bestD = reach * reach;
	for (let i = 0; i < nodeCount; i++) {
		const dx = nx[i] - x, dy = ny[i] - y, d = dx * dx + dy * dy;
		if (d < bestD) { bestD = d; best = i; }
	}
	return best;
}

function update(dt) {
	const speed = dt * MOTION * (reduced ? REDUCED_SPEED : 1);
	const ease = 1 - Math.exp(-speed * 0.6);
	for (let i = 0; i < nodeCount; i++) {
		// Each node picks a new spot near home now and then, so the network slowly reorganizes
		wait[i] -= speed;
		if (wait[i] <= 0) {
			wait[i] = 6 + Math.random() * 10;
			gx[i] = hx[i] + (Math.random() - 0.5) * 2 * DRIFT;
			gy[i] = hy[i] + (Math.random() - 0.5) * 2 * DRIFT;
		}
		nx[i] += (gx[i] - nx[i]) * ease;
		ny[i] += (gy[i] - ny[i]) * ease;
		energy[i] *= Math.exp(-dt * 1.8);
	}
	if (FIRE_EVERY > 0) {
		fireWait -= speed;
		if (fireWait <= 0) {
			fireWait = FIRE_EVERY * (0.5 + Math.random());
			fire(Math.floor(Math.random() * inputs), 0.6 + Math.random() * 0.4, 0.5);
		}
	}
	// A moving cursor wakes the nearest node; a resting one does not
	wakeWait -= dt;
	if (mouse.amount > 0.4 && wakeWait <= 0) {
		wakeWait = 0.35;
		const n = nearest(mouse.x, mouse.y, CURSOR_REACH);
		if (n >= 0) fire(n, 0.6, 0.5);
	}
	for (let p = 0; p < MAX_PULSES; p++) {
		const k = pl[p];
		if (k < 0) continue;
		pp[p] += ps[p] * speed;
		if (pp[p] < 1) continue;
		pl[p] = -1;
		const to = lt[k];
		energy[to] = Math.min(1, energy[to] + 0.35 * pb[p]);
		if (pb[p] > 0.25 && to < firstOfLast) fire(to, pb[p] * 0.7, reduced ? CASCADE * 0.4 : CASCADE);
	}
}

function draw() {
	ctx.clearRect(0, 0, w, h);
	const k = dark ? 1 : 0.8;
	for (let i = 0; i < linkCount; i++) {
		const a = lf[i], b = lt[i];
		const calm = lc[i];
		ctx.globalAlpha = Math.min(1, (LINK_ALPHA * (0.5 + lw[i] * 0.5) + Math.max(energy[a], energy[b]) * 0.18) * calm * k);
		ctx.strokeStyle = col.link;
		ctx.lineWidth = 1 + lw[i] * 0.5;
		ctx.beginPath();
		ctx.moveTo(nx[a], ny[a]);
		ctx.lineTo(nx[b], ny[b]);
		ctx.stroke();
	}
	for (let p = 0; p < MAX_PULSES; p++) {
		const l = pl[p];
		if (l < 0) continue;
		const a = lf[l], b = lt[l], f = pp[p];
		const x = nx[a] + (nx[b] - nx[a]) * f, y = ny[a] + (ny[b] - ny[a]) * f;
		ctx.globalAlpha = Math.min(1, (0.4 + pb[p] * 0.6) * band(x) * k * Math.min(1, f * 6, (1 - f) * 6));
		ctx.drawImage(pulseSprite, x - 12, y - 12);
	}
	for (let i = 0; i < nodeCount; i++) {
		const e = energy[i], c = ncalm[i] * k;
		// Every node keeps a faint halo at rest, which swells when it fires
		ctx.globalAlpha = Math.min(1, (0.22 + e * 0.6) * c);
		ctx.drawImage(haloSprite, nx[i] - 16, ny[i] - 16);
		ctx.globalAlpha = Math.min(1, (0.55 + e * 0.45) * c);
		ctx.fillStyle = col.node;
		ctx.beginPath();
		ctx.arc(nx[i], ny[i], NODE_RADIUS, 0, 6.2832);
		ctx.fill();
		if (e > 0.1) {
			ctx.globalAlpha = Math.min(1, e * 0.8 * c);
			ctx.fillStyle = col.core;
			ctx.beginPath();
			ctx.arc(nx[i], ny[i], NODE_RADIUS * 0.5, 0, 6.2832);
			ctx.fill();
		}
	}
	ctx.globalAlpha = 1;
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!ctx) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	mouse.target = Math.max(0, mouse.target - dt * 0.8);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 5);
	update(dt);
	draw();
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			resize(d.width, d.height, d.dpr);
			requestAnimationFrame(frame);
			break;
		case 'resize':
			resize(d.width, d.height, d.dpr);
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas) build();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
		case 'mousedown': {
			// A tap fires the nearest node down every link; a single soft pulse when motion is reduced
			const n = nearest(d.x, d.y, CURSOR_REACH * 1.3);
			if (n >= 0) fire(n, reduced ? 0.5 : 1, reduced ? 0.4 : 1);
			break;
		}
	}
};

/**
 * Title: Ocean Waves
 * Description: Layered translucent swells in your theme's colors roll across the lower screen with lit crests, rising bubbles and drifting caustic light, thin behind the chat and lift under the cursor.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const TIME_SCALE      = 1;     // wave speed; 0.5 is languid, 2 is choppy, 0 holds still (0-3)
const REDUCED_SPEED   = 0.2;   // share of the speed kept when the viewer asks to reduce motion (0-1)
const NUM_LAYERS      = 5;     // wave layers, back to front (1-10)
const LAYER_TOP       = 0.6;   // height of the deepest layer, as a share of the screen (0.1-0.8)
const LAYER_SPAN      = 0.3;   // vertical spread of the layers, as a share of the screen (0.1-0.8)
const AMPLITUDE_BACK  = 15;    // wave height of the deepest layer, in px (0-60)
const AMPLITUDE_FRONT = 40;    // wave height of the nearest layer, in px (0-100)
const WAVE_LENGTH     = 1;     // length of the swells; higher is longer (0.4-3)
const OPACITY         = 1;     // strength of the water (0.2-2)
const CREST_WIDTH     = 1.5;   // thickness of the lit crest line, in px; 0 turns it off (0-4)
const CENTER_CALM     = 0.7;   // how much the water thins behind the chat column (0-1)
const BAND_WIDTH      = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const MOUSE_SWELL     = 40;    // height of the swell under the cursor, in px; 0 turns it off (0-100)
const MOUSE_RADIUS    = 250;   // reach of the swell, in px (80-500)
const BUBBLES         = 30;    // rising foam bubbles; 0 turns them off (0-120)
const CAUSTICS        = 6;     // drifting patches of caustic light; 0 turns them off (0-12)
const WAVE_STEP       = 4;     // px between wave samples; raise to lighten the load (2-12)
const FOLLOW_THEME    = true;  // take the colors from the theme's palette
const HUE_DEEP        = 200;   // hue of the deepest layer when not following the theme (0-360)
const HUE_SHALLOW     = 220;   // hue of the nearest layer when not following the theme (0-360)
/* ──────────────────────────────────────────── */

const TAU = Math.PI * 2;
const STEP = Math.max(2, WAVE_STEP);
const L = Math.max(1, Math.min(10, Math.round(NUM_LAYERS)));
const NB = Math.max(0, Math.min(120, Math.round(BUBBLES)));
const NC = Math.max(0, Math.min(12, Math.round(CAUSTICS)));

let canvas, ctx;
let w = 0, h = 0, dpr = 1;
let last = 0, time = 0, reduced = false, dark = true, theme = null, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };

// Per-layer wave traits
const yBase = new Float32Array(L), amp = new Float32Array(L), freq = new Float32Array(L);
const speed = new Float32Array(L), phase = new Float32Array(L), depth = new Float32Array(L);
let pts = new Float32Array(2);
const fills = [], crests = [];
let calmMask = null;
// Bubbles
const bx = new Float32Array(NB), by = new Float32Array(NB), br = new Float32Array(NB);
const bvx = new Float32Array(NB), bvy = new Float32Array(NB), bop = new Float32Array(NB);
const blife = new Float32Array(NB), bdecay = new Float32Array(NB);
let bubbleSprite = null, causticSprite = null;

for (let i = 0; i < L; i++) phase[i] = Math.random() * TAU;

function lerp(a, b, t) { return a + (b - a) * t; }

function hexToRgb(hex) {
	const n = parseInt(String(hex).slice(1, 7), 16) || 0;
	return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function mix(a, b, t) {
	return [Math.round(lerp(a[0], b[0], t)), Math.round(lerp(a[1], b[1], t)), Math.round(lerp(a[2], b[2], t))];
}

function hsl(hue, s, l) {
	s /= 100; l /= 100;
	const k = (n) => (n + hue / 30) % 12;
	const a = s * Math.min(l, 1 - l);
	const f = (n) => Math.round(255 * (l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)))));
	return [f(0), f(8), f(4)];
}

function rgba(c, a) {
	return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + Math.max(0, a).toFixed(3) + ')';
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function band(x) {
	const d = Math.abs(x - colX()) / colHalf();
	const s = Math.min(1, Math.max(0, (d - 0.35) / 1.0)); // a wide, slow falloff, so the water has no visible seam
	return 1 - s * s * (3 - 2 * s);
}

function sprite(c) {
	const s = new OffscreenCanvas(128, 128);
	const g = s.getContext('2d');
	const grad = g.createRadialGradient(64, 64, 0, 64, 64, 64);
	for (let k = 0; k <= 8; k++) grad.addColorStop(k / 8, rgba(c, Math.exp(-k * k / 14) * (1 - k / 8)));
	g.fillStyle = grad;
	g.fillRect(0, 0, 128, 128);
	return s;
}

// Colors, cached gradients and sprites; rebuilt on theme change, resize and layout only
function build() {
	if (!ctx || !w) return;
	const c = FOLLOW_THEME && theme && theme.colors ? theme.colors : null;
	let back, front, crestTint, foam, glow;
	if (c) {
		const a = hexToRgb(c.accent), a3 = hexToRgb(c.accent3), bg = hexToRgb(c.background), tx = hexToRgb(c.text);
		back = dark ? mix(a3, bg, 0.45) : mix(a3, bg, 0.2);
		front = dark ? mix(a, a3, 0.3) : a;
		crestTint = dark ? tx : mix(a, tx, 0.35);
		foam = dark ? mix(a3, tx, 0.5) : a3;
		glow = dark ? mix(a3, tx, 0.3) : [255, 255, 255];
	} else {
		back = hsl(HUE_DEEP, 70, dark ? 15 : 40);
		front = hsl(HUE_SHALLOW, 70, dark ? 35 : 45);
		crestTint = dark ? hsl(HUE_SHALLOW - 10, 60, 70) : hsl(HUE_SHALLOW, 70, 30);
		foam = [150, 200, 220];
		glow = dark ? [120, 200, 220] : [255, 255, 255];
	}
	const a0 = (dark ? 0.08 : 0.05) * OPACITY, a1 = (dark ? 0.2 : 0.13) * OPACITY;
	for (let i = 0; i < L; i++) {
		const t = depth[i];
		const col = mix(back, front, t);
		const alpha = lerp(a0, a1, t);
		const crest = mix(col, crestTint, dark ? 0.4 : 0.5);
		const crestA = alpha * (dark ? 0.6 : 1.4) * 1.5;
		fills[i] = rgba(col, alpha);
		crests[i] = rgba(crest, Math.min(1, crestA));
	}
	// One mask thins everything behind the chat in a single pass, which bands far less than per-layer gradients
	calmMask = ctx.createLinearGradient(0, 0, w, 0);
	for (let s = 0; s <= 48; s++) calmMask.addColorStop(s / 48, 'rgba(0,0,0,' + (CENTER_CALM * band((s / 48) * w)).toFixed(3) + ')');
	bubbleSprite = sprite(foam);
	causticSprite = sprite(glow);
}

function resetBubble(i) {
	bx[i] = Math.random() * w;
	by[i] = h * (0.35 + Math.random() * 0.6);
	br[i] = 0.5 + Math.random() * 1.5;
	bop[i] = (0.03 + Math.random() * 0.06) * (dark ? 2.5 : 2);
	bvx[i] = (Math.random() - 0.5) * 18;
	bvy[i] = -(6 + Math.random() * 18);
	blife[i] = 1;
	bdecay[i] = 0.06 + Math.random() * 0.18;
}

function size(nw, nh, ndpr) {
	w = nw;
	h = nh;
	dpr = Math.min(2, ndpr || 1);
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	ctx.lineJoin = 'round';
	pts = new Float32Array(Math.ceil(w / STEP) + 2);
	for (let i = 0; i < L; i++) {
		const t = L > 1 ? i / (L - 1) : 0;
		depth[i] = t;
		yBase[i] = h * (LAYER_TOP + t * LAYER_SPAN);
		amp[i] = lerp(AMPLITUDE_BACK, AMPLITUDE_FRONT, t);
		freq[i] = lerp(0.007, 0.003, t) / WAVE_LENGTH;
		speed[i] = lerp(0.02, 0.008, t);
	}
	for (let i = 0; i < NB; i++) { resetBubble(i); blife[i] = Math.random(); }
	build();
}

function drawLayer(i, t) {
	const f = freq[i], a = amp[i], sp = speed[i], ph = phase[i], yb = yBase[i];
	const swell = MOUSE_SWELL * mouse.amount * (1 - depth[i] * 0.5) * (reduced ? 0.4 : 1);
	const dy = yb - mouse.y;
	const near = swell > 0.5 && Math.abs(dy) < MOUSE_RADIUS;
	const r2 = MOUSE_RADIUS * MOUSE_RADIUS;
	let n = 0;
	// Sample once into a reused buffer: the fill and the crest trace the same curve
	for (let x = 0; x <= w + STEP; x += STEP) {
		let y = yb + Math.sin(x * f + t * sp + ph) * a
			+ Math.sin(x * f * 2.3 + t * sp * 1.5 + ph * 2) * a * 0.3
			+ Math.sin(x * f * 4.7 + t * sp * 0.7) * a * 0.08;
		if (near) {
			const dx = x - mouse.x, d2 = dx * dx + dy * dy;
			if (d2 < r2) { const s = 1 - Math.sqrt(d2) / MOUSE_RADIUS; y -= s * s * swell; }
		}
		pts[n++] = y;
	}
	ctx.beginPath();
	ctx.moveTo(0, h);
	for (let k = 0; k < n; k++) ctx.lineTo(k * STEP, pts[k]);
	ctx.lineTo((n - 1) * STEP, h);
	ctx.closePath();
	ctx.fillStyle = fills[i];
	ctx.fill();
	if (CREST_WIDTH <= 0) return;
	ctx.beginPath();
	ctx.moveTo(0, pts[0]);
	for (let k = 1; k < n; k++) ctx.lineTo(k * STEP, pts[k]);
	ctx.strokeStyle = crests[i];
	ctx.lineWidth = CREST_WIDTH;
	ctx.stroke();
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!ctx || !bubbleSprite) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const pace = TIME_SCALE * (reduced ? REDUCED_SPEED : 1);
	time += dt * 60 * pace; // one unit is one frame at 60 fps, which the wave constants expect
	mouse.target = Math.max(0, mouse.target - dt * 0.6);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 2.5);

	ctx.globalAlpha = 1;
	ctx.globalCompositeOperation = 'source-over';
	ctx.clearRect(0, 0, w, h);
	for (let i = 0; i < L; i++) drawLayer(i, time);

	ctx.globalCompositeOperation = dark ? 'lighter' : 'source-over';
	for (let i = 0; i < NB; i++) {
		bx[i] += bvx[i] * dt * pace;
		by[i] += bvy[i] * dt * pace;
		blife[i] -= bdecay[i] * dt * pace;
		if (blife[i] <= 0 || by[i] < h * 0.2) resetBubble(i);
		const a = bop[i] * blife[i] * Math.min(1, (1 - blife[i]) * 8);
		if (a < 0.003) continue;
		const s = br[i] * 4;
		ctx.globalAlpha = Math.min(1, a * 3);
		ctx.drawImage(bubbleSprite, bx[i] - s * 0.5, by[i] - s * 0.5, s, s);
	}

	for (let i = 0; i < NC; i++) {
		const cx = w * (0.08 + 0.84 * ((i + 0.5) / NC)) + Math.sin(time * 0.003 + i * 1.5) * 80;
		const cy = h * (LAYER_TOP + LAYER_SPAN * 0.35) + Math.cos(time * 0.004 + i * 2.1) * 60;
		const r = 60 + Math.sin(time * 0.005 + i) * 20;
		const a = (0.015 + 0.01 * Math.sin(time * 0.006 + i * 3)) * (dark ? 3 : 8);
		if (a <= 0.002) continue;
		ctx.globalAlpha = Math.min(1, a);
		ctx.drawImage(causticSprite, cx - r, cy - r, r * 2, r * 2);
	}
	ctx.globalAlpha = 1;
	if (CENTER_CALM > 0) {
		ctx.globalCompositeOperation = 'destination-out';
		ctx.fillStyle = calmMask;
		ctx.fillRect(0, 0, w, h);
	}
	ctx.globalCompositeOperation = 'source-over';
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			reduced = !!d.reducedMotion;
			column = d.column || null;
			theme = d.theme || null;
			dark = !theme || theme.dark !== false;
			size(d.width, d.height, d.dpr);
			requestAnimationFrame(frame);
			break;
		case 'resize':
			if (ctx) size(d.width, d.height, d.dpr);
			break;
		case 'theme':
			theme = d;
			dark = d.dark !== false;
			build();
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			build();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

/**
 * Title: Parallax Vista (WebGL)
 * Description: Layered dusk mountain ranges open into a valley behind the chat, a soft sun glows beside it, mist pools in the folds and fireflies drift past, every layer shifting by its depth as the cursor moves.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const PARALLAX      = 1;     // strength of the cursor depth effect; 0 holds the layers still (0-2)
const DRIFT         = 0.01;  // idle sideways drift of the ranges (0-0.05)
const REDUCED_SPEED = 0.15;  // share of the drift kept when the viewer asks to reduce motion (0-1)
const FIREFLIES     = 0.6;   // brightness of the drifting fireflies; 0 turns them off (0-1.5)
const STARS         = 0.6;   // faint stars over the ranges, dark themes only (0-1)
const SUN_GLOW      = 1;     // brightness of the sun and the horizon glow (0-2)
const MIST          = 1;     // how much mist pools above each range (0-2)
const VALLEY        = 0.55;  // how deeply the ranges part behind the chat column (0-1)
const RANGE_HEIGHT  = 1;     // how tall the ranges rise (0.6-1.5)
const CENTER_CALM   = 0.7;   // how much the scene fades behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const RENDER_SCALE  = 0.6;   // resolution of the scene; ridges are soft, so 0.6 is plenty (0.3-1)
const MAX_FPS       = 30;    // frame cap; the vista moves slowly (15-60)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const COLOR_GLOW    = '#fa9457';  // apricot horizon glow when not following the theme
const COLOR_SUN     = '#ffd9a0';  // sun disk
const COLOR_FAR     = '#8a82b0';  // hazy far ranges
const COLOR_NEAR    = '#0b0d1c';  // near silhouettes
const COLOR_FLY     = '#ffcc73';  // fireflies
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform float u_drift[5];',
	'uniform vec2 u_look;',
	'uniform vec2 u_sun;',
	'uniform vec3 u_glow;',
	'uniform vec3 u_disk;',
	'uniform vec3 u_far;',
	'uniform vec3 u_near;',
	'uniform vec3 u_mist;',
	'uniform vec3 u_fly;',
	'uniform float u_dark;',
	'uniform vec2 u_col;',
	'float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }',
	'float noise(vec2 p) {',
	'	vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);',
	'	return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);',
	'}',
	'float fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 4; i++) { v += a * noise(p); p *= 2.03; a *= 0.5; } return v; }',
	'vec4 over(vec4 top, vec4 under) { return top + under * (1.0 - top.a); }',
	'float fireflies(vec2 p, float t) {',
	'	vec2 g = p * 7.0, gi = floor(g), gf = fract(g);',
	'	float sum = 0.0;',
	'	for (int j = -1; j <= 1; j++) {',
	'		for (int i = -1; i <= 1; i++) {',
	'			vec2 o = vec2(float(i), float(j)), id = gi + o;',
	'			float r = hash(id);',
	'			vec2 cp = o + vec2(hash(id + 1.7), hash(id + 3.3));',
	'			cp += vec2(cos(t * 0.4 + r * 6.28) * 0.15, sin(t * 0.6 + r * 6.28) * 0.35);',
	'			float tw = 0.5 + 0.5 * sin(t * 1.5 + r * 25.0);',
	'			sum += smoothstep(0.07, 0.0, length(gf - cp)) * tw * step(0.45, r);',
	'		}',
	'	}',
	'	return sum;',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	vec2 st = px / res;',
	'	float aspect = res.x / res.y;',
	'	float t = u_time;',
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float near = 1.0 - smoothstep(0.5, 1.3, band);',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * near;',
	'	vec2 sun = vec2(u_sun.x, res.y - u_sun.y);',
	'	float sunSide = exp(-abs(px.x - sun.x) / (res.y * 0.6));',
	'	float sg = ' + SUN_GLOW.toFixed(3) + ' * mix(0.6, 1.0, u_dark);',
	'	float hg = exp(-pow((st.y - 0.36) * 5.0, 2.0)) * (0.2 + 0.8 * sunSide) * 0.32 * sg * mix(0.5, 1.0, calm);',
	'	vec4 o = vec4(u_glow * hg, hg);',
	'	vec2 sgd = px * vec2(1.0, 1.0) / 1.5;',
	'	vec2 cell = floor(sgd / 6.0);',
	'	float hs = hash(cell);',
	'	float star = step(1.0 - 0.012 * ' + STARS.toFixed(3) + ', hs) * smoothstep(1.4, 0.2, length(sgd - (cell + 0.5) * 6.0)) * (0.55 + 0.45 * sin(t * 1.2 + hs * 80.0)) * smoothstep(0.5, 0.8, st.y) * u_dark * calm * 0.8;',
	'	o = over(vec4(vec3(star), star), o);',
	'	float sd = length(px - sun);',
	'	float sr = res.y * 0.045;',
	'	float glow = exp(-sd / (res.y * 0.16)) * 0.45 * sg;',
	'	float disk = smoothstep(sr + 1.5, sr - 1.5, sd) * mix(0.75, 1.0, u_dark) * min(1.0, sg);',
	'	o = over(vec4(u_glow * glow, glow), o);',
	'	o = over(vec4(u_disk * disk, disk), o);',
	'	for (int k = 0; k < 5; k++) {',
	'		float fk = float(k) / 4.0;',
	'		float baseY = mix(0.40, 0.11, fk) * ' + RANGE_HEIGHT.toFixed(3) + ';',
	'		float amp = mix(0.03, 0.13, fk) * ' + RANGE_HEIGHT.toFixed(3) + ';',
	'		float freq = mix(2.2, 1.3, fk);',
	'		float rx = st.x * aspect + u_look.x * mix(0.015, 0.14, fk) + u_drift[k];',
	'		float dip = 1.0 - ' + VALLEY.toFixed(3) + ' * near * mix(0.45, 0.7, fk);',
	'		float ridge = baseY * dip + u_look.y * mix(0.004, 0.03, fk) + (fbm(vec2(rx * freq, 7.0 * fk)) * 2.0 - 1.0) * amp * mix(1.0, 0.6, near);',
	'		float below = smoothstep(ridge + 0.002, ridge - 0.002, st.y);',
	'		float mist = smoothstep(ridge + 0.07, ridge, st.y) * (1.0 - below) * 0.22 * (1.0 - fk * 0.7) * ' + MIST.toFixed(3) + ' * mix(0.5, 1.0, calm);',
	'		o = over(vec4(u_mist * mist, mist), o);',
	'		float la = below * mix(mix(0.12, 0.42, fk), mix(0.28, 0.92, fk), u_dark) * mix(calm, 1.0, 0.25);',
	'		vec3 lc = mix(u_far, u_near, fk * fk);',
	'		lc = mix(lc, u_glow, (1.0 - fk) * 0.25 * sunSide);',
	'		o = over(vec4(lc * la, la), o);',
	'	}',
	'	vec2 fuv = st * vec2(aspect, 1.0) + u_look * 0.9;',
	'	float ff = fireflies(fuv, t) * ' + FIREFLIES.toFixed(3) + ' * smoothstep(0.6, 0.15, st.y) * calm * calm * mix(0.7, 1.0, u_dark);',
	'	o = over(vec4(u_fly * ff, ff), o);',
	'	o = clamp(o, 0.0, 1.0);',
	'	gl_FragColor = vec4(min(o.rgb, vec3(o.a)), o.a);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
const loc = {};
let w = 0, h = 0;
let last = 0, time = 0, reduced = false, column = null;
const drifts = new Float32Array(5);
const mouse = { x: -10000, y: -10000, amount: 0, target: 0, lx: 0, ly: 0 };
const sun = { x: -1, y: 0 };
const colors = {};

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function mix3(a, b, k) { return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]; }

// Glow and sun from accent2, far ranges from muted and accent, near ranges from the background's shadow
function applyTheme(t) {
	if (t) colors.dark = t.dark === false ? 0 : 1;
	if (colors.dark === undefined) colors.dark = 1;
	const dark = colors.dark === 1;
	if (!FOLLOW_THEME || !t || !t.rgb) {
		colors.glow = hexToRgb(COLOR_GLOW);
		colors.disk = dark ? hexToRgb(COLOR_SUN) : hexToRgb(COLOR_GLOW);
		colors.far = hexToRgb(COLOR_FAR);
		colors.near = dark ? hexToRgb(COLOR_NEAR) : mix3(hexToRgb(COLOR_FAR), hexToRgb(COLOR_NEAR), 0.5);
		colors.mist = dark ? [0.8, 0.75, 0.86] : [1, 1, 1];
		colors.fly = hexToRgb(COLOR_FLY);
		return;
	}
	const r = t.rgb;
	colors.glow = r.accent2;
	colors.disk = dark ? mix3(r.accent2, r.text, 0.55) : r.accent2;
	colors.far = mix3(r.muted, r.accent, 0.35);
	colors.near = dark ? mix3(r.background, [0, 0, 0], 0.7) : mix3(r.muted, r.text, 0.35);
	colors.mist = dark ? mix3(r.muted, r.text, 0.4) : [1, 1, 1];
	colors.fly = dark ? mix3(r.accent3, r.text, 0.3) : r.accent3;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_drift', 'u_look', 'u_sun', 'u_glow', 'u_disk', 'u_far', 'u_near', 'u_mist', 'u_fly', 'u_dark', 'u_col'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

function size() {
	canvas.width = Math.max(1, Math.round(w * RENDER_SCALE));
	canvas.height = Math.max(1, Math.round(h * RENDER_SCALE));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

// The sun sits in the middle of the wider margin beside the chat column
function sunTargetX() {
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const left = colX() - colHalf() - lo, right = hi - colX() - colHalf();
	return left >= right ? lo + Math.max(left * 0.5, h * 0.08) : hi - Math.max(right * 0.5, h * 0.08);
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const k = reduced ? REDUCED_SPEED : 1;
	time = (time + dt * k) % 3000;
	for (let i = 0; i < 5; i++) drifts[i] = (drifts[i] + dt * k * DRIFT * (0.3 + i * 0.175)) % 1000;
	// Layers lean toward the cursor, then settle back once it rests
	mouse.target = Math.max(0, mouse.target - dt * 0.3);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 2);
	const tx = w ? (mouse.x / w - 0.5) * mouse.amount * PARALLAX : 0;
	const ty = h ? (0.5 - mouse.y / h) * mouse.amount * PARALLAX : 0;
	const ease = Math.min(1, dt * (reduced ? 0.5 : 2.5));
	mouse.lx += (tx - mouse.lx) * ease;
	mouse.ly += (ty - mouse.ly) * ease;
	const sx = sunTargetX();
	sun.x = sun.x < 0 ? sx : sun.x + (sx - sun.x) * Math.min(1, dt * 1.5);
	sun.y = h * 0.6;
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform1fv(loc.u_drift, drifts);
	gl.uniform2f(loc.u_look, mouse.lx, mouse.ly);
	gl.uniform2f(loc.u_sun, sun.x, sun.y);
	gl.uniform3fv(loc.u_glow, colors.glow);
	gl.uniform3fv(loc.u_disk, colors.disk);
	gl.uniform3fv(loc.u_far, colors.far);
	gl.uniform3fv(loc.u_near, colors.near);
	gl.uniform3fv(loc.u_mist, colors.mist);
	gl.uniform3fv(loc.u_fly, colors.fly);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	const opts = { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' };
	gl = canvas.getContext('webgl2', opts) || canvas.getContext('webgl', opts);
	if (!gl) {
		console.warn('Parallax Vista: WebGL is not available, so the vista is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Parallax Vista:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Parallax Vista:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			for (let i = 0; i < 5; i++) drifts[i] = Math.random() * 100;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

/**
 * Title: Plasma Flow (WebGPU)
 * Description: Domain-warped plasma currents in your theme's accent colors, drawn with a WebGPU shader (soft drifting color blobs where WebGPU is missing), that thin behind the chat and bend toward the cursor with a fading glow.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const FLOW_SPEED    = 0.15;  // how fast the plasma currents drift (0-0.6)
const WARP          = 4;     // domain-warp strength; higher is more turbulent (0-8)
const MOUSE_GLOW    = 0.6;   // brightness of the light that follows the cursor (0-1.5)
const CURSOR_PULL   = 1;     // how far the currents bend toward the cursor (0-2)
const DIM           = 0.85;  // overall strength, so it reads as a background (0-1)
const REDUCED_SPEED = 0.15;  // share of the flow kept when the viewer asks to reduce motion (0-1)
const CENTER_CALM   = 0.8;   // how much the plasma thins behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const RENDER_SCALE  = 0.5;   // resolution of the plasma; it is soft, so half is plenty (0.25-1)
const MAX_FPS       = 30;    // frame cap; the currents move slowly (15-60)
const FOLLOW_THEME  = true;  // blend the theme's three accents; off cycles a rainbow palette
/* ──────────────────────────────────────────── */

const WGSL = `
struct U { a : vec4f, b : vec4f, c : vec4f, c1 : vec4f, c2 : vec4f, c3 : vec4f };
@group(0) @binding(0) var<uniform> u : U;
@vertex fn vs(@builtin(vertex_index) i : u32) -> @builtin(position) vec4f {
	var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));
	return vec4f(p[i], 0.0, 1.0);
}
fn hash(p0 : vec2f) -> f32 { var p = fract(p0 * vec2f(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
fn noise(p : vec2f) -> f32 {
	let i = floor(p); let f = fract(p); let w = f * f * (3.0 - 2.0 * f);
	return mix(mix(hash(i), hash(i + vec2f(1.0, 0.0)), w.x), mix(hash(i + vec2f(0.0, 1.0)), hash(i + vec2f(1.0, 1.0)), w.x), w.y);
}
fn fbm(p0 : vec2f) -> f32 {
	var p = p0; var v = 0.0; var a = 0.5;
	let m = mat2x2f(1.6, 1.2, -1.2, 1.6);
	for (var i = 0; i < 5; i++) { v += a * noise(p); p = m * p; a *= 0.5; }
	return v;
}
fn pal(t : f32) -> vec3f { return 0.5 + 0.5 * cos(6.28318 * (vec3f(t) + vec3f(0.0, 0.33, 0.67))); }
fn accents(t : f32) -> vec3f {
	let w = 0.5 + 0.5 * cos(6.28318 * (vec3f(t) - vec3f(0.0, 0.3333, 0.6667)));
	let k = w * w;
	return (u.c1.rgb * k.x + u.c2.rgb * k.y + u.c3.rgb * k.z) / (k.x + k.y + k.z);
}
@fragment fn fs(@builtin(position) frag : vec4f) -> @location(0) vec4f {
	let px = frag.xy / u.a.z;
	let res = u.a.xy / u.a.z;
	let s = min(res.x, res.y);
	let p = (px - 0.5 * res) / s;
	let m = (u.b.xy - 0.5 * res) / s;
	let pull = (m - p) * u.b.z * ${(CURSOR_PULL * 0.35).toFixed(4)} * exp(-length(p - m) * 2.0);
	let t = u.a.w * ${FLOW_SPEED.toFixed(4)};
	let q = vec2f(fbm(p + vec2f(0.0, t)), fbm(p + vec2f(5.2, 1.3 - t)));
	let r = vec2f(fbm(p + ${WARP.toFixed(3)} * q + vec2f(1.7, 9.2) + pull), fbm(p + ${WARP.toFixed(3)} * q + vec2f(8.3, 2.8) - pull));
	let f = fbm(p + ${WARP.toFixed(3)} * r);
	var col = select(pal(f + t), accents(f * 1.3 + q.x * 0.4 + t), u.c.z > 0.5);
	col = min(col * mix(0.95, 0.55 + 0.75 * f, u.b.w), vec3f(1.0));
	let band = abs(px.x - u.c.x) / u.c.y;
	let calm = 1.0 - ${CENTER_CALM.toFixed(3)} * (1.0 - smoothstep(0.6, 1.25, band));
	let md = length(p - m);
	let g = exp(-md * 5.0) * u.b.z * ${MOUSE_GLOW.toFixed(3)};
	var a = (0.1 + 0.9 * smoothstep(0.25, 0.75, f)) * mix(0.68, 0.85, u.b.w) * calm;
	let ga = g * mix(0.3, 0.55, u.b.w) * mix(0.35, 1.0, calm);
	var rgb = col * a + u.c3.rgb * ga;
	a = clamp((a + ga) * ${DIM.toFixed(3)}, 0.0, 1.0);
	return vec4f(min(rgb * ${DIM.toFixed(3)}, vec3f(a)), a);
}`;

let canvas = null, w = 0, h = 0;
let last = 0, time = 0, reduced = false, column = null, started = false;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };
const pal = { c1: hexToRgb('#7a8cff'), c2: hexToRgb('#c46cf0'), c3: hexToRgb('#4fd2e6'), dark: 1, follow: FOLLOW_THEME ? 1 : 0 };

// WebGPU state
let device = null, context = null, pipeline = null, bindGroup = null, uBuf = null, format = null, rebuilds = 0;
const uData = new Float32Array(24);
const attachment = { view: null, clearValue: { r: 0, g: 0, b: 0, a: 0 }, loadOp: 'clear', storeOp: 'store' };
const passDesc = { colorAttachments: [attachment] };
const cmds = [null];

// Canvas 2D fallback state
let ctx = null, blob = [], glow = null, mask = null;

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function applyTheme(t) {
	if (!t) return;
	pal.dark = t.dark === false ? 0 : 1;
	if (FOLLOW_THEME && t.rgb) { pal.c1 = t.rgb.accent; pal.c2 = t.rgb.accent2; pal.c3 = t.rgb.accent3; }
	if (ctx) buildSprites();
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function size() {
	canvas.width = Math.max(1, Math.round(w * RENDER_SCALE));
	canvas.height = Math.max(1, Math.round(h * RENDER_SCALE));
	if (ctx) { ctx.setTransform(RENDER_SCALE, 0, 0, RENDER_SCALE, 0, 0); buildMask(); }
}

/* ── WebGPU: everything that can fail happens before the canvas is touched ── */
async function buildGPU() {
	if (!navigator.gpu) throw new Error('WebGPU is not available');
	const adapter = await navigator.gpu.requestAdapter({ powerPreference: 'low-power' });
	if (!adapter) throw new Error('no GPU adapter');
	const dev = await adapter.requestDevice();
	format = navigator.gpu.getPreferredCanvasFormat();
	const module = dev.createShaderModule({ code: WGSL });
	const info = await module.getCompilationInfo();
	const errs = info.messages.filter((m) => m.type === 'error');
	if (errs.length) throw new Error('shader: ' + errs.map((m) => m.lineNum + ': ' + m.message).join('; '));
	pipeline = await dev.createRenderPipelineAsync({
		layout: 'auto',
		vertex: { module, entryPoint: 'vs' },
		fragment: { module, entryPoint: 'fs', targets: [{ format }] },
		primitive: { topology: 'triangle-list' },
	});
	uBuf = dev.createBuffer({ size: uData.byteLength, usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST });
	bindGroup = dev.createBindGroup({ layout: pipeline.getBindGroupLayout(0), entries: [{ binding: 0, resource: { buffer: uBuf } }] });
	dev.addEventListener('uncapturederror', (e) => console.error('Plasma Flow:', e.error.message));
	// A lost device is rebuilt on the same context; a canvas that holds a WebGPU context can't switch to 2D
	dev.lost.then((lost) => {
		if (device !== dev) return;
		device = null;
		if (lost.reason === 'destroyed' || rebuilds >= 3) return;
		rebuilds++;
		buildGPU().catch((err) => console.error('Plasma Flow: could not rebuild WebGPU:', err.message));
	});
	if (!context) context = canvas.getContext('webgpu');
	if (!context) throw new Error('no WebGPU canvas context');
	context.configure({ device: dev, format, alphaMode: 'premultiplied' });
	device = dev;
}

function drawGPU() {
	uData[0] = canvas.width; uData[1] = canvas.height; uData[2] = canvas.width / Math.max(1, w); uData[3] = time;
	uData[4] = mouse.x; uData[5] = mouse.y; uData[6] = mouse.amount; uData[7] = pal.dark;
	uData[8] = colX(); uData[9] = colHalf(); uData[10] = pal.follow;
	uData.set(pal.c1, 12); uData.set(pal.c2, 16); uData.set(pal.c3, 20);
	device.queue.writeBuffer(uBuf, 0, uData);
	attachment.view = context.getCurrentTexture().createView();
	const encoder = device.createCommandEncoder();
	const pass = encoder.beginRenderPass(passDesc);
	pass.setPipeline(pipeline);
	pass.setBindGroup(0, bindGroup);
	pass.draw(3);
	pass.end();
	cmds[0] = encoder.finish();
	device.queue.submit(cmds);
}

/* ── Canvas 2D fallback: soft color blobs on slow drifting paths ── */
function sprite(rgb, alpha) {
	const s = 128, c = new OffscreenCanvas(s, s), g = c.getContext('2d');
	const grad = g.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
	const col = Math.round(rgb[0] * 255) + ',' + Math.round(rgb[1] * 255) + ',' + Math.round(rgb[2] * 255);
	grad.addColorStop(0, 'rgba(' + col + ',' + alpha + ')');
	grad.addColorStop(0.5, 'rgba(' + col + ',' + alpha * 0.4 + ')');
	grad.addColorStop(1, 'rgba(' + col + ',0)');
	g.fillStyle = grad;
	g.fillRect(0, 0, s, s);
	return c;
}

function buildSprites() {
	const a = (pal.dark ? 0.45 : 0.28) * DIM;
	blob = [sprite(pal.c1, a), sprite(pal.c2, a), sprite(pal.c3, a)];
	glow = sprite(pal.c3, (pal.dark ? 0.4 : 0.25) * MOUSE_GLOW);
}

// One row of the calm band, stretched over the screen with destination-out
function buildMask() {
	const n = Math.max(2, Math.ceil(w / 4));
	mask = new OffscreenCanvas(n, 1);
	const m = mask.getContext('2d'), img = m.createImageData(n, 1);
	for (let i = 0; i < n; i++) {
		const b = Math.abs(i * 4 - colX()) / colHalf();
		const t = Math.min(1, Math.max(0, (b - 0.6) / 0.65));
		img.data[i * 4 + 3] = Math.round(255 * CENTER_CALM * (1 - t * t * (3 - 2 * t)));
	}
	m.putImageData(img, 0, 0);
}

function draw2D() {
	ctx.clearRect(0, 0, w, h);
	ctx.globalCompositeOperation = pal.dark ? 'lighter' : 'source-over';
	// Blobs wander in the chat area's margins beside the column, three a side
	const t = time * FLOW_SPEED * 3, r = Math.max(w, h) * 0.26;
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const le = Math.max(colX() - colHalf(), lo + w * 0.12), re = Math.min(colX() + colHalf(), hi - w * 0.12);
	for (let i = 0; i < 6; i++) {
		const sx = 0.5 + 0.5 * Math.sin(t * (0.5 + i * 0.13) + i * 2.1);
		const x = i % 2 ? re + (hi - re) * sx : lo + (le - lo) * sx;
		const y = h * (0.5 + 0.42 * Math.cos(t * (0.4 + i * 0.11) + i * 1.3));
		ctx.drawImage(blob[i % 3], x - r, y - r, r * 2, r * 2);
	}
	if (mouse.amount > 0.01) {
		ctx.globalAlpha = mouse.amount;
		ctx.drawImage(glow, mouse.x - 160, mouse.y - 160, 320, 320);
		ctx.globalAlpha = 1;
	}
	ctx.globalCompositeOperation = 'destination-out';
	ctx.drawImage(mask, 0, 0, w, h);
	ctx.globalCompositeOperation = 'source-over';
}

function start2D() {
	ctx = canvas.getContext('2d');
	if (!ctx) return;
	buildSprites();
	size();
	requestAnimationFrame(frame);
}

function frame(now) {
	requestAnimationFrame(frame);
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	time = (time + dt * (reduced ? REDUCED_SPEED : 1)) % 3000;
	mouse.target = Math.max(0, mouse.target - dt * 0.4);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * (reduced ? 1 : 3));
	if (device && pipeline) drawGPU();
	else if (ctx) draw2D();
}

function start() {
	if (started) return;
	started = true;
	buildGPU().then(() => {
		size();
		requestAnimationFrame(frame);
	}).catch((err) => {
		if (context) { console.error('Plasma Flow:', err.message); return; }
		if (err.message.indexOf('shader') === 0) console.error('Plasma Flow:', err.message);
		start2D();
	});
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			if (device || ctx) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (ctx) buildMask();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

/**
 * Title: Retro Sun
 * Description: A synthwave sun with scrolling stripe cutouts sets low in an outer third over a perspective grid that rolls toward you, under calm twinkling stars; the glow swells when the cursor comes near.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const SUN_X         = 0.8;   // where the sun sits, as a share of the width (0-1)
const SUN_SIZE      = 0.16;  // sun radius as a share of the smaller screen side (0.06-0.3)
const HORIZON       = 0.8;   // height of the horizon, as a share of the screen (0.6-0.9)
const STRIPES       = 7;     // stripe cutouts across the sun's lower half (0-14)
const STRIPE_SPEED  = 6;     // how fast the stripes drift down, in px per second (0-30)
const GRID_SPEED    = 0.35;  // how fast the grid rolls toward you (0-2)
const GRID_LINES    = 22;    // vertical grid lines (6-40)
const STAR_COUNT    = 110;   // stars in the sky (0-300)
const GLOW          = 1;     // strength of the sun's glow and the horizon haze (0-2)
const PULSE_SPEED   = 0.5;   // speed of the glow's slow breathing (0-3)
const CURSOR_GLOW   = 1;     // how much the glow swells near the cursor (0-2)
const REDUCED_SPEED = 0.15;  // share of the motion kept under reduced motion (0-1)
const CENTER_CALM   = 0.8;   // how much the grid and stars fade behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME  = true;  // take the colors from the theme's accents
const SUN_TOP       = '#ff6ec7';  // sun's upper color when not following the theme
const SUN_BOTTOM    = '#ffb347';  // sun's lower color
const GRID_COLOR    = '#b45cff';  // grid and horizon
/* ──────────────────────────────────────────── */

const MAX_STARS = 300, TAU = Math.PI * 2;

let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, reduced = false, dark = true, column = null;
let top = hex(SUN_TOP), bottom = hex(SUN_BOTTOM), grid = hex(GRID_COLOR), star = [255, 255, 255];
let sunBody, sunCut, sunG, glowSprite, hazeSprite, gridStyle, horizonStyle, starStyle;
let sunR = 100, sunX = 0, horizonY = 0, stripePhase = 0, gridPhase = 0, pulseT = 0;
const sx = new Float32Array(MAX_STARS), sy = new Float32Array(MAX_STARS), ss = new Float32Array(MAX_STARS);
const sp = new Float32Array(MAX_STARS), sph = new Float32Array(MAX_STARS), sa = new Float32Array(MAX_STARS);
let stars = 0;
const mouse = { x: -10000, y: -10000, amount: 0, boost: 0 };

function hex(c) { const n = parseInt(c.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function rgba(c, a) { return 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a.toFixed(3) + ')'; }
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }
function band(x) {
	const t = Math.min(1, Math.max(0, (Math.abs(x - colX()) / colHalf() - 0.55) / 0.7));
	return 1 - t * t * (3 - 2 * t);
}
function calm(x) { return 1 - CENTER_CALM * band(x); }

function applyTheme(t) {
	if (!t) return;
	dark = t.dark !== false;
	if (FOLLOW_THEME && t.colors) {
		top = hex(t.colors.accent2);
		bottom = mix(hex(t.colors.accent), hex(t.colors.accent2), 0.2);
		grid = hex(t.colors.accent3);
		star = dark ? mix(hex(t.colors.text), [255, 255, 255], 0.5) : hex(t.colors.muted);
	} else star = dark ? [255, 255, 255] : [90, 90, 120];
	if (w) build();
}

// A soft radial sprite in one color
function sprite(size, col, a0, a1) {
	const c = new OffscreenCanvas(size, size), g = c.getContext('2d'), r = size / 2;
	const grad = g.createRadialGradient(r, r, 0, r, r, r);
	grad.addColorStop(0, rgba(col, a0));
	grad.addColorStop(0.4, rgba(col, a1));
	grad.addColorStop(1, rgba(col, 0));
	g.fillStyle = grad;
	g.fillRect(0, 0, size, size);
	return c;
}

// A horizontal gradient that fades a stroke over the chat column
function columnFade(col, a) {
	const g = ctx.createLinearGradient(0, 0, w, 0), k = 1 - CENTER_CALM, c = colX() / w, b = colHalf() / w;
	const at = (u) => Math.min(1, Math.max(0, u));
	g.addColorStop(0, rgba(col, a));
	g.addColorStop(at(c - b * 1.25), rgba(col, a));
	g.addColorStop(at(c - b * 0.55), rgba(col, a * k));
	g.addColorStop(at(c + b * 0.55), rgba(col, a * k));
	g.addColorStop(at(c + b * 1.25), rgba(col, a));
	g.addColorStop(1, rgba(col, a));
	return g;
}

// Caches rebuilt on resize, layout and theme change: the sun body, its glow and the grid styles
function build() {
	sunR = Math.max(40, Math.min(w, h) * SUN_SIZE);
	horizonY = Math.round(h * HORIZON);
	// The sun sits just past the calm band on its preferred side, or the other side when that one has no room, inside the chat area
	const L = column ? column.left : 0, R = column ? column.right : w, pref = L + (R - L) * SUN_X;
	// Too big for either margin, it shrinks to fit the wider one rather than sitting on the column
	if (column) {
		const room = Math.max(colX() - colHalf() - L, R - colX() - colHalf());
		sunR = Math.max(24, Math.min(sunR, room / 2.4));
	}
	const lo = L + sunR * 1.1, hi = R - sunR * 1.1, off = colHalf() + sunR * 0.2;
	const right = Math.max(pref, colX() + off), left = Math.min(pref, colX() - off);
	const first = SUN_X > 0.5 ? right : left, other = SUN_X > 0.5 ? left : right;
	sunX = Math.abs(SUN_X - 0.5) <= 0.05 ? pref : first >= lo && first <= hi ? first : other >= lo && other <= hi ? other : first;
	sunX = Math.max(lo, Math.min(hi, sunX));
	const s = Math.ceil(sunR * 2 * dpr) + 4;
	sunBody = new OffscreenCanvas(s, s);
	const g = sunBody.getContext('2d');
	g.setTransform(dpr, 0, 0, dpr, 2, 2);
	const grad = g.createLinearGradient(0, 0, 0, sunR * 2);
	grad.addColorStop(0, rgba(mix(top, [255, 255, 255], dark ? 0.15 : 0), 1));
	grad.addColorStop(0.55, rgba(mix(top, bottom, 0.6), 1));
	grad.addColorStop(1, rgba(bottom, 1));
	g.fillStyle = grad;
	g.beginPath();
	g.arc(sunR, sunR, sunR, 0, TAU);
	g.fill();
	sunCut = new OffscreenCanvas(s, s);
	sunG = sunCut.getContext('2d');
	const a = dark ? 1 : 0.4;
	glowSprite = sprite(256, mix(top, bottom, 0.4), 0.7 * a, 0.22 * a);
	hazeSprite = sprite(256, top, 0.55 * a, 0.22 * a);
	gridStyle = columnFade(grid, dark ? 0.55 : 0.45);
	horizonStyle = columnFade(mix(top, grid, 0.3), dark ? 0.85 : 0.7);
	starStyle = rgba(star, 1);
}

function size() {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	build();
	stars = Math.min(MAX_STARS, Math.round(STAR_COUNT * Math.max(0.5, w * h / (1440 * 900))));
	for (let i = 0; i < stars; i++) {
		sx[i] = Math.random() * w;
		sy[i] = Math.pow(Math.random(), 1.2) * horizonY * 0.92;
		ss[i] = Math.random() < 0.15 ? 2 : 1;
		sp[i] = 0.5 + Math.random() * 1.5;
		sph[i] = Math.random() * TAU;
		sa[i] = (0.35 + Math.random() * 0.65) * calm(sx[i]);
	}
}

function frame(now) {
	requestAnimationFrame(frame);
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	if (!w || !h) return;
	const motion = reduced ? REDUCED_SPEED : 1;
	stripePhase = (stripePhase + STRIPE_SPEED * motion * dt) % 1000;
	gridPhase = (gridPhase + GRID_SPEED * motion * dt) % 1;
	pulseT = (pulseT + PULSE_SPEED * motion * dt) % 1000;
	ctx.clearRect(0, 0, w, h);
	ctx.globalCompositeOperation = 'source-over';

	// Stars, dimmer near the horizon and behind the column
	ctx.fillStyle = starStyle;
	const starA = dark ? 0.8 : 0.35;
	for (let i = 0; i < stars; i++) {
		const tw = 0.45 + 0.55 * Math.abs(Math.sin(now / 1000 * sp[i] * (reduced ? 0.25 : 1) + sph[i]));
		ctx.globalAlpha = starA * sa[i] * tw * (1 - sy[i] / horizonY * 0.7);
		ctx.fillRect(sx[i], sy[i], ss[i], ss[i]);
	}

	// Glow and haze, swelling a little when the cursor lingers near the sun
	mouse.amount = Math.max(0, mouse.amount - dt * 0.5);
	const dx = mouse.x - sunX, dy = mouse.y - horizonY;
	const near = Math.max(0, 1 - Math.sqrt(dx * dx + dy * dy) / (sunR * 3)) * mouse.amount * CURSOR_GLOW;
	mouse.boost += (near - mouse.boost) * Math.min(1, dt * 2);
	const pulse = 0.85 + 0.15 * Math.sin(pulseT * TAU / 4);
	ctx.globalCompositeOperation = dark ? 'lighter' : 'source-over';
	ctx.globalAlpha = Math.min(1, GLOW * pulse * 0.7 + mouse.boost * 0.35);
	const gr = sunR * 3.6;
	ctx.drawImage(glowSprite, sunX - gr, horizonY - sunR * 0.4 - gr, gr * 2, gr * 2);
	ctx.globalAlpha = Math.min(1, GLOW * 0.55);
	ctx.drawImage(hazeSprite, sunX - w * 0.25, horizonY - h * 0.08, w * 0.5, h * 0.16);
	ctx.globalCompositeOperation = 'source-over';

	// Sun: the cached body, with stripes cut out of its lower half each frame
	const s = sunCut.width;
	sunG.setTransform(1, 0, 0, 1, 0, 0);
	sunG.globalCompositeOperation = 'source-over';
	sunG.clearRect(0, 0, s, s);
	sunG.drawImage(sunBody, 0, 0);
	if (STRIPES > 0) {
		sunG.globalCompositeOperation = 'destination-out';
		sunG.fillStyle = '#000';
		const gap = sunR * 0.8 / STRIPES;
		for (let k = -1; k < STRIPES; k++) {
			const y = sunR * 0.6 + k * gap + (stripePhase % gap);
			const t = (y - sunR * 0.55) / (sunR * 0.8);
			if (t <= 0) continue;
			const thick = gap * (0.1 + 0.5 * t);
			sunG.fillRect(0, (y - thick / 2) * dpr + 2, s, thick * dpr);
		}
	}
	const lift = sunR * 0.35;
	ctx.save();
	ctx.beginPath();
	ctx.rect(sunX - sunR - 2, horizonY - sunR * 2, sunR * 2 + 4, sunR * 2);
	ctx.clip();
	ctx.globalAlpha = dark ? 0.95 : 0.8;
	ctx.drawImage(sunCut, sunX - sunR - 2 / dpr, horizonY - sunR - lift - 2 / dpr, s / dpr, s / dpr);
	ctx.restore();

	// Horizon line
	ctx.globalAlpha = 1;
	ctx.strokeStyle = horizonStyle;
	ctx.lineWidth = 1.5;
	ctx.beginPath();
	ctx.moveTo(0, horizonY);
	ctx.lineTo(w, horizonY);
	ctx.stroke();

	// Grid: lines from a vanishing point under the sun, rows rolling toward the viewer
	const depth = h - horizonY;
	ctx.strokeStyle = gridStyle;
	ctx.lineWidth = 1;
	ctx.globalAlpha = 0.8;
	ctx.beginPath();
	const spread = w * 2.4;
	for (let i = 0; i <= GRID_LINES; i++) {
		const bx = sunX + (i / GRID_LINES - 0.5) * spread;
		ctx.moveTo(sunX + (bx - sunX) * 0.04, horizonY);
		ctx.lineTo(bx, h);
	}
	ctx.stroke();
	for (let r = 0; r < 12; r++) {
		const z = (r + 1 - gridPhase) / 12;
		const y = horizonY + depth * z * z;
		ctx.globalAlpha = Math.min(1, z * 1.6) * 0.85;
		ctx.beginPath();
		ctx.moveTo(0, y);
		ctx.lineTo(w, y);
		ctx.stroke();
	}
	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			size();
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas) size();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.amount = 1;
			break;
	}
};

/**
 * Title: Rose Window (WebGL)
 * Description: A cathedral rose window of mirrored Voronoi glass in your theme's accents glows in the margin beside the chat, lit by a slow sunbeam that the cursor tilts, with dust motes drifting in the light.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const SYMMETRY      = 10;    // how many mirrored wedges the window folds into (4-24)
const CELL_SCALE    = 7;     // density of the glass panes (2-12)
const RING_COUNT    = 3.5;   // how many concentric lead rings cross the window (1-8)
const WINDOW_SIZE   = 0.4;   // window radius as a share of the screen's height; it shrinks to fit the margin (0.2-0.5)
const SHAFT_WIDTH   = 0.16;  // width of the sunbeam (0.05-0.4)
const SHAFT_SPEED   = 0.05;  // how fast the sunbeam sweeps back and forth; 0 holds it (0-0.3)
const REDUCED_SPEED = 0.2;   // share of the motion kept when the viewer asks to reduce motion (0-1)
const SHIMMER       = 1;     // how much the panes brighten and dim on their own (0-2)
const DUST_AMOUNT   = 1;     // brightness of the dust motes in the beam (0-2)
const CURSOR_TILT   = 1;     // how far the cursor tilts the sunbeam (0-2)
const PALETTE_SHIFT = 0;     // rotates the pane colors (0-1)
const CENTER_CALM   = 0.85;  // how much the beam and motes fade behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const RENDER_SCALE  = 1;     // resolution of the window; lower trades crisp lead lines for speed (0.4-1)
const MAX_FPS       = 30;    // frame cap; the light moves slowly (15-60)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform float u_angle;',
	'uniform vec3 u_win;',
	'uniform vec3 u_c1;',
	'uniform vec3 u_c2;',
	'uniform vec3 u_c3;',
	'uniform vec3 u_lead;',
	'uniform vec3 u_beam;',
	'uniform float u_theme;',
	'uniform float u_dark;',
	'uniform vec2 u_col;',
	'const float WR = 0.42;',
	'float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }',
	'vec2 hash2(vec2 p) { return vec2(hash(p), hash(p + 17.31)); }',
	'float noise(vec2 p) {',
	'	vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);',
	'	return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);',
	'}',
	'float fbm(vec2 p) { float v = 0.0, a = 0.5; mat2 m = mat2(1.6, 1.2, -1.2, 1.6); for (int i = 0; i < 4; i++) { v += a * noise(p); p = m * p; a *= 0.5; } return v; }',
	'vec3 voronoi(vec2 p) {',
	'	vec2 i = floor(p), f = fract(p);',
	'	float f1 = 8.0, f2 = 8.0, id = 0.0;',
	'	for (int y = -1; y <= 1; y++) {',
	'		for (int x = -1; x <= 1; x++) {',
	'			vec2 g = vec2(float(x), float(y));',
	'			vec2 r = g + hash2(i + g) - f;',
	'			float d = dot(r, r);',
	'			if (d < f1) { f2 = f1; f1 = d; id = hash(i + g + 3.1); } else if (d < f2) { f2 = d; }',
	'		}',
	'	}',
	'	return vec3(sqrt(f1), sqrt(f2), id);',
	'}',
	// Jewel tones: the artist's cosine palette, or the theme's three accents
	'vec3 pane(float x) {',
	'	vec3 own = pow(vec3(0.5) + vec3(0.5) * cos(6.2831853 * (x + vec3(0.0, 0.33, 0.67))), vec3(1.6)) * 1.2;',
	'	float k = floor(fract(x) * 6.0);',
	'	vec3 th = k < 1.0 ? u_c1 : (k < 2.0 ? mix(u_c1, u_c2, 0.5) : (k < 3.0 ? u_c2 : (k < 4.0 ? mix(u_c2, u_c3, 0.5) : (k < 5.0 ? u_c3 : mix(u_c3, u_c1, 0.5)))));',
	'	th *= 0.7 + 0.45 * fract(x * 7.0);',
	'	return mix(own, th, u_theme);',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	float t = u_time;',
	'	vec2 cen = vec2(u_win.x, res.y - u_win.y);',
	'	vec2 c = (px - cen) / u_win.z * WR;',
	'	float r = length(c);',
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.55, 1.25, band));',
	'	vec2 sd = vec2(cos(u_angle), sin(u_angle));',
	'	float pc = dot(c, vec2(-sd.y, sd.x));',
	'	float along = dot(c, sd);',
	'	float SW = ' + SHAFT_WIDTH.toFixed(3) + ';',
	'	float shaft = smoothstep(SW, SW * 0.15, abs(pc)) * (0.55 + 0.45 * fbm(vec2(along * 3.0 - t * 0.12, pc * 7.0)));',
	'	vec4 o = vec4(0.0);',
	'	vec3 tint = (u_c1 + u_c2 + u_c3) / 3.0;',
	'	float halo = exp(-max(r - WR, 0.0) * 9.0) * step(WR, r) * mix(0.10, 0.22, u_dark);',
	'	o = vec4(tint * halo, halo);',
	'	float spread = smoothstep(-0.05, 0.1, along) * exp(-max(along, 0.0) * 0.9) * step(WR * 0.98, r);',
	'	float ba = shaft * spread * calm * mix(0.06, 0.15, u_dark);',
	'	o = vec4(u_beam * ba, ba) + o * (1.0 - ba);',
	'	float mote = 0.0;',
	'	vec2 p = px / res.y;',
	'	for (int i = 0; i < 2; i++) {',
	'		float fi = float(i);',
	'		vec2 mp = p * (46.0 + fi * 30.0) + vec2(t * (1.5 + fi) * 0.4, -t * (0.8 + fi * 0.5) * 0.4);',
	'		vec2 mid = floor(mp);',
	'		float md = length(fract(mp) - (0.2 + 0.6 * hash2(mid)));',
	'		mote += smoothstep(0.12, 0.0, md) * step(0.85, hash(mid + 5.1)) * (0.5 + 0.5 * sin(t * 1.5 + hash(mid) * 30.0));',
	'	}',
	'	float ma = mote * shaft * spread * calm * calm * 0.8 * ' + DUST_AMOUNT.toFixed(3) + ' * mix(0.6, 1.0, u_dark);',
	'	if (r < WR * 1.03) {',
	'		float seg = 6.2831853 / ' + SYMMETRY.toFixed(1) + ';',
	'		float wa = mod(atan(c.y, c.x), seg);',
	'		float fa = abs(wa - seg * 0.5);',
	'		vec2 fp = vec2(cos(fa), sin(fa)) * r;',
	'		vec3 v = voronoi(fp * ' + CELL_SCALE.toFixed(2) + ' + 3.7);',
	'		float lead = 1.0 - smoothstep(0.0, 0.09, v.y - v.x);',
	'		float spoke = 1.0 - smoothstep(0.0025, 0.008, min(wa, seg - wa) * r);',
	'		float nr = fract(r * ' + RING_COUNT.toFixed(2) + ' / WR);',
	'		float ring = 1.0 - smoothstep(0.0025, 0.007, min(nr, 1.0 - nr) * WR / ' + RING_COUNT.toFixed(2) + ');',
	'		float hub = 1.0 - smoothstep(0.02, 0.026, r);',
	'		float leadMask = max(max(lead, hub), max(spoke, ring));',
	'		vec3 col = pane(v.z * 5.0 + ' + PALETTE_SHIFT.toFixed(3) + ');',
	'		float tex = 0.75 + 0.45 * noise(fp * 30.0 + v.z * 40.0);',
	'		float lum = 0.55 + 0.25 * ' + SHIMMER.toFixed(3) + ' * sin(t * 0.3 + v.z * 9.0);',
	'		float lit = lum * tex + shaft * 0.9;',
	'		float inside = smoothstep(WR, WR - 0.004, r);',
	'		float ga = clamp(lit * mix(0.6, 0.62, u_dark), 0.0, 0.95) * inside * (1.0 - leadMask);',
	'		vec3 gc = min(col * mix(1.0, 0.75 + 0.6 * lit, u_dark), vec3(1.0));',
	'		o = vec4(gc * ga, ga) + o * (1.0 - ga);',
	'		float rim = smoothstep(0.014, 0.004, abs(r - WR));',
	'		float la = max(leadMask * inside, rim) * mix(0.7, 0.85, u_dark);',
	'		o = vec4(u_lead * la, la) + o * (1.0 - la);',
	'	}',
	'	o = vec4(mix(u_beam, vec3(1.0), 0.4 * u_dark) * ma, ma) + o * (1.0 - ma);',
	'	o = clamp(o, 0.0, 1.0);',
	'	gl_FragColor = vec4(min(o.rgb, vec3(o.a)), o.a);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
const loc = {};
let w = 0, h = 0, dpr = 1;
let last = 0, time = 0, phase = 0, reduced = false, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0, lean: 0 };
const win = { x: -1, y: 0, r: 0 };
const colors = { c1: [1, 1, 1], c2: [1, 1, 1], c3: [1, 1, 1], lead: [0.02, 0.02, 0.02], beam: [1, 0.9, 0.7], theme: 0, dark: 1 };

function mix3(a, b, k) { return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]; }

// Panes in the accents, lead in the theme's darkest tone, the beam a warm white on dark themes
function applyTheme(t) {
	if (t) colors.dark = t.dark === false ? 0 : 1;
	const dark = colors.dark === 1;
	const follow = FOLLOW_THEME && t && t.rgb;
	colors.theme = follow ? 1 : 0;
	if (follow) {
		colors.c1 = t.rgb.accent;
		colors.c2 = t.rgb.accent2;
		colors.c3 = t.rgb.accent3;
	} else {
		colors.c1 = [0.9, 0.55, 0.2];
		colors.c2 = [0.35, 0.2, 0.8];
		colors.c3 = [0.8, 0.15, 0.3];
	}
	colors.lead = follow ? (dark ? mix3(t.rgb.background, [0, 0, 0], 0.8) : t.rgb.text) : (dark ? [0.02, 0.018, 0.016] : [0.15, 0.13, 0.12]);
	colors.beam = dark ? (follow ? mix3(t.rgb.text, t.rgb.accent, 0.2) : [1, 0.9, 0.7]) : (follow ? t.rgb.accent : [0.75, 0.5, 0.2]);
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_angle', 'u_win', 'u_c1', 'u_c2', 'u_c3', 'u_lead', 'u_beam', 'u_theme', 'u_dark', 'u_col'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

// Lead lines are line art, so the window follows the pixel ratio up to 1.5
function size() {
	const s = RENDER_SCALE * Math.min(dpr, 1.5);
	canvas.width = Math.max(1, Math.round(w * s));
	canvas.height = Math.max(1, Math.round(h * s));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

// The window fills the wider margin beside the chat column, measured inside the chat area so the sidebar can't cover it, cropped at the area's edge when the margin is narrow
function placeWindow(dt) {
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const left = colX() - colHalf() - lo, right = hi - colX() - colHalf();
	const room = Math.max(left, right);
	const r = Math.min(h * WINDOW_SIZE, Math.max(room * 0.85, h * 0.26));
	const x = left >= right ? lo + room - r : hi - room + r;
	const k = win.x < 0 ? 1 : Math.min(1, dt * 1.5);
	win.x += (x - win.x) * k;
	win.r += (r - win.r) * k;
	win.y = h * 0.42;
	return left >= right;
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const k = reduced ? REDUCED_SPEED : 1;
	time = (time + dt * k) % 2000;
	phase = (phase + dt * k * SHAFT_SPEED) % 6.2831853;
	mouse.target = Math.max(0, mouse.target - dt * 0.35);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 2);
	const want = w ? (mouse.x / w - 0.5) * mouse.amount * CURSOR_TILT : 0;
	mouse.lean += (want - mouse.lean) * Math.min(1, dt * (reduced ? 0.5 : 1.5));
	const onLeft = placeWindow(dt);
	// The beam falls down and inward from the window, sweeping gently either side of that line
	const base = onLeft ? -1.1 : Math.PI + 1.1;
	const angle = base + (onLeft ? 1 : -1) * (Math.sin(phase) * 0.3) + mouse.lean * 0.9;
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform1f(loc.u_angle, angle);
	gl.uniform3f(loc.u_win, win.x, win.y, Math.max(1, win.r));
	gl.uniform3fv(loc.u_c1, colors.c1);
	gl.uniform3fv(loc.u_c2, colors.c2);
	gl.uniform3fv(loc.u_c3, colors.c3);
	gl.uniform3fv(loc.u_lead, colors.lead);
	gl.uniform3fv(loc.u_beam, colors.beam);
	gl.uniform1f(loc.u_theme, colors.theme);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	const opts = { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' };
	gl = canvas.getContext('webgl2', opts) || canvas.getContext('webgl', opts);
	if (!gl) {
		console.warn('Rose Window: WebGL is not available, so the window is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Rose Window:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Rose Window:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			dpr = d.dpr || 1;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			dpr = d.dpr || dpr;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

/**
 * Title: Sandstorm
 * Description: Sand grains stream sideways at varied depths over low dunes, thickening as soft gust waves roll through; the sand thins behind the chat and parts around the cursor.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const GRAIN_COUNT    = 800;   // sand grains on a 1440 px wide screen (100-1500)
const WIND_SPEED     = 240;   // base wind, in px per second (40-600)
const REDUCED_SPEED  = 0.2;   // share of the wind kept under reduced motion (0-1)
const TURBULENCE     = 1;     // how much the grains bob up and down (0-3)
const GUST_EVERY     = 6;     // average seconds between gust waves; 0 turns them off (0-30)
const GUST_STRENGTH  = 1.4;   // how much a gust speeds and thickens the sand (0-4)
const HAZE           = 0.5;   // dust haze carried by the gusts (0-1)
const DUNE_HEIGHT    = 0.11;  // height of the dunes as a share of the screen; 0 hides them (0-0.2)
const LOW_WEIGHT     = 0.6;   // how much the sand gathers toward the ground (0-1)
const SHELTER        = 150;   // radius of the calm pocket around the cursor, in px (0-400)
const THEME_TINT     = 0.35;  // how far the sand leans toward the theme's colors (0-1)
const CENTER_CALM    = 0.8;   // how much the sand thins behind the chat column (0-1)
const BAND_WIDTH     = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME   = true;  // tint the sand with the theme's palette
const SAND_PALE      = '#e6cf9e';  // palest sand
const SAND_DEEP      = '#a87f4a';  // deepest sand
/* ──────────────────────────────────────────── */

const MAX_GRAINS = 1500, SHADES = 4, MAX_STREAKS = 24, TAU = Math.PI * 2;
const F = (n) => new Float32Array(n);

let canvas, ctx, w = 0, h = 0, last = 0, reduced = false, dark = true, column = null;
let pale = hex(SAND_PALE), deep = hex(SAND_DEEP), tint = null;
let grainSprite = [], hazeSprite, duneCache;
const gx = F(MAX_GRAINS), gy = F(MAX_GRAINS), gz = F(MAX_GRAINS), gs = F(MAX_GRAINS), gph = F(MAX_GRAINS), ga = F(MAX_GRAINS);
const gshade = new Uint8Array(MAX_GRAINS);
let grains = 0;
const kx = F(MAX_STREAKS), ky = F(MAX_STREAKS), kl = F(MAX_STREAKS), klife = F(MAX_STREAKS);
// Two gust waves can roll across at once: centre, width, strength and age
const wave = { x: F(2), width: F(2), power: F(2), age: F(2), wait: 2 };
const mouse = { x: -10000, y: -10000, amount: 0 };
let alphaScale = 1;

function hex(c) { const n = parseInt(c.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function rgba(c, a) { return 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a.toFixed(3) + ')'; }
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }
function band(x) {
	const t = Math.min(1, Math.max(0, (Math.abs(x - colX()) / colHalf() - 0.55) / 0.7));
	return 1 - t * t * (3 - 2 * t);
}

function sprite(size, col, a0, a1) {
	const c = new OffscreenCanvas(size, size), g = c.getContext('2d'), r = size / 2;
	const grad = g.createRadialGradient(r, r, 0, r, r, r);
	grad.addColorStop(0, rgba(col, a0));
	grad.addColorStop(0.45, rgba(col, a1));
	grad.addColorStop(1, rgba(col, 0));
	g.fillStyle = grad;
	g.fillRect(0, 0, size, size);
	return c;
}

function applyTheme(t) {
	if (t) {
		dark = t.dark !== false;
		tint = FOLLOW_THEME && t.colors ? t.colors : null;
	}
	let p = pale, d = deep;
	if (tint) {
		p = mix(p, hex(dark ? tint.text : tint.muted), THEME_TINT * 0.6);
		d = mix(d, hex(tint.accent2), THEME_TINT * 0.6);
	}
	if (!dark) { d = mix(d, [70, 45, 20], 0.45); p = mix(p, d, 0.65); }
	alphaScale = dark ? 1 : 1.3;
	for (let k = 0; k < SHADES; k++) grainSprite[k] = sprite(16, mix(p, d, k / (SHADES - 1)), 1, 0.9);
	hazeSprite = sprite(128, mix(p, d, 0.4), dark ? 0.4 : 0.26, dark ? 0.18 : 0.1);
	if (w) buildDunes(p, d);
}

// Ground, cached and rebuilt on layout: low dust over two soft dune ridges, both quieter behind the column
function buildDunes(p, d) {
	const ch = Math.max(2, Math.round(h * 0.32)), dh = Math.round(h * DUNE_HEIGHT);
	duneCache = new OffscreenCanvas(Math.max(1, Math.round(w)), ch);
	const g = duneCache.getContext('2d');
	let grad = g.createLinearGradient(0, 0, 0, ch);
	grad.addColorStop(0, rgba(p, 0));
	grad.addColorStop(1, rgba(mix(p, d, 0.5), dark ? 0.16 : 0.12));
	g.fillStyle = grad;
	g.fillRect(0, 0, w, ch);
	g.globalCompositeOperation = 'destination-out';
	grad = g.createLinearGradient(0, 0, w, 0);
	const cut = rgba([0, 0, 0], CENTER_CALM * 0.8), none = 'rgba(0,0,0,0)', m = colX() / w, i0 = colHalf() * 0.55 / w, o0 = colHalf() * 1.25 / w;
	const at = (u) => Math.min(1, Math.max(0, u));
	grad.addColorStop(at(m - o0), none);
	grad.addColorStop(at(m - i0), cut);
	grad.addColorStop(at(m + i0), cut);
	grad.addColorStop(at(m + o0), none);
	g.fillStyle = grad;
	g.fillRect(0, 0, w, ch);
	g.globalCompositeOperation = 'source-over';
	g.translate(0, ch - dh - 1);
	for (let l = 0; l < 2 && dh > 0; l++) {
		grad = g.createLinearGradient(0, 0, 0, dh);
		const c = mix(d, dark ? [0, 0, 0] : d, l ? 0.35 : 0.1);
		grad.addColorStop(0, rgba(c, (dark ? 0.32 : 0.22) + l * 0.12));
		grad.addColorStop(1, rgba(c, (dark ? 0.12 : 0.08) + l * 0.08));
		g.fillStyle = grad;
		g.beginPath();
		g.moveTo(0, dh + 1);
		const seed = l * 3.1 + Math.random() * 6;
		for (let x = 0; x <= w; x += 8) {
			const u = x / (420 - l * 120) + seed;
			const ridge = 0.5 + 0.35 * Math.sin(u) + 0.15 * Math.sin(u * 2.7 + 1.3);
			const sag = 1 - 0.75 * CENTER_CALM * band(x);
			g.lineTo(x, dh - dh * (l ? 0.55 : 0.95) * ridge * sag);
		}
		g.lineTo(w, dh + 1);
		g.closePath();
		g.fill();
	}
}

// Grains weigh toward the ground; nearer grains are larger, faster and brighter
function resetGrain(i, anywhere) {
	const z = Math.random();
	gz[i] = 0.35 + z * 0.65;
	gs[i] = 0.5 + z * z * 1.5;
	gx[i] = anywhere ? Math.random() * w : -10 - Math.random() * 60;
	gy[i] = h * (1 - Math.pow(Math.random(), 1 + LOW_WEIGHT * 1.6) * 1.02);
	gph[i] = Math.random() * TAU;
	ga[i] = 0.35 + Math.random() * 0.5;
	gshade[i] = Math.floor(Math.random() * SHADES);
}

function size() {
	canvas.width = Math.max(1, Math.round(w));
	canvas.height = Math.max(1, Math.round(h));
	grains = Math.min(MAX_GRAINS, Math.round(GRAIN_COUNT * Math.max(0.4, w / 1440) * Math.max(0.6, h / 900)));
	for (let i = 0; i < grains; i++) resetGrain(i, true);
	klife.fill(0);
	applyTheme(null);
}

function frame(now) {
	requestAnimationFrame(frame);
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	if (!w || !h) return;
	const motion = reduced ? REDUCED_SPEED : 1;
	const t = now / 1000;

	// Gust waves: born upwind, rolling faster than the sand, swelling then fading
	if (GUST_EVERY > 0 && !reduced) {
		wave.wait -= dt;
		if (wave.wait <= 0) {
			const k = wave.age[0] > wave.age[1] ? 0 : 1;
			wave.x[k] = -w * 0.3; wave.width[k] = w * (0.18 + Math.random() * 0.15);
			wave.power[k] = GUST_STRENGTH * (0.6 + Math.random() * 0.4); wave.age[k] = 0;
			wave.wait = GUST_EVERY * (0.6 + Math.random() * 0.8);
		}
	}
	for (let k = 0; k < 2; k++) {
		wave.age[k] += dt;
		wave.x[k] += WIND_SPEED * 1.5 * motion * dt;
		if (wave.x[k] > w * 1.4) wave.power[k] = 0;
	}

	ctx.clearRect(0, 0, w, h);
	ctx.globalCompositeOperation = 'source-over';

	// Haze carried by each wave, kept low and out of the column
	for (let k = 0; k < 2; k++) {
		const pw = wave.power[k] * Math.min(1, wave.age[k] / 1.5);
		if (pw < 0.02 || HAZE <= 0) continue;
		const x = wave.x[k];
		ctx.globalAlpha = Math.min(1, pw * HAZE * 0.9) * (1 - CENTER_CALM * band(x));
		ctx.drawImage(hazeSprite, x - wave.width[k] * 1.4, h * 0.45, wave.width[k] * 2.8, h * 0.65);
	}

	if (duneCache) { ctx.globalAlpha = 1; ctx.drawImage(duneCache, 0, h - duneCache.height); }

	// Grains
	mouse.amount = Math.max(0, mouse.amount - dt * 0.6);
	const shelter = SHELTER * mouse.amount, sh2 = shelter * shelter;
	const wx0 = wave.x[0], wx1 = wave.x[1], ww0 = 1 / Math.max(1, wave.width[0]), ww1 = 1 / Math.max(1, wave.width[1]);
	const p0 = wave.power[0] * Math.min(1, wave.age[0] / 1.5), p1 = wave.power[1] * Math.min(1, wave.age[1] / 1.5);
	for (let i = 0; i < grains; i++) {
		const d0 = (gx[i] - wx0) * ww0, d1 = (gx[i] - wx1) * ww1;
		const gust = p0 * Math.exp(-d0 * d0) + p1 * Math.exp(-d1 * d1);
		const v = WIND_SPEED * gz[i] * (1 + gust) * motion;
		gx[i] += v * dt;
		gy[i] += Math.sin(t * (1.3 + gz[i]) * motion + gph[i]) * 22 * TURBULENCE * gz[i] * motion * dt;
		if (sh2 > 0) {
			const dx = gx[i] - mouse.x, dy = gy[i] - mouse.y, dd = dx * dx + dy * dy;
			if (dd < sh2 && dd > 1) {
				const dist = Math.sqrt(dd), f = (1 - dist / shelter) * (1 - dist / shelter);
				gx[i] += dx / dist * f * 160 * dt;
				gy[i] += dy / dist * f * 260 * dt;
			}
		}
		if (gx[i] > w + 20 || gy[i] < -20 || gy[i] > h + 20) { resetGrain(i, false); continue; }
		const r = gs[i], len = r * 1.5 + v * 0.045;
		ctx.globalAlpha = Math.min(1, ga[i] * (0.6 + 0.4 * gz[i]) * (0.75 + gust * 0.5) * alphaScale) * (1 - CENTER_CALM * 0.9 * band(gx[i]));
		const th = dark ? r * 0.7 : r * 0.95;
		ctx.drawImage(grainSprite[gshade[i]], gx[i] - len, gy[i] - th, len * 2, th * 2);
	}

	// Streaks inside strong gusts, out to the sides
	for (let s = 0; s < MAX_STREAKS; s++) {
		if (klife[s] <= 0) {
			const k = p0 > p1 ? 0 : 1, pw = Math.max(p0, p1);
			if (reduced || pw < 0.6 || Math.random() > pw * dt * 3) continue;
			kx[s] = wave.x[k] + (Math.random() - 0.5) * wave.width[k];
			ky[s] = h * (0.35 + Math.random() * 0.6);
			kl[s] = 60 + Math.random() * 160;
			klife[s] = 1;
		}
		klife[s] -= dt * 1.4;
		kx[s] += WIND_SPEED * 2.2 * motion * dt;
		ctx.globalAlpha = Math.max(0, Math.sin(klife[s] * Math.PI)) * (1 - CENTER_CALM * band(kx[s]));
		ctx.drawImage(hazeSprite, kx[s] - kl[s], ky[s] - 3, kl[s], 6);
	}
	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			size();
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width; h = d.height;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas) applyTheme(null);
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.amount = 1;
			break;
	}
};

/**
 * Title: Snow Globe
 * Description: Snow in three depths drifts down the sides of the screen on a slow breeze, a few large flakes turn as crystals and glint, a moving cursor swirls the flakes, and a thin drift settles along the bottom edge.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const FLAKE_COUNT   = 170;   // snowflakes in the air (30-500)
const FLAKE_SIZE    = 1;     // size of the flakes (0.5-2)
const FALL_SPEED    = 55;    // falling speed of a mid-depth flake, in px per second (10-160)
const BREEZE        = 1;     // strength of the slow sideways breeze (0-3)
const CRYSTALS      = 0.4;   // share of near flakes drawn as six-armed crystals (0-1)
const GLINTS        = 1;     // how often flakes catch the light (0-3)
const SWIRL         = 1;     // how strongly a moving cursor swirls the snow (0-3)
const DRIFT_HEIGHT  = 6;     // tallest the drift along the bottom grows, in px; 0 turns it off (0-12)
const OPACITY       = 0.85;  // flake strength (0.2-1)
const MOTION        = 1;     // overall speed (0.2-2)
const REDUCED_SPEED = 0.25;  // speed kept when the viewer asks to reduce motion (0-1)
const CENTER_CALM   = 0.75;  // how much the snow thins behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const SNOW_COLOR    = '#f2f6ff';  // flake color when not following the theme
const GLINT_COLOR   = '#bfe0ff';  // glint color when not following the theme
/* ──────────────────────────────────────────── */

const N = FLAKE_COUNT, COL = 8;
let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, time = 0, reduced = false, dark = true, column = null;
