	const snap = dpr < 1.5 ? 0.5 : 0;
	const offX = Math.round((w - (cols - 1) * SPACING) / 2) + snap, offY = Math.round((h - (rows - 1) * SPACING) / 2) + snap;
	let i = 0;
	for (let c = 0; c < cols; c++) {
		for (let r = 0; r < rows; r++, i++) {
			ox[i] = px[i] = offX + c * SPACING;
			oy[i] = py[i] = offY + r * SPACING;
		}
