// Each point's calm and resting alpha step, from where the chat column sits; rebuilt on layout
function calmBuild() {
	for (let i = 0; i < count; i++) {
		calm[i] = band(ox[i]);
		lvl[i] = Math.round(((calm[i] - (1 - CENTER_CALM)) / Math.max(0.001, CENTER_CALM)) * (LEVELS - 1));
