			ctx.globalAlpha = peak * (b + 1) / 3;
			ctx.beginPath();
			for (let i = 0; i < count; i++) {
				const act = activity(i);
				if (act < 0.08 || accentOf(i) !== a) continue;
				if (Math.min(2, Math.floor(act * calm[i] * 3)) !== b) continue;
				cross(i, CROSS_SIZE + act * 2);
			}
