}

function rgba(c, a, lift) {
	const r = Math.round(c[0] + (255 - c[0]) * lift), g = Math.round(c[1] + (255 - c[1]) * lift), b = Math.round(c[2] + (255 - c[2]) * lift);
	return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';
}

// One soft glow per color, rebuilt on theme change
function buildSprites() {
	for (let i = 0; i < NCOL; i++) {
		const c = hexToRgb(palette[i]);
		const s = sprites[i] || new OffscreenCanvas(SPRITE, SPRITE);
		const g = s.getContext('2d');
		g.clearRect(0, 0, SPRITE, SPRITE);
		const grad = g.createRadialGradient(SPRITE / 2, SPRITE / 2, 0, SPRITE / 2, SPRITE / 2, SPRITE / 2);
		if (dark) {
			grad.addColorStop(0, rgba(c, 1, 0.8));
			grad.addColorStop(0.12, rgba(c, 1, 0.45));
			grad.addColorStop(0.3, rgba(c, 0.55, 0.05));
			grad.addColorStop(0.6, rgba(c, 0.14, 0));
		} else {
			grad.addColorStop(0, rgba(c, 1, 0));
			grad.addColorStop(0.22, rgba(c, 0.95, 0));
			grad.addColorStop(0.4, rgba(c, 0.35, 0));
			grad.addColorStop(0.65, rgba(c, 0.06, 0));
		}
		grad.addColorStop(1, rgba(c, 0, 0));
		g.fillStyle = grad;
		g.fillRect(0, 0, SPRITE, SPRITE);
		sprites[i] = s;
	}
}

function applyTheme(t) {
	if (!t) return;
	dark = t.dark !== false;
	if (FOLLOW_THEME && t.colors) {
		const c = t.colors;
		palette = [c.accent, c.accent2, c.accent3, dark ? c.text : c.accent];
	}
	if (ctx) buildSprites();
}

function size(oldW, oldH) {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	calmBuild();
	if (!oldW) return;
	// Keep the show in place on the resized screen
	const sx = w / oldW, sy = h / oldH;
	for (let i = 0; i < count; i++) { px[i] *= sx; py[i] *= sy; }
	for (let i = 0; i < MAX_ROCKETS; i++) { rx[i] *= sx; ry[i] *= sy; bx[i] *= sx; by[i] *= sy; }
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

// The calm table, from where the chat column sits; rebuilt on resize and layout
function calmBuild() {
	calmLut = new Float32Array((w >> 2) + 2);
	for (let i = 0; i < calmLut.length; i++) {
		const d = Math.abs(i * 4 - colX()) / colHalf();
		const t = Math.min(1, Math.max(0, (d - 0.55) / 0.7));
		calmLut[i] = 1 - CENTER_CALM * (1 - t * t * (3 - 2 * t));
	}
}

// A spot beside the chat column, on the side with room, inside the chat area so the sidebar can't cover it, kept off its very edge
function besideX() {
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const left = Math.max(0, colX() - colHalf() - lo), right = Math.max(0, hi - colX() - colHalf());
	if (left + right < 60) return Math.random() < 0.5 ? lo + w * (0.04 + Math.random() * 0.17) : hi - w * (0.04 + Math.random() * 0.17);
	const r = Math.random() * (left + right);
	return Math.max(lo + w * 0.03, Math.min(hi - w * 0.03, r < left ? lo + r * 0.85 : hi - (r - left) * 0.85));
}

function calm(x) {
	const i = x >> 2;
	return calmLut[i < 0 ? 0 : i >= calmLut.length ? calmLut.length - 1 : i];
}

function burst(x, y, power, c, gentle) {
	const n = Math.round(BURST_SIZE * power * (gentle ? 0.4 : 1));
	const speed = SPREAD * (0.6 + 0.4 * power) * (gentle ? 0.45 : 1);
	const ring = Math.random() < 0.3;
	const b = bnext; bnext = (bnext + 1) % MAX_ROCKETS;
	bx[b] = x; by[b] = y; bage[b] = 0; bpow[b] = power * (gentle ? 0.6 : 1); bcol[b] = c;
	for (let i = 0; i < n && count < MAX_SPARKS; i++) {
		const glitter = i % 4 === 3, willow = !glitter && i % 5 === 0;
		const a = (i / n) * 6.2832 + Math.random() * 0.4;
		const v = speed * (ring && !glitter ? 0.92 + Math.random() * 0.08 : 0.45 + Math.random() * 0.55);
		const k = count++;
		px[k] = x; py[k] = y;
		vx[k] = Math.cos(a) * v; vy[k] = Math.sin(a) * v - speed * 0.12;
		span[k] = life[k] = SPARK_LIFE * (glitter ? 0.7 + Math.random() * 0.6 : willow ? 1.8 + Math.random() * 0.6 : 0.6 + Math.random() * 0.5);
		sz[k] = (glitter ? 14 : 22 + power * 8) * GLOW * (0.8 + Math.random() * 0.4);
		col[k] = glitter || willow ? 3 : c;
		kind[k] = glitter ? 1 : willow ? 2 : 0;
	}
}

function launch() {
	for (let i = 0; i < MAX_ROCKETS; i++) {
		if (ron[i]) continue;
		rx[i] = besideX();
		ry[i] = h + 6;
		const rise = h * (0.5 + Math.random() * 0.3);
		rvy[i] = -Math.sqrt(2 * 420 * rise);
		rcol[i] = Math.floor(Math.random() * 3);
		ron[i] = 1;
		return;
	}
}

// Reduced motion: no rockets, only a slow bloom that opens in place
function bloom() {
	burst(besideX(), h * (0.2 + Math.random() * 0.4), 1.4, Math.floor(Math.random() * 3), true);
}

function frame(now) {
	requestAnimationFrame(frame);
	const real = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const dt = real * MOTION * (reduced ? REDUCED_SPEED : 1);
	time += dt;
	ctx.clearRect(0, 0, w, h);

	if (IDLE_EVERY > 0) {
		idleWait -= real;
		if (idleWait <= 0) {
			if (reduced) bloom(); else launch();
			idleWait = IDLE_EVERY * (reduced ? 1.6 : 1) * (0.6 + Math.random() * 0.8);
		}
	}

	const drag = Math.exp(-1.3 * dt), grav = (reduced ? 0.15 : 1) * GRAVITY * dt;
	const op = dark ? 'lighter' : 'source-over', base = dark ? 0.95 : 0.9;
	ctx.globalCompositeOperation = op;

	// Rockets: a bright head with a short fading tail, bursting near the top of the climb
	for (let i = 0; i < MAX_ROCKETS; i++) {
		if (!ron[i]) continue;
		rvy[i] += 420 * dt;
		ry[i] += rvy[i] * dt;
		const s = sprites[rcol[i]], a = base * 0.8 * calm(rx[i]);
		for (let t = 3; t >= 0; t--) {
			ctx.globalAlpha = a * (1 - t * 0.22);
			const d = 14 - t * 2;
			ctx.drawImage(s, rx[i] - d / 2, ry[i] - rvy[i] * t * 0.018 - d / 2, d, d);
		}
		if (rvy[i] > -50) {
			ron[i] = 0;
			burst(rx[i], ry[i], 0.75 + Math.random() * 0.3, rcol[i], false);
		}
	}

	// Blooms swell for a moment, then fade over about a second
	for (let i = 0; i < MAX_ROCKETS; i++) {
		if (bage[i] > 1.4) continue;
		bage[i] += dt;
		const e = bage[i] < 0.12 ? bage[i] / 0.12 : Math.max(0, 1 - (bage[i] - 0.12) / 1.2);
		const d = (90 + 70 * bage[i]) * bpow[i] * GLOW;
		ctx.globalAlpha = (dark ? 0.32 : 0.16) * e * e * calm(bx[i]);
		ctx.drawImage(sprites[bcol[i]], bx[i] - d / 2, by[i] - d / 2, d, d);
	}

	// Sparks: drag, gravity, then a head and a two-step tail along the velocity
	for (let i = 0; i < count; i++) {
		life[i] -= dt;
		if (life[i] <= 0 || py[i] > h + 20) {
			const j = --count;
			px[i] = px[j]; py[i] = py[j]; vx[i] = vx[j]; vy[i] = vy[j];
			life[i] = life[j]; span[i] = span[j]; sz[i] = sz[j]; col[i] = col[j]; kind[i] = kind[j];
			i--;
			continue;
		}
		if (kind[i] === 2) { vx[i] *= drag * drag; vy[i] = vy[i] * drag * drag + grav * 0.5; }
		else { vx[i] *= drag; vy[i] = vy[i] * drag + grav; }
		px[i] += vx[i] * dt; py[i] += vy[i] * dt;
		const f = life[i] / span[i];
		let a = base * Math.pow(f, dark ? 0.6 : 0.45) * calm(px[i]);
		if (kind[i]) a *= (kind[i] === 2 ? 0.6 : 1) * (0.55 + 0.45 * Math.sin(time * (kind[i] === 2 ? 7 : 22) + i * 1.7));
		const s = sprites[col[i]], d = sz[i] * (0.55 + 0.45 * f);
		ctx.globalAlpha = a;
		ctx.drawImage(s, px[i] - d / 2, py[i] - d / 2, d, d);
		if (!kind[i] && !reduced) {
			ctx.globalAlpha = a * 0.45;
			ctx.drawImage(s, px[i] - vx[i] * 0.05 - d * 0.4, py[i] - vy[i] * 0.05 - d * 0.4, d * 0.8, d * 0.8);
			ctx.globalAlpha = a * 0.2;
			ctx.drawImage(s, px[i] - vx[i] * 0.1 - d * 0.3, py[i] - vy[i] * 0.1 - d * 0.3, d * 0.6, d * 0.6);
		}
	}
	ctx.globalAlpha = 1;
	ctx.globalCompositeOperation = 'source-over';
}

function tap(x, y) {
	if (time - lastTap < 0.7 && Math.abs(x - tapX) + Math.abs(y - tapY) < 140) combo = Math.min(COMBO_MAX, combo + 1);
	else combo = 0;
	lastTap = time; tapX = x; tapY = y;
	idleWait = Math.max(idleWait, IDLE_EVERY);
	// Over the chat column (the Send button included) the burst stays small
	const c = calm(x), power = (0.7 + combo * 0.25) * Math.max(0.35, c);
	burst(x, y, power, Math.floor(Math.random() * 3), reduced);
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			buildSprites();
			size(0, 0);
			requestAnimationFrame(frame);
			break;
		case 'resize': {
			const ow = w, oh = h;
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			if (canvas) size(ow, oh);
			break;
		}
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas) calmBuild();
			break;
		case 'mousedown':
			tap(d.x, d.y);
			break;
	}
};

/**
 * Title: Terminator (WebGL)
 * Description: A slowly turning planet beside the chat whose daylight follows your local time, with a warm sunset line, city lights on the night side, drifting clouds, an atmosphere halo and faint stars; moving the cursor across it nudges its spin.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const INTENSITY     = 0.95;  // how strongly the planet shows (0-1)
const SPIN_SPEED    = 0.03;  // how fast the planet turns, in radians per second (0-0.3)
const REDUCED_SPEED = 0.2;   // share of the spin kept when the viewer asks to reduce motion (0-1)
const PREVIEW_CYCLE = 0;     // seconds for one full day as a preview; 0 follows your real local time (0-600)
const GLOBE_SIZE    = 0.3;   // planet radius as a share of the screen height (0.15-0.45)
const CENTER_CALM   = 0.85;  // how much the scene fades behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const STAR_DENSITY  = 0.5;   // faint stars around the planet, dark themes only (0-1)
const CITY_LIGHTS   = 1;     // brightness of the city lights on the night side (0-2)
const CURSOR_SPIN   = 1;     // how much a cursor sweep across the planet turns it (0-3)
const RENDER_SCALE  = 0.75;  // resolution of the scene (0.5-1)
const MAX_FPS       = 30;    // frame cap; the planet turns slowly (15-60)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const OCEAN_COLOR   = '#0a2a5c';  // ocean color when not following the theme
const LAND_COLOR    = '#2f6b2a';  // land color
const CITY_COLOR    = '#ffbf59';  // city lights and sunset line
const ATMO_COLOR    = '#4d80ff';  // atmosphere color
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform float u_dark;',
	'uniform vec3 u_globe;',
	'uniform vec3 u_sun;',
	'uniform vec4 u_rot;',
	'uniform vec2 u_col;',
	'uniform vec3 u_ocean;',
	'uniform vec3 u_land;',
	'uniform vec3 u_city;',
	'uniform vec3 u_atmo;',
	'float hash2(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }',
	'float hash3(vec3 p) { p = fract(p * 0.1031); p += dot(p, p.zyx + 31.32); return fract((p.x + p.y) * p.z); }',
	'float noise3(vec3 p) {',
	'	vec3 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);',
	'	vec2 e = vec2(1.0, 0.0);',
	'	return mix(mix(mix(hash3(i), hash3(i + e.xyy), u.x), mix(hash3(i + e.yxy), hash3(i + e.xxy), u.x), u.y),',
	'		mix(mix(hash3(i + e.yyx), hash3(i + e.xyx), u.x), mix(hash3(i + e.yxx), hash3(i + e.xxx), u.x), u.y), u.z);',
	'}',
	'float fbm3(vec3 p) {',
	'	float v = 0.0, a = 0.5;',
	'	for (int i = 0; i < 5; i++) { v += a * noise3(p); p = p * 2.03 + vec3(1.7, 9.2, 3.4); a *= 0.5; }',
	'	return v;',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float calmSoft = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.55, 1.25, band));',
	'	float calmHard = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.88, 1.0, band));',
	'	vec2 p = (px - u_globe.xy) / u_globe.z;',
	'	float r = length(p);',
	'	vec3 L = u_sun;',
	'	vec2 cell = floor(px / 70.0);',
	'	vec2 sp = (cell + vec2(hash2(cell), hash2(cell + 7.1))) * 70.0;',
	'	float lit = step(1.0 - ' + STAR_DENSITY.toFixed(3) + ' * 0.5, hash2(cell + 3.3));',
	'	float tw = 0.55 + 0.45 * sin(u_time * (0.5 + hash2(cell + 1.9) * 1.5) + hash2(cell) * 6.283);',
	'	float a = lit * tw * smoothstep(1.8, 0.0, length(px - sp)) * u_dark * calmSoft * smoothstep(1.05, 1.3, r) * 0.7;',
	'	vec3 col = vec3(0.86, 0.9, 1.0) * a;',
	'	float side = 0.3 + 0.7 * clamp(0.5 + dot(p / max(r, 0.001), L.xy) * 0.9 + L.z * 0.4, 0.0, 1.0);',
	'	float ha = exp(-max(r - 1.0, 0.0) * 9.0) * step(1.0, r) * side * mix(0.4, 0.6, u_dark);',
	'	col += u_atmo * ha;',
	'	a += ha;',
	'	if (r < 1.0) {',
	'		vec3 n = vec3(p, sqrt(1.0 - r * r));',
	'		float lam = dot(n, L);',
	'		float day = smoothstep(-0.06, 0.25, lam);',
	'		vec3 nr = vec3(n.x * u_rot.x + n.z * u_rot.y, n.y, n.z * u_rot.x - n.x * u_rot.y);',
	'		vec3 nc = vec3(n.x * u_rot.z + n.z * u_rot.w, n.y, n.z * u_rot.z - n.x * u_rot.w);',
	'		float h = fbm3(nr * 2.3);',
	'		float land = smoothstep(0.47, 0.51, h);',
	'		float ice = smoothstep(0.84, 0.92, abs(n.y) + (h - 0.5) * 0.25);',
	'		vec3 ground = mix(u_land * (0.8 + (h - 0.5) * 2.0), u_land * vec3(1.35, 1.05, 0.7), smoothstep(0.6, 0.72, h));',
	'		vec3 surf = mix(u_ocean * (0.7 + h * 0.6), ground, land);',
	'		surf = mix(surf, vec3(0.9, 0.93, 0.97), ice);',
	'		float cl = smoothstep(0.5, 0.76, fbm3(nc * vec3(2.4, 5.2, 2.4) + 4.0));',
	'		surf = mix(surf, vec3(0.92, 0.94, 0.97), cl * 0.65);',
	'		vec3 planet = surf * (mix(0.4, 0.1, u_dark) + day) + u_atmo * (1.0 - day) * 0.04;',
	'		vec3 hv = normalize(L + vec3(0.0, 0.0, 1.0));',
	'		planet += vec3(1.0, 0.95, 0.85) * pow(max(dot(n, hv), 0.0), 48.0) * (1.0 - land) * (1.0 - cl) * day * 0.45;',
	'		float cities = smoothstep(0.5, 0.6, fbm3(nr * 6.0 + 2.0)) * smoothstep(0.56, 0.8, noise3(nr * 60.0)) * smoothstep(0.5, 0.56, h) * (1.0 - ice) * (1.0 - cl * 0.8);',
	'		planet += u_city * cities * (1.0 - day) * ' + CITY_LIGHTS.toFixed(3) + ' * 1.6;',
	'		planet += u_city * exp(-pow(lam * 5.0, 2.0)) * (0.3 - cl * 0.12);',
	'		float fres = pow(1.0 - n.z, 2.5);',
	'		planet += u_atmo * fres * (0.15 + 0.85 * smoothstep(-0.2, 0.5, lam)) * 0.9;',
	'		float ga = mix(mix(0.8, 0.92, u_dark), 1.0, max(day, fres * 0.6)) * smoothstep(1.0, 1.0 - 1.5 / u_globe.z, r);',
	'		col = planet * ga + col * (1.0 - ga);',
	'		a = ga + a * (1.0 - ga);',
	'	}',
	'	float k = calmHard * ' + INTENSITY.toFixed(3) + ';',
	'	a = clamp(a * k, 0.0, 1.0);',
	'	gl_FragColor = vec4(min(col * k, vec3(a)), a);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
let loc = {};
let w = 0, h = 0, dpr = 1;
let last = 0, time = 0, reduced = false, column = null;
let spin = 0, cloudSpin = 0, spinBoost = 0, hour = 12, clock = 0, hourWait = 0;
const globe = { x: -10000, y: 0, r: 100, tx: 0, ty: 0, tr: 100 };
const sun = { x: 0, y: 0, z: 1 };
const mouse = { x: -10000, y: -10000 };
const colors = { ocean: hexToRgb(OCEAN_COLOR), land: hexToRgb(LAND_COLOR), city: hexToRgb(CITY_COLOR), atmo: hexToRgb(ATMO_COLOR), dark: 1 };

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function mixRgb(a, b, t, k) {
	return [(a[0] + (b[0] - a[0]) * t) * k, (a[1] + (b[1] - a[1]) * t) * k, (a[2] + (b[2] - a[2]) * t) * k];
}

function applyTheme(t) {
	if (!t) return;
	colors.dark = t.dark === false ? 0 : 1;
	if (!FOLLOW_THEME || !t.rgb) return;
	const ocean = hexToRgb(OCEAN_COLOR), land = hexToRgb(LAND_COLOR);
	colors.ocean = mixRgb(ocean, mixRgb(t.rgb.accent, t.rgb.accent3, 0.5, 0.45), 0.55, 1);
	colors.land = mixRgb(land, mixRgb(t.rgb.muted, t.rgb.accent3, 0.3, 0.6), 0.35, 1);
	colors.city = mixRgb(t.rgb.accent2, [1, 0.85, 0.55], colors.dark ? 0.6 : 0.2, 1);
	colors.atmo = t.rgb.accent3;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_dark', 'u_globe', 'u_sun', 'u_rot', 'u_col', 'u_ocean', 'u_land', 'u_city', 'u_atmo'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

function size() {
	const k = Math.min(dpr, 2) * RENDER_SCALE;
	canvas.width = Math.max(1, Math.round(w * k));
	canvas.height = Math.max(1, Math.round(h * k));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
	place(true);
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

// The planet sits in the margin beside the column, inside the chat area so the sidebar never covers it.
// A margin too narrow for the whole planet shows its limb rising past the chat area's right edge instead.
function place(now) {
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const mL = Math.max(0, colX() - colHalf() - lo), mR = Math.max(0, hi - colX() - colHalf());
	const r0 = GLOBE_SIZE * h, fitL = Math.min(r0, mL / 2.3);
	if (fitL >= r0 * 0.5 && mL >= mR) {
		globe.tr = fitL;
		globe.tx = lo + mL * 0.5;
	} else if (mR >= r0 * 2.3) {
		globe.tr = r0;
		globe.tx = hi - mR * 0.5;
	} else {
		globe.tr = r0;
		globe.tx = hi + r0 - Math.min(2.2 * r0, mR + 0.3 * r0);
	}
	globe.ty = h * 0.58;
	if (now || globe.x < -9000) { globe.x = globe.tx; globe.y = globe.ty; globe.r = globe.tr; }
}

function readHour() {
	if (PREVIEW_CYCLE > 0) return (clock / PREVIEW_CYCLE * 24) % 24;
	const d = new Date();
	return d.getHours() + d.getMinutes() / 60 + d.getSeconds() / 3600;
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const pace = reduced ? REDUCED_SPEED : 1;
	time = (time + dt * pace) % 3000;
	clock += dt;
	hourWait -= dt;
	if (hourWait <= 0 || PREVIEW_CYCLE > 0) {
		hour = readHour();
		hourWait = 5;
		const lon = (hour - 12) / 24 * Math.PI * 2;
		const len = Math.hypot(1, 0.25);
		sun.x = Math.sin(lon) / len; sun.y = 0.25 / len; sun.z = Math.cos(lon) / len;
	}
	spinBoost *= Math.exp(-dt * 1.2);
	spin = (spin + (SPIN_SPEED + spinBoost) * pace * dt) % (Math.PI * 2);
	cloudSpin = (cloudSpin + (SPIN_SPEED * 1.35 + spinBoost) * pace * dt) % (Math.PI * 2);
	const ease = Math.min(1, dt * 2);
	globe.x += (globe.tx - globe.x) * ease;
	globe.y += (globe.ty - globe.y) * ease;
	globe.r += (globe.tr - globe.r) * ease;
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform3f(loc.u_globe, globe.x, h - globe.y, globe.r);
	gl.uniform3f(loc.u_sun, sun.x, sun.y, sun.z);
	gl.uniform4f(loc.u_rot, Math.cos(spin), Math.sin(spin), Math.cos(cloudSpin), Math.sin(cloudSpin));
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.uniform3fv(loc.u_ocean, colors.ocean);
	gl.uniform3fv(loc.u_land, colors.land);
	gl.uniform3fv(loc.u_city, colors.city);
	gl.uniform3fv(loc.u_atmo, colors.atmo);
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	const opts = { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' };
	gl = canvas.getContext('webgl2', opts) || canvas.getContext('webgl', opts);
	if (!gl) {
		console.warn('Terminator: WebGL is not available, so the planet is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Terminator:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Terminator:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			dpr = d.dpr || 1;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			dpr = d.dpr || dpr;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			place(false);
			break;
		case 'mousemove': {
			const dx = mouse.x > -9000 ? d.x - mouse.x : 0;
			mouse.x = d.x;
			mouse.y = d.y;
			if (Math.hypot(d.x - globe.x, d.y - globe.y) < globe.r * 1.3) {
				spinBoost = Math.max(-0.6, Math.min(0.6, spinBoost + dx / globe.r * 0.4 * CURSOR_SPIN));
			}
			break;
		}
	}
};

/**
 * Title: The Genesis Lattice
 * Description: Conway's Game of Life drawn as a breathing 3D mesh of glowing nodes and bonds in the theme's accent colors, dense at the screen's edges and faint over the chat column; the cursor sows new life and tilts the mesh.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const CELL_SIZE    = 22;     // spacing of the lattice, in px (12-48)
const TICK         = 0.12;   // seconds between generations (0.04-1)
const FADE         = 7;      // how quickly nodes fade in and out (1-20)
const DENSITY      = 0.3;    // share of cells alive at the start, at the edges (0.05-0.5)
const WAVE         = 15;     // height of the breathing wave, in px (0-40)
const WAVE_SPEED   = 1.2;    // speed of the breathing wave (0-4)
const PARALLAX     = 1;      // how far the mesh tilts toward the cursor (0-3)
const NODE_SIZE    = 0.32;   // node radius as a share of the spacing (0.1-0.5)
const FABRIC       = 1;      // strength of the faint mesh of empty cells (0-2)
const RESEED_EVERY = 5;      // seconds between fresh colonies beside the chat column; 0 turns them off (0-120)
const CENTER_CALM  = 0.8;    // how much the mesh thins and fades over the chat column (0-1)
const BAND_WIDTH   = 520;    // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME = true;   // take the colors from the theme's palette
const COLOR_ALIVE  = '#00ffb4'; // color of a living node when not following the theme
const COLOR_DYING  = '#7a3cf0'; // color a node fades through as it dies
/* ──────────────────────────────────────────── */

const K = 5, TAU = Math.PI * 2;
let cols = 0, rows = 0, total = 0, ox = 0, oy = 0;
let grid = new Uint8Array(0), next = new Uint8Array(0), vis = new Float32Array(0), calmOf = new Float32Array(0);
let dist = new Float32Array(0), ptX = new Float32Array(0), ptY = new Float32Array(0);
let canvas, ctx, mask = null, w = 0, h = 0, dpr = 1, last = 0, reduced = false, dark = true, time = 0, acc = 0, reseed = 0, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, px: 0, py: 0 };
const col = { node: [], bond: [], fabric: '' };

function rgbOf(hex) { const n = parseInt(hex.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function css(c) { return 'rgb(' + (c[0] | 0) + ',' + (c[1] | 0) + ',' + (c[2] | 0) + ')'; }
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }
function band(x) { const t = Math.min(1, Math.max(0, (Math.abs(x - colX()) / colHalf() - 0.55) / 0.7)); return 1 - t * t * (3 - 2 * t); }

// K color steps from dying to alive, for nodes and for the bonds between them
function applyTheme(t) {
	if (t) dark = t.dark !== false;
	const th = FOLLOW_THEME && t && t.colors ? t.colors : null;
	let alive = rgbOf(th ? th.accent : COLOR_ALIVE), dying = rgbOf(th ? th.accent2 : COLOR_DYING);
	const muted = rgbOf(th ? th.muted : dark ? '#7a7890' : '#6b7480');
	if (!th && !dark) { alive = mix(alive, [20, 30, 40], 0.45); dying = mix(dying, [20, 30, 40], 0.3); }
	for (let k = 0; k < K; k++) {
		const c = mix(dying, alive, k / (K - 1));
		col.node[k] = css(c);
		col.bond[k] = css(mix(c, muted, 0.35));
	}
	col.fabric = css(mix(muted, alive, 0.3));
}

function size() {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	// The lattice covers the screen plus at most one cell past each edge; life wraps around it
	cols = Math.ceil(w / CELL_SIZE) + 2;
	rows = Math.ceil(h / CELL_SIZE) + 2;
	total = cols * rows;
	ox = (w - (cols - 1) * CELL_SIZE) / 2;
	oy = (h - (rows - 1) * CELL_SIZE) / 2;
	grid = new Uint8Array(total);
	next = new Uint8Array(total);
	vis = new Float32Array(total);
	calmOf = new Float32Array(total);
	dist = new Float32Array(total);
	ptX = new Float32Array(total);
	ptY = new Float32Array(total);
	calmBuild();
	for (let y = 0; y < rows; y++) {
		for (let x = 0; x < cols; x++) {
			const i = y * cols + x, bx = ox + x * CELL_SIZE, by = oy + y * CELL_SIZE;
			dist[i] = Math.hypot(bx - w / 2, by - h / 2) * 0.008;
			grid[i] = vis[i] = Math.random() < DENSITY * (0.25 + 0.75 * calmOf[i]) ? 1 : 0;
		}
	}
}

// The fabric's erase mask and each cell's calm, from where the chat column sits; rebuilt on layout
function calmBuild() {
	mask = ctx.createLinearGradient(0, 0, w, 0);
	for (let i = 0; i <= 24; i++) mask.addColorStop(i / 24, 'rgba(0,0,0,' + (CENTER_CALM * band((w * i) / 24)).toFixed(3) + ')');
	for (let x = 0; x < cols; x++) {
		const c = 1 - CENTER_CALM * band(ox + x * CELL_SIZE);
		for (let y = 0; y < rows; y++) calmOf[y * cols + x] = c;
	}
}

function burst(cx, cy, r, p) {
	for (let dy = -r; dy <= r; dy++) {
		for (let dx = -r; dx <= r; dx++) {
			if (Math.random() >= p) continue;
			grid[((cy + dy + rows) % rows) * cols + ((cx + dx + cols) % cols)] = 1;
		}
	}
}

// A fresh colony beside the chat column, on the side with room, inside the chat area so the sidebar can't cover it
function outerBurst() {
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const c0 = Math.max(0, Math.ceil((lo - ox) / CELL_SIZE)), c1 = Math.min(cols, Math.floor((hi - ox) / CELL_SIZE) + 1);
	const lc = Math.floor((colX() - colHalf() - ox) / CELL_SIZE), rc = Math.ceil((colX() + colHalf() - ox) / CELL_SIZE);
	const left = Math.max(0, lc - c0 - 2), right = Math.max(0, c1 - 3 - rc), y = Math.floor(Math.random() * rows);
	if (left + right < 4) {
		const e = Math.floor(Math.random() * (c1 - c0) * 0.28);
		burst(Math.random() < 0.5 ? c0 + e + 2 : c1 - 3 - e, y, 6, 0.4);
		return;
	}
	const r = Math.floor(Math.random() * (left + right));
	burst(r < left ? c0 + 2 + r : c1 - 3 - (r - left), y, 6, 0.4);
}

// One generation: birth on 3, survival on 2 or 3; the column thins a little each step
function step() {
	let pop = 0;
	for (let y = 0; y < rows; y++) {
		const up = (y ? y - 1 : rows - 1) * cols, mid = y * cols, dn = (y < rows - 1 ? y + 1 : 0) * cols;
		for (let x = 0; x < cols; x++) {
			const l = x ? x - 1 : cols - 1, r = x < cols - 1 ? x + 1 : 0;
			const n = grid[up + l] + grid[up + x] + grid[up + r] + grid[mid + l] + grid[mid + r] + grid[dn + l] + grid[dn + x] + grid[dn + r];
			const i = mid + x;
			let v = n === 3 || (n === 2 && grid[i]) ? 1 : 0;
			if (v && Math.random() < (1 - calmOf[i]) * 0.08) v = 0;
			next[i] = v;
			pop += v;
		}
	}
	const t = grid;
	grid = next;
	next = t;
	if (pop < total * 0.05) outerBurst();
}

// The cell under a screen point, undoing the tilt and the wave
function cellAt(sx, sy) {
	let gx = Math.round((sx - ox) / CELL_SIZE), gy = Math.round((sy - oy) / CELL_SIZE);
	if (gx < 0 || gy < 0 || gx >= cols || gy >= rows) return -1;
	const i = gy * cols + gx;
	gx = Math.round((sx - (ptX[i] - (ox + gx * CELL_SIZE)) - ox) / CELL_SIZE);
	gy = Math.round((sy - (ptY[i] - (oy + gy * CELL_SIZE)) - oy) / CELL_SIZE);
	return gx < 0 || gy < 0 || gx >= cols || gy >= rows ? -1 : gy * cols + gx;
}

function frame(now) {
	requestAnimationFrame(frame);
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const sdt = dt * (reduced ? 0.2 : 1);
	time = (time + sdt * WAVE_SPEED) % (TAU * 100);
	mouse.amount = Math.max(0, mouse.amount - dt * 0.5);
	// The tilt follows a moving cursor and settles back to level once it rests
	const tx = mouse.amount > 0 ? mouse.x - w / 2 : 0, ty = mouse.amount > 0 ? mouse.y - h / 2 : 0, ease = Math.min(1, dt * (mouse.amount > 0 ? 3 : 0.8));
	mouse.px += (tx - mouse.px) * ease;
	mouse.py += (ty - mouse.py) * ease;

	acc += sdt;
	if (acc >= TICK) {
		acc = Math.min(acc - TICK, TICK);
		if (mouse.amount > 0.5 && !reduced) {
			const c = cellAt(mouse.x, mouse.y);
			if (c >= 0) { grid[c] = 1; grid[(c + 1) % total] = Math.random() < 0.5 ? 1 : 0; grid[(c + cols) % total] = Math.random() < 0.5 ? 1 : 0; }
		}
		step();
	}
	if (RESEED_EVERY > 0 && (reseed += sdt) >= RESEED_EVERY) { reseed = 0; outerBurst(); }

	const f = 1 - Math.exp(-FADE * dt * (reduced ? 0.5 : 1)), par = 0.08 * PARALLAX;
	for (let y = 0; y < rows; y++) {
		const tiltX = mouse.px * par * ((y - rows / 2) / rows);
		for (let x = 0; x < cols; x++) {
			const i = y * cols + x;
			vis[i] += (grid[i] - vis[i]) * f;
			ptX[i] = ox + x * CELL_SIZE + tiltX;
			ptY[i] = oy + y * CELL_SIZE + Math.sin(dist[i] - time) * WAVE + mouse.py * par * ((x - cols / 2) / cols);
		}
	}

	ctx.clearRect(0, 0, w, h);
	const la = dark ? 1 : 0.75;
	// The empty lattice as a faint breathing fabric, erased over the column before life is drawn
	if (FABRIC > 0) {
		ctx.beginPath();
		for (let y = 0; y < rows; y++) {
			ctx.moveTo(ptX[y * cols], ptY[y * cols]);
			for (let x = 1; x < cols; x++) ctx.lineTo(ptX[y * cols + x], ptY[y * cols + x]);
		}
		for (let x = 0; x < cols; x++) {
			ctx.moveTo(ptX[x], ptY[x]);
			for (let y = 1; y < rows; y++) ctx.lineTo(ptX[y * cols + x], ptY[y * cols + x]);
		}
		ctx.strokeStyle = col.fabric;
		ctx.lineWidth = 1;
		ctx.globalAlpha = Math.min(1, FABRIC * (dark ? 0.09 : 0.08));
		ctx.stroke();
		ctx.globalCompositeOperation = 'destination-out';
		ctx.globalAlpha = 1;
		ctx.fillStyle = mask;
		ctx.fillRect(0, 0, w, h);
		ctx.globalCompositeOperation = 'source-over';
	}
	// Bonds, one path per color step: right, down and diagonal neighbors that are both alive
	ctx.lineWidth = 1;
	for (let k = 0; k < K; k++) {
		ctx.beginPath();
		for (let y = 0; y < rows - 1; y++) {
			for (let x = 0; x < cols - 1; x++) {
				const i = y * cols + x, v = vis[i] * calmOf[i];
				if (vis[i] < 0.05 || Math.min(K - 1, (v * K) | 0) !== k) continue;
				const r = i + 1, b = i + cols, d = b + 1;
				if (vis[r] > 0.05) { ctx.moveTo(ptX[i], ptY[i]); ctx.lineTo(ptX[r], ptY[r]); }
				if (vis[b] > 0.05) { ctx.moveTo(ptX[i], ptY[i]); ctx.lineTo(ptX[b], ptY[b]); }
				if (vis[d] > 0.05) { ctx.moveTo(ptX[i], ptY[i]); ctx.lineTo(ptX[d], ptY[d]); }
			}
		}
		ctx.strokeStyle = col.bond[k];
		ctx.globalAlpha = ((k + 0.5) / K) * 0.32 * la;
		ctx.stroke();
	}
	// Nodes on top, one path per color step
	const nr = CELL_SIZE * NODE_SIZE;
	for (let k = 0; k < K; k++) {
		ctx.beginPath();
		for (let i = 0; i < total; i++) {
			const v = vis[i];
			if (v < 0.05 || Math.min(K - 1, (v * calmOf[i] * K) | 0) !== k) continue;
			const r = Math.max(0.6, v * nr * (0.55 + 0.45 * calmOf[i]));
			ctx.moveTo(ptX[i] + r, ptY[i]);
			ctx.arc(ptX[i], ptY[i], r, 0, TAU);
		}
		ctx.fillStyle = col.node[k];
		ctx.globalAlpha = (0.15 + 0.75 * ((k + 0.5) / K)) * la;
		ctx.fill();
	}
	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width;
			h = d.height;
			dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			size();
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			dpr = Math.min(d.dpr || 1, 2);
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas) calmBuild();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.amount = 1;
			break;
		case 'mousedown': {
			// A tap sows a small colony where it lands
			const c = cellAt(d.x, d.y);
			if (c >= 0) burst(c % cols, (c / cols) | 0, 3, 0.45);
			break;
		}
	}
};

/**
 * Title: Thunderhead (WebGL)
 * Description: Domain-warped storm clouds with silver edges churn across the top of the screen over slanted rain; lightning now and then tears down beside the chat column, sometimes twice, and sweeping the cursor sideways gusts the wind.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const INTENSITY     = 0.85;  // how strongly the storm shows (0-1)
const CLOUD_SCALE   = 2.1;   // size of the billows; higher is smaller (1-4)
const WIND_SPEED    = 0.06;  // how fast the clouds drift (0-0.3)
const REDUCED_SPEED = 0.15;  // share of the drift kept when the viewer asks to reduce motion; lightning stops (0-1)
const RAIN_OPACITY  = 0.1;   // how visible the rain is (0-0.4)
const RAIN_SPEED    = 1.6;   // how fast the rain falls (0-4)
const STRIKE_MIN    = 6;     // fewest seconds between lightning strikes (2-30)
const STRIKE_MAX    = 16;    // most seconds between lightning strikes; 0 turns lightning off (0-60)
const DOUBLE_CHANCE = 0.35;  // chance of a quick second strike (0-1)
const BOLT_LENGTH   = 0.55;  // how far a bolt reaches down, as a share of the screen height (0.2-0.9)
const CURSOR_WIND   = 1;     // how much a sideways cursor sweep gusts the wind (0-2)
const CENTER_CALM   = 0.7;   // how much the storm thins behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const RENDER_SCALE  = 0.5;   // resolution of the clouds; they are soft, so half is plenty (0.25-1)
const MAX_FPS       = 30;    // frame cap (15-60)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const CLOUD_COLOR   = '#5c6478';  // cloud body when not following the theme
const SILVER_COLOR  = '#a8b2c8';  // moonlit cloud edges
const BOLT_COLOR    = '#dce6ff';  // lightning
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform float u_wind;',
	'uniform float u_dark;',
	'uniform vec4 u_flash;',
	'uniform vec2 u_col;',
	'uniform vec3 u_cloud;',
	'uniform vec3 u_silver;',
	'uniform vec3 u_bolt;',
	'float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }',
	'float noise(vec2 p) {',
	'	vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);',
	'	return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);',
	'}',
	'float fbm4(vec2 p) {',
	'	float v = 0.0, a = 0.5;',
	'	mat2 m = mat2(1.6, 1.2, -1.2, 1.6);',
	'	for (int i = 0; i < 4; i++) { v += a * noise(p); p = m * p; a *= 0.5; }',
	'	return v;',
	'}',
	'float fbm(vec2 p) {',
	'	float v = 0.0, a = 0.5;',
	'	mat2 m = mat2(1.6, 1.2, -1.2, 1.6);',
	'	for (int i = 0; i < 5; i++) { v += a * noise(p); p = m * p; a *= 0.5; }',
	'	return v;',
	'}',
	'float bolt(vec2 p, vec4 fl) {',
	'	float on = smoothstep(0.35, 0.7, fl.z);',
	'	if (on < 0.01) return 0.0;',
	'	float len = ' + BOLT_LENGTH.toFixed(3) + ';',
	'	float seg = clamp((fl.y - p.y) / len, 0.0, 1.0);',
	'	float xo = (noise(vec2(p.y * 7.0, fl.w * 57.0)) - 0.5) * 0.22 * seg + (noise(vec2(p.y * 23.0, fl.w * 91.0)) - 0.5) * 0.07 * seg;',
	'	float d = abs(p.x - fl.x - xo);',
	'	float inY = step(fl.y - len * (0.75 + 0.25 * fl.w), p.y) * step(p.y, fl.y);',
	'	return (exp(-d * 260.0) + exp(-d * 26.0) * 0.22) * inY * on * (1.0 - seg * 0.5);',
	'}',
	'float rain(vec2 p, float t, float nx) {',
	'	vec2 rp = vec2(p.x * nx + p.y * 6.0, p.y * 1.4 + t);',
	'	vec2 id = vec2(floor(rp.x), 0.0);',
	'	float y = fract(rp.y + hash(id) * 13.7);',
	'	float s = smoothstep(0.55, 0.95, y) * smoothstep(1.0, 0.97, y);',
	'	return s * smoothstep(0.35, 0.0, abs(fract(rp.x) - 0.5)) * step(0.4, hash(id + 7.3));',
	'}',
	'void main() {',
