// Strikes land outside the calm band, nudged outward when called over the column
function strikeX(x) {
	const mid = colX(), reach = colHalf() * 0.95, lo = (column ? column.left : 0) + w * 0.04, hi = (column ? column.right : w) - w * 0.04;
	if (Math.abs(x - mid) < reach) {
