		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

function size() {
	canvas.width = Math.max(1, Math.round(w * RENDER_SCALE));
	canvas.height = Math.max(1, Math.round(h * RENDER_SCALE));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

// ── Blooms: a slow swell of light beside the chat column, never over it ──
function updateBloom(dt) {
	bloom.age += dt;
	if (BLOOM_EVERY <= 0 || MOTION <= 0 || reduced || bloom.age < 10) return;
	bloom.wait -= dt;
	if (bloom.wait > 0) return;
	// The margins beside the column, inside the chat area so the sidebar can't cover a bloom
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const left = Math.max(0, colX() - colHalf() - lo), right = Math.max(0, hi - colX() - colHalf());
	if (left + right < 80) return;
	const r = Math.random() * (left + right);
	bloom.x = r < left ? lo + r * 0.85 : hi - (r - left) * 0.85;
	bloom.y = h * (0.15 + Math.random() * 0.7);
	bloom.strength = 0.5 + Math.random() * 0.5;
	bloom.age = 0;
	bloom.wait = BLOOM_EVERY * (0.6 + Math.random() * 0.8);
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	time = (time + dt * MOTION * (reduced ? REDUCED_SPEED : 1)) % 3000;
	mouse.target = Math.max(0, mouse.target - dt * 0.4);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 3);
	updateBloom(dt);
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform3f(loc.u_mouse, mouse.x, mouse.y, mouse.amount);
	gl.uniform3fv(loc.u_c1, colors.c1);
	gl.uniform3fv(loc.u_c2, colors.c2);
	gl.uniform3fv(loc.u_c3, colors.c3);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform4f(loc.u_bloom, bloom.x, bloom.y, bloom.age, bloom.strength);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	gl = canvas.getContext('webgl2', { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' })
		|| canvas.getContext('webgl', { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' });
	if (!gl) {
		console.warn('Aether Nebula: WebGL is not available, so the nebula is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Aether Nebula:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Aether Nebula:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

light.customCSS:
:root {
	--aether-glass: color-mix(in oklab, var(--color-gray-50) 62%, transparent);
	--aether-sidebar: color-mix(in oklab, var(--color-gray-50) 68%, transparent);
	--aether-bubble: color-mix(in oklab, var(--color-gray-200) 55%, transparent);
	--aether-selected: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--aether-line: color-mix(in oklab, var(--color-gray-500) 26%, transparent);
	--aether-glow: color-mix(in oklab, var(--color-gray-600) 45%, transparent);
	--aether-ring: color-mix(in oklab, var(--color-gray-500) 20%, transparent);
	--aether-shade: color-mix(in oklab, var(--color-gray-500) 30%, transparent);
}

/* Frosted surfaces over the nebula, in Open WebUI's own shapes. Colors come
   from the palette. !important only where Canvas FX transparency clears a
   background first. */
#message-input-container {
	background-color: var(--aether-glass) !important;
	border-color: var(--aether-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--aether-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--aether-glow) !important;
	box-shadow: 0 0 0 3px var(--aether-ring), 0 12px 40px -16px var(--aether-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--aether-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--aether-line);
}
#sidebar {
	background-color: var(--aether-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--aether-line);
}
#sidebar-chat-item.selected {
	background-color: var(--aether-selected);
}
html {
	scrollbar-color: var(--aether-line) transparent;
}
::selection {
	background-color: var(--aether-ring);
}

