	bloom.y = h * (0.15 + Math.random() * 0.7);
	bloom.strength = 0.5 + Math.random() * 0.5;
	bloom.age = 0;
	bloom.wait = BLOOM_EVERY * (0.6 + Math.random() * 0.8);
