const REDUCED_SPEED = 0.3;   // share of the speed kept when the viewer asks to reduce motion (0-1)
const CURSOR_REACH  = 200;   // how near the cursor must come to wake a node, in px (60-400)
const CENTER_CALM   = 0.8;   // how much the network fades behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const LINK_COLOR    = '#64a0ff';  // connection color when not following the theme
const NODE_COLOR    = '#78b4ff';  // node and pulse color
const GLOW_COLOR    = '#64b4ff';  // halo around energized nodes
const CORE_COLOR    = '#c8e6ff';  // bright center of energized nodes
/* ──────────────────────────────────────────── */

const MAX_NODES = 90, MAX_LINKS = 300;

let canvas, ctx;
let w = 0, h = 0, dpr = 1;
let last = 0, reduced = false, dark = true, fireWait = 1, wakeWait = 0, column = null;
let nodeCount = 0, linkCount = 0, firstOfLast = 0, inputs = 1;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };
const col = { link: LINK_COLOR, node: NODE_COLOR, glow: GLOW_COLOR, core: CORE_COLOR };
let pulseSprite = null, haloSprite = null;
// Nodes: position, home, wander target, phase, energy, calm
const nx = new Float32Array(MAX_NODES), ny = new Float32Array(MAX_NODES);
const hx = new Float32Array(MAX_NODES), hy = new Float32Array(MAX_NODES);
const gx = new Float32Array(MAX_NODES), gy = new Float32Array(MAX_NODES);
const wait = new Float32Array(MAX_NODES), energy = new Float32Array(MAX_NODES), ncalm = new Float32Array(MAX_NODES);
// Links: from, to, weight; outgoing links of a node are contiguous (start index and count)
const lf = new Int16Array(MAX_LINKS), lt = new Int16Array(MAX_LINKS), lw = new Float32Array(MAX_LINKS), lc = new Float32Array(MAX_LINKS);
const outStart = new Int16Array(MAX_NODES), outCount = new Uint8Array(MAX_NODES);
// Pulses: link, progress 0-1, speed, brightness
const pl = new Int16Array(MAX_PULSES).fill(-1), pp = new Float32Array(MAX_PULSES);
const ps = new Float32Array(MAX_PULSES), pb = new Float32Array(MAX_PULSES);

// A soft round glow in one color: the color filled, then masked by a radial falloff
function sprite(color, r) {
	const c = new OffscreenCanvas(r * 2, r * 2), g = c.getContext('2d');
	g.fillStyle = color;
	g.fillRect(0, 0, r * 2, r * 2);
	const grad = g.createRadialGradient(r, r, 0, r, r, r);
	grad.addColorStop(0, 'rgba(255,255,255,1)');
	grad.addColorStop(0.2, 'rgba(255,255,255,0.8)');
	grad.addColorStop(0.5, 'rgba(255,255,255,0.2)');
	grad.addColorStop(1, 'rgba(255,255,255,0)');
	g.globalCompositeOperation = 'destination-in';
	g.fillStyle = grad;
	g.fillRect(0, 0, r * 2, r * 2);
	return c;
}

// Links take the muted color, nodes and pulses the accent, halos accent2, cores the text color
function applyTheme(t) {
	if (t) {
		dark = t.dark !== false;
		if (FOLLOW_THEME && t.colors) {
			col.link = t.colors.muted;
			col.node = t.colors.accent;
			col.glow = t.colors.accent2;
			col.core = dark ? t.colors.text : t.colors.accent3;
		}
	}
	pulseSprite = sprite(col.node, 12);
	haloSprite = sprite(col.glow, 16);
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function band(x) {
	const b = Math.abs(x - colX()) / colHalf();
	const s = Math.min(1, Math.max(0, (b - 0.55) / 0.7));
	return 1 - CENTER_CALM * (1 - s * s * (3 - 2 * s));
}

function build() {
	nodeCount = linkCount = 0;
	pl.fill(-1);
	const layers = Math.max(2, Math.min(9, LAYERS));
	let prevStart = 0, prevCount = 0;
	// Free space left and right of the calm band inside the chat area, each at least an eighth of the screen wide (reaching into the band's fade when short)
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const m = w * 0.05, room = Math.max(80, w * 0.125), l0 = lo + m, l1 = Math.max(l0 + room, colX() - colHalf()), r1 = hi - m, r0 = Math.min(r1 - room, colX() + colHalf());
	for (let l = 0; l < layers; l++) {
		const edge = l === 0 || l === layers - 1;
		const count = Math.min(MAX_NODES - nodeCount, edge ? 3 + Math.floor(Math.random() * 3) : 5 + Math.floor(Math.random() * 5));
		const start = nodeCount;
		// Layers gather on either side of the chat column; long faint links bridge it from a middle layer
		const u = l / (layers - 1);
		const x = u < 0.5 ? l0 + (l1 - l0) * u * 1.7 : u > 0.5 ? r1 - (r1 - r0) * (1 - u) * 1.7 : colX();
		for (let n = 0; n < count; n++) {
			const i = nodeCount++;
			hx[i] = gx[i] = nx[i] = x + (Math.random() - 0.5) * 30;
			hy[i] = gy[i] = ny[i] = (h / (count + 1)) * (n + 1) + (Math.random() - 0.5) * 20;
			wait[i] = Math.random() * 10;
			energy[i] = 0;
			ncalm[i] = band(x);
		}
		// Sparse wiring from the previous layer: one to three links per node, to its neighbours across
		for (let p = prevStart; p < prevStart + prevCount && l > 0; p++) {
			outStart[p] = linkCount;
			const links = 1 + Math.floor(Math.random() * Math.min(3, count));
			const across = ((p - prevStart) / Math.max(1, prevCount - 1)) * (count - 1);
			const first = Math.round(across - (links - 1) / 2 + (Math.random() - 0.5) * 1.5);
			for (let k = 0; k < links && linkCount < MAX_LINKS; k++) {
				lf[linkCount] = p;
				lt[linkCount] = start + Math.min(count - 1, Math.max(0, first + k));
				lw[linkCount] = 0.3 + Math.random() * 0.7;
				lc[linkCount] = Math.min(ncalm[p], ncalm[lt[linkCount]], band((hx[p] + hx[lt[linkCount]]) / 2));
				linkCount++;
			}
			outCount[p] = linkCount - outStart[p];
		}
		if (l === 0) inputs = count;
		prevStart = start;
		prevCount = count;
	}
	firstOfLast = prevStart;
	for (let p = prevStart; p < nodeCount; p++) outCount[p] = 0;
}

function resize(width, height, ratio) {
	w = width;
	h = height;
	dpr = Math.min(ratio || 1, 2);
	if (!canvas) return;
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	build();
}

function fire(node, brightness, chance) {
	energy[node] = Math.min(1, energy[node] + 0.4 * brightness);
	for (let k = outStart[node], end = k + outCount[node]; k < end; k++) {
		if (Math.random() >= chance) continue;
		for (let p = 0; p < MAX_PULSES; p++) {
			if (pl[p] >= 0) continue;
			pl[p] = k; pp[p] = 0; ps[p] = PULSE_SPEED * (0.7 + Math.random() * 0.6); pb[p] = brightness;
			break;
		}
	}
}

function nearest(x, y, reach) {
	let best = -1, bestD = reach * reach;
	for (let i = 0; i < nodeCount; i++) {
		const dx = nx[i] - x, dy = ny[i] - y, d = dx * dx + dy * dy;
		if (d < bestD) { bestD = d; best = i; }
	}
	return best;
}

function update(dt) {
	const speed = dt * MOTION * (reduced ? REDUCED_SPEED : 1);
	const ease = 1 - Math.exp(-speed * 0.6);
	for (let i = 0; i < nodeCount; i++) {
		// Each node picks a new spot near home now and then, so the network slowly reorganizes
		wait[i] -= speed;
		if (wait[i] <= 0) {
			wait[i] = 6 + Math.random() * 10;
			gx[i] = hx[i] + (Math.random() - 0.5) * 2 * DRIFT;
			gy[i] = hy[i] + (Math.random() - 0.5) * 2 * DRIFT;
		}
		nx[i] += (gx[i] - nx[i]) * ease;
		ny[i] += (gy[i] - ny[i]) * ease;
		energy[i] *= Math.exp(-dt * 1.8);
	}
	if (FIRE_EVERY > 0) {
		fireWait -= speed;
		if (fireWait <= 0) {
			fireWait = FIRE_EVERY * (0.5 + Math.random());
			fire(Math.floor(Math.random() * inputs), 0.6 + Math.random() * 0.4, 0.5);
		}
	}
	// A moving cursor wakes the nearest node; a resting one does not
	wakeWait -= dt;
	if (mouse.amount > 0.4 && wakeWait <= 0) {
		wakeWait = 0.35;
		const n = nearest(mouse.x, mouse.y, CURSOR_REACH);
		if (n >= 0) fire(n, 0.6, 0.5);
	}
	for (let p = 0; p < MAX_PULSES; p++) {
		const k = pl[p];
		if (k < 0) continue;
		pp[p] += ps[p] * speed;
		if (pp[p] < 1) continue;
		pl[p] = -1;
		const to = lt[k];
		energy[to] = Math.min(1, energy[to] + 0.35 * pb[p]);
		if (pb[p] > 0.25 && to < firstOfLast) fire(to, pb[p] * 0.7, reduced ? CASCADE * 0.4 : CASCADE);
	}
}

function draw() {
	ctx.clearRect(0, 0, w, h);
	const k = dark ? 1 : 0.8;
	for (let i = 0; i < linkCount; i++) {
		const a = lf[i], b = lt[i];
		const calm = lc[i];
		ctx.globalAlpha = Math.min(1, (LINK_ALPHA * (0.5 + lw[i] * 0.5) + Math.max(energy[a], energy[b]) * 0.18) * calm * k);
		ctx.strokeStyle = col.link;
		ctx.lineWidth = 1 + lw[i] * 0.5;
		ctx.beginPath();
		ctx.moveTo(nx[a], ny[a]);
		ctx.lineTo(nx[b], ny[b]);
		ctx.stroke();
	}
	for (let p = 0; p < MAX_PULSES; p++) {
		const l = pl[p];
		if (l < 0) continue;
		const a = lf[l], b = lt[l], f = pp[p];
		const x = nx[a] + (nx[b] - nx[a]) * f, y = ny[a] + (ny[b] - ny[a]) * f;
		ctx.globalAlpha = Math.min(1, (0.4 + pb[p] * 0.6) * band(x) * k * Math.min(1, f * 6, (1 - f) * 6));
		ctx.drawImage(pulseSprite, x - 12, y - 12);
	}
	for (let i = 0; i < nodeCount; i++) {
		const e = energy[i], c = ncalm[i] * k;
		// Every node keeps a faint halo at rest, which swells when it fires
		ctx.globalAlpha = Math.min(1, (0.22 + e * 0.6) * c);
		ctx.drawImage(haloSprite, nx[i] - 16, ny[i] - 16);
		ctx.globalAlpha = Math.min(1, (0.55 + e * 0.45) * c);
		ctx.fillStyle = col.node;
		ctx.beginPath();
		ctx.arc(nx[i], ny[i], NODE_RADIUS, 0, 6.2832);
		ctx.fill();
		if (e > 0.1) {
			ctx.globalAlpha = Math.min(1, e * 0.8 * c);
			ctx.fillStyle = col.core;
			ctx.beginPath();
			ctx.arc(nx[i], ny[i], NODE_RADIUS * 0.5, 0, 6.2832);
			ctx.fill();
		}
	}
	ctx.globalAlpha = 1;
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!ctx) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	mouse.target = Math.max(0, mouse.target - dt * 0.8);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 5);
	update(dt);
	draw();
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			resize(d.width, d.height, d.dpr);
			requestAnimationFrame(frame);
			break;
		case 'resize':
			resize(d.width, d.height, d.dpr);
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas) build();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
		case 'mousedown': {
			// A tap fires the nearest node down every link; a single soft pulse when motion is reduced
			const n = nearest(d.x, d.y, CURSOR_REACH * 1.3);
			if (n >= 0) fire(n, reduced ? 0.5 : 1, reduced ? 0.4 : 1);
			break;
		}
	}
};

dark.customCSS:
:root {
	--biolum-glass: color-mix(in oklab, var(--color-gray-900) 58%, transparent);
	--biolum-sidebar: color-mix(in oklab, var(--color-gray-950) 70%, transparent);
	--biolum-bubble: color-mix(in oklab, var(--color-gray-700) 45%, transparent);
	--biolum-selected: color-mix(in oklab, var(--color-gray-500) 20%, transparent);
	--biolum-line: color-mix(in oklab, var(--color-gray-400) 22%, transparent);
	--biolum-glow: oklch(0.85 0.14 200 / 0.55);
	--biolum-ring: oklch(0.85 0.14 200 / 0.18);
	--biolum-shade: color-mix(in oklab, var(--color-gray-950) 65%, transparent);
	--biolum-accent: oklch(0.87 0.12 200);
}

/* Frosted water over the deep, with a cyan glow on what matters. !important only where Canvas FX transparency clears a background first. */
#message-input-container {
	background-color: var(--biolum-glass) !important;
	border-color: var(--biolum-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--biolum-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--biolum-glow) !important;
	box-shadow: 0 0 0 3px var(--biolum-ring), 0 12px 40px -16px var(--biolum-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--biolum-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--biolum-line);
}
#sidebar {
	background-color: var(--biolum-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--biolum-line);
}
#sidebar-chat-item.selected { background-color: var(--biolum-selected); }
.markdown-prose :is(h1, h2, h3) { color: var(--biolum-accent); text-shadow: 0 0 14px var(--biolum-ring); }
.markdown-prose a { color: var(--biolum-accent); text-decoration-color: var(--biolum-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--biolum-glow); }
.markdown-prose hr { border-color: var(--biolum-line); }
html { scrollbar-color: var(--biolum-line) transparent; }
::selection { background-color: var(--biolum-ring); }

dark.canvasScript:
/**
 * Title: Deep Ocean
 * Description: A seafloor in your theme's colors, with light shafts, glowing jellyfish, plankton, swaying kelp and caustics on the sand, kept to the sides of the chat; the cursor stirs the current and a tap sends a sonar ring.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const JELLY_COUNT   = 7;     // glowing jellyfish (0-16)
const KELP_STRANDS  = 12;    // kelp fronds along the floor (0-24)
const PLANKTON      = 120;   // tiny drifting particles (0-300)
const RAY_COUNT     = 5;     // shafts of light from the surface (0-10)
const CURRENT       = 1;     // speed of the whole scene; 0 holds it still (0-3)
const REDUCED_SPEED = 0.2;   // share of the speed kept when the viewer asks to reduce motion (0-1)
const MOUSE_CURRENT = 1;     // how strongly the cursor stirs the current and nudges the jellies (0-3)
const PULSE_EVERY   = 45;    // average seconds between distant sonar rings; 0 turns them off (0-300)
const WATER_TINT    = 1;     // strength of the light glow from the surface (0-2)
const CAUSTICS      = 1;     // strength of the caustic light on the sand (0-2)
const FLOOR_HEIGHT  = 0.15;  // height of the sandy floor, as a share of the screen (0.05-0.3)
const CENTER_CALM   = 0.75;  // how much the scene fades behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const WATER_COLOR   = '#3c96c8';  // surface glow and light shafts when not following the theme
const JELLY_A       = '#5ee0f0';  // first jellyfish color
const JELLY_B       = '#b27cf0';  // second jellyfish color
const KELP_COLOR    = '#3a6e28';  // kelp
const SAND_COLOR    = '#2a2e1e';  // sandy floor
/* ──────────────────────────────────────────── */

const TAU = Math.PI * 2;
const NJ = Math.min(16, JELLY_COUNT | 0), NK = Math.min(24, KELP_STRANDS | 0), NP = Math.min(300, PLANKTON | 0), NR = Math.min(10, RAY_COUNT | 0);
const SEGS = 12, TW = 160, TH = 80, RINGS = 4;

let canvas, ctx;
let w = 0, h = 0, dpr = 1, floorY = 0;
let last = 0, T = 0, reduced = false, dark = true, theme = null, nextPulse = PULSE_EVERY * 0.5, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };

// Pools
const jx = new Float32Array(NJ), jy = new Float32Array(NJ), jsz = new Float32Array(NJ), jdepth = new Float32Array(NJ);
const jvx = new Float32Array(NJ), jrise = new Float32Array(NJ), jphase = new Float32Array(NJ), jtone = new Uint8Array(NJ), jtent = new Uint8Array(NJ);
const ppx = new Float32Array(NP), ppy = new Float32Array(NP), pps = new Float32Array(NP), ppd = new Float32Array(NP), ppa = new Float32Array(NP);
const rx = new Float32Array(NR), rw = new Float32Array(NR), rph = new Float32Array(NR), ra = new Float32Array(NR);
const kx = new Float32Array(NK), kh = new Float32Array(NK), kw = new Float32Array(NK), kph = new Float32Array(NK), kleaf = new Int8Array(NK * SEGS);
const kpx = new Float32Array(SEGS + 1), kpy = new Float32Array(SEGS + 1);
const ringX = new Float32Array(RINGS), ringY = new Float32Array(RINGS), ringR = new Float32Array(RINGS), ringA = new Float32Array(RINGS);

// Cached colors, gradients and sprites (rebuilt on theme change and resize)
const C = {};
let tint, rayGrad, calmMask, ringStyle, floorImg, caustic, glows = [];
let causticField = null;

function hexToRgb(hex) { const n = parseInt(String(hex).slice(1, 7), 16) || 0; return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function mix(a, b, t) { return [0, 1, 2].map((k) => Math.round(a[k] + (b[k] - a[k]) * t)); }
function rgba(c, a) { return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + Math.max(0, Math.min(1, a)).toFixed(3) + ')'; }
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

// The chat area's edges, which leave out the sidebar
function areaL() { return column ? column.left : 0; }
function areaR() { return column ? column.right : w; }
// Room beside the chat column on one side, at most reach of the screen wide
function room(right, reach) { const e = colX() + (right ? 1 : -1) * colHalf() * 0.5; return Math.max(40, Math.min(w * reach, right ? areaR() - e : e - areaL())); }
// A spot in the outer thirds, or nearer the edge when the chat column leaves less room
function side() { return Math.random() < 0.5 ? areaL() + Math.random() * room(false, 0.3) : areaR() - Math.random() * room(true, 0.3); }
function band(x) { const d = Math.abs(x - colX()) / colHalf(), s = Math.min(1, Math.max(0, (d - 0.5) / 0.8)); return 1 - s * s * (3 - 2 * s); }

function palette() {
	const c = FOLLOW_THEME && theme && theme.colors ? theme.colors : null;
	if (c) {
		const a = hexToRgb(c.accent), a2 = hexToRgb(c.accent2), a3 = hexToRgb(c.accent3), tx = hexToRgb(c.text), mu = hexToRgb(c.muted), bg = hexToRgb(c.background);
		return { water: a3, ray: dark ? mix(a3, tx, 0.3) : a3, jelly: [a3, a2], core: dark ? tx : a, kelp: dark ? mix(mix(a3, mu, 0.5), bg, 0.3) : mix(a3, tx, 0.35), sand: dark ? mix(mu, bg, 0.6) : mix(mu, bg, 0.3), light: dark ? mix(a3, tx, 0.4) : bg, mote: dark ? mix(a3, tx, 0.5) : a3 };
	}
	const water = hexToRgb(WATER_COLOR);
	return { water, ray: mix(water, [255, 255, 255], 0.25), jelly: [hexToRgb(JELLY_A), hexToRgb(JELLY_B)], core: [220, 250, 255], kelp: hexToRgb(KELP_COLOR), sand: hexToRgb(SAND_COLOR), light: [80, 180, 220], mote: [140, 200, 220] };
}

function glowSprite(c) {
	const s = new OffscreenCanvas(64, 64), g = s.getContext('2d'), gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
	gr.addColorStop(0, rgba(c, 0.6)); gr.addColorStop(0.4, rgba(c, 0.18)); gr.addColorStop(1, rgba(c, 0));
	g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
	return s;
}

// Wrapping cell-edge field for the caustic network, computed once
function buildField() {
	causticField = new Float32Array(TW * TH);
	const N = 11, sx = [], sy = [];
	for (let i = 0; i < N; i++) { sx.push(Math.random() * TW); sy.push(Math.random() * TH); }
	for (let y = 0; y < TH; y++) for (let x = 0; x < TW; x++) {
		let f1 = 1e9, f2 = 1e9;
		for (let i = 0; i < N; i++) {
			// A periodic warp curves the cell edges like real caustics and keeps the tile seamless
			let dx = Math.abs(x + Math.sin(y / TH * TAU * 2) * 5 - sx[i]), dy = Math.abs(y + Math.sin(x / TW * TAU * 3) * 4 - sy[i]);
			if (dx > TW) dx -= TW;
			if (dx > TW / 2) dx = TW - dx;
			if (dy > TH / 2) dy = TH - dy;
			const d = Math.sqrt(dx * dx + dy * dy);
			if (d < f1) { f2 = f1; f1 = d; } else if (d < f2) f2 = d;
		}
		const e = Math.max(0, 1 - (f2 - f1) / 9);
		const v = y / TH; // fades in from the top of the floor, so the tile needs no mask
		causticField[y * TW + x] = e * e * e * Math.min(1, v * 3) * (1 - v * 0.3);
	}
}

// The calm band's mask, rebuilt on resize, theme and layout
function buildMask() {
	calmMask = ctx.createLinearGradient(0, 0, w, 0);
	for (let s = 0; s <= 40; s++) calmMask.addColorStop(s / 40, 'rgba(0,0,0,' + (CENTER_CALM * band((s / 40) * w)).toFixed(3) + ')');
}

// Light shafts and kelp stand beside the chat column, placed again when it moves
function placeSides() {
	const L = room(false, 0.31), R = room(true, 0.31);
	for (let i = 0; i < NR; i++) rx[i] = side();
	for (let i = 0; i < NK; i++) {
		const f = (i + 0.5) / NK;
		kx[i] = (f < 0.5 ? areaL() + f * 2 * L : areaR() - (1 - f) * 2 * R) + (Math.random() - 0.5) * 30;
	}
}

function build() {
	if (!ctx || !w) return;
	const p = palette();
	if (!causticField) buildField();
	const fh = h - floorY;
	tint = ctx.createLinearGradient(0, 0, 0, h * 0.7);
	tint.addColorStop(0, rgba(p.water, (dark ? 0.14 : 0.09) * WATER_TINT));
	tint.addColorStop(1, rgba(p.water, 0));
	rayGrad = ctx.createLinearGradient(0, 0, 0, floorY);
	rayGrad.addColorStop(0, rgba(p.ray, 0.5)); rayGrad.addColorStop(0.5, rgba(p.ray, 0.16)); rayGrad.addColorStop(1, rgba(p.ray, 0));
	buildMask();
	ringStyle = rgba(p.water, dark ? 0.6 : 0.5);
	glows = [glowSprite(p.jelly[0]), glowSprite(p.jelly[1])];
	C.bell = p.jelly.map((c) => rgba(c, dark ? 0.45 : 0.4));
	C.inner = p.jelly.map((c) => rgba(mix(c, p.core, 0.5), dark ? 0.5 : 0.35));
	C.tent = p.jelly.map((c) => rgba(c, dark ? 0.35 : 0.3));
	C.kelp = rgba(p.kelp, dark ? 0.8 : 0.55);
	C.leaf = rgba(mix(p.kelp, p.light, 0.15), dark ? 0.55 : 0.4);
	C.mote = rgba(p.mote, 1);
	// Floor (sand and soft dunes) and the caustic tile, pre-rendered once
	floorImg = new OffscreenCanvas(Math.ceil(w * dpr), Math.ceil((fh + 60) * dpr));
	const g = floorImg.getContext('2d');
	g.scale(dpr, dpr);
	const fg = g.createLinearGradient(0, 0, 0, fh + 60);
	fg.addColorStop(0, rgba(p.sand, 0)); fg.addColorStop(0.4, rgba(p.sand, dark ? 0.6 : 0.4)); fg.addColorStop(1, rgba(p.sand, dark ? 0.75 : 0.55));
	g.fillStyle = fg; g.fillRect(0, 0, w, fh + 60);
	g.fillStyle = rgba(mix(p.sand, p.light, 0.25), dark ? 0.25 : 0.2);
	for (let i = 0; i < 34; i++) {
		g.beginPath();
		g.ellipse((i / 34) * w + Math.sin(i * 4.7) * 20, 66 + Math.sin(i * 2.1) * 8, 22 + Math.sin(i * 3) * 10, 4, 0, 0, TAU);
		g.fill();
	}
	caustic = new OffscreenCanvas(TW, TH);
	const cg = caustic.getContext('2d'), img = cg.createImageData(TW, TH);
	for (let i = 0; i < TW * TH; i++) { img.data[i * 4] = p.light[0]; img.data[i * 4 + 1] = p.light[1]; img.data[i * 4 + 2] = p.light[2]; img.data[i * 4 + 3] = causticField[i] * 255; }
	cg.putImageData(img, 0, 0);
}

function spawnJelly(i, anywhere) {
	jdepth[i] = Math.random();
	jsz[i] = 12 + (1 - jdepth[i]) * 16 + Math.random() * 8;
	jx[i] = side();
	jy[i] = anywhere ? h * (0.08 + Math.random() * 0.6) : floorY + jsz[i] * 3;
	jvx[i] = 0;
	jrise[i] = 1.5 + Math.random() * 3.5;
	jphase[i] = Math.random() * TAU;
	jtone[i] = Math.random() < 0.5 ? 0 : 1;
	jtent[i] = 5 + ((Math.random() * 4) | 0);
}

function seed() {
	for (let i = 0; i < NJ; i++) spawnJelly(i, true);
	for (let i = 0; i < NP; i++) { ppx[i] = Math.random() * w; ppy[i] = Math.random() * h; pps[i] = 0.05 + Math.random() * 0.15; ppd[i] = Math.random() * TAU; ppa[i] = 0.15 + Math.random() * 0.35; }
	for (let i = 0; i < NR; i++) { rw[i] = 30 + Math.random() * 70; rph[i] = Math.random() * TAU; ra[i] = 0.04 + Math.random() * 0.05; }
	placeSides();
	for (let i = 0; i < NK; i++) {
		kh[i] = 0.18 + Math.random() * 0.22;
		kw[i] = 2 + Math.random() * 2.5;
		kph[i] = Math.random() * TAU;
		for (let s = 0; s < SEGS; s++) kleaf[i * SEGS + s] = s > 1 && Math.random() > 0.25 ? (s & 1 ? 1 : -1) : 0;
	}
}

function size(nw, nh, ndpr) {
	const sx = w ? nw / w : 1, sy = h ? nh / h : 1, had = w > 0;
	w = nw; h = nh;
	dpr = Math.min(2, ndpr || 1);
	floorY = h * (1 - FLOOR_HEIGHT);
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	ctx.lineCap = 'round';
	if (!had) seed();
	else {
		// Keep the scene on a resize: move everything with the screen instead of re-rolling it
		for (let i = 0; i < NJ; i++) { jx[i] *= sx; jy[i] *= sy; }
		for (let i = 0; i < NP; i++) { ppx[i] *= sx; ppy[i] *= sy; }
		for (let i = 0; i < NR; i++) rx[i] *= sx;
		for (let i = 0; i < NK; i++) kx[i] *= sx;
	}
	build();
}

function drawJelly(i, t) {
	const pulse = 0.75 + 0.25 * Math.sin(t * 0.03 + jphase[i]);
	const cx = jx[i] + Math.sin(t * 0.008 + jphase[i]) * 8, cy = jy[i], sz = jsz[i] * pulse, k = jtone[i];
	const a = (0.55 + (1 - jdepth[i]) * 0.45);
	ctx.globalAlpha = a * (0.6 + 0.4 * pulse);
	ctx.drawImage(glows[k], cx - sz * 3, cy - sz * 3, sz * 6, sz * 6);
	ctx.globalAlpha = a;
	ctx.fillStyle = C.bell[k];
	ctx.beginPath();
	ctx.ellipse(cx, cy, sz * 0.7, sz * 0.5 * pulse + 2, 0, Math.PI, 0);
	ctx.fill();
	ctx.fillStyle = C.inner[k];
	ctx.beginPath();
	ctx.ellipse(cx, cy + sz * 0.05, sz * 0.4, sz * 0.25 * pulse + 1, 0, Math.PI, 0);
	ctx.fill();
	ctx.strokeStyle = C.tent[k];
	ctx.lineWidth = 1;
	ctx.beginPath();
	const n = jtent[i];
	for (let s = 0; s < n; s++) {
		const tx = cx + (s / (n - 1) - 0.5) * sz, len = sz * (1.4 + Math.sin(t * 0.012 + s * 1.3) * 0.4);
		ctx.moveTo(tx, cy + 1);
		ctx.bezierCurveTo(tx + Math.sin(t * 0.015 + s * 2) * 8, cy + len * 0.5, tx + Math.sin(t * 0.01 + s * 3) * 12, cy + len * 0.8, tx + Math.sin(t * 0.008 + s) * 10, cy + len);
	}
	ctx.stroke();
}

// A frond bends as one wave, so it curves instead of zigzagging
function drawKelp(i, t, cur) {
	const segH = h * kh[i] / SEGS;
	kpx[0] = kx[i]; kpy[0] = h + 4;
	for (let s = 1; s <= SEGS; s++) {
		const prog = s / SEGS;
		kpx[s] = kx[i] + Math.sin(t * 0.012 + kph[i] - s * 0.45) * (2 + s * 1.6) + cur * prog * prog * 200;
		kpy[s] = h + 4 - segH * s;
	}
	for (let half = 0; half < 2; half++) {
		const a = half ? SEGS >> 1 : 0, b = half ? SEGS : SEGS >> 1;
		ctx.lineWidth = kw[i] * (half ? 0.65 : 1);
		ctx.beginPath();
		ctx.moveTo(kpx[a], kpy[a]);
		for (let s = a + 1; s <= b; s++) ctx.quadraticCurveTo(kpx[s - 1], kpy[s - 1], (kpx[s - 1] + kpx[s]) * 0.5, (kpy[s - 1] + kpy[s]) * 0.5);
		ctx.lineTo(kpx[b], kpy[b]);
		ctx.stroke();
	}
	ctx.beginPath();
	for (let s = 1; s < SEGS; s++) {
		const sd = kleaf[i * SEGS + s];
		if (!sd) continue;
		const x = kpx[s], y = kpy[s], len = (10 + (1 - s / SEGS) * 14) * (0.8 + 0.2 * Math.sin(t * 0.016 + kph[i] + s));
		ctx.moveTo(x, y);
		ctx.quadraticCurveTo(x + sd * len * 0.5, y - 7, x + sd * len, y - 4);
		ctx.quadraticCurveTo(x + sd * len * 0.5, y + 3, x, y + 2);
	}
	ctx.fill();
}

function ring(x, y) {
	let k = 0;
	for (let i = 1; i < RINGS; i++) if (ringA[i] < ringA[k]) k = i;
	ringX[k] = x; ringY[k] = y; ringR[k] = 0; ringA[k] = 0.14;
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!ctx || !caustic) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const pace = CURRENT * (reduced ? REDUCED_SPEED : 1), f = dt * 60 * pace;
	T += f;
	const t = T;
	mouse.target = Math.max(0, mouse.target - dt * 0.5);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 2);
	const cur = (Math.min(w, Math.max(0, mouse.x)) / w - 0.5) * 0.15 * MOUSE_CURRENT * mouse.amount;

	ctx.globalAlpha = 1;
	ctx.globalCompositeOperation = 'source-over';
	ctx.clearRect(0, 0, w, h);
	ctx.fillStyle = tint;
	ctx.fillRect(0, 0, w, h * 0.7);
	const glow = dark ? 'lighter' : 'source-over';
	ctx.globalCompositeOperation = glow;

	// Light shafts, in the outer thirds
	ctx.fillStyle = rayGrad;
	for (let i = 0; i < NR; i++) {
		const sway = Math.sin(t * 0.003 + rph[i]) * 40 + cur * 300, top = rx[i] + sway, half = rw[i] * 0.9;
		ctx.globalAlpha = ra[i] * (0.7 + 0.3 * Math.sin(t * 0.004 + rph[i])) * (dark ? 1.4 : 1);
		ctx.beginPath();
		ctx.moveTo(top - rw[i] * 0.3, 0); ctx.lineTo(top + rw[i] * 0.3, 0);
		ctx.lineTo(top + half + sway * 0.5, floorY); ctx.lineTo(top - half + sway * 0.5, floorY);
		ctx.fill();
	}

	// Sonar rings: rare and distant, or from a tap
	if (PULSE_EVERY > 0 && !reduced && pace > 0) {
		nextPulse -= dt;
		if (nextPulse <= 0) { ring(side(), h * (0.3 + Math.random() * 0.3)); nextPulse = PULSE_EVERY * (0.6 + Math.random() * 0.8); }
	}
	ctx.strokeStyle = ringStyle;
	ctx.lineWidth = 1.5;
	for (let i = 0; i < RINGS; i++) {
		if (ringA[i] < 0.004) continue;
		ringR[i] += 150 * dt * pace;
		ringA[i] *= Math.exp(-0.35 * dt * pace);
		if (ringR[i] > Math.max(w, h)) { ringA[i] = 0; continue; }
		ctx.globalAlpha = ringA[i] * Math.min(1, ringR[i] / 40);
		ctx.beginPath();
		ctx.arc(ringX[i], ringY[i], ringR[i], 0, TAU);
		ctx.stroke();
	}

	// Plankton
	ctx.fillStyle = C.mote;
	for (let i = 0; i < NP; i++) {
		ppx[i] += (Math.sin(t * 0.005 + ppd[i]) * pps[i] + cur * 6) * f;
		ppy[i] += (pps[i] * 0.5 + Math.cos(t * 0.003 + ppd[i]) * 0.1) * f;
		if (ppy[i] > h + 5 || ppx[i] < -10 || ppx[i] > w + 10) { ppx[i] = Math.random() * w; ppy[i] = -5; }
		ctx.globalAlpha = ppa[i] * (0.5 + 0.5 * Math.sin(t * 0.02 + ppd[i])) * (dark ? 1 : 0.8);
		ctx.fillRect(ppx[i] - 1, ppy[i] - 1, 2, 2);
	}

	// Jellyfish rise slowly and ease away from the cursor
	ctx.globalCompositeOperation = 'source-over';
	for (let i = 0; i < NJ; i++) {
		const dx = jx[i] - mouse.x, dy = jy[i] - mouse.y, d2 = dx * dx + dy * dy;
		if (d2 < 32400 && d2 > 1) jvx[i] += dx / Math.sqrt(d2) * 30 * MOUSE_CURRENT * mouse.amount * dt;
		jvx[i] *= 1 - Math.min(1, dt * 0.8);
		jx[i] += (Math.sin(t * 0.003 + jphase[i]) * 0.3 + cur * 5 * (1 - jdepth[i] * 0.5)) * f + jvx[i] * dt * pace;
		jy[i] -= jrise[i] * dt * pace;
		if (jy[i] < -jsz[i] * 3) spawnJelly(i, false);
		if (jx[i] < -100) jx[i] = w + 50; else if (jx[i] > w + 100) jx[i] = -50;
		drawJelly(i, t);
	}

	// Floor and its caustic network: two scales of one tile slide past each other
	ctx.globalAlpha = 1;
	ctx.drawImage(floorImg, 0, floorY - 60, w, h - floorY + 60);
	if (CAUSTICS > 0) {
		ctx.globalCompositeOperation = glow;
		ctx.globalAlpha = Math.min(1, CAUSTICS * (dark ? 0.15 : 0.55));
		for (let k = 0; k < 2; k++) {
			const tw = TW * (k ? 2.3 : 1.6), off = k ? (t * 0.25) % tw : tw - (t * 0.18) % tw;
			for (let x = -off; x < w; x += tw) ctx.drawImage(caustic, x, floorY, tw, h - floorY);
		}
		ctx.globalCompositeOperation = 'source-over';
	}

	// Kelp in front, in the outer thirds
	ctx.globalAlpha = 1;
	ctx.strokeStyle = C.kelp;
	ctx.fillStyle = C.leaf;
	for (let i = 0; i < NK; i++) drawKelp(i, t, cur);

	// One pass thins everything behind the chat column
	if (CENTER_CALM > 0) {
		ctx.globalCompositeOperation = 'destination-out';
		ctx.fillStyle = calmMask;
		ctx.fillRect(0, 0, w, h);
	}
	ctx.globalCompositeOperation = 'source-over';
	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			reduced = !!d.reducedMotion;
			column = d.column || null;
			theme = d.theme || null;
			dark = !theme || theme.dark !== false;
			size(d.width, d.height, d.dpr);
			requestAnimationFrame(frame);
			break;
		case 'resize':
			if (ctx) size(d.width, d.height, d.dpr);
			break;
		case 'theme':
			theme = d;
			dark = d.dark !== false;
			build();
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (!ctx || !w) break;
			placeSides();
			buildMask();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
		case 'mousedown':
			if (!reduced) ring(d.x, d.y);
			break;
	}
};

light.customCSS:
:root {
	--biolum-glass: color-mix(in oklab, var(--color-gray-50) 62%, transparent);
	--biolum-sidebar: color-mix(in oklab, var(--color-gray-50) 68%, transparent);
	--biolum-bubble: color-mix(in oklab, var(--color-gray-200) 55%, transparent);
	--biolum-selected: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--biolum-line: color-mix(in oklab, var(--color-gray-500) 26%, transparent);
	--biolum-glow: oklch(0.58 0.11 205 / 0.55);
	--biolum-ring: oklch(0.65 0.11 205 / 0.2);
	--biolum-shade: color-mix(in oklab, var(--color-gray-500) 30%, transparent);
	--biolum-accent: oklch(0.47 0.1 210);
}

/* Sunlit shallows: clear glass, teal ink. !important only where Canvas FX transparency clears a background first. */
#message-input-container {
	background-color: var(--biolum-glass) !important;
	border-color: var(--biolum-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--biolum-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--biolum-glow) !important;
	box-shadow: 0 0 0 3px var(--biolum-ring), 0 12px 40px -16px var(--biolum-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--biolum-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--biolum-line);
}
#sidebar {
	background-color: var(--biolum-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--biolum-line);
}
#sidebar-chat-item.selected { background-color: var(--biolum-selected); }
.markdown-prose :is(h1, h2, h3) { color: var(--biolum-accent); }
.markdown-prose a { color: var(--biolum-accent); text-decoration-color: var(--biolum-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--biolum-glow); }
.markdown-prose hr { border-color: var(--biolum-line); }
html { scrollbar-color: var(--biolum-line) transparent; }
::selection { background-color: var(--biolum-ring); }

light.canvasScript:
/**
 * Title: Deep Ocean
 * Description: A seafloor in your theme's colors, with light shafts, glowing jellyfish, plankton, swaying kelp and caustics on the sand, kept to the sides of the chat; the cursor stirs the current and a tap sends a sonar ring.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const JELLY_COUNT   = 5;     // glowing jellyfish (0-16)
const KELP_STRANDS  = 12;    // kelp fronds along the floor (0-24)
const PLANKTON      = 90;   // tiny drifting particles (0-300)
const RAY_COUNT     = 5;     // shafts of light from the surface (0-10)
const CURRENT       = 1;     // speed of the whole scene; 0 holds it still (0-3)
const REDUCED_SPEED = 0.2;   // share of the speed kept when the viewer asks to reduce motion (0-1)
const MOUSE_CURRENT = 1;     // how strongly the cursor stirs the current and nudges the jellies (0-3)
const PULSE_EVERY   = 45;    // average seconds between distant sonar rings; 0 turns them off (0-300)
const WATER_TINT    = 1.4;     // strength of the light glow from the surface (0-2)
const CAUSTICS      = 1.4;     // strength of the caustic light on the sand (0-2)
const FLOOR_HEIGHT  = 0.15;  // height of the sandy floor, as a share of the screen (0.05-0.3)
const CENTER_CALM   = 0.75;  // how much the scene fades behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const WATER_COLOR   = '#3c96c8';  // surface glow and light shafts when not following the theme
const JELLY_A       = '#5ee0f0';  // first jellyfish color
const JELLY_B       = '#b27cf0';  // second jellyfish color
const KELP_COLOR    = '#3a6e28';  // kelp
const SAND_COLOR    = '#2a2e1e';  // sandy floor
/* ──────────────────────────────────────────── */

const TAU = Math.PI * 2;
const NJ = Math.min(16, JELLY_COUNT | 0), NK = Math.min(24, KELP_STRANDS | 0), NP = Math.min(300, PLANKTON | 0), NR = Math.min(10, RAY_COUNT | 0);
const SEGS = 12, TW = 160, TH = 80, RINGS = 4;

let canvas, ctx;
let w = 0, h = 0, dpr = 1, floorY = 0;
let last = 0, T = 0, reduced = false, dark = true, theme = null, nextPulse = PULSE_EVERY * 0.5, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };

// Pools
const jx = new Float32Array(NJ), jy = new Float32Array(NJ), jsz = new Float32Array(NJ), jdepth = new Float32Array(NJ);
const jvx = new Float32Array(NJ), jrise = new Float32Array(NJ), jphase = new Float32Array(NJ), jtone = new Uint8Array(NJ), jtent = new Uint8Array(NJ);
const ppx = new Float32Array(NP), ppy = new Float32Array(NP), pps = new Float32Array(NP), ppd = new Float32Array(NP), ppa = new Float32Array(NP);
const rx = new Float32Array(NR), rw = new Float32Array(NR), rph = new Float32Array(NR), ra = new Float32Array(NR);
const kx = new Float32Array(NK), kh = new Float32Array(NK), kw = new Float32Array(NK), kph = new Float32Array(NK), kleaf = new Int8Array(NK * SEGS);
const kpx = new Float32Array(SEGS + 1), kpy = new Float32Array(SEGS + 1);
const ringX = new Float32Array(RINGS), ringY = new Float32Array(RINGS), ringR = new Float32Array(RINGS), ringA = new Float32Array(RINGS);

// Cached colors, gradients and sprites (rebuilt on theme change and resize)
const C = {};
let tint, rayGrad, calmMask, ringStyle, floorImg, caustic, glows = [];
let causticField = null;

function hexToRgb(hex) { const n = parseInt(String(hex).slice(1, 7), 16) || 0; return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function mix(a, b, t) { return [0, 1, 2].map((k) => Math.round(a[k] + (b[k] - a[k]) * t)); }
function rgba(c, a) { return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + Math.max(0, Math.min(1, a)).toFixed(3) + ')'; }
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

// The chat area's edges, which leave out the sidebar
function areaL() { return column ? column.left : 0; }
function areaR() { return column ? column.right : w; }
// Room beside the chat column on one side, at most reach of the screen wide
function room(right, reach) { const e = colX() + (right ? 1 : -1) * colHalf() * 0.5; return Math.max(40, Math.min(w * reach, right ? areaR() - e : e - areaL())); }
// A spot in the outer thirds, or nearer the edge when the chat column leaves less room
function side() { return Math.random() < 0.5 ? areaL() + Math.random() * room(false, 0.3) : areaR() - Math.random() * room(true, 0.3); }
function band(x) { const d = Math.abs(x - colX()) / colHalf(), s = Math.min(1, Math.max(0, (d - 0.5) / 0.8)); return 1 - s * s * (3 - 2 * s); }

function palette() {
	const c = FOLLOW_THEME && theme && theme.colors ? theme.colors : null;
	if (c) {
		const a = hexToRgb(c.accent), a2 = hexToRgb(c.accent2), a3 = hexToRgb(c.accent3), tx = hexToRgb(c.text), mu = hexToRgb(c.muted), bg = hexToRgb(c.background);
		return { water: a3, ray: dark ? mix(a3, tx, 0.3) : a3, jelly: [a3, a2], core: dark ? tx : a, kelp: dark ? mix(mix(a3, mu, 0.5), bg, 0.3) : mix(a3, tx, 0.35), sand: dark ? mix(mu, bg, 0.6) : mix(mu, bg, 0.3), light: dark ? mix(a3, tx, 0.4) : bg, mote: dark ? mix(a3, tx, 0.5) : a3 };
	}
	const water = hexToRgb(WATER_COLOR);
	return { water, ray: mix(water, [255, 255, 255], 0.25), jelly: [hexToRgb(JELLY_A), hexToRgb(JELLY_B)], core: [220, 250, 255], kelp: hexToRgb(KELP_COLOR), sand: hexToRgb(SAND_COLOR), light: [80, 180, 220], mote: [140, 200, 220] };
}

function glowSprite(c) {
	const s = new OffscreenCanvas(64, 64), g = s.getContext('2d'), gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
	gr.addColorStop(0, rgba(c, 0.6)); gr.addColorStop(0.4, rgba(c, 0.18)); gr.addColorStop(1, rgba(c, 0));
	g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
	return s;
}

// Wrapping cell-edge field for the caustic network, computed once
function buildField() {
	causticField = new Float32Array(TW * TH);
	const N = 11, sx = [], sy = [];
	for (let i = 0; i < N; i++) { sx.push(Math.random() * TW); sy.push(Math.random() * TH); }
	for (let y = 0; y < TH; y++) for (let x = 0; x < TW; x++) {
		let f1 = 1e9, f2 = 1e9;
		for (let i = 0; i < N; i++) {
			// A periodic warp curves the cell edges like real caustics and keeps the tile seamless
			let dx = Math.abs(x + Math.sin(y / TH * TAU * 2) * 5 - sx[i]), dy = Math.abs(y + Math.sin(x / TW * TAU * 3) * 4 - sy[i]);
			if (dx > TW) dx -= TW;
			if (dx > TW / 2) dx = TW - dx;
			if (dy > TH / 2) dy = TH - dy;
			const d = Math.sqrt(dx * dx + dy * dy);
			if (d < f1) { f2 = f1; f1 = d; } else if (d < f2) f2 = d;
		}
		const e = Math.max(0, 1 - (f2 - f1) / 9);
		const v = y / TH; // fades in from the top of the floor, so the tile needs no mask
		causticField[y * TW + x] = e * e * e * Math.min(1, v * 3) * (1 - v * 0.3);
	}
}

// The calm band's mask, rebuilt on resize, theme and layout
function buildMask() {
	calmMask = ctx.createLinearGradient(0, 0, w, 0);
	for (let s = 0; s <= 40; s++) calmMask.addColorStop(s / 40, 'rgba(0,0,0,' + (CENTER_CALM * band((s / 40) * w)).toFixed(3) + ')');
}

// Light shafts and kelp stand beside the chat column, placed again when it moves
function placeSides() {
	const L = room(false, 0.31), R = room(true, 0.31);
	for (let i = 0; i < NR; i++) rx[i] = side();
	for (let i = 0; i < NK; i++) {
		const f = (i + 0.5) / NK;
		kx[i] = (f < 0.5 ? areaL() + f * 2 * L : areaR() - (1 - f) * 2 * R) + (Math.random() - 0.5) * 30;
	}
}

function build() {
	if (!ctx || !w) return;
	const p = palette();
	if (!causticField) buildField();
	const fh = h - floorY;
	tint = ctx.createLinearGradient(0, 0, 0, h * 0.7);
	tint.addColorStop(0, rgba(p.water, (dark ? 0.14 : 0.09) * WATER_TINT));
	tint.addColorStop(1, rgba(p.water, 0));
	rayGrad = ctx.createLinearGradient(0, 0, 0, floorY);
	rayGrad.addColorStop(0, rgba(p.ray, 0.5)); rayGrad.addColorStop(0.5, rgba(p.ray, 0.16)); rayGrad.addColorStop(1, rgba(p.ray, 0));
	buildMask();
	ringStyle = rgba(p.water, dark ? 0.6 : 0.5);
	glows = [glowSprite(p.jelly[0]), glowSprite(p.jelly[1])];
	C.bell = p.jelly.map((c) => rgba(c, dark ? 0.45 : 0.4));
	C.inner = p.jelly.map((c) => rgba(mix(c, p.core, 0.5), dark ? 0.5 : 0.35));
	C.tent = p.jelly.map((c) => rgba(c, dark ? 0.35 : 0.3));
	C.kelp = rgba(p.kelp, dark ? 0.8 : 0.55);
	C.leaf = rgba(mix(p.kelp, p.light, 0.15), dark ? 0.55 : 0.4);
	C.mote = rgba(p.mote, 1);
	// Floor (sand and soft dunes) and the caustic tile, pre-rendered once
	floorImg = new OffscreenCanvas(Math.ceil(w * dpr), Math.ceil((fh + 60) * dpr));
	const g = floorImg.getContext('2d');
	g.scale(dpr, dpr);
	const fg = g.createLinearGradient(0, 0, 0, fh + 60);
	fg.addColorStop(0, rgba(p.sand, 0)); fg.addColorStop(0.4, rgba(p.sand, dark ? 0.6 : 0.4)); fg.addColorStop(1, rgba(p.sand, dark ? 0.75 : 0.55));
	g.fillStyle = fg; g.fillRect(0, 0, w, fh + 60);
	g.fillStyle = rgba(mix(p.sand, p.light, 0.25), dark ? 0.25 : 0.2);
	for (let i = 0; i < 34; i++) {
		g.beginPath();
		g.ellipse((i / 34) * w + Math.sin(i * 4.7) * 20, 66 + Math.sin(i * 2.1) * 8, 22 + Math.sin(i * 3) * 10, 4, 0, 0, TAU);
		g.fill();
	}
	caustic = new OffscreenCanvas(TW, TH);
	const cg = caustic.getContext('2d'), img = cg.createImageData(TW, TH);
	for (let i = 0; i < TW * TH; i++) { img.data[i * 4] = p.light[0]; img.data[i * 4 + 1] = p.light[1]; img.data[i * 4 + 2] = p.light[2]; img.data[i * 4 + 3] = causticField[i] * 255; }
	cg.putImageData(img, 0, 0);
}

function spawnJelly(i, anywhere) {
	jdepth[i] = Math.random();
	jsz[i] = 12 + (1 - jdepth[i]) * 16 + Math.random() * 8;
	jx[i] = side();
	jy[i] = anywhere ? h * (0.08 + Math.random() * 0.6) : floorY + jsz[i] * 3;
	jvx[i] = 0;
	jrise[i] = 1.5 + Math.random() * 3.5;
	jphase[i] = Math.random() * TAU;
	jtone[i] = Math.random() < 0.5 ? 0 : 1;
	jtent[i] = 5 + ((Math.random() * 4) | 0);
}

function seed() {
	for (let i = 0; i < NJ; i++) spawnJelly(i, true);
	for (let i = 0; i < NP; i++) { ppx[i] = Math.random() * w; ppy[i] = Math.random() * h; pps[i] = 0.05 + Math.random() * 0.15; ppd[i] = Math.random() * TAU; ppa[i] = 0.15 + Math.random() * 0.35; }
	for (let i = 0; i < NR; i++) { rw[i] = 30 + Math.random() * 70; rph[i] = Math.random() * TAU; ra[i] = 0.04 + Math.random() * 0.05; }
	placeSides();
	for (let i = 0; i < NK; i++) {
		kh[i] = 0.18 + Math.random() * 0.22;
		kw[i] = 2 + Math.random() * 2.5;
		kph[i] = Math.random() * TAU;
		for (let s = 0; s < SEGS; s++) kleaf[i * SEGS + s] = s > 1 && Math.random() > 0.25 ? (s & 1 ? 1 : -1) : 0;
	}
}

function size(nw, nh, ndpr) {
	const sx = w ? nw / w : 1, sy = h ? nh / h : 1, had = w > 0;
	w = nw; h = nh;
	dpr = Math.min(2, ndpr || 1);
	floorY = h * (1 - FLOOR_HEIGHT);
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	ctx.lineCap = 'round';
	if (!had) seed();
	else {
		// Keep the scene on a resize: move everything with the screen instead of re-rolling it
		for (let i = 0; i < NJ; i++) { jx[i] *= sx; jy[i] *= sy; }
		for (let i = 0; i < NP; i++) { ppx[i] *= sx; ppy[i] *= sy; }
		for (let i = 0; i < NR; i++) rx[i] *= sx;
		for (let i = 0; i < NK; i++) kx[i] *= sx;
	}
	build();
}

function drawJelly(i, t) {
	const pulse = 0.75 + 0.25 * Math.sin(t * 0.03 + jphase[i]);
	const cx = jx[i] + Math.sin(t * 0.008 + jphase[i]) * 8, cy = jy[i], sz = jsz[i] * pulse, k = jtone[i];
	const a = (0.55 + (1 - jdepth[i]) * 0.45);
	ctx.globalAlpha = a * (0.6 + 0.4 * pulse);
	ctx.drawImage(glows[k], cx - sz * 3, cy - sz * 3, sz * 6, sz * 6);
	ctx.globalAlpha = a;
	ctx.fillStyle = C.bell[k];
	ctx.beginPath();
	ctx.ellipse(cx, cy, sz * 0.7, sz * 0.5 * pulse + 2, 0, Math.PI, 0);
	ctx.fill();
	ctx.fillStyle = C.inner[k];
	ctx.beginPath();
	ctx.ellipse(cx, cy + sz * 0.05, sz * 0.4, sz * 0.25 * pulse + 1, 0, Math.PI, 0);
	ctx.fill();
	ctx.strokeStyle = C.tent[k];
	ctx.lineWidth = 1;
	ctx.beginPath();
	const n = jtent[i];
	for (let s = 0; s < n; s++) {
		const tx = cx + (s / (n - 1) - 0.5) * sz, len = sz * (1.4 + Math.sin(t * 0.012 + s * 1.3) * 0.4);
		ctx.moveTo(tx, cy + 1);
		ctx.bezierCurveTo(tx + Math.sin(t * 0.015 + s * 2) * 8, cy + len * 0.5, tx + Math.sin(t * 0.01 + s * 3) * 12, cy + len * 0.8, tx + Math.sin(t * 0.008 + s) * 10, cy + len);
	}
	ctx.stroke();
}

// A frond bends as one wave, so it curves instead of zigzagging
function drawKelp(i, t, cur) {
	const segH = h * kh[i] / SEGS;
	kpx[0] = kx[i]; kpy[0] = h + 4;
	for (let s = 1; s <= SEGS; s++) {
		const prog = s / SEGS;
		kpx[s] = kx[i] + Math.sin(t * 0.012 + kph[i] - s * 0.45) * (2 + s * 1.6) + cur * prog * prog * 200;
		kpy[s] = h + 4 - segH * s;
	}
	for (let half = 0; half < 2; half++) {
		const a = half ? SEGS >> 1 : 0, b = half ? SEGS : SEGS >> 1;
		ctx.lineWidth = kw[i] * (half ? 0.65 : 1);
		ctx.beginPath();
		ctx.moveTo(kpx[a], kpy[a]);
		for (let s = a + 1; s <= b; s++) ctx.quadraticCurveTo(kpx[s - 1], kpy[s - 1], (kpx[s - 1] + kpx[s]) * 0.5, (kpy[s - 1] + kpy[s]) * 0.5);
		ctx.lineTo(kpx[b], kpy[b]);
		ctx.stroke();
	}
	ctx.beginPath();
	for (let s = 1; s < SEGS; s++) {
		const sd = kleaf[i * SEGS + s];
		if (!sd) continue;
		const x = kpx[s], y = kpy[s], len = (10 + (1 - s / SEGS) * 14) * (0.8 + 0.2 * Math.sin(t * 0.016 + kph[i] + s));
		ctx.moveTo(x, y);
		ctx.quadraticCurveTo(x + sd * len * 0.5, y - 7, x + sd * len, y - 4);
		ctx.quadraticCurveTo(x + sd * len * 0.5, y + 3, x, y + 2);
	}
	ctx.fill();
}

function ring(x, y) {
	let k = 0;
	for (let i = 1; i < RINGS; i++) if (ringA[i] < ringA[k]) k = i;
	ringX[k] = x; ringY[k] = y; ringR[k] = 0; ringA[k] = 0.14;
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!ctx || !caustic) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const pace = CURRENT * (reduced ? REDUCED_SPEED : 1), f = dt * 60 * pace;
	T += f;
	const t = T;
	mouse.target = Math.max(0, mouse.target - dt * 0.5);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 2);
	const cur = (Math.min(w, Math.max(0, mouse.x)) / w - 0.5) * 0.15 * MOUSE_CURRENT * mouse.amount;

	ctx.globalAlpha = 1;
	ctx.globalCompositeOperation = 'source-over';
	ctx.clearRect(0, 0, w, h);
	ctx.fillStyle = tint;
	ctx.fillRect(0, 0, w, h * 0.7);
	const glow = dark ? 'lighter' : 'source-over';
	ctx.globalCompositeOperation = glow;

	// Light shafts, in the outer thirds
	ctx.fillStyle = rayGrad;
	for (let i = 0; i < NR; i++) {
		const sway = Math.sin(t * 0.003 + rph[i]) * 40 + cur * 300, top = rx[i] + sway, half = rw[i] * 0.9;
		ctx.globalAlpha = ra[i] * (0.7 + 0.3 * Math.sin(t * 0.004 + rph[i])) * (dark ? 1.4 : 1);
		ctx.beginPath();
		ctx.moveTo(top - rw[i] * 0.3, 0); ctx.lineTo(top + rw[i] * 0.3, 0);
		ctx.lineTo(top + half + sway * 0.5, floorY); ctx.lineTo(top - half + sway * 0.5, floorY);
		ctx.fill();
	}

	// Sonar rings: rare and distant, or from a tap
	if (PULSE_EVERY > 0 && !reduced && pace > 0) {
		nextPulse -= dt;
		if (nextPulse <= 0) { ring(side(), h * (0.3 + Math.random() * 0.3)); nextPulse = PULSE_EVERY * (0.6 + Math.random() * 0.8); }
	}
	ctx.strokeStyle = ringStyle;
	ctx.lineWidth = 1.5;
	for (let i = 0; i < RINGS; i++) {
		if (ringA[i] < 0.004) continue;
		ringR[i] += 150 * dt * pace;
		ringA[i] *= Math.exp(-0.35 * dt * pace);
		if (ringR[i] > Math.max(w, h)) { ringA[i] = 0; continue; }
		ctx.globalAlpha = ringA[i] * Math.min(1, ringR[i] / 40);
		ctx.beginPath();
		ctx.arc(ringX[i], ringY[i], ringR[i], 0, TAU);
		ctx.stroke();
	}

	// Plankton
	ctx.fillStyle = C.mote;
	for (let i = 0; i < NP; i++) {
		ppx[i] += (Math.sin(t * 0.005 + ppd[i]) * pps[i] + cur * 6) * f;
		ppy[i] += (pps[i] * 0.5 + Math.cos(t * 0.003 + ppd[i]) * 0.1) * f;
		if (ppy[i] > h + 5 || ppx[i] < -10 || ppx[i] > w + 10) { ppx[i] = Math.random() * w; ppy[i] = -5; }
		ctx.globalAlpha = ppa[i] * (0.5 + 0.5 * Math.sin(t * 0.02 + ppd[i])) * (dark ? 1 : 0.8);
		ctx.fillRect(ppx[i] - 1, ppy[i] - 1, 2, 2);
	}

	// Jellyfish rise slowly and ease away from the cursor
	ctx.globalCompositeOperation = 'source-over';
	for (let i = 0; i < NJ; i++) {
		const dx = jx[i] - mouse.x, dy = jy[i] - mouse.y, d2 = dx * dx + dy * dy;
		if (d2 < 32400 && d2 > 1) jvx[i] += dx / Math.sqrt(d2) * 30 * MOUSE_CURRENT * mouse.amount * dt;
		jvx[i] *= 1 - Math.min(1, dt * 0.8);
		jx[i] += (Math.sin(t * 0.003 + jphase[i]) * 0.3 + cur * 5 * (1 - jdepth[i] * 0.5)) * f + jvx[i] * dt * pace;
		jy[i] -= jrise[i] * dt * pace;
		if (jy[i] < -jsz[i] * 3) spawnJelly(i, false);
		if (jx[i] < -100) jx[i] = w + 50; else if (jx[i] > w + 100) jx[i] = -50;
		drawJelly(i, t);
	}

	// Floor and its caustic network: two scales of one tile slide past each other
	ctx.globalAlpha = 1;
	ctx.drawImage(floorImg, 0, floorY - 60, w, h - floorY + 60);
	if (CAUSTICS > 0) {
		ctx.globalCompositeOperation = glow;
		ctx.globalAlpha = Math.min(1, CAUSTICS * (dark ? 0.15 : 0.55));
		for (let k = 0; k < 2; k++) {
			const tw = TW * (k ? 2.3 : 1.6), off = k ? (t * 0.25) % tw : tw - (t * 0.18) % tw;
			for (let x = -off; x < w; x += tw) ctx.drawImage(caustic, x, floorY, tw, h - floorY);
		}
		ctx.globalCompositeOperation = 'source-over';
	}

	// Kelp in front, in the outer thirds
	ctx.globalAlpha = 1;
	ctx.strokeStyle = C.kelp;
	ctx.fillStyle = C.leaf;
	for (let i = 0; i < NK; i++) drawKelp(i, t, cur);

	// One pass thins everything behind the chat column
	if (CENTER_CALM > 0) {
		ctx.globalCompositeOperation = 'destination-out';
		ctx.fillStyle = calmMask;
		ctx.fillRect(0, 0, w, h);
	}
	ctx.globalCompositeOperation = 'source-over';
	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			reduced = !!d.reducedMotion;
			column = d.column || null;
			theme = d.theme || null;
			dark = !theme || theme.dark !== false;
			size(d.width, d.height, d.dpr);
			requestAnimationFrame(frame);
			break;
		case 'resize':
			if (ctx) size(d.width, d.height, d.dpr);
			break;
		case 'theme':
			theme = d;
			dark = d.dark !== false;
			build();
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (!ctx || !w) break;
			placeSides();
			buildMask();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
		case 'mousedown':
			if (!reduced) ring(d.x, d.y);
			break;
	}
};

oled.customCSS:
:root {
	--biolum-glass: color-mix(in oklab, var(--color-gray-850) 60%, transparent);
	--biolum-sidebar: color-mix(in oklab, var(--color-gray-950) 80%, transparent);
	--biolum-bubble: color-mix(in oklab, var(--color-gray-700) 52%, transparent);
	--biolum-selected: color-mix(in oklab, var(--color-gray-500) 20%, transparent);
	--biolum-line: color-mix(in oklab, var(--color-gray-400) 22%, transparent);
	--biolum-glow: oklch(0.85 0.14 200 / 0.55);
	--biolum-ring: oklch(0.85 0.14 200 / 0.18);
	--biolum-shade: color-mix(in oklab, var(--color-gray-950) 65%, transparent);
	--biolum-accent: oklch(0.87 0.12 200);
}

/* Frosted water over the deep, with a cyan glow on what matters. !important only where Canvas FX transparency clears a background first. */
#message-input-container {
	background-color: var(--biolum-glass) !important;
	border-color: var(--biolum-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--biolum-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--biolum-glow) !important;
	box-shadow: 0 0 0 3px var(--biolum-ring), 0 12px 40px -16px var(--biolum-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--biolum-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--biolum-line);
}
#sidebar {
	background-color: var(--biolum-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--biolum-line);
}
#sidebar-chat-item.selected { background-color: var(--biolum-selected); }
.markdown-prose :is(h1, h2, h3) { color: var(--biolum-accent); text-shadow: 0 0 14px var(--biolum-ring); }
.markdown-prose a { color: var(--biolum-accent); text-decoration-color: var(--biolum-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--biolum-glow); }
.markdown-prose hr { border-color: var(--biolum-line); }
html { scrollbar-color: var(--biolum-line) transparent; }
::selection { background-color: var(--biolum-ring); }

oled.canvasScript:
/**
 * Title: Deep Ocean
 * Description: A seafloor in your theme's colors, with light shafts, glowing jellyfish, plankton, swaying kelp and caustics on the sand, kept to the sides of the chat; the cursor stirs the current and a tap sends a sonar ring.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const JELLY_COUNT   = 7;     // glowing jellyfish (0-16)
const KELP_STRANDS  = 12;    // kelp fronds along the floor (0-24)
const PLANKTON      = 120;   // tiny drifting particles (0-300)
const RAY_COUNT     = 5;     // shafts of light from the surface (0-10)
const CURRENT       = 1;     // speed of the whole scene; 0 holds it still (0-3)
const REDUCED_SPEED = 0.2;   // share of the speed kept when the viewer asks to reduce motion (0-1)
const MOUSE_CURRENT = 1;     // how strongly the cursor stirs the current and nudges the jellies (0-3)
const PULSE_EVERY   = 45;    // average seconds between distant sonar rings; 0 turns them off (0-300)
const WATER_TINT    = 1;     // strength of the light glow from the surface (0-2)
const CAUSTICS      = 1;     // strength of the caustic light on the sand (0-2)
const FLOOR_HEIGHT  = 0.15;  // height of the sandy floor, as a share of the screen (0.05-0.3)
const CENTER_CALM   = 0.75;  // how much the scene fades behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const WATER_COLOR   = '#3c96c8';  // surface glow and light shafts when not following the theme
const JELLY_A       = '#5ee0f0';  // first jellyfish color
const JELLY_B       = '#b27cf0';  // second jellyfish color
const KELP_COLOR    = '#3a6e28';  // kelp
const SAND_COLOR    = '#2a2e1e';  // sandy floor
/* ──────────────────────────────────────────── */

const TAU = Math.PI * 2;
const NJ = Math.min(16, JELLY_COUNT | 0), NK = Math.min(24, KELP_STRANDS | 0), NP = Math.min(300, PLANKTON | 0), NR = Math.min(10, RAY_COUNT | 0);
const SEGS = 12, TW = 160, TH = 80, RINGS = 4;

let canvas, ctx;
let w = 0, h = 0, dpr = 1, floorY = 0;
let last = 0, T = 0, reduced = false, dark = true, theme = null, nextPulse = PULSE_EVERY * 0.5, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };

// Pools
const jx = new Float32Array(NJ), jy = new Float32Array(NJ), jsz = new Float32Array(NJ), jdepth = new Float32Array(NJ);
const jvx = new Float32Array(NJ), jrise = new Float32Array(NJ), jphase = new Float32Array(NJ), jtone = new Uint8Array(NJ), jtent = new Uint8Array(NJ);
const ppx = new Float32Array(NP), ppy = new Float32Array(NP), pps = new Float32Array(NP), ppd = new Float32Array(NP), ppa = new Float32Array(NP);
const rx = new Float32Array(NR), rw = new Float32Array(NR), rph = new Float32Array(NR), ra = new Float32Array(NR);
const kx = new Float32Array(NK), kh = new Float32Array(NK), kw = new Float32Array(NK), kph = new Float32Array(NK), kleaf = new Int8Array(NK * SEGS);
const kpx = new Float32Array(SEGS + 1), kpy = new Float32Array(SEGS + 1);
const ringX = new Float32Array(RINGS), ringY = new Float32Array(RINGS), ringR = new Float32Array(RINGS), ringA = new Float32Array(RINGS);

// Cached colors, gradients and sprites (rebuilt on theme change and resize)
const C = {};
let tint, rayGrad, calmMask, ringStyle, floorImg, caustic, glows = [];
let causticField = null;

function hexToRgb(hex) { const n = parseInt(String(hex).slice(1, 7), 16) || 0; return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function mix(a, b, t) { return [0, 1, 2].map((k) => Math.round(a[k] + (b[k] - a[k]) * t)); }
function rgba(c, a) { return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + Math.max(0, Math.min(1, a)).toFixed(3) + ')'; }
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

// The chat area's edges, which leave out the sidebar
function areaL() { return column ? column.left : 0; }
function areaR() { return column ? column.right : w; }
// Room beside the chat column on one side, at most reach of the screen wide
function room(right, reach) { const e = colX() + (right ? 1 : -1) * colHalf() * 0.5; return Math.max(40, Math.min(w * reach, right ? areaR() - e : e - areaL())); }
// A spot in the outer thirds, or nearer the edge when the chat column leaves less room
function side() { return Math.random() < 0.5 ? areaL() + Math.random() * room(false, 0.3) : areaR() - Math.random() * room(true, 0.3); }
function band(x) { const d = Math.abs(x - colX()) / colHalf(), s = Math.min(1, Math.max(0, (d - 0.5) / 0.8)); return 1 - s * s * (3 - 2 * s); }

function palette() {
	const c = FOLLOW_THEME && theme && theme.colors ? theme.colors : null;
	if (c) {
		const a = hexToRgb(c.accent), a2 = hexToRgb(c.accent2), a3 = hexToRgb(c.accent3), tx = hexToRgb(c.text), mu = hexToRgb(c.muted), bg = hexToRgb(c.background);
		return { water: a3, ray: dark ? mix(a3, tx, 0.3) : a3, jelly: [a3, a2], core: dark ? tx : a, kelp: dark ? mix(mix(a3, mu, 0.5), bg, 0.3) : mix(a3, tx, 0.35), sand: dark ? mix(mu, bg, 0.6) : mix(mu, bg, 0.3), light: dark ? mix(a3, tx, 0.4) : bg, mote: dark ? mix(a3, tx, 0.5) : a3 };
	}
	const water = hexToRgb(WATER_COLOR);
	return { water, ray: mix(water, [255, 255, 255], 0.25), jelly: [hexToRgb(JELLY_A), hexToRgb(JELLY_B)], core: [220, 250, 255], kelp: hexToRgb(KELP_COLOR), sand: hexToRgb(SAND_COLOR), light: [80, 180, 220], mote: [140, 200, 220] };
}

function glowSprite(c) {
	const s = new OffscreenCanvas(64, 64), g = s.getContext('2d'), gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
	gr.addColorStop(0, rgba(c, 0.6)); gr.addColorStop(0.4, rgba(c, 0.18)); gr.addColorStop(1, rgba(c, 0));
	g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
	return s;
}

// Wrapping cell-edge field for the caustic network, computed once
function buildField() {
	causticField = new Float32Array(TW * TH);
	const N = 11, sx = [], sy = [];
	for (let i = 0; i < N; i++) { sx.push(Math.random() * TW); sy.push(Math.random() * TH); }
	for (let y = 0; y < TH; y++) for (let x = 0; x < TW; x++) {
		let f1 = 1e9, f2 = 1e9;
		for (let i = 0; i < N; i++) {
			// A periodic warp curves the cell edges like real caustics and keeps the tile seamless
			let dx = Math.abs(x + Math.sin(y / TH * TAU * 2) * 5 - sx[i]), dy = Math.abs(y + Math.sin(x / TW * TAU * 3) * 4 - sy[i]);
			if (dx > TW) dx -= TW;
			if (dx > TW / 2) dx = TW - dx;
			if (dy > TH / 2) dy = TH - dy;
			const d = Math.sqrt(dx * dx + dy * dy);
			if (d < f1) { f2 = f1; f1 = d; } else if (d < f2) f2 = d;
		}
		const e = Math.max(0, 1 - (f2 - f1) / 9);
		const v = y / TH; // fades in from the top of the floor, so the tile needs no mask
		causticField[y * TW + x] = e * e * e * Math.min(1, v * 3) * (1 - v * 0.3);
	}
}

// The calm band's mask, rebuilt on resize, theme and layout
function buildMask() {
	calmMask = ctx.createLinearGradient(0, 0, w, 0);
	for (let s = 0; s <= 40; s++) calmMask.addColorStop(s / 40, 'rgba(0,0,0,' + (CENTER_CALM * band((s / 40) * w)).toFixed(3) + ')');
}

// Light shafts and kelp stand beside the chat column, placed again when it moves
function placeSides() {
	const L = room(false, 0.31), R = room(true, 0.31);
	for (let i = 0; i < NR; i++) rx[i] = side();
	for (let i = 0; i < NK; i++) {
		const f = (i + 0.5) / NK;
		kx[i] = (f < 0.5 ? areaL() + f * 2 * L : areaR() - (1 - f) * 2 * R) + (Math.random() - 0.5) * 30;
	}
}

function build() {
	if (!ctx || !w) return;
	const p = palette();
	if (!causticField) buildField();
	const fh = h - floorY;
	tint = ctx.createLinearGradient(0, 0, 0, h * 0.7);
	tint.addColorStop(0, rgba(p.water, (dark ? 0.14 : 0.09) * WATER_TINT));
	tint.addColorStop(1, rgba(p.water, 0));
	rayGrad = ctx.createLinearGradient(0, 0, 0, floorY);
	rayGrad.addColorStop(0, rgba(p.ray, 0.5)); rayGrad.addColorStop(0.5, rgba(p.ray, 0.16)); rayGrad.addColorStop(1, rgba(p.ray, 0));
	buildMask();
	ringStyle = rgba(p.water, dark ? 0.6 : 0.5);
	glows = [glowSprite(p.jelly[0]), glowSprite(p.jelly[1])];
	C.bell = p.jelly.map((c) => rgba(c, dark ? 0.45 : 0.4));
	C.inner = p.jelly.map((c) => rgba(mix(c, p.core, 0.5), dark ? 0.5 : 0.35));
	C.tent = p.jelly.map((c) => rgba(c, dark ? 0.35 : 0.3));
	C.kelp = rgba(p.kelp, dark ? 0.8 : 0.55);
	C.leaf = rgba(mix(p.kelp, p.light, 0.15), dark ? 0.55 : 0.4);
	C.mote = rgba(p.mote, 1);
	// Floor (sand and soft dunes) and the caustic tile, pre-rendered once
	floorImg = new OffscreenCanvas(Math.ceil(w * dpr), Math.ceil((fh + 60) * dpr));
	const g = floorImg.getContext('2d');
	g.scale(dpr, dpr);
	const fg = g.createLinearGradient(0, 0, 0, fh + 60);
	fg.addColorStop(0, rgba(p.sand, 0)); fg.addColorStop(0.4, rgba(p.sand, dark ? 0.6 : 0.4)); fg.addColorStop(1, rgba(p.sand, dark ? 0.75 : 0.55));
	g.fillStyle = fg; g.fillRect(0, 0, w, fh + 60);
	g.fillStyle = rgba(mix(p.sand, p.light, 0.25), dark ? 0.25 : 0.2);
	for (let i = 0; i < 34; i++) {
		g.beginPath();
		g.ellipse((i / 34) * w + Math.sin(i * 4.7) * 20, 66 + Math.sin(i * 2.1) * 8, 22 + Math.sin(i * 3) * 10, 4, 0, 0, TAU);
		g.fill();
	}
	caustic = new OffscreenCanvas(TW, TH);
	const cg = caustic.getContext('2d'), img = cg.createImageData(TW, TH);
	for (let i = 0; i < TW * TH; i++) { img.data[i * 4] = p.light[0]; img.data[i * 4 + 1] = p.light[1]; img.data[i * 4 + 2] = p.light[2]; img.data[i * 4 + 3] = causticField[i] * 255; }
	cg.putImageData(img, 0, 0);
}

function spawnJelly(i, anywhere) {
	jdepth[i] = Math.random();
	jsz[i] = 12 + (1 - jdepth[i]) * 16 + Math.random() * 8;
	jx[i] = side();
	jy[i] = anywhere ? h * (0.08 + Math.random() * 0.6) : floorY + jsz[i] * 3;
	jvx[i] = 0;
	jrise[i] = 1.5 + Math.random() * 3.5;
	jphase[i] = Math.random() * TAU;
	jtone[i] = Math.random() < 0.5 ? 0 : 1;
	jtent[i] = 5 + ((Math.random() * 4) | 0);
}

function seed() {
	for (let i = 0; i < NJ; i++) spawnJelly(i, true);
	for (let i = 0; i < NP; i++) { ppx[i] = Math.random() * w; ppy[i] = Math.random() * h; pps[i] = 0.05 + Math.random() * 0.15; ppd[i] = Math.random() * TAU; ppa[i] = 0.15 + Math.random() * 0.35; }
	for (let i = 0; i < NR; i++) { rw[i] = 30 + Math.random() * 70; rph[i] = Math.random() * TAU; ra[i] = 0.04 + Math.random() * 0.05; }
	placeSides();
	for (let i = 0; i < NK; i++) {
		kh[i] = 0.18 + Math.random() * 0.22;
		kw[i] = 2 + Math.random() * 2.5;
		kph[i] = Math.random() * TAU;
		for (let s = 0; s < SEGS; s++) kleaf[i * SEGS + s] = s > 1 && Math.random() > 0.25 ? (s & 1 ? 1 : -1) : 0;
	}
}

function size(nw, nh, ndpr) {
	const sx = w ? nw / w : 1, sy = h ? nh / h : 1, had = w > 0;
	w = nw; h = nh;
	dpr = Math.min(2, ndpr || 1);
	floorY = h * (1 - FLOOR_HEIGHT);
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	ctx.lineCap = 'round';
	if (!had) seed();
	else {
		// Keep the scene on a resize: move everything with the screen instead of re-rolling it
		for (let i = 0; i < NJ; i++) { jx[i] *= sx; jy[i] *= sy; }
		for (let i = 0; i < NP; i++) { ppx[i] *= sx; ppy[i] *= sy; }
		for (let i = 0; i < NR; i++) rx[i] *= sx;
		for (let i = 0; i < NK; i++) kx[i] *= sx;
	}
	build();
}

function drawJelly(i, t) {
	const pulse = 0.75 + 0.25 * Math.sin(t * 0.03 + jphase[i]);
	const cx = jx[i] + Math.sin(t * 0.008 + jphase[i]) * 8, cy = jy[i], sz = jsz[i] * pulse, k = jtone[i];
	const a = (0.55 + (1 - jdepth[i]) * 0.45);
	ctx.globalAlpha = a * (0.6 + 0.4 * pulse);
	ctx.drawImage(glows[k], cx - sz * 3, cy - sz * 3, sz * 6, sz * 6);
	ctx.globalAlpha = a;
	ctx.fillStyle = C.bell[k];
	ctx.beginPath();
	ctx.ellipse(cx, cy, sz * 0.7, sz * 0.5 * pulse + 2, 0, Math.PI, 0);
	ctx.fill();
	ctx.fillStyle = C.inner[k];
	ctx.beginPath();
	ctx.ellipse(cx, cy + sz * 0.05, sz * 0.4, sz * 0.25 * pulse + 1, 0, Math.PI, 0);
	ctx.fill();
	ctx.strokeStyle = C.tent[k];
	ctx.lineWidth = 1;
	ctx.beginPath();
	const n = jtent[i];
	for (let s = 0; s < n; s++) {
		const tx = cx + (s / (n - 1) - 0.5) * sz, len = sz * (1.4 + Math.sin(t * 0.012 + s * 1.3) * 0.4);
		ctx.moveTo(tx, cy + 1);
		ctx.bezierCurveTo(tx + Math.sin(t * 0.015 + s * 2) * 8, cy + len * 0.5, tx + Math.sin(t * 0.01 + s * 3) * 12, cy + len * 0.8, tx + Math.sin(t * 0.008 + s) * 10, cy + len);
	}
	ctx.stroke();
}

// A frond bends as one wave, so it curves instead of zigzagging
function drawKelp(i, t, cur) {
	const segH = h * kh[i] / SEGS;
	kpx[0] = kx[i]; kpy[0] = h + 4;
	for (let s = 1; s <= SEGS; s++) {
		const prog = s / SEGS;
		kpx[s] = kx[i] + Math.sin(t * 0.012 + kph[i] - s * 0.45) * (2 + s * 1.6) + cur * prog * prog * 200;
		kpy[s] = h + 4 - segH * s;
	}
	for (let half = 0; half < 2; half++) {
		const a = half ? SEGS >> 1 : 0, b = half ? SEGS : SEGS >> 1;
		ctx.lineWidth = kw[i] * (half ? 0.65 : 1);
		ctx.beginPath();
		ctx.moveTo(kpx[a], kpy[a]);
		for (let s = a + 1; s <= b; s++) ctx.quadraticCurveTo(kpx[s - 1], kpy[s - 1], (kpx[s - 1] + kpx[s]) * 0.5, (kpy[s - 1] + kpy[s]) * 0.5);
		ctx.lineTo(kpx[b], kpy[b]);
		ctx.stroke();
	}
	ctx.beginPath();
	for (let s = 1; s < SEGS; s++) {
		const sd = kleaf[i * SEGS + s];
		if (!sd) continue;
		const x = kpx[s], y = kpy[s], len = (10 + (1 - s / SEGS) * 14) * (0.8 + 0.2 * Math.sin(t * 0.016 + kph[i] + s));
		ctx.moveTo(x, y);
		ctx.quadraticCurveTo(x + sd * len * 0.5, y - 7, x + sd * len, y - 4);
		ctx.quadraticCurveTo(x + sd * len * 0.5, y + 3, x, y + 2);
	}
	ctx.fill();
}

function ring(x, y) {
	let k = 0;
	for (let i = 1; i < RINGS; i++) if (ringA[i] < ringA[k]) k = i;
	ringX[k] = x; ringY[k] = y; ringR[k] = 0; ringA[k] = 0.14;
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!ctx || !caustic) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const pace = CURRENT * (reduced ? REDUCED_SPEED : 1), f = dt * 60 * pace;
	T += f;
	const t = T;
	mouse.target = Math.max(0, mouse.target - dt * 0.5);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 2);
	const cur = (Math.min(w, Math.max(0, mouse.x)) / w - 0.5) * 0.15 * MOUSE_CURRENT * mouse.amount;

	ctx.globalAlpha = 1;
	ctx.globalCompositeOperation = 'source-over';
	ctx.clearRect(0, 0, w, h);
	ctx.fillStyle = tint;
	ctx.fillRect(0, 0, w, h * 0.7);
	const glow = dark ? 'lighter' : 'source-over';
	ctx.globalCompositeOperation = glow;

	// Light shafts, in the outer thirds
	ctx.fillStyle = rayGrad;
	for (let i = 0; i < NR; i++) {
		const sway = Math.sin(t * 0.003 + rph[i]) * 40 + cur * 300, top = rx[i] + sway, half = rw[i] * 0.9;
		ctx.globalAlpha = ra[i] * (0.7 + 0.3 * Math.sin(t * 0.004 + rph[i])) * (dark ? 1.4 : 1);
		ctx.beginPath();
		ctx.moveTo(top - rw[i] * 0.3, 0); ctx.lineTo(top + rw[i] * 0.3, 0);
		ctx.lineTo(top + half + sway * 0.5, floorY); ctx.lineTo(top - half + sway * 0.5, floorY);
		ctx.fill();
	}

	// Sonar rings: rare and distant, or from a tap
	if (PULSE_EVERY > 0 && !reduced && pace > 0) {
		nextPulse -= dt;
		if (nextPulse <= 0) { ring(side(), h * (0.3 + Math.random() * 0.3)); nextPulse = PULSE_EVERY * (0.6 + Math.random() * 0.8); }
	}
	ctx.strokeStyle = ringStyle;
	ctx.lineWidth = 1.5;
	for (let i = 0; i < RINGS; i++) {
		if (ringA[i] < 0.004) continue;
		ringR[i] += 150 * dt * pace;
		ringA[i] *= Math.exp(-0.35 * dt * pace);
		if (ringR[i] > Math.max(w, h)) { ringA[i] = 0; continue; }
		ctx.globalAlpha = ringA[i] * Math.min(1, ringR[i] / 40);
		ctx.beginPath();
		ctx.arc(ringX[i], ringY[i], ringR[i], 0, TAU);
		ctx.stroke();
	}

	// Plankton
	ctx.fillStyle = C.mote;
	for (let i = 0; i < NP; i++) {
		ppx[i] += (Math.sin(t * 0.005 + ppd[i]) * pps[i] + cur * 6) * f;
		ppy[i] += (pps[i] * 0.5 + Math.cos(t * 0.003 + ppd[i]) * 0.1) * f;
		if (ppy[i] > h + 5 || ppx[i] < -10 || ppx[i] > w + 10) { ppx[i] = Math.random() * w; ppy[i] = -5; }
		ctx.globalAlpha = ppa[i] * (0.5 + 0.5 * Math.sin(t * 0.02 + ppd[i])) * (dark ? 1 : 0.8);
		ctx.fillRect(ppx[i] - 1, ppy[i] - 1, 2, 2);
	}

	// Jellyfish rise slowly and ease away from the cursor
	ctx.globalCompositeOperation = 'source-over';
	for (let i = 0; i < NJ; i++) {
		const dx = jx[i] - mouse.x, dy = jy[i] - mouse.y, d2 = dx * dx + dy * dy;
		if (d2 < 32400 && d2 > 1) jvx[i] += dx / Math.sqrt(d2) * 30 * MOUSE_CURRENT * mouse.amount * dt;
		jvx[i] *= 1 - Math.min(1, dt * 0.8);
		jx[i] += (Math.sin(t * 0.003 + jphase[i]) * 0.3 + cur * 5 * (1 - jdepth[i] * 0.5)) * f + jvx[i] * dt * pace;
		jy[i] -= jrise[i] * dt * pace;
		if (jy[i] < -jsz[i] * 3) spawnJelly(i, false);
		if (jx[i] < -100) jx[i] = w + 50; else if (jx[i] > w + 100) jx[i] = -50;
		drawJelly(i, t);
	}

	// Floor and its caustic network: two scales of one tile slide past each other
	ctx.globalAlpha = 1;
	ctx.drawImage(floorImg, 0, floorY - 60, w, h - floorY + 60);
	if (CAUSTICS > 0) {
		ctx.globalCompositeOperation = glow;
		ctx.globalAlpha = Math.min(1, CAUSTICS * (dark ? 0.15 : 0.55));
		for (let k = 0; k < 2; k++) {
			const tw = TW * (k ? 2.3 : 1.6), off = k ? (t * 0.25) % tw : tw - (t * 0.18) % tw;
			for (let x = -off; x < w; x += tw) ctx.drawImage(caustic, x, floorY, tw, h - floorY);
		}
		ctx.globalCompositeOperation = 'source-over';
	}

	// Kelp in front, in the outer thirds
	ctx.globalAlpha = 1;
	ctx.strokeStyle = C.kelp;
	ctx.fillStyle = C.leaf;
	for (let i = 0; i < NK; i++) drawKelp(i, t, cur);

	// One pass thins everything behind the chat column
	if (CENTER_CALM > 0) {
		ctx.globalCompositeOperation = 'destination-out';
		ctx.fillStyle = calmMask;
		ctx.fillRect(0, 0, w, h);
	}
	ctx.globalCompositeOperation = 'source-over';
	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			reduced = !!d.reducedMotion;
			column = d.column || null;
			theme = d.theme || null;
			dark = !theme || theme.dark !== false;
			size(d.width, d.height, d.dpr);
			requestAnimationFrame(frame);
			break;
		case 'resize':
			if (ctx) size(d.width, d.height, d.dpr);
			break;
		case 'theme':
			theme = d;
			dark = d.dark !== false;
			build();
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (!ctx || !w) break;
			placeSides();
			buildMask();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
		case 'mousedown':
			if (!reduced) ring(d.x, d.y);
			break;
	}
};

her.customCSS:
:root {
	--biolum-glass: color-mix(in oklab, var(--color-gray-50) 62%, transparent);
	--biolum-sidebar: color-mix(in oklab, var(--color-gray-50) 68%, transparent);
	--biolum-bubble: color-mix(in oklab, var(--color-gray-200) 55%, transparent);
	--biolum-selected: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--biolum-line: color-mix(in oklab, var(--color-gray-500) 26%, transparent);
	--biolum-glow: oklch(0.58 0.1 175 / 0.55);
	--biolum-ring: oklch(0.65 0.1 175 / 0.2);
	--biolum-shade: color-mix(in oklab, var(--color-gray-500) 30%, transparent);
	--biolum-accent: oklch(0.47 0.09 180);
}

/* Sunlit shallows: clear glass, teal ink. !important only where Canvas FX transparency clears a background first. */
#message-input-container {
	background-color: var(--biolum-glass) !important;
	border-color: var(--biolum-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--biolum-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--biolum-glow) !important;
	box-shadow: 0 0 0 3px var(--biolum-ring), 0 12px 40px -16px var(--biolum-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--biolum-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--biolum-line);
}
#sidebar {
	background-color: var(--biolum-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--biolum-line);
}
#sidebar-chat-item.selected { background-color: var(--biolum-selected); }
.markdown-prose :is(h1, h2, h3) { color: var(--biolum-accent); }
.markdown-prose a { color: var(--biolum-accent); text-decoration-color: var(--biolum-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--biolum-glow); }
.markdown-prose hr { border-color: var(--biolum-line); }
html { scrollbar-color: var(--biolum-line) transparent; }
::selection { background-color: var(--biolum-ring); }

her.canvasScript:
/**
 * Title: Deep Ocean
 * Description: A seafloor in your theme's colors, with light shafts, glowing jellyfish, plankton, swaying kelp and caustics on the sand, kept to the sides of the chat; the cursor stirs the current and a tap sends a sonar ring.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const JELLY_COUNT   = 5;     // glowing jellyfish (0-16)
const KELP_STRANDS  = 12;    // kelp fronds along the floor (0-24)
const PLANKTON      = 90;   // tiny drifting particles (0-300)
const RAY_COUNT     = 5;     // shafts of light from the surface (0-10)
const CURRENT       = 1;     // speed of the whole scene; 0 holds it still (0-3)
const REDUCED_SPEED = 0.2;   // share of the speed kept when the viewer asks to reduce motion (0-1)
const MOUSE_CURRENT = 1;     // how strongly the cursor stirs the current and nudges the jellies (0-3)
const PULSE_EVERY   = 45;    // average seconds between distant sonar rings; 0 turns them off (0-300)
const WATER_TINT    = 1.4;     // strength of the light glow from the surface (0-2)
const CAUSTICS      = 1.4;     // strength of the caustic light on the sand (0-2)
const FLOOR_HEIGHT  = 0.15;  // height of the sandy floor, as a share of the screen (0.05-0.3)
const CENTER_CALM   = 0.75;  // how much the scene fades behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const WATER_COLOR   = '#3c96c8';  // surface glow and light shafts when not following the theme
const JELLY_A       = '#5ee0f0';  // first jellyfish color
const JELLY_B       = '#b27cf0';  // second jellyfish color
const KELP_COLOR    = '#3a6e28';  // kelp
const SAND_COLOR    = '#2a2e1e';  // sandy floor
/* ──────────────────────────────────────────── */

const TAU = Math.PI * 2;
const NJ = Math.min(16, JELLY_COUNT | 0), NK = Math.min(24, KELP_STRANDS | 0), NP = Math.min(300, PLANKTON | 0), NR = Math.min(10, RAY_COUNT | 0);
const SEGS = 12, TW = 160, TH = 80, RINGS = 4;

let canvas, ctx;
let w = 0, h = 0, dpr = 1, floorY = 0;
let last = 0, T = 0, reduced = false, dark = true, theme = null, nextPulse = PULSE_EVERY * 0.5, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };

// Pools
const jx = new Float32Array(NJ), jy = new Float32Array(NJ), jsz = new Float32Array(NJ), jdepth = new Float32Array(NJ);
const jvx = new Float32Array(NJ), jrise = new Float32Array(NJ), jphase = new Float32Array(NJ), jtone = new Uint8Array(NJ), jtent = new Uint8Array(NJ);
const ppx = new Float32Array(NP), ppy = new Float32Array(NP), pps = new Float32Array(NP), ppd = new Float32Array(NP), ppa = new Float32Array(NP);
const rx = new Float32Array(NR), rw = new Float32Array(NR), rph = new Float32Array(NR), ra = new Float32Array(NR);
const kx = new Float32Array(NK), kh = new Float32Array(NK), kw = new Float32Array(NK), kph = new Float32Array(NK), kleaf = new Int8Array(NK * SEGS);
const kpx = new Float32Array(SEGS + 1), kpy = new Float32Array(SEGS + 1);
const ringX = new Float32Array(RINGS), ringY = new Float32Array(RINGS), ringR = new Float32Array(RINGS), ringA = new Float32Array(RINGS);

// Cached colors, gradients and sprites (rebuilt on theme change and resize)
const C = {};
let tint, rayGrad, calmMask, ringStyle, floorImg, caustic, glows = [];
let causticField = null;

function hexToRgb(hex) { const n = parseInt(String(hex).slice(1, 7), 16) || 0; return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function mix(a, b, t) { return [0, 1, 2].map((k) => Math.round(a[k] + (b[k] - a[k]) * t)); }
function rgba(c, a) { return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + Math.max(0, Math.min(1, a)).toFixed(3) + ')'; }
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

// The chat area's edges, which leave out the sidebar
function areaL() { return column ? column.left : 0; }
function areaR() { return column ? column.right : w; }
// Room beside the chat column on one side, at most reach of the screen wide
function room(right, reach) { const e = colX() + (right ? 1 : -1) * colHalf() * 0.5; return Math.max(40, Math.min(w * reach, right ? areaR() - e : e - areaL())); }
// A spot in the outer thirds, or nearer the edge when the chat column leaves less room
function side() { return Math.random() < 0.5 ? areaL() + Math.random() * room(false, 0.3) : areaR() - Math.random() * room(true, 0.3); }
function band(x) { const d = Math.abs(x - colX()) / colHalf(), s = Math.min(1, Math.max(0, (d - 0.5) / 0.8)); return 1 - s * s * (3 - 2 * s); }

function palette() {
	const c = FOLLOW_THEME && theme && theme.colors ? theme.colors : null;
	if (c) {
		const a = hexToRgb(c.accent), a2 = hexToRgb(c.accent2), a3 = hexToRgb(c.accent3), tx = hexToRgb(c.text), mu = hexToRgb(c.muted), bg = hexToRgb(c.background);
		return { water: a3, ray: dark ? mix(a3, tx, 0.3) : a3, jelly: [a3, a2], core: dark ? tx : a, kelp: dark ? mix(mix(a3, mu, 0.5), bg, 0.3) : mix(a3, tx, 0.35), sand: dark ? mix(mu, bg, 0.6) : mix(mu, bg, 0.3), light: dark ? mix(a3, tx, 0.4) : bg, mote: dark ? mix(a3, tx, 0.5) : a3 };
	}
	const water = hexToRgb(WATER_COLOR);
	return { water, ray: mix(water, [255, 255, 255], 0.25), jelly: [hexToRgb(JELLY_A), hexToRgb(JELLY_B)], core: [220, 250, 255], kelp: hexToRgb(KELP_COLOR), sand: hexToRgb(SAND_COLOR), light: [80, 180, 220], mote: [140, 200, 220] };
}

function glowSprite(c) {
	const s = new OffscreenCanvas(64, 64), g = s.getContext('2d'), gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
	gr.addColorStop(0, rgba(c, 0.6)); gr.addColorStop(0.4, rgba(c, 0.18)); gr.addColorStop(1, rgba(c, 0));
	g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
	return s;
}

// Wrapping cell-edge field for the caustic network, computed once
function buildField() {
	causticField = new Float32Array(TW * TH);
	const N = 11, sx = [], sy = [];
	for (let i = 0; i < N; i++) { sx.push(Math.random() * TW); sy.push(Math.random() * TH); }
	for (let y = 0; y < TH; y++) for (let x = 0; x < TW; x++) {
		let f1 = 1e9, f2 = 1e9;
		for (let i = 0; i < N; i++) {
			// A periodic warp curves the cell edges like real caustics and keeps the tile seamless
			let dx = Math.abs(x + Math.sin(y / TH * TAU * 2) * 5 - sx[i]), dy = Math.abs(y + Math.sin(x / TW * TAU * 3) * 4 - sy[i]);
			if (dx > TW) dx -= TW;
			if (dx > TW / 2) dx = TW - dx;
			if (dy > TH / 2) dy = TH - dy;
			const d = Math.sqrt(dx * dx + dy * dy);
			if (d < f1) { f2 = f1; f1 = d; } else if (d < f2) f2 = d;
		}
		const e = Math.max(0, 1 - (f2 - f1) / 9);
		const v = y / TH; // fades in from the top of the floor, so the tile needs no mask
		causticField[y * TW + x] = e * e * e * Math.min(1, v * 3) * (1 - v * 0.3);
	}
}

// The calm band's mask, rebuilt on resize, theme and layout
function buildMask() {
	calmMask = ctx.createLinearGradient(0, 0, w, 0);
	for (let s = 0; s <= 40; s++) calmMask.addColorStop(s / 40, 'rgba(0,0,0,' + (CENTER_CALM * band((s / 40) * w)).toFixed(3) + ')');
}

// Light shafts and kelp stand beside the chat column, placed again when it moves
function placeSides() {
	const L = room(false, 0.31), R = room(true, 0.31);
	for (let i = 0; i < NR; i++) rx[i] = side();
	for (let i = 0; i < NK; i++) {
		const f = (i + 0.5) / NK;
		kx[i] = (f < 0.5 ? areaL() + f * 2 * L : areaR() - (1 - f) * 2 * R) + (Math.random() - 0.5) * 30;
	}
}

function build() {
	if (!ctx || !w) return;
	const p = palette();
	if (!causticField) buildField();
	const fh = h - floorY;
	tint = ctx.createLinearGradient(0, 0, 0, h * 0.7);
	tint.addColorStop(0, rgba(p.water, (dark ? 0.14 : 0.09) * WATER_TINT));
	tint.addColorStop(1, rgba(p.water, 0));
	rayGrad = ctx.createLinearGradient(0, 0, 0, floorY);
	rayGrad.addColorStop(0, rgba(p.ray, 0.5)); rayGrad.addColorStop(0.5, rgba(p.ray, 0.16)); rayGrad.addColorStop(1, rgba(p.ray, 0));
	buildMask();
	ringStyle = rgba(p.water, dark ? 0.6 : 0.5);
	glows = [glowSprite(p.jelly[0]), glowSprite(p.jelly[1])];
	C.bell = p.jelly.map((c) => rgba(c, dark ? 0.45 : 0.4));
	C.inner = p.jelly.map((c) => rgba(mix(c, p.core, 0.5), dark ? 0.5 : 0.35));
	C.tent = p.jelly.map((c) => rgba(c, dark ? 0.35 : 0.3));
	C.kelp = rgba(p.kelp, dark ? 0.8 : 0.55);
	C.leaf = rgba(mix(p.kelp, p.light, 0.15), dark ? 0.55 : 0.4);
	C.mote = rgba(p.mote, 1);
	// Floor (sand and soft dunes) and the caustic tile, pre-rendered once
	floorImg = new OffscreenCanvas(Math.ceil(w * dpr), Math.ceil((fh + 60) * dpr));
	const g = floorImg.getContext('2d');
	g.scale(dpr, dpr);
	const fg = g.createLinearGradient(0, 0, 0, fh + 60);
	fg.addColorStop(0, rgba(p.sand, 0)); fg.addColorStop(0.4, rgba(p.sand, dark ? 0.6 : 0.4)); fg.addColorStop(1, rgba(p.sand, dark ? 0.75 : 0.55));
	g.fillStyle = fg; g.fillRect(0, 0, w, fh + 60);
	g.fillStyle = rgba(mix(p.sand, p.light, 0.25), dark ? 0.25 : 0.2);
	for (let i = 0; i < 34; i++) {
		g.beginPath();
		g.ellipse((i / 34) * w + Math.sin(i * 4.7) * 20, 66 + Math.sin(i * 2.1) * 8, 22 + Math.sin(i * 3) * 10, 4, 0, 0, TAU);
		g.fill();
	}
	caustic = new OffscreenCanvas(TW, TH);
	const cg = caustic.getContext('2d'), img = cg.createImageData(TW, TH);
	for (let i = 0; i < TW * TH; i++) { img.data[i * 4] = p.light[0]; img.data[i * 4 + 1] = p.light[1]; img.data[i * 4 + 2] = p.light[2]; img.data[i * 4 + 3] = causticField[i] * 255; }
	cg.putImageData(img, 0, 0);
}

function spawnJelly(i, anywhere) {
	jdepth[i] = Math.random();
	jsz[i] = 12 + (1 - jdepth[i]) * 16 + Math.random() * 8;
	jx[i] = side();
	jy[i] = anywhere ? h * (0.08 + Math.random() * 0.6) : floorY + jsz[i] * 3;
	jvx[i] = 0;
	jrise[i] = 1.5 + Math.random() * 3.5;
	jphase[i] = Math.random() * TAU;
	jtone[i] = Math.random() < 0.5 ? 0 : 1;
	jtent[i] = 5 + ((Math.random() * 4) | 0);
}

function seed() {
	for (let i = 0; i < NJ; i++) spawnJelly(i, true);
	for (let i = 0; i < NP; i++) { ppx[i] = Math.random() * w; ppy[i] = Math.random() * h; pps[i] = 0.05 + Math.random() * 0.15; ppd[i] = Math.random() * TAU; ppa[i] = 0.15 + Math.random() * 0.35; }
	for (let i = 0; i < NR; i++) { rw[i] = 30 + Math.random() * 70; rph[i] = Math.random() * TAU; ra[i] = 0.04 + Math.random() * 0.05; }
	placeSides();
	for (let i = 0; i < NK; i++) {
		kh[i] = 0.18 + Math.random() * 0.22;
		kw[i] = 2 + Math.random() * 2.5;
		kph[i] = Math.random() * TAU;
		for (let s = 0; s < SEGS; s++) kleaf[i * SEGS + s] = s > 1 && Math.random() > 0.25 ? (s & 1 ? 1 : -1) : 0;
	}
}

function size(nw, nh, ndpr) {
	const sx = w ? nw / w : 1, sy = h ? nh / h : 1, had = w > 0;
	w = nw; h = nh;
	dpr = Math.min(2, ndpr || 1);
	floorY = h * (1 - FLOOR_HEIGHT);
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	ctx.lineCap = 'round';
	if (!had) seed();
	else {
		// Keep the scene on a resize: move everything with the screen instead of re-rolling it
		for (let i = 0; i < NJ; i++) { jx[i] *= sx; jy[i] *= sy; }
		for (let i = 0; i < NP; i++) { ppx[i] *= sx; ppy[i] *= sy; }
		for (let i = 0; i < NR; i++) rx[i] *= sx;
		for (let i = 0; i < NK; i++) kx[i] *= sx;
	}
	build();
}

function drawJelly(i, t) {
	const pulse = 0.75 + 0.25 * Math.sin(t * 0.03 + jphase[i]);
	const cx = jx[i] + Math.sin(t * 0.008 + jphase[i]) * 8, cy = jy[i], sz = jsz[i] * pulse, k = jtone[i];
	const a = (0.55 + (1 - jdepth[i]) * 0.45);
	ctx.globalAlpha = a * (0.6 + 0.4 * pulse);
	ctx.drawImage(glows[k], cx - sz * 3, cy - sz * 3, sz * 6, sz * 6);
	ctx.globalAlpha = a;
	ctx.fillStyle = C.bell[k];
	ctx.beginPath();
	ctx.ellipse(cx, cy, sz * 0.7, sz * 0.5 * pulse + 2, 0, Math.PI, 0);
	ctx.fill();
	ctx.fillStyle = C.inner[k];
	ctx.beginPath();
	ctx.ellipse(cx, cy + sz * 0.05, sz * 0.4, sz * 0.25 * pulse + 1, 0, Math.PI, 0);
	ctx.fill();
	ctx.strokeStyle = C.tent[k];
	ctx.lineWidth = 1;
	ctx.beginPath();
	const n = jtent[i];
	for (let s = 0; s < n; s++) {
		const tx = cx + (s / (n - 1) - 0.5) * sz, len = sz * (1.4 + Math.sin(t * 0.012 + s * 1.3) * 0.4);
		ctx.moveTo(tx, cy + 1);
		ctx.bezierCurveTo(tx + Math.sin(t * 0.015 + s * 2) * 8, cy + len * 0.5, tx + Math.sin(t * 0.01 + s * 3) * 12, cy + len * 0.8, tx + Math.sin(t * 0.008 + s) * 10, cy + len);
	}
	ctx.stroke();
}

// A frond bends as one wave, so it curves instead of zigzagging
function drawKelp(i, t, cur) {
	const segH = h * kh[i] / SEGS;
	kpx[0] = kx[i]; kpy[0] = h + 4;
	for (let s = 1; s <= SEGS; s++) {
		const prog = s / SEGS;
		kpx[s] = kx[i] + Math.sin(t * 0.012 + kph[i] - s * 0.45) * (2 + s * 1.6) + cur * prog * prog * 200;
		kpy[s] = h + 4 - segH * s;
	}
	for (let half = 0; half < 2; half++) {
		const a = half ? SEGS >> 1 : 0, b = half ? SEGS : SEGS >> 1;
		ctx.lineWidth = kw[i] * (half ? 0.65 : 1);
		ctx.beginPath();
		ctx.moveTo(kpx[a], kpy[a]);
		for (let s = a + 1; s <= b; s++) ctx.quadraticCurveTo(kpx[s - 1], kpy[s - 1], (kpx[s - 1] + kpx[s]) * 0.5, (kpy[s - 1] + kpy[s]) * 0.5);
		ctx.lineTo(kpx[b], kpy[b]);
		ctx.stroke();
	}
	ctx.beginPath();
	for (let s = 1; s < SEGS; s++) {
		const sd = kleaf[i * SEGS + s];
		if (!sd) continue;
		const x = kpx[s], y = kpy[s], len = (10 + (1 - s / SEGS) * 14) * (0.8 + 0.2 * Math.sin(t * 0.016 + kph[i] + s));
		ctx.moveTo(x, y);
		ctx.quadraticCurveTo(x + sd * len * 0.5, y - 7, x + sd * len, y - 4);
		ctx.quadraticCurveTo(x + sd * len * 0.5, y + 3, x, y + 2);
	}
	ctx.fill();
}

function ring(x, y) {
	let k = 0;
	for (let i = 1; i < RINGS; i++) if (ringA[i] < ringA[k]) k = i;
	ringX[k] = x; ringY[k] = y; ringR[k] = 0; ringA[k] = 0.14;
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!ctx || !caustic) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const pace = CURRENT * (reduced ? REDUCED_SPEED : 1), f = dt * 60 * pace;
	T += f;
	const t = T;
	mouse.target = Math.max(0, mouse.target - dt * 0.5);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 2);
	const cur = (Math.min(w, Math.max(0, mouse.x)) / w - 0.5) * 0.15 * MOUSE_CURRENT * mouse.amount;

	ctx.globalAlpha = 1;
	ctx.globalCompositeOperation = 'source-over';
	ctx.clearRect(0, 0, w, h);
	ctx.fillStyle = tint;
	ctx.fillRect(0, 0, w, h * 0.7);
	const glow = dark ? 'lighter' : 'source-over';
	ctx.globalCompositeOperation = glow;

	// Light shafts, in the outer thirds
	ctx.fillStyle = rayGrad;
	for (let i = 0; i < NR; i++) {
		const sway = Math.sin(t * 0.003 + rph[i]) * 40 + cur * 300, top = rx[i] + sway, half = rw[i] * 0.9;
		ctx.globalAlpha = ra[i] * (0.7 + 0.3 * Math.sin(t * 0.004 + rph[i])) * (dark ? 1.4 : 1);
		ctx.beginPath();
		ctx.moveTo(top - rw[i] * 0.3, 0); ctx.lineTo(top + rw[i] * 0.3, 0);
		ctx.lineTo(top + half + sway * 0.5, floorY); ctx.lineTo(top - half + sway * 0.5, floorY);
		ctx.fill();
	}

	// Sonar rings: rare and distant, or from a tap
	if (PULSE_EVERY > 0 && !reduced && pace > 0) {
		nextPulse -= dt;
		if (nextPulse <= 0) { ring(side(), h * (0.3 + Math.random() * 0.3)); nextPulse = PULSE_EVERY * (0.6 + Math.random() * 0.8); }
	}
	ctx.strokeStyle = ringStyle;
	ctx.lineWidth = 1.5;
	for (let i = 0; i < RINGS; i++) {
		if (ringA[i] < 0.004) continue;
		ringR[i] += 150 * dt * pace;
		ringA[i] *= Math.exp(-0.35 * dt * pace);
		if (ringR[i] > Math.max(w, h)) { ringA[i] = 0; continue; }
		ctx.globalAlpha = ringA[i] * Math.min(1, ringR[i] / 40);
		ctx.beginPath();
		ctx.arc(ringX[i], ringY[i], ringR[i], 0, TAU);
		ctx.stroke();
	}

	// Plankton
	ctx.fillStyle = C.mote;
	for (let i = 0; i < NP; i++) {
		ppx[i] += (Math.sin(t * 0.005 + ppd[i]) * pps[i] + cur * 6) * f;
		ppy[i] += (pps[i] * 0.5 + Math.cos(t * 0.003 + ppd[i]) * 0.1) * f;
		if (ppy[i] > h + 5 || ppx[i] < -10 || ppx[i] > w + 10) { ppx[i] = Math.random() * w; ppy[i] = -5; }
		ctx.globalAlpha = ppa[i] * (0.5 + 0.5 * Math.sin(t * 0.02 + ppd[i])) * (dark ? 1 : 0.8);
		ctx.fillRect(ppx[i] - 1, ppy[i] - 1, 2, 2);
	}

	// Jellyfish rise slowly and ease away from the cursor
	ctx.globalCompositeOperation = 'source-over';
	for (let i = 0; i < NJ; i++) {
		const dx = jx[i] - mouse.x, dy = jy[i] - mouse.y, d2 = dx * dx + dy * dy;
		if (d2 < 32400 && d2 > 1) jvx[i] += dx / Math.sqrt(d2) * 30 * MOUSE_CURRENT * mouse.amount * dt;
		jvx[i] *= 1 - Math.min(1, dt * 0.8);
		jx[i] += (Math.sin(t * 0.003 + jphase[i]) * 0.3 + cur * 5 * (1 - jdepth[i] * 0.5)) * f + jvx[i] * dt * pace;
		jy[i] -= jrise[i] * dt * pace;
		if (jy[i] < -jsz[i] * 3) spawnJelly(i, false);
		if (jx[i] < -100) jx[i] = w + 50; else if (jx[i] > w + 100) jx[i] = -50;
		drawJelly(i, t);
	}

	// Floor and its caustic network: two scales of one tile slide past each other
	ctx.globalAlpha = 1;
	ctx.drawImage(floorImg, 0, floorY - 60, w, h - floorY + 60);
	if (CAUSTICS > 0) {
		ctx.globalCompositeOperation = glow;
		ctx.globalAlpha = Math.min(1, CAUSTICS * (dark ? 0.15 : 0.55));
		for (let k = 0; k < 2; k++) {
			const tw = TW * (k ? 2.3 : 1.6), off = k ? (t * 0.25) % tw : tw - (t * 0.18) % tw;
			for (let x = -off; x < w; x += tw) ctx.drawImage(caustic, x, floorY, tw, h - floorY);
		}
		ctx.globalCompositeOperation = 'source-over';
	}

	// Kelp in front, in the outer thirds
	ctx.globalAlpha = 1;
	ctx.strokeStyle = C.kelp;
	ctx.fillStyle = C.leaf;
	for (let i = 0; i < NK; i++) drawKelp(i, t, cur);

	// One pass thins everything behind the chat column
	if (CENTER_CALM > 0) {
		ctx.globalCompositeOperation = 'destination-out';
		ctx.fillStyle = calmMask;
		ctx.fillRect(0, 0, w, h);
	}
	ctx.globalCompositeOperation = 'source-over';
	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			reduced = !!d.reducedMotion;
			column = d.column || null;
			theme = d.theme || null;
			dark = !theme || theme.dark !== false;
			size(d.width, d.height, d.dpr);
			requestAnimationFrame(frame);
			break;
		case 'resize':
			if (ctx) size(d.width, d.height, d.dpr);
			break;
		case 'theme':
			theme = d;
			dark = d.dark !== false;
			build();
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (!ctx || !w) break;
			placeSides();
			buildMask();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
		case 'mousedown':
			if (!reduced) ring(d.x, d.y);
			break;
	}
};

dark.customCSS:
:root {
	--bolt-glass: color-mix(in oklab, var(--color-gray-900) 66%, transparent);
	--bolt-sidebar: color-mix(in oklab, var(--color-gray-950) 76%, transparent);
	--bolt-bubble: color-mix(in oklab, var(--color-gray-700) 42%, transparent);
	--bolt-selected: color-mix(in oklab, var(--color-gray-500) 20%, transparent);
	--bolt-line: color-mix(in oklab, var(--color-gray-400) 22%, transparent);
	--bolt-glow: oklch(0.84 0.13 220 / 0.6);
	--bolt-ring: oklch(0.84 0.13 220 / 0.18);
	--bolt-shade: color-mix(in oklab, var(--color-gray-950) 65%, transparent);
	--bolt-accent: oklch(0.85 0.11 225);
}

/* Storm glass: cerulean surfaces, an electric edge on focus. !important only where Canvas FX transparency clears a background first. */
#message-input-container {
	background-color: var(--bolt-glass) !important;
	border-color: var(--bolt-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--bolt-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--bolt-glow) !important;
	box-shadow: 0 0 0 3px var(--bolt-ring), 0 12px 40px -16px var(--bolt-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--bolt-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--bolt-line);
}
#sidebar {
	background-color: var(--bolt-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--bolt-line);
}
#sidebar-chat-item.selected { background-color: var(--bolt-selected); }
.markdown-prose :is(h1, h2, h3) { color: var(--bolt-accent); letter-spacing: 0.01em; }
.markdown-prose a { color: var(--bolt-accent); text-decoration-color: var(--bolt-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--bolt-glow); }
.markdown-prose hr { border-color: var(--bolt-line); }
html { scrollbar-color: var(--bolt-line) transparent; }
::selection { background-color: var(--bolt-ring); }

dark.canvasScript:
/**
 * Title: Thunderstorm
 * Description: Slanting rain at three depths under drifting cloud banks, with branching lightning that strikes beside the chat column above a low city skyline; tap to call a strike.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const RAIN_DENSITY    = 0.8;     // how much rain falls (0-2)
const RAIN_SPEED      = 1;     // fall speed; also slows the clouds (0.2-2)
const REDUCED_SPEED   = 0.25;  // share of the speed kept under reduced motion (0-1)
const WIND            = 0.16;  // base slant of the rain, in radians (0-0.5)
const GUST_STRENGTH   = 0.22;  // extra slant a gust adds (0-0.5)
const CURSOR_WIND     = 1;     // how far the cursor tilts the rain; eases back when it stops (0-2)
const STRIKE_EVERY    = 20;    // average seconds between strikes; 0 for taps only (0-120)
const FLASH_INTENSITY = 0.15;   // how strongly a strike lights the sky near it (0-1)
const BRANCHING       = 0.55;  // how much the bolts fork (0-1)
const CLOUD_COVER     = 1;     // how thick the cloud banks are (0-2)
const SKYLINE_HEIGHT  = 0.13;  // tallest building as a share of the screen height (0-0.2)
const CENTER_CALM     = 0.8;   // how much rain and cloud thin behind the chat column (0-1)
const BAND_WIDTH      = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME    = true;  // take the colors from the theme's palette
const RAIN_COLOR      = '#9fb4cc';  // rain when not following the theme
const CLOUD_COLOR     = '#3a4152';  // cloud banks
const BOLT_COLOR      = '#bcd0ff';  // lightning glow
const WINDOW_COLOR    = '#e8c27a';  // lit windows in the skyline
/* ──────────────────────────────────────────── */

const MAX_DROPS = 1100, MAX_PTS = 700, MAX_LINES = 36;

let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, reduced = false, dark = true, column = null;
let pal = { rain: hex(RAIN_COLOR), cloud: hex(CLOUD_COLOR), bolt: hex(BOLT_COLOR), win: hex(WINDOW_COLOR), bg: [26, 24, 38], text: [235, 238, 245] };
let rainStyle = ['', '', ''], boltGlow = '', boltCore = '', boltHot = '';
let cloudSprite, litSprite, flashSprite, skyline, skyW = 0, skyH = 0;

const F = (n) => new Float32Array(n), MAX_PUFFS = 140;
const rx = F(MAX_DROPS), ry = F(MAX_DROPS), rs = F(MAX_DROPS), rl = F(MAX_DROPS);
const cx = F(MAX_PUFFS), cy = F(MAX_PUFFS), cr = F(MAX_PUFFS), cv = F(MAX_PUFFS), ca = F(MAX_PUFFS);
let drops = 0, puffs = 0;

// Bolt geometry: polylines packed in typed arrays, branches queued so each line stays contiguous
const px = F(MAX_PTS), py = F(MAX_PTS), qx = F(MAX_LINES), qy = F(MAX_LINES), qa = F(MAX_LINES), ql = F(MAX_LINES);
const lStart = new Uint16Array(MAX_LINES), lLen = new Uint16Array(MAX_LINES), lDepth = new Uint8Array(MAX_LINES), qd = new Uint8Array(MAX_LINES);
let nPts = 0, nLines = 0, qCount = 0;
const bolt = { age: 99, x: 0, glowAge: 99, glowX: 0, wait: STRIKE_EVERY * 0.4, glowWait: 5, cool: 0 };
let wind = WIND, gust = 0, gustTarget = 0, gustWait = 6;
const mouse = { x: 0, amount: 0 };

function hex(c) { const n = parseInt(c.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function rgba(c, a) { return 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a.toFixed(3) + ')'; }
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }
function band(x) {
	const d = Math.abs(x - colX()) / colHalf();
	const t = Math.min(1, Math.max(0, (d - 0.55) / 0.7));
	return 1 - t * t * (3 - 2 * t);
}
function calm(x) { return 1 - CENTER_CALM * band(x); }
// A spot within a share f of the screen beside the chat column, on the side with room, inside the chat area so the sidebar can't cover it
function edge(f) {
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const left = Math.max(0, colX() - colHalf() - lo), right = Math.max(0, hi - colX() - colHalf()), m = w * f;
	if (left + right < 60) return Math.random() < 0.5 ? lo + Math.random() * m : hi - Math.random() * m;
	const r = Math.random() * (left + right);
	return r < left ? lo + (r / left) * Math.min(left, m) : hi - ((r - left) / right) * Math.min(right, m);
}

function sprite(size, col, a0, a1) {
	const c = new OffscreenCanvas(size, size), g = c.getContext('2d');
	const grad = g.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
	grad.addColorStop(0, rgba(col, a0));
	grad.addColorStop(0.5, rgba(col, a1));
	grad.addColorStop(1, rgba(col, 0));
	g.fillStyle = grad;
	g.fillRect(0, 0, size, size);
	return c;
}

function applyTheme(t) {
	if (t) {
		dark = t.dark !== false;
		if (FOLLOW_THEME && t.colors) {
			const c = t.colors, m = hex(c.muted), bg = hex(c.background), a3 = hex(c.accent3);
			pal = {
				rain: dark ? mix(m, a3, 0.35) : mix(m, hex(c.text), 0.25),
				cloud: dark ? mix(bg, m, 0.3) : mix(m, hex(c.text), 0.35),
				bolt: dark ? mix(a3, [255, 255, 255], 0.35) : hex(c.accent),
				win: hex(c.accent2), bg: bg, text: hex(c.text),
			};
		}
	}
	buildColors();
}

function buildColors() {
	const k = dark ? 1 : 0.55;
	for (let l = 0; l < 3; l++) rainStyle[l] = rgba(pal.rain, (0.22 + l * 0.17) * k);
	boltGlow = rgba(pal.bolt, dark ? 0.16 : 0.12);
	boltCore = rgba(pal.bolt, dark ? 0.85 : 0.6);
	boltHot = dark ? rgba(mix(pal.bolt, [255, 255, 255], 0.7), 0.95) : rgba(mix(pal.bolt, pal.text, 0.5), 0.75);
	cloudSprite = sprite(128, pal.cloud, dark ? 0.7 : 0.26, dark ? 0.4 : 0.14);
	litSprite = sprite(128, dark ? mix(pal.bolt, pal.cloud, 0.35) : mix(pal.bolt, pal.bg, 0.5), dark ? 0.5 : 0.25, 0.18);
	flashSprite = sprite(256, dark ? pal.bolt : mix(pal.bolt, pal.bg, 0.3), dark ? 0.32 : 0.16, 0.1);
	if (w) buildSkyline();
}

// ── Skyline: drawn once per resize, layout or theme into a cached strip along the bottom fifth ──
function buildSkyline() {
	skyH = Math.max(8, Math.round(h * Math.max(0.03, SKYLINE_HEIGHT) + 8));
	skyW = Math.max(1, w);
	skyline = new OffscreenCanvas(Math.round(skyW * dpr), Math.round(skyH * dpr));
	const g = skyline.getContext('2d');
	g.setTransform(dpr, 0, 0, dpr, 0, 0);
	const body = dark ? mix(pal.bg, [0, 0, 0], 0.5) : mix(pal.cloud, pal.bg, 0.25);
	const back = dark ? mix(pal.bg, pal.cloud, 0.6) : mix(pal.cloud, pal.bg, 0.55);
	for (let row = 0; row < 2; row++) {
		let x = -10 - Math.random() * 30;
		while (x < skyW + 10) {
			const bw = 16 + Math.random() * 44;
			const quiet = band(x + bw / 2);
			const tall = (row ? 0.35 : 0.6) + Math.random() * (row ? 0.65 : 0.4);
			const bh = Math.max(6, (skyH - 8) * tall * (1 - 0.55 * quiet));
			const top = skyH - bh;
			g.globalAlpha = (row ? (dark ? 0.85 : 0.5) : (dark ? 0.55 : 0.3)) * (1 - 0.5 * CENTER_CALM * quiet);
			g.fillStyle = rgba(row ? body : back, 1);
			g.fillRect(x, top, bw, bh);
			if (row && quiet < 0.5) {
				g.fillStyle = rgba(pal.win, 1);
				for (let fy = top + 5; fy < skyH - 4; fy += 6) {
					for (let fx = x + 3; fx < x + bw - 4; fx += 5) {
						if (Math.random() < 0.12) { g.globalAlpha = (dark ? 0.35 : 0.3) * (0.4 + Math.random() * 0.6); g.fillRect(fx, fy, 2, 2); }
					}
				}
			}
			x += bw + (row ? 2 + Math.random() * 10 : -4 + Math.random() * 14);
		}
	}
}

// ── Rain: spawn rejected over the chat column so it stays thin there ──
function spawnX() {
	for (let tries = 0; tries < 4; tries++) {
		const x = Math.random() * (w + 200) - 100;
		if (Math.random() < 1 - 0.85 * CENTER_CALM * band(x)) return x;
	}
	return edge(0.15);
}
function resetDrop(i, anywhere) {
	const z = i % 3;
	rx[i] = spawnX();
	ry[i] = anywhere ? Math.random() * h : -20 - Math.random() * 60;
	rs[i] = (480 + z * 330) * (0.85 + Math.random() * 0.3);
	rl[i] = (7 + z * 6) * (0.8 + Math.random() * 0.4);
}

function size() {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	drops = Math.min(MAX_DROPS, Math.round(w * h / 2400 * RAIN_DENSITY));
	for (let i = 0; i < drops; i++) resetDrop(i, true);
	puffs = Math.min(MAX_PUFFS, Math.round(w / 24 * CLOUD_COVER));
	const s = Math.max(0.6, Math.min(1.2, h / 900));
	for (let i = 0; i < puffs; i++) {
		cx[i] = Math.random() * (w + 400) - 200;
		cy[i] = h * (Math.pow(Math.random(), 1.6) * 0.2 - 0.01);
		cr[i] = (70 + Math.random() * 110) * s;
		cv[i] = 5 + Math.random() * 9;
		ca[i] = 0.55 + Math.random() * 0.45;
	}
	if (w && h) buildSkyline();
}

// ── Lightning: a mean-reverting walk for the channel, forks queued and tapering ──
function addLine(x0, y0, ang, len, depth) {
	if (nLines >= MAX_LINES || nPts >= MAX_PTS - 4) return;
	const li = nLines++;
	lStart[li] = nPts; lDepth[li] = depth;
	const steps = Math.max(4, Math.min(48, Math.floor(len / 13), MAX_PTS - nPts - 1));
	const seg = len / steps, ca2 = Math.cos(ang), sa2 = Math.sin(ang);
	let off = 0;
	px[nPts] = x0; py[nPts] = y0; nPts++;
	for (let i = 1; i <= steps; i++) {
		off = off * 0.82 + (Math.random() - 0.5) * seg * 1.7;
		const d = i * seg;
		const x = x0 + ca2 * d - sa2 * off, y = y0 + sa2 * d + ca2 * off;
		px[nPts] = x; py[nPts] = y; nPts++;
		const t = i / steps;
		if (depth < 3 && i > 2 && i < steps - 2 && Math.random() < BRANCHING * (depth ? 0.08 : 0.14) * (1.1 - t)) {
			if (qCount >= MAX_LINES) continue;
			qx[qCount] = x; qy[qCount] = y; qd[qCount] = depth + 1;
			qa[qCount] = ang + (Math.random() < 0.5 ? -1 : 1) * (0.35 + Math.random() * 0.6);
			ql[qCount++] = len * (1 - t) * (0.3 + Math.random() * 0.35);
		}
	}
	lLen[li] = nPts - lStart[li];
}

// Strikes land outside the calm band, nudged outward when called over the column
function strikeX(x) {
	const mid = colX(), reach = colHalf() * 0.95, lo = (column ? column.left : 0) + w * 0.04, hi = (column ? column.right : w) - w * 0.04;
	if (Math.abs(x - mid) < reach) {
		// Toward the nearer side, or the other one when the nearer has no room
		const out = x < mid ? mid - reach : mid + reach;
		x = out < lo ? mid + reach : out > hi ? mid - reach : out;
	}
	return Math.max(lo, Math.min(hi, x));
}

function strike(x) {
	if (reduced || bolt.cool > 0) { glowAt(x); return; }
	const x0 = strikeX(x);
	const top = h * (0.06 + Math.random() * 0.06), bottom = h * (0.84 + Math.random() * 0.08);
	const lean = (x0 < colX() ? -1 : 1) * Math.random() * 0.18;
	nPts = 0; nLines = 0; qCount = 0;
	addLine(x0, top, Math.PI / 2 + lean, bottom - top, 0);
	for (let q = 0; q < qCount; q++) addLine(qx[q], qy[q], qa[q], ql[q], qd[q]);
	bolt.x = x0; bolt.age = 0; bolt.cool = 0.9;
}
function glowAt(x) { bolt.glowX = strikeX(x); bolt.glowAge = 0; }

// A strike flickers twice, then fades over half a second
function boltLight(a) { return a < 0.06 ? 1 : a < 0.12 ? 0.35 : a < 0.2 ? 0.9 : Math.max(0, Math.exp(-(a - 0.2) * 6) - 0.01); }

function drawBolt(light) {
	ctx.lineCap = 'round';
	ctx.lineJoin = 'round';
	for (let pass = 0; pass < 3; pass++) {
		ctx.strokeStyle = pass === 0 ? boltGlow : pass === 1 ? boltCore : boltHot;
		for (let l = 0; l < nLines; l++) {
			const fade = lDepth[l] ? Math.pow(0.55, lDepth[l]) : 1;
			if (pass === 2 && lDepth[l] > 1) continue;
			ctx.globalAlpha = light * fade;
			ctx.lineWidth = (pass === 0 ? 9 : pass === 1 ? 2.6 : 1.1) * (lDepth[l] ? 0.7 / lDepth[l] : 1);
			ctx.beginPath();
			const s = lStart[l], e = s + lLen[l];
			ctx.moveTo(px[s], py[s]);
			for (let i = s + 1; i < e; i++) ctx.lineTo(px[i], py[i]);
			ctx.stroke();
		}
	}
}

function frame(now) {
	requestAnimationFrame(frame);
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	if (!w || !h) return;
	const sp = RAIN_SPEED * (reduced ? REDUCED_SPEED : 1);

	// Wind: base slant, slow gusts, and a cursor tilt that eases back after the cursor stops
	gustWait -= dt;
	if (gustWait <= 0) { gustTarget = reduced ? 0 : (Math.random() - 0.25) * GUST_STRENGTH; gustWait = 5 + Math.random() * 9; }
	if (gustWait < 3) gustTarget *= 1 - Math.min(1, dt * 0.4);
	gust += (gustTarget - gust) * Math.min(1, dt * 0.8);
	mouse.amount = Math.max(0, mouse.amount - dt * 0.25);
	const tilt = (mouse.x / w - 0.5) * 0.35 * CURSOR_WIND * mouse.amount;
	wind += (WIND + gust + tilt - wind) * Math.min(1, dt * 1.5);
	const vx = Math.sin(wind), vy = Math.cos(wind);

	// Strike timers
	bolt.age += dt; bolt.glowAge += dt; bolt.cool -= dt;
	if (STRIKE_EVERY > 0) {
		bolt.wait -= dt;
		if (bolt.wait <= 0) { strike(edge(0.3)); bolt.wait = STRIKE_EVERY * (0.5 + Math.random()); }
	}
	bolt.glowWait -= dt;
	if (bolt.glowWait <= 0) { glowAt(edge(0.25)); bolt.glowWait = 6 + Math.random() * 10; }
	const light = bolt.age < 1.2 ? boltLight(bolt.age) : 0;
	const glow = bolt.glowAge < 3 ? Math.sin(Math.PI * bolt.glowAge / 3) * (reduced ? 0.5 : 0.6) : 0;

	ctx.clearRect(0, 0, w, h);

	// Flash: a soft swell over the sky around the strike, never across the column
	if (light > 0.01 && FLASH_INTENSITY > 0) {
		ctx.globalAlpha = Math.min(1, light * FLASH_INTENSITY * 1.6);
		ctx.drawImage(flashSprite, bolt.x - w * 0.32, -h * 0.35, w * 0.64, h * 0.95);
	}

	// Cloud banks, lit from within near a strike or a distant glow
	const drift = dt * sp * 1.4;
	for (let i = 0; i < puffs; i++) {
		cx[i] += cv[i] * drift;
		if (cx[i] > w + 200) cx[i] -= w + 400;
		const r = cr[i], c = calm(cx[i]);
		ctx.globalAlpha = ca[i] * c;
		ctx.drawImage(cloudSprite, cx[i] - r, cy[i] - r * 0.55, r * 2, r * 1.1);
		let lit = 0;
		if (light > 0.01) lit += light * FLASH_INTENSITY * 2.2 * Math.max(0, 1 - Math.abs(cx[i] - bolt.x) / (w * 0.3));
		if (glow > 0.01) lit += glow * Math.max(0, 1 - Math.abs(cx[i] - bolt.glowX) / 260);
		if (lit > 0.01) {
			ctx.globalAlpha = Math.min(1, lit) * c;
			ctx.drawImage(litSprite, cx[i] - r * 0.8, cy[i] - r * 0.4, r * 1.6, r * 0.8);
		}
	}

	if (light > 0.01) drawBolt(light);

	if (skyline) { ctx.globalAlpha = 1; ctx.drawImage(skyline, 0, h - skyH, skyW, skyH); }

	// Rain, one path per depth layer
	for (let l = 0; l < 3; l++) {
		ctx.strokeStyle = rainStyle[l];
		ctx.lineWidth = l === 2 ? 1.2 : 1;
		ctx.globalAlpha = 1;
		ctx.beginPath();
		for (let i = l; i < drops; i += 3) {
			const v = rs[i] * sp;
			rx[i] += vx * v * dt;
			ry[i] += vy * v * dt;
			if (ry[i] > h + 20) resetDrop(i, false);
			else if (rx[i] > w + 120) rx[i] -= w + 220;
			else if (rx[i] < -120) rx[i] += w + 220;
			const len = rl[i] * (0.6 + 0.4 * sp);
			ctx.moveTo(rx[i], ry[i]);
			ctx.lineTo(rx[i] - vx * len, ry[i] - vy * len);
		}
		ctx.stroke();
	}

	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			size();
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas && w && h) buildSkyline();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.amount = 1;
			break;
		case 'mousedown':
			strike(d.x);
			break;
	}
};

light.customCSS:
:root {
	--bolt-glass: color-mix(in oklab, var(--color-gray-50) 70%, transparent);
	--bolt-sidebar: color-mix(in oklab, var(--color-gray-50) 68%, transparent);
	--bolt-bubble: color-mix(in oklab, var(--color-gray-200) 55%, transparent);
	--bolt-selected: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--bolt-line: color-mix(in oklab, var(--color-gray-500) 26%, transparent);
	--bolt-glow: oklch(0.56 0.15 240 / 0.55);
	--bolt-ring: oklch(0.62 0.14 240 / 0.2);
	--bolt-shade: color-mix(in oklab, var(--color-gray-500) 30%, transparent);
	--bolt-accent: oklch(0.47 0.14 245);
}

/* Storm glass: cerulean surfaces, an electric edge on focus. !important only where Canvas FX transparency clears a background first. */
#message-input-container {
	background-color: var(--bolt-glass) !important;
	border-color: var(--bolt-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--bolt-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--bolt-glow) !important;
	box-shadow: 0 0 0 3px var(--bolt-ring), 0 12px 40px -16px var(--bolt-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--bolt-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--bolt-line);
}
#sidebar {
	background-color: var(--bolt-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--bolt-line);
}
#sidebar-chat-item.selected { background-color: var(--bolt-selected); }
.markdown-prose :is(h1, h2, h3) { color: var(--bolt-accent); letter-spacing: 0.01em; }
.markdown-prose a { color: var(--bolt-accent); text-decoration-color: var(--bolt-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--bolt-glow); }
.markdown-prose hr { border-color: var(--bolt-line); }
html { scrollbar-color: var(--bolt-line) transparent; }
::selection { background-color: var(--bolt-ring); }

light.canvasScript:
/**
 * Title: Thunderstorm
 * Description: Slanting rain at three depths under drifting cloud banks, with branching lightning that strikes beside the chat column above a low city skyline; tap to call a strike.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const RAIN_DENSITY    = 0.7;     // how much rain falls (0-2)
const RAIN_SPEED      = 1;     // fall speed; also slows the clouds (0.2-2)
const REDUCED_SPEED   = 0.25;  // share of the speed kept under reduced motion (0-1)
const WIND            = 0.16;  // base slant of the rain, in radians (0-0.5)
const GUST_STRENGTH   = 0.22;  // extra slant a gust adds (0-0.5)
const CURSOR_WIND     = 1;     // how far the cursor tilts the rain; eases back when it stops (0-2)
const STRIKE_EVERY    = 24;    // average seconds between strikes; 0 for taps only (0-120)
const FLASH_INTENSITY = 0.12;   // how strongly a strike lights the sky near it (0-1)
const BRANCHING       = 0.55;  // how much the bolts fork (0-1)
const CLOUD_COVER     = 1;     // how thick the cloud banks are (0-2)
const SKYLINE_HEIGHT  = 0.13;  // tallest building as a share of the screen height (0-0.2)
const CENTER_CALM     = 0.8;   // how much rain and cloud thin behind the chat column (0-1)
const BAND_WIDTH      = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME    = true;  // take the colors from the theme's palette
const RAIN_COLOR      = '#9fb4cc';  // rain when not following the theme
const CLOUD_COLOR     = '#3a4152';  // cloud banks
const BOLT_COLOR      = '#bcd0ff';  // lightning glow
const WINDOW_COLOR    = '#e8c27a';  // lit windows in the skyline
/* ──────────────────────────────────────────── */

const MAX_DROPS = 1100, MAX_PTS = 700, MAX_LINES = 36;

let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, reduced = false, dark = true, column = null;
let pal = { rain: hex(RAIN_COLOR), cloud: hex(CLOUD_COLOR), bolt: hex(BOLT_COLOR), win: hex(WINDOW_COLOR), bg: [26, 24, 38], text: [235, 238, 245] };
let rainStyle = ['', '', ''], boltGlow = '', boltCore = '', boltHot = '';
let cloudSprite, litSprite, flashSprite, skyline, skyW = 0, skyH = 0;

const F = (n) => new Float32Array(n), MAX_PUFFS = 140;
const rx = F(MAX_DROPS), ry = F(MAX_DROPS), rs = F(MAX_DROPS), rl = F(MAX_DROPS);
const cx = F(MAX_PUFFS), cy = F(MAX_PUFFS), cr = F(MAX_PUFFS), cv = F(MAX_PUFFS), ca = F(MAX_PUFFS);
let drops = 0, puffs = 0;

// Bolt geometry: polylines packed in typed arrays, branches queued so each line stays contiguous
const px = F(MAX_PTS), py = F(MAX_PTS), qx = F(MAX_LINES), qy = F(MAX_LINES), qa = F(MAX_LINES), ql = F(MAX_LINES);
const lStart = new Uint16Array(MAX_LINES), lLen = new Uint16Array(MAX_LINES), lDepth = new Uint8Array(MAX_LINES), qd = new Uint8Array(MAX_LINES);
let nPts = 0, nLines = 0, qCount = 0;
const bolt = { age: 99, x: 0, glowAge: 99, glowX: 0, wait: STRIKE_EVERY * 0.4, glowWait: 5, cool: 0 };
let wind = WIND, gust = 0, gustTarget = 0, gustWait = 6;
const mouse = { x: 0, amount: 0 };

function hex(c) { const n = parseInt(c.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function rgba(c, a) { return 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a.toFixed(3) + ')'; }
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }
function band(x) {
	const d = Math.abs(x - colX()) / colHalf();
	const t = Math.min(1, Math.max(0, (d - 0.55) / 0.7));
	return 1 - t * t * (3 - 2 * t);
}
function calm(x) { return 1 - CENTER_CALM * band(x); }
// A spot within a share f of the screen beside the chat column, on the side with room, inside the chat area so the sidebar can't cover it
function edge(f) {
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const left = Math.max(0, colX() - colHalf() - lo), right = Math.max(0, hi - colX() - colHalf()), m = w * f;
	if (left + right < 60) return Math.random() < 0.5 ? lo + Math.random() * m : hi - Math.random() * m;
	const r = Math.random() * (left + right);
	return r < left ? lo + (r / left) * Math.min(left, m) : hi - ((r - left) / right) * Math.min(right, m);
}

function sprite(size, col, a0, a1) {
	const c = new OffscreenCanvas(size, size), g = c.getContext('2d');
	const grad = g.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
	grad.addColorStop(0, rgba(col, a0));
	grad.addColorStop(0.5, rgba(col, a1));
	grad.addColorStop(1, rgba(col, 0));
	g.fillStyle = grad;
	g.fillRect(0, 0, size, size);
	return c;
}

function applyTheme(t) {
	if (t) {
		dark = t.dark !== false;
		if (FOLLOW_THEME && t.colors) {
			const c = t.colors, m = hex(c.muted), bg = hex(c.background), a3 = hex(c.accent3);
			pal = {
				rain: dark ? mix(m, a3, 0.35) : mix(m, hex(c.text), 0.25),
				cloud: dark ? mix(bg, m, 0.3) : mix(m, hex(c.text), 0.35),
				bolt: dark ? mix(a3, [255, 255, 255], 0.35) : hex(c.accent),
				win: hex(c.accent2), bg: bg, text: hex(c.text),
			};
		}
	}
	buildColors();
}

function buildColors() {
	const k = dark ? 1 : 0.55;
	for (let l = 0; l < 3; l++) rainStyle[l] = rgba(pal.rain, (0.22 + l * 0.17) * k);
	boltGlow = rgba(pal.bolt, dark ? 0.16 : 0.12);
	boltCore = rgba(pal.bolt, dark ? 0.85 : 0.6);
	boltHot = dark ? rgba(mix(pal.bolt, [255, 255, 255], 0.7), 0.95) : rgba(mix(pal.bolt, pal.text, 0.5), 0.75);
	cloudSprite = sprite(128, pal.cloud, dark ? 0.7 : 0.26, dark ? 0.4 : 0.14);
	litSprite = sprite(128, dark ? mix(pal.bolt, pal.cloud, 0.35) : mix(pal.bolt, pal.bg, 0.5), dark ? 0.5 : 0.25, 0.18);
	flashSprite = sprite(256, dark ? pal.bolt : mix(pal.bolt, pal.bg, 0.3), dark ? 0.32 : 0.16, 0.1);
	if (w) buildSkyline();
}

// ── Skyline: drawn once per resize, layout or theme into a cached strip along the bottom fifth ──
function buildSkyline() {
	skyH = Math.max(8, Math.round(h * Math.max(0.03, SKYLINE_HEIGHT) + 8));
	skyW = Math.max(1, w);
	skyline = new OffscreenCanvas(Math.round(skyW * dpr), Math.round(skyH * dpr));
	const g = skyline.getContext('2d');
	g.setTransform(dpr, 0, 0, dpr, 0, 0);
	const body = dark ? mix(pal.bg, [0, 0, 0], 0.5) : mix(pal.cloud, pal.bg, 0.25);
	const back = dark ? mix(pal.bg, pal.cloud, 0.6) : mix(pal.cloud, pal.bg, 0.55);
	for (let row = 0; row < 2; row++) {
		let x = -10 - Math.random() * 30;
		while (x < skyW + 10) {
			const bw = 16 + Math.random() * 44;
			const quiet = band(x + bw / 2);
			const tall = (row ? 0.35 : 0.6) + Math.random() * (row ? 0.65 : 0.4);
			const bh = Math.max(6, (skyH - 8) * tall * (1 - 0.55 * quiet));
			const top = skyH - bh;
			g.globalAlpha = (row ? (dark ? 0.85 : 0.5) : (dark ? 0.55 : 0.3)) * (1 - 0.5 * CENTER_CALM * quiet);
			g.fillStyle = rgba(row ? body : back, 1);
			g.fillRect(x, top, bw, bh);
			if (row && quiet < 0.5) {
				g.fillStyle = rgba(pal.win, 1);
				for (let fy = top + 5; fy < skyH - 4; fy += 6) {
					for (let fx = x + 3; fx < x + bw - 4; fx += 5) {
						if (Math.random() < 0.12) { g.globalAlpha = (dark ? 0.35 : 0.3) * (0.4 + Math.random() * 0.6); g.fillRect(fx, fy, 2, 2); }
					}
				}
			}
			x += bw + (row ? 2 + Math.random() * 10 : -4 + Math.random() * 14);
		}
	}
}

// ── Rain: spawn rejected over the chat column so it stays thin there ──
function spawnX() {
	for (let tries = 0; tries < 4; tries++) {
		const x = Math.random() * (w + 200) - 100;
		if (Math.random() < 1 - 0.85 * CENTER_CALM * band(x)) return x;
	}
	return edge(0.15);
}
function resetDrop(i, anywhere) {
	const z = i % 3;
	rx[i] = spawnX();
	ry[i] = anywhere ? Math.random() * h : -20 - Math.random() * 60;
	rs[i] = (480 + z * 330) * (0.85 + Math.random() * 0.3);
	rl[i] = (7 + z * 6) * (0.8 + Math.random() * 0.4);
}

function size() {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	drops = Math.min(MAX_DROPS, Math.round(w * h / 2400 * RAIN_DENSITY));
	for (let i = 0; i < drops; i++) resetDrop(i, true);
	puffs = Math.min(MAX_PUFFS, Math.round(w / 24 * CLOUD_COVER));
	const s = Math.max(0.6, Math.min(1.2, h / 900));
	for (let i = 0; i < puffs; i++) {
		cx[i] = Math.random() * (w + 400) - 200;
		cy[i] = h * (Math.pow(Math.random(), 1.6) * 0.2 - 0.01);
		cr[i] = (70 + Math.random() * 110) * s;
		cv[i] = 5 + Math.random() * 9;
		ca[i] = 0.55 + Math.random() * 0.45;
	}
	if (w && h) buildSkyline();
}

// ── Lightning: a mean-reverting walk for the channel, forks queued and tapering ──
function addLine(x0, y0, ang, len, depth) {
	if (nLines >= MAX_LINES || nPts >= MAX_PTS - 4) return;
	const li = nLines++;
	lStart[li] = nPts; lDepth[li] = depth;
	const steps = Math.max(4, Math.min(48, Math.floor(len / 13), MAX_PTS - nPts - 1));
	const seg = len / steps, ca2 = Math.cos(ang), sa2 = Math.sin(ang);
	let off = 0;
	px[nPts] = x0; py[nPts] = y0; nPts++;
	for (let i = 1; i <= steps; i++) {
		off = off * 0.82 + (Math.random() - 0.5) * seg * 1.7;
		const d = i * seg;
		const x = x0 + ca2 * d - sa2 * off, y = y0 + sa2 * d + ca2 * off;
		px[nPts] = x; py[nPts] = y; nPts++;
		const t = i / steps;
		if (depth < 3 && i > 2 && i < steps - 2 && Math.random() < BRANCHING * (depth ? 0.08 : 0.14) * (1.1 - t)) {
			if (qCount >= MAX_LINES) continue;
			qx[qCount] = x; qy[qCount] = y; qd[qCount] = depth + 1;
			qa[qCount] = ang + (Math.random() < 0.5 ? -1 : 1) * (0.35 + Math.random() * 0.6);
			ql[qCount++] = len * (1 - t) * (0.3 + Math.random() * 0.35);
		}
	}
	lLen[li] = nPts - lStart[li];
}

// Strikes land outside the calm band, nudged outward when called over the column
function strikeX(x) {
	const mid = colX(), reach = colHalf() * 0.95, lo = (column ? column.left : 0) + w * 0.04, hi = (column ? column.right : w) - w * 0.04;
	if (Math.abs(x - mid) < reach) {
		// Toward the nearer side, or the other one when the nearer has no room
		const out = x < mid ? mid - reach : mid + reach;
		x = out < lo ? mid + reach : out > hi ? mid - reach : out;
	}
	return Math.max(lo, Math.min(hi, x));
}

function strike(x) {
	if (reduced || bolt.cool > 0) { glowAt(x); return; }
	const x0 = strikeX(x);
	const top = h * (0.06 + Math.random() * 0.06), bottom = h * (0.84 + Math.random() * 0.08);
	const lean = (x0 < colX() ? -1 : 1) * Math.random() * 0.18;
	nPts = 0; nLines = 0; qCount = 0;
	addLine(x0, top, Math.PI / 2 + lean, bottom - top, 0);
	for (let q = 0; q < qCount; q++) addLine(qx[q], qy[q], qa[q], ql[q], qd[q]);
	bolt.x = x0; bolt.age = 0; bolt.cool = 0.9;
}
function glowAt(x) { bolt.glowX = strikeX(x); bolt.glowAge = 0; }

// A strike flickers twice, then fades over half a second
function boltLight(a) { return a < 0.06 ? 1 : a < 0.12 ? 0.35 : a < 0.2 ? 0.9 : Math.max(0, Math.exp(-(a - 0.2) * 6) - 0.01); }

function drawBolt(light) {
	ctx.lineCap = 'round';
	ctx.lineJoin = 'round';
	for (let pass = 0; pass < 3; pass++) {
		ctx.strokeStyle = pass === 0 ? boltGlow : pass === 1 ? boltCore : boltHot;
		for (let l = 0; l < nLines; l++) {
			const fade = lDepth[l] ? Math.pow(0.55, lDepth[l]) : 1;
			if (pass === 2 && lDepth[l] > 1) continue;
			ctx.globalAlpha = light * fade;
			ctx.lineWidth = (pass === 0 ? 9 : pass === 1 ? 2.6 : 1.1) * (lDepth[l] ? 0.7 / lDepth[l] : 1);
			ctx.beginPath();
			const s = lStart[l], e = s + lLen[l];
			ctx.moveTo(px[s], py[s]);
			for (let i = s + 1; i < e; i++) ctx.lineTo(px[i], py[i]);
			ctx.stroke();
		}
	}
}

function frame(now) {
	requestAnimationFrame(frame);
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	if (!w || !h) return;
	const sp = RAIN_SPEED * (reduced ? REDUCED_SPEED : 1);

	// Wind: base slant, slow gusts, and a cursor tilt that eases back after the cursor stops
	gustWait -= dt;
	if (gustWait <= 0) { gustTarget = reduced ? 0 : (Math.random() - 0.25) * GUST_STRENGTH; gustWait = 5 + Math.random() * 9; }
	if (gustWait < 3) gustTarget *= 1 - Math.min(1, dt * 0.4);
	gust += (gustTarget - gust) * Math.min(1, dt * 0.8);
	mouse.amount = Math.max(0, mouse.amount - dt * 0.25);
	const tilt = (mouse.x / w - 0.5) * 0.35 * CURSOR_WIND * mouse.amount;
	wind += (WIND + gust + tilt - wind) * Math.min(1, dt * 1.5);
	const vx = Math.sin(wind), vy = Math.cos(wind);

	// Strike timers
	bolt.age += dt; bolt.glowAge += dt; bolt.cool -= dt;
	if (STRIKE_EVERY > 0) {
		bolt.wait -= dt;
		if (bolt.wait <= 0) { strike(edge(0.3)); bolt.wait = STRIKE_EVERY * (0.5 + Math.random()); }
	}
	bolt.glowWait -= dt;
	if (bolt.glowWait <= 0) { glowAt(edge(0.25)); bolt.glowWait = 6 + Math.random() * 10; }
	const light = bolt.age < 1.2 ? boltLight(bolt.age) : 0;
	const glow = bolt.glowAge < 3 ? Math.sin(Math.PI * bolt.glowAge / 3) * (reduced ? 0.5 : 0.6) : 0;

	ctx.clearRect(0, 0, w, h);

	// Flash: a soft swell over the sky around the strike, never across the column
	if (light > 0.01 && FLASH_INTENSITY > 0) {
		ctx.globalAlpha = Math.min(1, light * FLASH_INTENSITY * 1.6);
		ctx.drawImage(flashSprite, bolt.x - w * 0.32, -h * 0.35, w * 0.64, h * 0.95);
	}

	// Cloud banks, lit from within near a strike or a distant glow
	const drift = dt * sp * 1.4;
	for (let i = 0; i < puffs; i++) {
		cx[i] += cv[i] * drift;
		if (cx[i] > w + 200) cx[i] -= w + 400;
		const r = cr[i], c = calm(cx[i]);
		ctx.globalAlpha = ca[i] * c;
		ctx.drawImage(cloudSprite, cx[i] - r, cy[i] - r * 0.55, r * 2, r * 1.1);
		let lit = 0;
		if (light > 0.01) lit += light * FLASH_INTENSITY * 2.2 * Math.max(0, 1 - Math.abs(cx[i] - bolt.x) / (w * 0.3));
		if (glow > 0.01) lit += glow * Math.max(0, 1 - Math.abs(cx[i] - bolt.glowX) / 260);
		if (lit > 0.01) {
			ctx.globalAlpha = Math.min(1, lit) * c;
			ctx.drawImage(litSprite, cx[i] - r * 0.8, cy[i] - r * 0.4, r * 1.6, r * 0.8);
		}
	}

	if (light > 0.01) drawBolt(light);

	if (skyline) { ctx.globalAlpha = 1; ctx.drawImage(skyline, 0, h - skyH, skyW, skyH); }

	// Rain, one path per depth layer
	for (let l = 0; l < 3; l++) {
		ctx.strokeStyle = rainStyle[l];
		ctx.lineWidth = l === 2 ? 1.2 : 1;
		ctx.globalAlpha = 1;
		ctx.beginPath();
		for (let i = l; i < drops; i += 3) {
			const v = rs[i] * sp;
			rx[i] += vx * v * dt;
			ry[i] += vy * v * dt;
			if (ry[i] > h + 20) resetDrop(i, false);
			else if (rx[i] > w + 120) rx[i] -= w + 220;
			else if (rx[i] < -120) rx[i] += w + 220;
			const len = rl[i] * (0.6 + 0.4 * sp);
			ctx.moveTo(rx[i], ry[i]);
			ctx.lineTo(rx[i] - vx * len, ry[i] - vy * len);
		}
		ctx.stroke();
	}

	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			size();
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas && w && h) buildSkyline();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.amount = 1;
			break;
		case 'mousedown':
			strike(d.x);
			break;
	}
};

oled.customCSS:
:root {
	--bolt-glass: color-mix(in oklab, var(--color-gray-850) 64%, transparent);
	--bolt-sidebar: color-mix(in oklab, var(--color-gray-950) 82%, transparent);
	--bolt-bubble: color-mix(in oklab, var(--color-gray-700) 50%, transparent);
	--bolt-selected: color-mix(in oklab, var(--color-gray-500) 20%, transparent);
	--bolt-line: color-mix(in oklab, var(--color-gray-400) 22%, transparent);
	--bolt-glow: oklch(0.84 0.13 220 / 0.6);
	--bolt-ring: oklch(0.84 0.13 220 / 0.18);
	--bolt-shade: color-mix(in oklab, var(--color-gray-950) 65%, transparent);
	--bolt-accent: oklch(0.85 0.11 225);
}

/* Storm glass: cerulean surfaces, an electric edge on focus. !important only where Canvas FX transparency clears a background first. */
#message-input-container {
	background-color: var(--bolt-glass) !important;
	border-color: var(--bolt-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--bolt-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--bolt-glow) !important;
	box-shadow: 0 0 0 3px var(--bolt-ring), 0 12px 40px -16px var(--bolt-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--bolt-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--bolt-line);
}
#sidebar {
	background-color: var(--bolt-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--bolt-line);
}
#sidebar-chat-item.selected { background-color: var(--bolt-selected); }
.markdown-prose :is(h1, h2, h3) { color: var(--bolt-accent); letter-spacing: 0.01em; }
.markdown-prose a { color: var(--bolt-accent); text-decoration-color: var(--bolt-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--bolt-glow); }
.markdown-prose hr { border-color: var(--bolt-line); }
html { scrollbar-color: var(--bolt-line) transparent; }
::selection { background-color: var(--bolt-ring); }

oled.canvasScript:
/**
 * Title: Thunderstorm
 * Description: Slanting rain at three depths under drifting cloud banks, with branching lightning that strikes beside the chat column above a low city skyline; tap to call a strike.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const RAIN_DENSITY    = 0.8;     // how much rain falls (0-2)
const RAIN_SPEED      = 1;     // fall speed; also slows the clouds (0.2-2)
const REDUCED_SPEED   = 0.25;  // share of the speed kept under reduced motion (0-1)
const WIND            = 0.16;  // base slant of the rain, in radians (0-0.5)
const GUST_STRENGTH   = 0.22;  // extra slant a gust adds (0-0.5)
const CURSOR_WIND     = 1;     // how far the cursor tilts the rain; eases back when it stops (0-2)
const STRIKE_EVERY    = 20;    // average seconds between strikes; 0 for taps only (0-120)
const FLASH_INTENSITY = 0.15;   // how strongly a strike lights the sky near it (0-1)
const BRANCHING       = 0.55;  // how much the bolts fork (0-1)
const CLOUD_COVER     = 1;     // how thick the cloud banks are (0-2)
const SKYLINE_HEIGHT  = 0.13;  // tallest building as a share of the screen height (0-0.2)
const CENTER_CALM     = 0.8;   // how much rain and cloud thin behind the chat column (0-1)
const BAND_WIDTH      = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME    = true;  // take the colors from the theme's palette
const RAIN_COLOR      = '#9fb4cc';  // rain when not following the theme
const CLOUD_COLOR     = '#3a4152';  // cloud banks
const BOLT_COLOR      = '#bcd0ff';  // lightning glow
const WINDOW_COLOR    = '#e8c27a';  // lit windows in the skyline
/* ──────────────────────────────────────────── */

const MAX_DROPS = 1100, MAX_PTS = 700, MAX_LINES = 36;

let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, reduced = false, dark = true, column = null;
let pal = { rain: hex(RAIN_COLOR), cloud: hex(CLOUD_COLOR), bolt: hex(BOLT_COLOR), win: hex(WINDOW_COLOR), bg: [26, 24, 38], text: [235, 238, 245] };
let rainStyle = ['', '', ''], boltGlow = '', boltCore = '', boltHot = '';
let cloudSprite, litSprite, flashSprite, skyline, skyW = 0, skyH = 0;

const F = (n) => new Float32Array(n), MAX_PUFFS = 140;
const rx = F(MAX_DROPS), ry = F(MAX_DROPS), rs = F(MAX_DROPS), rl = F(MAX_DROPS);
const cx = F(MAX_PUFFS), cy = F(MAX_PUFFS), cr = F(MAX_PUFFS), cv = F(MAX_PUFFS), ca = F(MAX_PUFFS);
let drops = 0, puffs = 0;

// Bolt geometry: polylines packed in typed arrays, branches queued so each line stays contiguous
const px = F(MAX_PTS), py = F(MAX_PTS), qx = F(MAX_LINES), qy = F(MAX_LINES), qa = F(MAX_LINES), ql = F(MAX_LINES);
const lStart = new Uint16Array(MAX_LINES), lLen = new Uint16Array(MAX_LINES), lDepth = new Uint8Array(MAX_LINES), qd = new Uint8Array(MAX_LINES);
let nPts = 0, nLines = 0, qCount = 0;
const bolt = { age: 99, x: 0, glowAge: 99, glowX: 0, wait: STRIKE_EVERY * 0.4, glowWait: 5, cool: 0 };
let wind = WIND, gust = 0, gustTarget = 0, gustWait = 6;
const mouse = { x: 0, amount: 0 };

function hex(c) { const n = parseInt(c.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function rgba(c, a) { return 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a.toFixed(3) + ')'; }
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }
function band(x) {
	const d = Math.abs(x - colX()) / colHalf();
	const t = Math.min(1, Math.max(0, (d - 0.55) / 0.7));
	return 1 - t * t * (3 - 2 * t);
}
function calm(x) { return 1 - CENTER_CALM * band(x); }
// A spot within a share f of the screen beside the chat column, on the side with room, inside the chat area so the sidebar can't cover it
function edge(f) {
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const left = Math.max(0, colX() - colHalf() - lo), right = Math.max(0, hi - colX() - colHalf()), m = w * f;
	if (left + right < 60) return Math.random() < 0.5 ? lo + Math.random() * m : hi - Math.random() * m;
	const r = Math.random() * (left + right);
	return r < left ? lo + (r / left) * Math.min(left, m) : hi - ((r - left) / right) * Math.min(right, m);
}

function sprite(size, col, a0, a1) {
	const c = new OffscreenCanvas(size, size), g = c.getContext('2d');
	const grad = g.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
	grad.addColorStop(0, rgba(col, a0));
	grad.addColorStop(0.5, rgba(col, a1));
	grad.addColorStop(1, rgba(col, 0));
	g.fillStyle = grad;
	g.fillRect(0, 0, size, size);
	return c;
}

function applyTheme(t) {
	if (t) {
		dark = t.dark !== false;
		if (FOLLOW_THEME && t.colors) {
			const c = t.colors, m = hex(c.muted), bg = hex(c.background), a3 = hex(c.accent3);
			pal = {
				rain: dark ? mix(m, a3, 0.35) : mix(m, hex(c.text), 0.25),
				cloud: dark ? mix(bg, m, 0.3) : mix(m, hex(c.text), 0.35),
				bolt: dark ? mix(a3, [255, 255, 255], 0.35) : hex(c.accent),
				win: hex(c.accent2), bg: bg, text: hex(c.text),
			};
		}
	}
	buildColors();
}

function buildColors() {
	const k = dark ? 1 : 0.55;
	for (let l = 0; l < 3; l++) rainStyle[l] = rgba(pal.rain, (0.22 + l * 0.17) * k);
	boltGlow = rgba(pal.bolt, dark ? 0.16 : 0.12);
	boltCore = rgba(pal.bolt, dark ? 0.85 : 0.6);
	boltHot = dark ? rgba(mix(pal.bolt, [255, 255, 255], 0.7), 0.95) : rgba(mix(pal.bolt, pal.text, 0.5), 0.75);
	cloudSprite = sprite(128, pal.cloud, dark ? 0.7 : 0.26, dark ? 0.4 : 0.14);
	litSprite = sprite(128, dark ? mix(pal.bolt, pal.cloud, 0.35) : mix(pal.bolt, pal.bg, 0.5), dark ? 0.5 : 0.25, 0.18);
	flashSprite = sprite(256, dark ? pal.bolt : mix(pal.bolt, pal.bg, 0.3), dark ? 0.32 : 0.16, 0.1);
	if (w) buildSkyline();
}

// ── Skyline: drawn once per resize, layout or theme into a cached strip along the bottom fifth ──
function buildSkyline() {
	skyH = Math.max(8, Math.round(h * Math.max(0.03, SKYLINE_HEIGHT) + 8));
	skyW = Math.max(1, w);
	skyline = new OffscreenCanvas(Math.round(skyW * dpr), Math.round(skyH * dpr));
	const g = skyline.getContext('2d');
	g.setTransform(dpr, 0, 0, dpr, 0, 0);
	const body = dark ? mix(pal.bg, [0, 0, 0], 0.5) : mix(pal.cloud, pal.bg, 0.25);
	const back = dark ? mix(pal.bg, pal.cloud, 0.6) : mix(pal.cloud, pal.bg, 0.55);
	for (let row = 0; row < 2; row++) {
		let x = -10 - Math.random() * 30;
		while (x < skyW + 10) {
			const bw = 16 + Math.random() * 44;
			const quiet = band(x + bw / 2);
			const tall = (row ? 0.35 : 0.6) + Math.random() * (row ? 0.65 : 0.4);
			const bh = Math.max(6, (skyH - 8) * tall * (1 - 0.55 * quiet));
			const top = skyH - bh;
			g.globalAlpha = (row ? (dark ? 0.85 : 0.5) : (dark ? 0.55 : 0.3)) * (1 - 0.5 * CENTER_CALM * quiet);
			g.fillStyle = rgba(row ? body : back, 1);
			g.fillRect(x, top, bw, bh);
			if (row && quiet < 0.5) {
				g.fillStyle = rgba(pal.win, 1);
				for (let fy = top + 5; fy < skyH - 4; fy += 6) {
					for (let fx = x + 3; fx < x + bw - 4; fx += 5) {
						if (Math.random() < 0.12) { g.globalAlpha = (dark ? 0.35 : 0.3) * (0.4 + Math.random() * 0.6); g.fillRect(fx, fy, 2, 2); }
					}
				}
			}
			x += bw + (row ? 2 + Math.random() * 10 : -4 + Math.random() * 14);
		}
	}
}

// ── Rain: spawn rejected over the chat column so it stays thin there ──
function spawnX() {
	for (let tries = 0; tries < 4; tries++) {
		const x = Math.random() * (w + 200) - 100;
		if (Math.random() < 1 - 0.85 * CENTER_CALM * band(x)) return x;
	}
	return edge(0.15);
}
function resetDrop(i, anywhere) {
	const z = i % 3;
	rx[i] = spawnX();
	ry[i] = anywhere ? Math.random() * h : -20 - Math.random() * 60;
	rs[i] = (480 + z * 330) * (0.85 + Math.random() * 0.3);
	rl[i] = (7 + z * 6) * (0.8 + Math.random() * 0.4);
}

function size() {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	drops = Math.min(MAX_DROPS, Math.round(w * h / 2400 * RAIN_DENSITY));
	for (let i = 0; i < drops; i++) resetDrop(i, true);
	puffs = Math.min(MAX_PUFFS, Math.round(w / 24 * CLOUD_COVER));
	const s = Math.max(0.6, Math.min(1.2, h / 900));
	for (let i = 0; i < puffs; i++) {
		cx[i] = Math.random() * (w + 400) - 200;
		cy[i] = h * (Math.pow(Math.random(), 1.6) * 0.2 - 0.01);
		cr[i] = (70 + Math.random() * 110) * s;
		cv[i] = 5 + Math.random() * 9;
		ca[i] = 0.55 + Math.random() * 0.45;
	}
	if (w && h) buildSkyline();
}

// ── Lightning: a mean-reverting walk for the channel, forks queued and tapering ──
function addLine(x0, y0, ang, len, depth) {
	if (nLines >= MAX_LINES || nPts >= MAX_PTS - 4) return;
	const li = nLines++;
	lStart[li] = nPts; lDepth[li] = depth;
	const steps = Math.max(4, Math.min(48, Math.floor(len / 13), MAX_PTS - nPts - 1));
	const seg = len / steps, ca2 = Math.cos(ang), sa2 = Math.sin(ang);
	let off = 0;
	px[nPts] = x0; py[nPts] = y0; nPts++;
	for (let i = 1; i <= steps; i++) {
		off = off * 0.82 + (Math.random() - 0.5) * seg * 1.7;
		const d = i * seg;
		const x = x0 + ca2 * d - sa2 * off, y = y0 + sa2 * d + ca2 * off;
		px[nPts] = x; py[nPts] = y; nPts++;
		const t = i / steps;
		if (depth < 3 && i > 2 && i < steps - 2 && Math.random() < BRANCHING * (depth ? 0.08 : 0.14) * (1.1 - t)) {
			if (qCount >= MAX_LINES) continue;
			qx[qCount] = x; qy[qCount] = y; qd[qCount] = depth + 1;
			qa[qCount] = ang + (Math.random() < 0.5 ? -1 : 1) * (0.35 + Math.random() * 0.6);
			ql[qCount++] = len * (1 - t) * (0.3 + Math.random() * 0.35);
		}
	}
	lLen[li] = nPts - lStart[li];
}

// Strikes land outside the calm band, nudged outward when called over the column
function strikeX(x) {
	const mid = colX(), reach = colHalf() * 0.95, lo = (column ? column.left : 0) + w * 0.04, hi = (column ? column.right : w) - w * 0.04;
	if (Math.abs(x - mid) < reach) {
		// Toward the nearer side, or the other one when the nearer has no room
		const out = x < mid ? mid - reach : mid + reach;
		x = out < lo ? mid + reach : out > hi ? mid - reach : out;
	}
	return Math.max(lo, Math.min(hi, x));
}

function strike(x) {
	if (reduced || bolt.cool > 0) { glowAt(x); return; }
	const x0 = strikeX(x);
	const top = h * (0.06 + Math.random() * 0.06), bottom = h * (0.84 + Math.random() * 0.08);
	const lean = (x0 < colX() ? -1 : 1) * Math.random() * 0.18;
	nPts = 0; nLines = 0; qCount = 0;
	addLine(x0, top, Math.PI / 2 + lean, bottom - top, 0);
	for (let q = 0; q < qCount; q++) addLine(qx[q], qy[q], qa[q], ql[q], qd[q]);
	bolt.x = x0; bolt.age = 0; bolt.cool = 0.9;
}
function glowAt(x) { bolt.glowX = strikeX(x); bolt.glowAge = 0; }

// A strike flickers twice, then fades over half a second
function boltLight(a) { return a < 0.06 ? 1 : a < 0.12 ? 0.35 : a < 0.2 ? 0.9 : Math.max(0, Math.exp(-(a - 0.2) * 6) - 0.01); }

function drawBolt(light) {
	ctx.lineCap = 'round';
	ctx.lineJoin = 'round';
	for (let pass = 0; pass < 3; pass++) {
		ctx.strokeStyle = pass === 0 ? boltGlow : pass === 1 ? boltCore : boltHot;
		for (let l = 0; l < nLines; l++) {
			const fade = lDepth[l] ? Math.pow(0.55, lDepth[l]) : 1;
			if (pass === 2 && lDepth[l] > 1) continue;
			ctx.globalAlpha = light * fade;
			ctx.lineWidth = (pass === 0 ? 9 : pass === 1 ? 2.6 : 1.1) * (lDepth[l] ? 0.7 / lDepth[l] : 1);
			ctx.beginPath();
			const s = lStart[l], e = s + lLen[l];
			ctx.moveTo(px[s], py[s]);
			for (let i = s + 1; i < e; i++) ctx.lineTo(px[i], py[i]);
			ctx.stroke();
		}
	}
}

function frame(now) {
	requestAnimationFrame(frame);
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	if (!w || !h) return;
	const sp = RAIN_SPEED * (reduced ? REDUCED_SPEED : 1);

	// Wind: base slant, slow gusts, and a cursor tilt that eases back after the cursor stops
	gustWait -= dt;
	if (gustWait <= 0) { gustTarget = reduced ? 0 : (Math.random() - 0.25) * GUST_STRENGTH; gustWait = 5 + Math.random() * 9; }
	if (gustWait < 3) gustTarget *= 1 - Math.min(1, dt * 0.4);
	gust += (gustTarget - gust) * Math.min(1, dt * 0.8);
	mouse.amount = Math.max(0, mouse.amount - dt * 0.25);
	const tilt = (mouse.x / w - 0.5) * 0.35 * CURSOR_WIND * mouse.amount;
	wind += (WIND + gust + tilt - wind) * Math.min(1, dt * 1.5);
	const vx = Math.sin(wind), vy = Math.cos(wind);

	// Strike timers
	bolt.age += dt; bolt.glowAge += dt; bolt.cool -= dt;
	if (STRIKE_EVERY > 0) {
		bolt.wait -= dt;
		if (bolt.wait <= 0) { strike(edge(0.3)); bolt.wait = STRIKE_EVERY * (0.5 + Math.random()); }
	}
	bolt.glowWait -= dt;
	if (bolt.glowWait <= 0) { glowAt(edge(0.25)); bolt.glowWait = 6 + Math.random() * 10; }
	const light = bolt.age < 1.2 ? boltLight(bolt.age) : 0;
	const glow = bolt.glowAge < 3 ? Math.sin(Math.PI * bolt.glowAge / 3) * (reduced ? 0.5 : 0.6) : 0;

	ctx.clearRect(0, 0, w, h);

	// Flash: a soft swell over the sky around the strike, never across the column
	if (light > 0.01 && FLASH_INTENSITY > 0) {
		ctx.globalAlpha = Math.min(1, light * FLASH_INTENSITY * 1.6);
		ctx.drawImage(flashSprite, bolt.x - w * 0.32, -h * 0.35, w * 0.64, h * 0.95);
	}

	// Cloud banks, lit from within near a strike or a distant glow
	const drift = dt * sp * 1.4;
	for (let i = 0; i < puffs; i++) {
		cx[i] += cv[i] * drift;
		if (cx[i] > w + 200) cx[i] -= w + 400;
		const r = cr[i], c = calm(cx[i]);
		ctx.globalAlpha = ca[i] * c;
		ctx.drawImage(cloudSprite, cx[i] - r, cy[i] - r * 0.55, r * 2, r * 1.1);
		let lit = 0;
		if (light > 0.01) lit += light * FLASH_INTENSITY * 2.2 * Math.max(0, 1 - Math.abs(cx[i] - bolt.x) / (w * 0.3));
		if (glow > 0.01) lit += glow * Math.max(0, 1 - Math.abs(cx[i] - bolt.glowX) / 260);
		if (lit > 0.01) {
			ctx.globalAlpha = Math.min(1, lit) * c;
			ctx.drawImage(litSprite, cx[i] - r * 0.8, cy[i] - r * 0.4, r * 1.6, r * 0.8);
		}
	}

	if (light > 0.01) drawBolt(light);

	if (skyline) { ctx.globalAlpha = 1; ctx.drawImage(skyline, 0, h - skyH, skyW, skyH); }

	// Rain, one path per depth layer
	for (let l = 0; l < 3; l++) {
		ctx.strokeStyle = rainStyle[l];
		ctx.lineWidth = l === 2 ? 1.2 : 1;
		ctx.globalAlpha = 1;
		ctx.beginPath();
		for (let i = l; i < drops; i += 3) {
			const v = rs[i] * sp;
			rx[i] += vx * v * dt;
			ry[i] += vy * v * dt;
			if (ry[i] > h + 20) resetDrop(i, false);
			else if (rx[i] > w + 120) rx[i] -= w + 220;
			else if (rx[i] < -120) rx[i] += w + 220;
			const len = rl[i] * (0.6 + 0.4 * sp);
			ctx.moveTo(rx[i], ry[i]);
			ctx.lineTo(rx[i] - vx * len, ry[i] - vy * len);
		}
		ctx.stroke();
	}

	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			size();
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas && w && h) buildSkyline();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.amount = 1;
			break;
		case 'mousedown':
			strike(d.x);
			break;
	}
};

her.customCSS:
:root {
	--bolt-glass: color-mix(in oklab, var(--color-gray-50) 70%, transparent);
	--bolt-sidebar: color-mix(in oklab, var(--color-gray-50) 68%, transparent);
	--bolt-bubble: color-mix(in oklab, var(--color-gray-200) 55%, transparent);
	--bolt-selected: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--bolt-line: color-mix(in oklab, var(--color-gray-500) 26%, transparent);
	--bolt-glow: oklch(0.56 0.13 268 / 0.55);
	--bolt-ring: oklch(0.62 0.13 268 / 0.2);
	--bolt-shade: color-mix(in oklab, var(--color-gray-500) 30%, transparent);
	--bolt-accent: oklch(0.47 0.13 270);
}

/* Storm glass: cerulean surfaces, an electric edge on focus. !important only where Canvas FX transparency clears a background first. */
#message-input-container {
	background-color: var(--bolt-glass) !important;
	border-color: var(--bolt-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--bolt-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--bolt-glow) !important;
	box-shadow: 0 0 0 3px var(--bolt-ring), 0 12px 40px -16px var(--bolt-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--bolt-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--bolt-line);
}
#sidebar {
	background-color: var(--bolt-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--bolt-line);
}
#sidebar-chat-item.selected { background-color: var(--bolt-selected); }
.markdown-prose :is(h1, h2, h3) { color: var(--bolt-accent); letter-spacing: 0.01em; }
.markdown-prose a { color: var(--bolt-accent); text-decoration-color: var(--bolt-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--bolt-glow); }
.markdown-prose hr { border-color: var(--bolt-line); }
html { scrollbar-color: var(--bolt-line) transparent; }
::selection { background-color: var(--bolt-ring); }

her.canvasScript:
/**
 * Title: Thunderstorm
 * Description: Slanting rain at three depths under drifting cloud banks, with branching lightning that strikes beside the chat column above a low city skyline; tap to call a strike.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const RAIN_DENSITY    = 0.7;     // how much rain falls (0-2)
const RAIN_SPEED      = 1;     // fall speed; also slows the clouds (0.2-2)
const REDUCED_SPEED   = 0.25;  // share of the speed kept under reduced motion (0-1)
const WIND            = 0.16;  // base slant of the rain, in radians (0-0.5)
const GUST_STRENGTH   = 0.22;  // extra slant a gust adds (0-0.5)
const CURSOR_WIND     = 1;     // how far the cursor tilts the rain; eases back when it stops (0-2)
const STRIKE_EVERY    = 24;    // average seconds between strikes; 0 for taps only (0-120)
const FLASH_INTENSITY = 0.12;   // how strongly a strike lights the sky near it (0-1)
const BRANCHING       = 0.55;  // how much the bolts fork (0-1)
const CLOUD_COVER     = 1;     // how thick the cloud banks are (0-2)
const SKYLINE_HEIGHT  = 0.13;  // tallest building as a share of the screen height (0-0.2)
const CENTER_CALM     = 0.8;   // how much rain and cloud thin behind the chat column (0-1)
const BAND_WIDTH      = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME    = true;  // take the colors from the theme's palette
const RAIN_COLOR      = '#9fb4cc';  // rain when not following the theme
const CLOUD_COLOR     = '#3a4152';  // cloud banks
const BOLT_COLOR      = '#bcd0ff';  // lightning glow
const WINDOW_COLOR    = '#e8c27a';  // lit windows in the skyline
/* ──────────────────────────────────────────── */

const MAX_DROPS = 1100, MAX_PTS = 700, MAX_LINES = 36;

let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, reduced = false, dark = true, column = null;
let pal = { rain: hex(RAIN_COLOR), cloud: hex(CLOUD_COLOR), bolt: hex(BOLT_COLOR), win: hex(WINDOW_COLOR), bg: [26, 24, 38], text: [235, 238, 245] };
let rainStyle = ['', '', ''], boltGlow = '', boltCore = '', boltHot = '';
let cloudSprite, litSprite, flashSprite, skyline, skyW = 0, skyH = 0;

const F = (n) => new Float32Array(n), MAX_PUFFS = 140;
const rx = F(MAX_DROPS), ry = F(MAX_DROPS), rs = F(MAX_DROPS), rl = F(MAX_DROPS);
const cx = F(MAX_PUFFS), cy = F(MAX_PUFFS), cr = F(MAX_PUFFS), cv = F(MAX_PUFFS), ca = F(MAX_PUFFS);
let drops = 0, puffs = 0;

// Bolt geometry: polylines packed in typed arrays, branches queued so each line stays contiguous
const px = F(MAX_PTS), py = F(MAX_PTS), qx = F(MAX_LINES), qy = F(MAX_LINES), qa = F(MAX_LINES), ql = F(MAX_LINES);
const lStart = new Uint16Array(MAX_LINES), lLen = new Uint16Array(MAX_LINES), lDepth = new Uint8Array(MAX_LINES), qd = new Uint8Array(MAX_LINES);
let nPts = 0, nLines = 0, qCount = 0;
const bolt = { age: 99, x: 0, glowAge: 99, glowX: 0, wait: STRIKE_EVERY * 0.4, glowWait: 5, cool: 0 };
let wind = WIND, gust = 0, gustTarget = 0, gustWait = 6;
const mouse = { x: 0, amount: 0 };

function hex(c) { const n = parseInt(c.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function rgba(c, a) { return 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a.toFixed(3) + ')'; }
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }
function band(x) {
	const d = Math.abs(x - colX()) / colHalf();
	const t = Math.min(1, Math.max(0, (d - 0.55) / 0.7));
	return 1 - t * t * (3 - 2 * t);
}
function calm(x) { return 1 - CENTER_CALM * band(x); }
// A spot within a share f of the screen beside the chat column, on the side with room, inside the chat area so the sidebar can't cover it
function edge(f) {
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const left = Math.max(0, colX() - colHalf() - lo), right = Math.max(0, hi - colX() - colHalf()), m = w * f;
	if (left + right < 60) return Math.random() < 0.5 ? lo + Math.random() * m : hi - Math.random() * m;
	const r = Math.random() * (left + right);
	return r < left ? lo + (r / left) * Math.min(left, m) : hi - ((r - left) / right) * Math.min(right, m);
}

function sprite(size, col, a0, a1) {
	const c = new OffscreenCanvas(size, size), g = c.getContext('2d');
	const grad = g.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
	grad.addColorStop(0, rgba(col, a0));
	grad.addColorStop(0.5, rgba(col, a1));
	grad.addColorStop(1, rgba(col, 0));
	g.fillStyle = grad;
	g.fillRect(0, 0, size, size);
	return c;
}

function applyTheme(t) {
	if (t) {
		dark = t.dark !== false;
		if (FOLLOW_THEME && t.colors) {
			const c = t.colors, m = hex(c.muted), bg = hex(c.background), a3 = hex(c.accent3);
			pal = {
				rain: dark ? mix(m, a3, 0.35) : mix(m, hex(c.text), 0.25),
				cloud: dark ? mix(bg, m, 0.3) : mix(m, hex(c.text), 0.35),
				bolt: dark ? mix(a3, [255, 255, 255], 0.35) : hex(c.accent),
				win: hex(c.accent2), bg: bg, text: hex(c.text),
			};
		}
	}
	buildColors();
}

function buildColors() {
	const k = dark ? 1 : 0.55;
	for (let l = 0; l < 3; l++) rainStyle[l] = rgba(pal.rain, (0.22 + l * 0.17) * k);
	boltGlow = rgba(pal.bolt, dark ? 0.16 : 0.12);
	boltCore = rgba(pal.bolt, dark ? 0.85 : 0.6);
	boltHot = dark ? rgba(mix(pal.bolt, [255, 255, 255], 0.7), 0.95) : rgba(mix(pal.bolt, pal.text, 0.5), 0.75);
	cloudSprite = sprite(128, pal.cloud, dark ? 0.7 : 0.26, dark ? 0.4 : 0.14);
	litSprite = sprite(128, dark ? mix(pal.bolt, pal.cloud, 0.35) : mix(pal.bolt, pal.bg, 0.5), dark ? 0.5 : 0.25, 0.18);
	flashSprite = sprite(256, dark ? pal.bolt : mix(pal.bolt, pal.bg, 0.3), dark ? 0.32 : 0.16, 0.1);
	if (w) buildSkyline();
}

// ── Skyline: drawn once per resize, layout or theme into a cached strip along the bottom fifth ──
function buildSkyline() {
	skyH = Math.max(8, Math.round(h * Math.max(0.03, SKYLINE_HEIGHT) + 8));
	skyW = Math.max(1, w);
	skyline = new OffscreenCanvas(Math.round(skyW * dpr), Math.round(skyH * dpr));
	const g = skyline.getContext('2d');
	g.setTransform(dpr, 0, 0, dpr, 0, 0);
	const body = dark ? mix(pal.bg, [0, 0, 0], 0.5) : mix(pal.cloud, pal.bg, 0.25);
	const back = dark ? mix(pal.bg, pal.cloud, 0.6) : mix(pal.cloud, pal.bg, 0.55);
	for (let row = 0; row < 2; row++) {
		let x = -10 - Math.random() * 30;
		while (x < skyW + 10) {
			const bw = 16 + Math.random() * 44;
			const quiet = band(x + bw / 2);
			const tall = (row ? 0.35 : 0.6) + Math.random() * (row ? 0.65 : 0.4);
			const bh = Math.max(6, (skyH - 8) * tall * (1 - 0.55 * quiet));
			const top = skyH - bh;
			g.globalAlpha = (row ? (dark ? 0.85 : 0.5) : (dark ? 0.55 : 0.3)) * (1 - 0.5 * CENTER_CALM * quiet);
			g.fillStyle = rgba(row ? body : back, 1);
			g.fillRect(x, top, bw, bh);
			if (row && quiet < 0.5) {
				g.fillStyle = rgba(pal.win, 1);
				for (let fy = top + 5; fy < skyH - 4; fy += 6) {
					for (let fx = x + 3; fx < x + bw - 4; fx += 5) {
						if (Math.random() < 0.12) { g.globalAlpha = (dark ? 0.35 : 0.3) * (0.4 + Math.random() * 0.6); g.fillRect(fx, fy, 2, 2); }
					}
				}
			}
			x += bw + (row ? 2 + Math.random() * 10 : -4 + Math.random() * 14);
		}
	}
}

// ── Rain: spawn rejected over the chat column so it stays thin there ──
function spawnX() {
	for (let tries = 0; tries < 4; tries++) {
		const x = Math.random() * (w + 200) - 100;
		if (Math.random() < 1 - 0.85 * CENTER_CALM * band(x)) return x;
	}
	return edge(0.15);
}
function resetDrop(i, anywhere) {
	const z = i % 3;
	rx[i] = spawnX();
	ry[i] = anywhere ? Math.random() * h : -20 - Math.random() * 60;
	rs[i] = (480 + z * 330) * (0.85 + Math.random() * 0.3);
	rl[i] = (7 + z * 6) * (0.8 + Math.random() * 0.4);
}

function size() {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	drops = Math.min(MAX_DROPS, Math.round(w * h / 2400 * RAIN_DENSITY));
	for (let i = 0; i < drops; i++) resetDrop(i, true);
	puffs = Math.min(MAX_PUFFS, Math.round(w / 24 * CLOUD_COVER));
	const s = Math.max(0.6, Math.min(1.2, h / 900));
	for (let i = 0; i < puffs; i++) {
		cx[i] = Math.random() * (w + 400) - 200;
		cy[i] = h * (Math.pow(Math.random(), 1.6) * 0.2 - 0.01);
		cr[i] = (70 + Math.random() * 110) * s;
		cv[i] = 5 + Math.random() * 9;
		ca[i] = 0.55 + Math.random() * 0.45;
	}
	if (w && h) buildSkyline();
}

// ── Lightning: a mean-reverting walk for the channel, forks queued and tapering ──
function addLine(x0, y0, ang, len, depth) {
	if (nLines >= MAX_LINES || nPts >= MAX_PTS - 4) return;
	const li = nLines++;
	lStart[li] = nPts; lDepth[li] = depth;
	const steps = Math.max(4, Math.min(48, Math.floor(len / 13), MAX_PTS - nPts - 1));
	const seg = len / steps, ca2 = Math.cos(ang), sa2 = Math.sin(ang);
	let off = 0;
	px[nPts] = x0; py[nPts] = y0; nPts++;
	for (let i = 1; i <= steps; i++) {
		off = off * 0.82 + (Math.random() - 0.5) * seg * 1.7;
		const d = i * seg;
		const x = x0 + ca2 * d - sa2 * off, y = y0 + sa2 * d + ca2 * off;
		px[nPts] = x; py[nPts] = y; nPts++;
		const t = i / steps;
		if (depth < 3 && i > 2 && i < steps - 2 && Math.random() < BRANCHING * (depth ? 0.08 : 0.14) * (1.1 - t)) {
			if (qCount >= MAX_LINES) continue;
			qx[qCount] = x; qy[qCount] = y; qd[qCount] = depth + 1;
			qa[qCount] = ang + (Math.random() < 0.5 ? -1 : 1) * (0.35 + Math.random() * 0.6);
			ql[qCount++] = len * (1 - t) * (0.3 + Math.random() * 0.35);
		}
	}
	lLen[li] = nPts - lStart[li];
}

// Strikes land outside the calm band, nudged outward when called over the column
function strikeX(x) {
	const mid = colX(), reach = colHalf() * 0.95, lo = (column ? column.left : 0) + w * 0.04, hi = (column ? column.right : w) - w * 0.04;
	if (Math.abs(x - mid) < reach) {
		// Toward the nearer side, or the other one when the nearer has no room
		const out = x < mid ? mid - reach : mid + reach;
		x = out < lo ? mid + reach : out > hi ? mid - reach : out;
	}
	return Math.max(lo, Math.min(hi, x));
}

function strike(x) {
	if (reduced || bolt.cool > 0) { glowAt(x); return; }
	const x0 = strikeX(x);
	const top = h * (0.06 + Math.random() * 0.06), bottom = h * (0.84 + Math.random() * 0.08);
	const lean = (x0 < colX() ? -1 : 1) * Math.random() * 0.18;
	nPts = 0; nLines = 0; qCount = 0;
	addLine(x0, top, Math.PI / 2 + lean, bottom - top, 0);
	for (let q = 0; q < qCount; q++) addLine(qx[q], qy[q], qa[q], ql[q], qd[q]);
	bolt.x = x0; bolt.age = 0; bolt.cool = 0.9;
}
function glowAt(x) { bolt.glowX = strikeX(x); bolt.glowAge = 0; }

// A strike flickers twice, then fades over half a second
function boltLight(a) { return a < 0.06 ? 1 : a < 0.12 ? 0.35 : a < 0.2 ? 0.9 : Math.max(0, Math.exp(-(a - 0.2) * 6) - 0.01); }

function drawBolt(light) {
	ctx.lineCap = 'round';
	ctx.lineJoin = 'round';
	for (let pass = 0; pass < 3; pass++) {
		ctx.strokeStyle = pass === 0 ? boltGlow : pass === 1 ? boltCore : boltHot;
		for (let l = 0; l < nLines; l++) {
			const fade = lDepth[l] ? Math.pow(0.55, lDepth[l]) : 1;
			if (pass === 2 && lDepth[l] > 1) continue;
			ctx.globalAlpha = light * fade;
			ctx.lineWidth = (pass === 0 ? 9 : pass === 1 ? 2.6 : 1.1) * (lDepth[l] ? 0.7 / lDepth[l] : 1);
			ctx.beginPath();
			const s = lStart[l], e = s + lLen[l];
			ctx.moveTo(px[s], py[s]);
			for (let i = s + 1; i < e; i++) ctx.lineTo(px[i], py[i]);
			ctx.stroke();
		}
	}
}

function frame(now) {
	requestAnimationFrame(frame);
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	if (!w || !h) return;
	const sp = RAIN_SPEED * (reduced ? REDUCED_SPEED : 1);

	// Wind: base slant, slow gusts, and a cursor tilt that eases back after the cursor stops
	gustWait -= dt;
	if (gustWait <= 0) { gustTarget = reduced ? 0 : (Math.random() - 0.25) * GUST_STRENGTH; gustWait = 5 + Math.random() * 9; }
	if (gustWait < 3) gustTarget *= 1 - Math.min(1, dt * 0.4);
	gust += (gustTarget - gust) * Math.min(1, dt * 0.8);
	mouse.amount = Math.max(0, mouse.amount - dt * 0.25);
	const tilt = (mouse.x / w - 0.5) * 0.35 * CURSOR_WIND * mouse.amount;
	wind += (WIND + gust + tilt - wind) * Math.min(1, dt * 1.5);
	const vx = Math.sin(wind), vy = Math.cos(wind);

	// Strike timers
	bolt.age += dt; bolt.glowAge += dt; bolt.cool -= dt;
	if (STRIKE_EVERY > 0) {
		bolt.wait -= dt;
		if (bolt.wait <= 0) { strike(edge(0.3)); bolt.wait = STRIKE_EVERY * (0.5 + Math.random()); }
	}
	bolt.glowWait -= dt;
	if (bolt.glowWait <= 0) { glowAt(edge(0.25)); bolt.glowWait = 6 + Math.random() * 10; }
	const light = bolt.age < 1.2 ? boltLight(bolt.age) : 0;
	const glow = bolt.glowAge < 3 ? Math.sin(Math.PI * bolt.glowAge / 3) * (reduced ? 0.5 : 0.6) : 0;

	ctx.clearRect(0, 0, w, h);

	// Flash: a soft swell over the sky around the strike, never across the column
	if (light > 0.01 && FLASH_INTENSITY > 0) {
		ctx.globalAlpha = Math.min(1, light * FLASH_INTENSITY * 1.6);
		ctx.drawImage(flashSprite, bolt.x - w * 0.32, -h * 0.35, w * 0.64, h * 0.95);
	}

	// Cloud banks, lit from within near a strike or a distant glow
	const drift = dt * sp * 1.4;
	for (let i = 0; i < puffs; i++) {
		cx[i] += cv[i] * drift;
		if (cx[i] > w + 200) cx[i] -= w + 400;
		const r = cr[i], c = calm(cx[i]);
		ctx.globalAlpha = ca[i] * c;
		ctx.drawImage(cloudSprite, cx[i] - r, cy[i] - r * 0.55, r * 2, r * 1.1);
		let lit = 0;
		if (light > 0.01) lit += light * FLASH_INTENSITY * 2.2 * Math.max(0, 1 - Math.abs(cx[i] - bolt.x) / (w * 0.3));
		if (glow > 0.01) lit += glow * Math.max(0, 1 - Math.abs(cx[i] - bolt.glowX) / 260);
		if (lit > 0.01) {
			ctx.globalAlpha = Math.min(1, lit) * c;
			ctx.drawImage(litSprite, cx[i] - r * 0.8, cy[i] - r * 0.4, r * 1.6, r * 0.8);
		}
	}

	if (light > 0.01) drawBolt(light);

	if (skyline) { ctx.globalAlpha = 1; ctx.drawImage(skyline, 0, h - skyH, skyW, skyH); }

	// Rain, one path per depth layer
	for (let l = 0; l < 3; l++) {
		ctx.strokeStyle = rainStyle[l];
		ctx.lineWidth = l === 2 ? 1.2 : 1;
		ctx.globalAlpha = 1;
		ctx.beginPath();
		for (let i = l; i < drops; i += 3) {
			const v = rs[i] * sp;
			rx[i] += vx * v * dt;
			ry[i] += vy * v * dt;
			if (ry[i] > h + 20) resetDrop(i, false);
			else if (rx[i] > w + 120) rx[i] -= w + 220;
			else if (rx[i] < -120) rx[i] += w + 220;
			const len = rl[i] * (0.6 + 0.4 * sp);
			ctx.moveTo(rx[i], ry[i]);
			ctx.lineTo(rx[i] - vx * len, ry[i] - vy * len);
		}
		ctx.stroke();
	}

	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			size();
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas && w && h) buildSkyline();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.amount = 1;
			break;
		case 'mousedown':
			strike(d.x);
			break;
	}
};

dark.customCSS:
:root {
	--fog-glass: color-mix(in oklab, var(--color-gray-900) 56%, transparent);
	--fog-sidebar: color-mix(in oklab, var(--color-gray-950) 70%, transparent);
	--fog-bubble: color-mix(in oklab, var(--tdp-accent-3) 8%, var(--color-gray-800) 48%);
	--fog-selected: color-mix(in oklab, var(--color-gray-500) 20%, transparent);
	--fog-line: color-mix(in oklab, var(--color-gray-400) 20%, transparent);
	--fog-shade: color-mix(in oklab, var(--color-gray-950) 70%, transparent);
	--fog-glow: color-mix(in oklab, var(--tdp-accent-3) 45%, transparent);
	--fog-ring: color-mix(in oklab, var(--tdp-accent-3) 16%, transparent);
	--fog-sign: color-mix(in oklab, var(--tdp-accent-2) 85%, transparent);
	--fog-link: var(--tdp-accent);
	--fog-strong: color-mix(in oklab, var(--tdp-accent) 30%, var(--color-gray-100));
	--fog-pill-shadow: 0 14px 40px -18px var(--fog-shade), 0 10px 30px -22px color-mix(in oklab, var(--tdp-accent) 55%, transparent);
}

/* Rain-wet glass over the river city: Open WebUI's own shapes, a neon
   sign stripe on the open chat. !important only where Canvas FX clears a background. */
#message-input-container {
	background-color: var(--fog-glass) !important;
	border-color: var(--fog-line) !important;
	backdrop-filter: blur(16px) saturate(1.25);
	box-shadow: var(--fog-pill-shadow);
	transition: border-color 0.3s ease, box-shadow 0.3s ease;
}
#message-input-container:focus-within {
	border-color: var(--fog-glow) !important;
	box-shadow: 0 0 0 3px var(--fog-ring), var(--fog-pill-shadow);
}
.chat-user .rounded-3xl {
	background-color: var(--fog-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--fog-line);
}
#sidebar {
	background-color: var(--fog-sidebar) !important;
	backdrop-filter: blur(22px) saturate(1.2);
	border-inline-end: 1px solid var(--fog-line);
}
#sidebar-chat-item.selected { background-color: var(--fog-selected); box-shadow: inset 2px 0 0 var(--fog-sign); }
.markdown-prose a { color: var(--fog-link); text-decoration-color: var(--fog-glow); }
.markdown-prose strong { color: var(--fog-strong); }
.markdown-prose blockquote { border-inline-start-color: var(--fog-sign); }
.markdown-prose hr { border-color: var(--fog-line); }
html { scrollbar-color: var(--fog-line) transparent; }
::selection { background-color: var(--fog-ring); }

dark.canvasScript:
/**
 * Title: Chongqing Fog City (WebGL)
 * Description: Layered neon towers of a river city drift past in river mist and mirror onto rippling water, dipping and dimming behind the chat while the cursor turns your head.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const PAN_SPEED       = 1;     // how fast the skyline drifts sideways; 0 holds it still (0-3)
const MOTION          = 1;     // speed of the mist, ripples and window flicker (0-2)
const REDUCED_SPEED   = 0.15;  // share of the motion kept when the viewer asks to reduce motion (0-1)
const FOG_DENSITY     = 1;     // river-mist thickness (0-2)
const NEON_BRIGHTNESS = 1;     // glow of the lit windows and signs (0-2)
const WINDOW_DENSITY  = 0.45;  // share of windows that are lit (0-1)
const CITY_HEIGHT     = 1;     // how tall the towers climb (0.5-1.5)
const WATERLINE       = 0.22;  // height of the river's edge, as a share of the screen (0.1-0.4)
const LOOK_AROUND     = 1;     // how far the layers shift as the cursor moves (0-2)
const CENTER_CALM     = 0.8;   // how much the city dips and dims behind the chat column (0-1)
const BAND_WIDTH      = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const RENDER_SCALE    = 0.75;  // resolution of the scene; windows stay crisp at 0.75 (0.35-1)
const MAX_FPS         = 30;    // frame cap; the city moves slowly (15-60)
const FOLLOW_THEME    = true;  // take the colors from the theme's palette
const COLOR_AMBER     = '#ffb857';  // main window color when not following the theme
const COLOR_CYAN      = '#40e6ff';  // second window color
const COLOR_MAGENTA   = '#ff3d80';  // sign and lantern color
const COLOR_HAZE      = '#8a4a6a';  // fog color, where the neon bleeds into the mist
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform float u_pan[5];',
	'uniform vec2 u_look;',
	'uniform vec3 u_c1;',
	'uniform vec3 u_c2;',
	'uniform vec3 u_c3;',
	'uniform vec3 u_haze;',
	'uniform vec3 u_body;',
	'uniform float u_dark;',
	'uniform vec2 u_col;',
	'const float H = ' + WATERLINE.toFixed(3) + ';',
	'float h11(float n) { return fract(sin(mod(n, 1024.0) * 12.9898) * 43758.5453); }',
	'float h21(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }',
	'float noise(vec2 p) {',
	'	vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);',
	'	return mix(mix(h21(i), h21(i + vec2(1.0, 0.0)), u.x), mix(h21(i + vec2(0.0, 1.0)), h21(i + vec2(1.0, 1.0)), u.x), u.y);',
	'}',
	'float fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 4; i++) { v += a * noise(p); p *= 2.03; a *= 0.5; } return v; }',
	'vec3 winColor(float k) { return k < 0.5 ? u_c1 : (k < 0.75 ? u_c2 : (k < 0.92 ? u_c3 : mix(u_c2, vec3(1.0), 0.4))); }',
	'vec4 over(vec4 top, vec4 under) { return top + under * (1.0 - top.a); }',
	// The skyline at point p (in screen heights), premultiplied; calm dims it, dip lowers it
	'vec4 city(vec2 p, float calm, float fog) {',
	'	vec2 colH = u_col / (u_res.y / u_scale);',
	'	float sy = max(p.y - H, 0.0);',
	'	float g = exp(-sy * 3.5) * (0.14 + 0.10 * fog) * mix(0.55, 1.0, calm) * mix(0.6, 1.0, u_dark);',
	'	vec4 acc = vec4(u_haze * g, g) * step(H, p.y);',
	'	for (int i = 0; i < 5; i++) {',
	'		float fi = float(i), depth = fi / 4.0;',
	'		float scale = mix(6.5, 2.3, depth);',
	'		float off = u_pan[i] + u_look.x * (0.4 + depth * 1.4) + fi * 17.0;',
	'		float wx = p.x * scale + off;',
	'		float ci = floor(wx), f = fract(wx);',
	'		float rnd = h11(ci + fi * 57.0), rw = h11(ci * 1.73 + fi * 23.0);',
	'		float bandB = abs((ci + 0.5 - off) / scale - colH.x) / colH.y;',
	'		float dip = 1.0 - 0.5 * ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.4, 1.2, bandB));',
	'		float topH = (mix(0.20, 0.30, depth) + rnd * mix(0.12, 0.34, depth)) * ' + CITY_HEIGHT.toFixed(3) + ' * dip;',
	'		float wB = 0.70 + rw * 0.22, edge = (1.0 - wB) * 0.5;',
	'		float aa = scale / (u_res.y / u_scale);',
	'		float inB = smoothstep(edge - aa, edge, f) * smoothstep(1.0 - edge + aa, 1.0 - edge, f) * step(H, p.y) * smoothstep(H + topH + 0.002, H + topH, p.y);',
	'		float lx = (f - edge) / wB, ly = p.y - H;',
	'		float wCols = floor(5.0 + rw * 6.0), rowH = mix(0.011, 0.016, depth);',
	'		vec2 cell = vec2(floor(lx * wCols), floor(ly / rowH));',
	'		vec2 wf = vec2(fract(lx * wCols), fract(ly / rowH));',
	'		float frame = step(0.22, wf.x) * step(wf.x, 0.78) * step(0.3, wf.y) * step(wf.y, 0.78) * step(ly, topH - 0.012);',
	'		float seed = h21(cell + vec2(mod(ci, 1024.0) * 7.0, fi * 11.0));',
	'		float lit = step(mix(0.80, 0.25, ' + WINDOW_DENSITY.toFixed(3) + '), seed);',
	'		float flick = 0.78 + 0.22 * step(0.5, h21(cell + floor(u_time * (0.12 + seed * 0.3))));',
	'		float emit = lit * frame * flick * (0.45 + 0.55 * h21(cell + 3.7)) * (0.35 + depth * 0.65) * ' + NEON_BRIGHTNESS.toFixed(3) + ' * mix(0.75, 1.0, u_dark);',
	'		float sg = step(0.62, rnd) * step(0.5, depth) * step(0.06, lx) * step(lx, 0.12) * step(0.08, ly) * step(ly, topH * 0.7);',
	'		emit = max(emit, sg * (0.55 + 0.35 * sin(u_time * 0.8 + rnd * 20.0)) * ' + NEON_BRIGHTNESS.toFixed(3) + ');',
	'		vec3 wc = sg > 0.5 ? mix(u_c2, u_c3, step(0.8, rnd)) : winColor(h11(cell.x + cell.y * 3.1 + ci));',
	'		float haze = (1.0 - depth) * (0.35 + 0.3 * fog);',
	'		vec3 body = mix(u_body, u_haze, haze * mix(0.6, 0.15, u_dark));',
	'		float rise = mix(smoothstep(-0.02, 0.16 + 0.08 * fog, ly), 1.0, depth * 0.55);',
	'		float ba = mix(mix(0.22, 0.80, depth), mix(0.10, 0.38, depth), 1.0 - u_dark) * inB * calm * mix(0.35, 1.0, rise);',
	'		float we = emit * inB * calm * calm * mix(1.0 - haze * 0.6, 1.0, depth);',
	'		acc = over(vec4(body * ba + wc * we, max(ba, we)), acc);',
	'		if (i == 2) {',
	'			float mist = fbm(vec2(p.x * 2.4 - u_time * 0.04, p.y * 3.2 + u_time * 0.015));',
	'			float ma = smoothstep(0.35, 0.8, mist) * exp(-abs(p.y - H - 0.06) * 6.0) * 0.45 * fog * mix(0.4, 1.0, calm) * step(H, p.y);',
	'			ma *= mix(0.55, 1.0, u_dark);',
	'			acc = over(vec4(u_haze * ma, ma), acc);',
	'		}',
	'	}',
	'	return acc;',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	vec2 p = px / res.y;',
	'	p.y += u_look.y * 0.02;',
	'	float fog = ' + FOG_DENSITY.toFixed(3) + ';',
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float near = 1.0 - smoothstep(0.5, 1.3, band);',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * near;',
	'	vec4 col;',
	'	if (p.y >= H) {',
	'		col = city(p, calm, fog);',
	'	} else {',
	'		float d = H - p.y;',
	'		vec2 rp = vec2(p.x + sin(p.y * 42.0 + u_time * 1.6) * 0.004 * (1.0 + d * 3.0) + sin(p.y * 11.0 - u_time * 0.7) * 0.01 * d, H + d * 1.1);',
	'		float glint = smoothstep(0.45, 0.9, noise(vec2(p.x * 40.0, p.y * 150.0 - u_time * 1.2)));',
	'		vec4 refl = city(rp, calm, fog) * exp(-d * 5.0) * mix(0.5, 0.7, u_dark) * (0.6 + 0.8 * glint);',
	'		float wa = mix(0.06, 0.32, u_dark) * smoothstep(0.0, 0.05, d) * mix(0.35, 1.0, calm) * smoothstep(0.0, 0.18, p.y + 0.06);',
	'		col = over(refl, vec4(u_body * wa, wa));',
	'	}',
	'	col.a = clamp(col.a, 0.0, 1.0);',
	'	gl_FragColor = vec4(min(col.rgb, vec3(col.a)), col.a);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
const loc = {};
let w = 0, h = 0, dpr = 1;
let last = 0, time = 0, reduced = false, column = null;
const pans = new Float32Array(5);
const mouse = { x: -10000, y: -10000, amount: 0, target: 0, lx: 0, ly: 0 };
const colors = { c1: hexToRgb(COLOR_AMBER), c2: hexToRgb(COLOR_CYAN), c3: hexToRgb(COLOR_MAGENTA), haze: hexToRgb(COLOR_HAZE), body: [0.02, 0.02, 0.035], dark: 1 };

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function mix3(a, b, k) { return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]; }

// Windows in the accents, towers in the theme's structure color, fog between muted and accent2
function applyTheme(t) {
	if (t) colors.dark = t.dark === false ? 0 : 1;
	const own = !FOLLOW_THEME || !t || !t.rgb;
	if (own) {
		colors.c1 = hexToRgb(COLOR_AMBER);
		colors.c2 = hexToRgb(COLOR_CYAN);
		colors.c3 = hexToRgb(COLOR_MAGENTA);
		colors.haze = colors.dark ? hexToRgb(COLOR_HAZE) : [0.96, 0.95, 0.96];
		colors.body = colors.dark ? [0.02, 0.02, 0.035] : [0.36, 0.38, 0.44];
		return;
	}
	colors.c1 = t.rgb.accent;
	colors.c2 = t.rgb.accent3;
	colors.c3 = t.rgb.accent2;
	colors.haze = colors.dark ? mix3(t.rgb.muted, t.rgb.accent2, 0.35) : mix3(t.rgb.background, [1, 1, 1], 0.5);
	colors.body = colors.dark ? mix3(t.rgb.background, [0, 0, 0], 0.75) : t.rgb.muted;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_pan', 'u_look', 'u_c1', 'u_c2', 'u_c3', 'u_haze', 'u_body', 'u_dark', 'u_col'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

// Window grids are line art, so the scene follows the pixel ratio up to 2
function size() {
	const s = RENDER_SCALE * Math.min(dpr, 2);
	canvas.width = Math.max(1, Math.round(w * s));
	canvas.height = Math.max(1, Math.round(h * s));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const k = reduced ? REDUCED_SPEED : 1;
	time = (time + dt * MOTION * k) % 3000;
	for (let i = 0; i < 5; i++) pans[i] = (pans[i] + dt * PAN_SPEED * k * (0.015 + i * 0.02)) % 1024;
	// The head turn eases toward the cursor, then drifts back once it rests
	mouse.target = Math.max(0, mouse.target - dt * 0.35);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 2);
	const tx = w ? (mouse.x / w - 0.5) * mouse.amount * LOOK_AROUND : 0;
	const ty = h ? (0.5 - mouse.y / h) * mouse.amount * LOOK_AROUND : 0;
	const ease = Math.min(1, dt * (reduced ? 0.6 : 2.5));
	mouse.lx += (tx - mouse.lx) * ease;
	mouse.ly += (ty - mouse.ly) * ease;
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform1fv(loc.u_pan, pans);
	gl.uniform2f(loc.u_look, mouse.lx, mouse.ly);
	gl.uniform3fv(loc.u_c1, colors.c1);
	gl.uniform3fv(loc.u_c2, colors.c2);
	gl.uniform3fv(loc.u_c3, colors.c3);
	gl.uniform3fv(loc.u_haze, colors.haze);
	gl.uniform3fv(loc.u_body, colors.body);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	const opts = { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' };
	gl = canvas.getContext('webgl2', opts) || canvas.getContext('webgl', opts);
	if (!gl) {
		console.warn('Chongqing Fog City: WebGL is not available, so the city is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Chongqing Fog City:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Chongqing Fog City:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			dpr = d.dpr || 1;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			for (let i = 0; i < 5; i++) pans[i] = Math.random() * 1024;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			dpr = d.dpr || dpr;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

light.customCSS:
:root {
	--fog-glass: color-mix(in oklab, var(--color-gray-50) 64%, transparent);
	--fog-sidebar: color-mix(in oklab, var(--color-gray-50) 70%, transparent);
	--fog-bubble: color-mix(in oklab, var(--tdp-accent-3) 8%, var(--color-gray-100) 56%);
	--fog-selected: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--fog-line: color-mix(in oklab, var(--color-gray-500) 26%, transparent);
	--fog-shade: color-mix(in oklab, var(--color-gray-600) 26%, transparent);
	--fog-glow: color-mix(in oklab, var(--tdp-accent-3) 50%, transparent);
	--fog-ring: color-mix(in oklab, var(--tdp-accent-3) 18%, transparent);
	--fog-sign: var(--tdp-accent-2);
	--fog-link: var(--tdp-accent-3);
	--fog-strong: color-mix(in oklab, var(--tdp-accent) 25%, var(--color-gray-900));
	--fog-pill-shadow: 0 14px 40px -18px var(--fog-shade);
}

/* Rain-wet glass over the river city: Open WebUI's own shapes, a neon
   sign stripe on the open chat. !important only where Canvas FX clears a background. */
#message-input-container {
	background-color: var(--fog-glass) !important;
	border-color: var(--fog-line) !important;
	backdrop-filter: blur(16px) saturate(1.25);
	box-shadow: var(--fog-pill-shadow);
	transition: border-color 0.3s ease, box-shadow 0.3s ease;
}
#message-input-container:focus-within {
	border-color: var(--fog-glow) !important;
	box-shadow: 0 0 0 3px var(--fog-ring), var(--fog-pill-shadow);
}
.chat-user .rounded-3xl {
	background-color: var(--fog-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--fog-line);
}
#sidebar {
	background-color: var(--fog-sidebar) !important;
	backdrop-filter: blur(22px) saturate(1.2);
	border-inline-end: 1px solid var(--fog-line);
}
#sidebar-chat-item.selected { background-color: var(--fog-selected); box-shadow: inset 2px 0 0 var(--fog-sign); }
.markdown-prose a { color: var(--fog-link); text-decoration-color: var(--fog-glow); }
.markdown-prose strong { color: var(--fog-strong); }
.markdown-prose blockquote { border-inline-start-color: var(--fog-sign); }
.markdown-prose hr { border-color: var(--fog-line); }
html { scrollbar-color: var(--fog-line) transparent; }
::selection { background-color: var(--fog-ring); }

light.canvasScript:
/**
 * Title: Chongqing Fog City (WebGL)
 * Description: Layered neon towers of a river city drift past in river mist and mirror onto rippling water, dipping and dimming behind the chat while the cursor turns your head.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const PAN_SPEED       = 1;     // how fast the skyline drifts sideways; 0 holds it still (0-3)
const MOTION          = 1;     // speed of the mist, ripples and window flicker (0-2)
const REDUCED_SPEED   = 0.15;  // share of the motion kept when the viewer asks to reduce motion (0-1)
const FOG_DENSITY     = 1;     // river-mist thickness (0-2)
const NEON_BRIGHTNESS = 1.4;     // glow of the lit windows and signs (0-2)
const WINDOW_DENSITY  = 0.45;  // share of windows that are lit (0-1)
const CITY_HEIGHT     = 1;     // how tall the towers climb (0.5-1.5)
const WATERLINE       = 0.22;  // height of the river's edge, as a share of the screen (0.1-0.4)
const LOOK_AROUND     = 1;     // how far the layers shift as the cursor moves (0-2)
const CENTER_CALM     = 0.8;   // how much the city dips and dims behind the chat column (0-1)
const BAND_WIDTH      = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const RENDER_SCALE    = 0.75;  // resolution of the scene; windows stay crisp at 0.75 (0.35-1)
const MAX_FPS         = 30;    // frame cap; the city moves slowly (15-60)
const FOLLOW_THEME    = true;  // take the colors from the theme's palette
const COLOR_AMBER     = '#ffb857';  // main window color when not following the theme
const COLOR_CYAN      = '#40e6ff';  // second window color
const COLOR_MAGENTA   = '#ff3d80';  // sign and lantern color
const COLOR_HAZE      = '#8a4a6a';  // fog color, where the neon bleeds into the mist
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform float u_pan[5];',
	'uniform vec2 u_look;',
	'uniform vec3 u_c1;',
	'uniform vec3 u_c2;',
	'uniform vec3 u_c3;',
	'uniform vec3 u_haze;',
	'uniform vec3 u_body;',
	'uniform float u_dark;',
	'uniform vec2 u_col;',
	'const float H = ' + WATERLINE.toFixed(3) + ';',
	'float h11(float n) { return fract(sin(mod(n, 1024.0) * 12.9898) * 43758.5453); }',
	'float h21(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }',
	'float noise(vec2 p) {',
	'	vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);',
	'	return mix(mix(h21(i), h21(i + vec2(1.0, 0.0)), u.x), mix(h21(i + vec2(0.0, 1.0)), h21(i + vec2(1.0, 1.0)), u.x), u.y);',
	'}',
	'float fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 4; i++) { v += a * noise(p); p *= 2.03; a *= 0.5; } return v; }',
	'vec3 winColor(float k) { return k < 0.5 ? u_c1 : (k < 0.75 ? u_c2 : (k < 0.92 ? u_c3 : mix(u_c2, vec3(1.0), 0.4))); }',
	'vec4 over(vec4 top, vec4 under) { return top + under * (1.0 - top.a); }',
	// The skyline at point p (in screen heights), premultiplied; calm dims it, dip lowers it
	'vec4 city(vec2 p, float calm, float fog) {',
	'	vec2 colH = u_col / (u_res.y / u_scale);',
	'	float sy = max(p.y - H, 0.0);',
	'	float g = exp(-sy * 3.5) * (0.14 + 0.10 * fog) * mix(0.55, 1.0, calm) * mix(0.6, 1.0, u_dark);',
	'	vec4 acc = vec4(u_haze * g, g) * step(H, p.y);',
	'	for (int i = 0; i < 5; i++) {',
	'		float fi = float(i), depth = fi / 4.0;',
	'		float scale = mix(6.5, 2.3, depth);',
	'		float off = u_pan[i] + u_look.x * (0.4 + depth * 1.4) + fi * 17.0;',
	'		float wx = p.x * scale + off;',
	'		float ci = floor(wx), f = fract(wx);',
	'		float rnd = h11(ci + fi * 57.0), rw = h11(ci * 1.73 + fi * 23.0);',
	'		float bandB = abs((ci + 0.5 - off) / scale - colH.x) / colH.y;',
	'		float dip = 1.0 - 0.5 * ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.4, 1.2, bandB));',
	'		float topH = (mix(0.20, 0.30, depth) + rnd * mix(0.12, 0.34, depth)) * ' + CITY_HEIGHT.toFixed(3) + ' * dip;',
	'		float wB = 0.70 + rw * 0.22, edge = (1.0 - wB) * 0.5;',
	'		float aa = scale / (u_res.y / u_scale);',
	'		float inB = smoothstep(edge - aa, edge, f) * smoothstep(1.0 - edge + aa, 1.0 - edge, f) * step(H, p.y) * smoothstep(H + topH + 0.002, H + topH, p.y);',
	'		float lx = (f - edge) / wB, ly = p.y - H;',
	'		float wCols = floor(5.0 + rw * 6.0), rowH = mix(0.011, 0.016, depth);',
	'		vec2 cell = vec2(floor(lx * wCols), floor(ly / rowH));',
	'		vec2 wf = vec2(fract(lx * wCols), fract(ly / rowH));',
	'		float frame = step(0.22, wf.x) * step(wf.x, 0.78) * step(0.3, wf.y) * step(wf.y, 0.78) * step(ly, topH - 0.012);',
	'		float seed = h21(cell + vec2(mod(ci, 1024.0) * 7.0, fi * 11.0));',
	'		float lit = step(mix(0.80, 0.25, ' + WINDOW_DENSITY.toFixed(3) + '), seed);',
	'		float flick = 0.78 + 0.22 * step(0.5, h21(cell + floor(u_time * (0.12 + seed * 0.3))));',
	'		float emit = lit * frame * flick * (0.45 + 0.55 * h21(cell + 3.7)) * (0.35 + depth * 0.65) * ' + NEON_BRIGHTNESS.toFixed(3) + ' * mix(0.75, 1.0, u_dark);',
	'		float sg = step(0.62, rnd) * step(0.5, depth) * step(0.06, lx) * step(lx, 0.12) * step(0.08, ly) * step(ly, topH * 0.7);',
	'		emit = max(emit, sg * (0.55 + 0.35 * sin(u_time * 0.8 + rnd * 20.0)) * ' + NEON_BRIGHTNESS.toFixed(3) + ');',
	'		vec3 wc = sg > 0.5 ? mix(u_c2, u_c3, step(0.8, rnd)) : winColor(h11(cell.x + cell.y * 3.1 + ci));',
	'		float haze = (1.0 - depth) * (0.35 + 0.3 * fog);',
	'		vec3 body = mix(u_body, u_haze, haze * mix(0.6, 0.15, u_dark));',
	'		float rise = mix(smoothstep(-0.02, 0.16 + 0.08 * fog, ly), 1.0, depth * 0.55);',
	'		float ba = mix(mix(0.22, 0.80, depth), mix(0.10, 0.38, depth), 1.0 - u_dark) * inB * calm * mix(0.35, 1.0, rise);',
	'		float we = emit * inB * calm * calm * mix(1.0 - haze * 0.6, 1.0, depth);',
	'		acc = over(vec4(body * ba + wc * we, max(ba, we)), acc);',
	'		if (i == 2) {',
	'			float mist = fbm(vec2(p.x * 2.4 - u_time * 0.04, p.y * 3.2 + u_time * 0.015));',
	'			float ma = smoothstep(0.35, 0.8, mist) * exp(-abs(p.y - H - 0.06) * 6.0) * 0.45 * fog * mix(0.4, 1.0, calm) * step(H, p.y);',
	'			ma *= mix(0.55, 1.0, u_dark);',
	'			acc = over(vec4(u_haze * ma, ma), acc);',
	'		}',
	'	}',
	'	return acc;',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	vec2 p = px / res.y;',
	'	p.y += u_look.y * 0.02;',
	'	float fog = ' + FOG_DENSITY.toFixed(3) + ';',
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float near = 1.0 - smoothstep(0.5, 1.3, band);',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * near;',
	'	vec4 col;',
	'	if (p.y >= H) {',
	'		col = city(p, calm, fog);',
	'	} else {',
	'		float d = H - p.y;',
	'		vec2 rp = vec2(p.x + sin(p.y * 42.0 + u_time * 1.6) * 0.004 * (1.0 + d * 3.0) + sin(p.y * 11.0 - u_time * 0.7) * 0.01 * d, H + d * 1.1);',
	'		float glint = smoothstep(0.45, 0.9, noise(vec2(p.x * 40.0, p.y * 150.0 - u_time * 1.2)));',
	'		vec4 refl = city(rp, calm, fog) * exp(-d * 5.0) * mix(0.5, 0.7, u_dark) * (0.6 + 0.8 * glint);',
	'		float wa = mix(0.06, 0.32, u_dark) * smoothstep(0.0, 0.05, d) * mix(0.35, 1.0, calm) * smoothstep(0.0, 0.18, p.y + 0.06);',
	'		col = over(refl, vec4(u_body * wa, wa));',
	'	}',
	'	col.a = clamp(col.a, 0.0, 1.0);',
	'	gl_FragColor = vec4(min(col.rgb, vec3(col.a)), col.a);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
const loc = {};
let w = 0, h = 0, dpr = 1;
let last = 0, time = 0, reduced = false, column = null;
const pans = new Float32Array(5);
const mouse = { x: -10000, y: -10000, amount: 0, target: 0, lx: 0, ly: 0 };
const colors = { c1: hexToRgb(COLOR_AMBER), c2: hexToRgb(COLOR_CYAN), c3: hexToRgb(COLOR_MAGENTA), haze: hexToRgb(COLOR_HAZE), body: [0.02, 0.02, 0.035], dark: 1 };

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function mix3(a, b, k) { return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]; }

// Windows in the accents, towers in the theme's structure color, fog between muted and accent2
function applyTheme(t) {
	if (t) colors.dark = t.dark === false ? 0 : 1;
	const own = !FOLLOW_THEME || !t || !t.rgb;
	if (own) {
		colors.c1 = hexToRgb(COLOR_AMBER);
		colors.c2 = hexToRgb(COLOR_CYAN);
		colors.c3 = hexToRgb(COLOR_MAGENTA);
		colors.haze = colors.dark ? hexToRgb(COLOR_HAZE) : [0.96, 0.95, 0.96];
		colors.body = colors.dark ? [0.02, 0.02, 0.035] : [0.36, 0.38, 0.44];
		return;
	}
	colors.c1 = t.rgb.accent;
	colors.c2 = t.rgb.accent3;
	colors.c3 = t.rgb.accent2;
	colors.haze = colors.dark ? mix3(t.rgb.muted, t.rgb.accent2, 0.35) : mix3(t.rgb.background, [1, 1, 1], 0.5);
	colors.body = colors.dark ? mix3(t.rgb.background, [0, 0, 0], 0.75) : t.rgb.muted;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_pan', 'u_look', 'u_c1', 'u_c2', 'u_c3', 'u_haze', 'u_body', 'u_dark', 'u_col'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

// Window grids are line art, so the scene follows the pixel ratio up to 2
function size() {
	const s = RENDER_SCALE * Math.min(dpr, 2);
	canvas.width = Math.max(1, Math.round(w * s));
	canvas.height = Math.max(1, Math.round(h * s));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const k = reduced ? REDUCED_SPEED : 1;
	time = (time + dt * MOTION * k) % 3000;
	for (let i = 0; i < 5; i++) pans[i] = (pans[i] + dt * PAN_SPEED * k * (0.015 + i * 0.02)) % 1024;
	// The head turn eases toward the cursor, then drifts back once it rests
	mouse.target = Math.max(0, mouse.target - dt * 0.35);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 2);
	const tx = w ? (mouse.x / w - 0.5) * mouse.amount * LOOK_AROUND : 0;
	const ty = h ? (0.5 - mouse.y / h) * mouse.amount * LOOK_AROUND : 0;
	const ease = Math.min(1, dt * (reduced ? 0.6 : 2.5));
	mouse.lx += (tx - mouse.lx) * ease;
	mouse.ly += (ty - mouse.ly) * ease;
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform1fv(loc.u_pan, pans);
	gl.uniform2f(loc.u_look, mouse.lx, mouse.ly);
	gl.uniform3fv(loc.u_c1, colors.c1);
	gl.uniform3fv(loc.u_c2, colors.c2);
	gl.uniform3fv(loc.u_c3, colors.c3);
	gl.uniform3fv(loc.u_haze, colors.haze);
	gl.uniform3fv(loc.u_body, colors.body);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	const opts = { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' };
	gl = canvas.getContext('webgl2', opts) || canvas.getContext('webgl', opts);
	if (!gl) {
		console.warn('Chongqing Fog City: WebGL is not available, so the city is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Chongqing Fog City:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Chongqing Fog City:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			dpr = d.dpr || 1;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			for (let i = 0; i < 5; i++) pans[i] = Math.random() * 1024;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			dpr = d.dpr || dpr;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

oled.customCSS:
:root {
	--fog-glass: color-mix(in oklab, var(--color-gray-950) 62%, transparent);
	--fog-sidebar: color-mix(in oklab, var(--color-gray-950) 76%, transparent);
	--fog-bubble: color-mix(in oklab, var(--tdp-accent-3) 8%, var(--color-gray-800) 48%);
	--fog-selected: color-mix(in oklab, var(--color-gray-500) 20%, transparent);
	--fog-line: color-mix(in oklab, var(--color-gray-400) 20%, transparent);
	--fog-shade: color-mix(in oklab, var(--color-gray-950) 70%, transparent);
	--fog-glow: color-mix(in oklab, var(--tdp-accent-3) 45%, transparent);
	--fog-ring: color-mix(in oklab, var(--tdp-accent-3) 16%, transparent);
	--fog-sign: color-mix(in oklab, var(--tdp-accent-2) 85%, transparent);
	--fog-link: var(--tdp-accent);
	--fog-strong: color-mix(in oklab, var(--tdp-accent) 30%, var(--color-gray-100));
	--fog-pill-shadow: 0 14px 40px -18px var(--fog-shade), 0 10px 30px -22px color-mix(in oklab, var(--tdp-accent) 55%, transparent);
}

/* Rain-wet glass over the river city: Open WebUI's own shapes, a neon
   sign stripe on the open chat. !important only where Canvas FX clears a background. */
#message-input-container {
	background-color: var(--fog-glass) !important;
	border-color: var(--fog-line) !important;
	backdrop-filter: blur(16px) saturate(1.25);
	box-shadow: var(--fog-pill-shadow);
	transition: border-color 0.3s ease, box-shadow 0.3s ease;
}
#message-input-container:focus-within {
	border-color: var(--fog-glow) !important;
	box-shadow: 0 0 0 3px var(--fog-ring), var(--fog-pill-shadow);
}
.chat-user .rounded-3xl {
	background-color: var(--fog-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--fog-line);
}
#sidebar {
	background-color: var(--fog-sidebar) !important;
	backdrop-filter: blur(22px) saturate(1.2);
	border-inline-end: 1px solid var(--fog-line);
}
#sidebar-chat-item.selected { background-color: var(--fog-selected); box-shadow: inset 2px 0 0 var(--fog-sign); }
.markdown-prose a { color: var(--fog-link); text-decoration-color: var(--fog-glow); }
.markdown-prose strong { color: var(--fog-strong); }
.markdown-prose blockquote { border-inline-start-color: var(--fog-sign); }
.markdown-prose hr { border-color: var(--fog-line); }
html { scrollbar-color: var(--fog-line) transparent; }
::selection { background-color: var(--fog-ring); }

oled.canvasScript:
/**
 * Title: Chongqing Fog City (WebGL)
 * Description: Layered neon towers of a river city drift past in river mist and mirror onto rippling water, dipping and dimming behind the chat while the cursor turns your head.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const PAN_SPEED       = 1;     // how fast the skyline drifts sideways; 0 holds it still (0-3)
const MOTION          = 1;     // speed of the mist, ripples and window flicker (0-2)
const REDUCED_SPEED   = 0.15;  // share of the motion kept when the viewer asks to reduce motion (0-1)
const FOG_DENSITY     = 1;     // river-mist thickness (0-2)
const NEON_BRIGHTNESS = 1;     // glow of the lit windows and signs (0-2)
const WINDOW_DENSITY  = 0.45;  // share of windows that are lit (0-1)
const CITY_HEIGHT     = 1;     // how tall the towers climb (0.5-1.5)
const WATERLINE       = 0.22;  // height of the river's edge, as a share of the screen (0.1-0.4)
const LOOK_AROUND     = 1;     // how far the layers shift as the cursor moves (0-2)
const CENTER_CALM     = 0.8;   // how much the city dips and dims behind the chat column (0-1)
const BAND_WIDTH      = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const RENDER_SCALE    = 0.75;  // resolution of the scene; windows stay crisp at 0.75 (0.35-1)
const MAX_FPS         = 30;    // frame cap; the city moves slowly (15-60)
const FOLLOW_THEME    = true;  // take the colors from the theme's palette
const COLOR_AMBER     = '#ffb857';  // main window color when not following the theme
const COLOR_CYAN      = '#40e6ff';  // second window color
const COLOR_MAGENTA   = '#ff3d80';  // sign and lantern color
const COLOR_HAZE      = '#8a4a6a';  // fog color, where the neon bleeds into the mist
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform float u_pan[5];',
	'uniform vec2 u_look;',
	'uniform vec3 u_c1;',
	'uniform vec3 u_c2;',
	'uniform vec3 u_c3;',
	'uniform vec3 u_haze;',
	'uniform vec3 u_body;',
	'uniform float u_dark;',
	'uniform vec2 u_col;',
	'const float H = ' + WATERLINE.toFixed(3) + ';',
	'float h11(float n) { return fract(sin(mod(n, 1024.0) * 12.9898) * 43758.5453); }',
	'float h21(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }',
	'float noise(vec2 p) {',
	'	vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);',
	'	return mix(mix(h21(i), h21(i + vec2(1.0, 0.0)), u.x), mix(h21(i + vec2(0.0, 1.0)), h21(i + vec2(1.0, 1.0)), u.x), u.y);',
	'}',
	'float fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 4; i++) { v += a * noise(p); p *= 2.03; a *= 0.5; } return v; }',
	'vec3 winColor(float k) { return k < 0.5 ? u_c1 : (k < 0.75 ? u_c2 : (k < 0.92 ? u_c3 : mix(u_c2, vec3(1.0), 0.4))); }',
	'vec4 over(vec4 top, vec4 under) { return top + under * (1.0 - top.a); }',
	// The skyline at point p (in screen heights), premultiplied; calm dims it, dip lowers it
	'vec4 city(vec2 p, float calm, float fog) {',
	'	vec2 colH = u_col / (u_res.y / u_scale);',
	'	float sy = max(p.y - H, 0.0);',
	'	float g = exp(-sy * 3.5) * (0.14 + 0.10 * fog) * mix(0.55, 1.0, calm) * mix(0.6, 1.0, u_dark);',
	'	vec4 acc = vec4(u_haze * g, g) * step(H, p.y);',
	'	for (int i = 0; i < 5; i++) {',
	'		float fi = float(i), depth = fi / 4.0;',
	'		float scale = mix(6.5, 2.3, depth);',
	'		float off = u_pan[i] + u_look.x * (0.4 + depth * 1.4) + fi * 17.0;',
	'		float wx = p.x * scale + off;',
	'		float ci = floor(wx), f = fract(wx);',
	'		float rnd = h11(ci + fi * 57.0), rw = h11(ci * 1.73 + fi * 23.0);',
	'		float bandB = abs((ci + 0.5 - off) / scale - colH.x) / colH.y;',
	'		float dip = 1.0 - 0.5 * ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.4, 1.2, bandB));',
	'		float topH = (mix(0.20, 0.30, depth) + rnd * mix(0.12, 0.34, depth)) * ' + CITY_HEIGHT.toFixed(3) + ' * dip;',
	'		float wB = 0.70 + rw * 0.22, edge = (1.0 - wB) * 0.5;',
	'		float aa = scale / (u_res.y / u_scale);',
	'		float inB = smoothstep(edge - aa, edge, f) * smoothstep(1.0 - edge + aa, 1.0 - edge, f) * step(H, p.y) * smoothstep(H + topH + 0.002, H + topH, p.y);',
	'		float lx = (f - edge) / wB, ly = p.y - H;',
	'		float wCols = floor(5.0 + rw * 6.0), rowH = mix(0.011, 0.016, depth);',
	'		vec2 cell = vec2(floor(lx * wCols), floor(ly / rowH));',
	'		vec2 wf = vec2(fract(lx * wCols), fract(ly / rowH));',
	'		float frame = step(0.22, wf.x) * step(wf.x, 0.78) * step(0.3, wf.y) * step(wf.y, 0.78) * step(ly, topH - 0.012);',
	'		float seed = h21(cell + vec2(mod(ci, 1024.0) * 7.0, fi * 11.0));',
	'		float lit = step(mix(0.80, 0.25, ' + WINDOW_DENSITY.toFixed(3) + '), seed);',
	'		float flick = 0.78 + 0.22 * step(0.5, h21(cell + floor(u_time * (0.12 + seed * 0.3))));',
	'		float emit = lit * frame * flick * (0.45 + 0.55 * h21(cell + 3.7)) * (0.35 + depth * 0.65) * ' + NEON_BRIGHTNESS.toFixed(3) + ' * mix(0.75, 1.0, u_dark);',
	'		float sg = step(0.62, rnd) * step(0.5, depth) * step(0.06, lx) * step(lx, 0.12) * step(0.08, ly) * step(ly, topH * 0.7);',
	'		emit = max(emit, sg * (0.55 + 0.35 * sin(u_time * 0.8 + rnd * 20.0)) * ' + NEON_BRIGHTNESS.toFixed(3) + ');',
	'		vec3 wc = sg > 0.5 ? mix(u_c2, u_c3, step(0.8, rnd)) : winColor(h11(cell.x + cell.y * 3.1 + ci));',
	'		float haze = (1.0 - depth) * (0.35 + 0.3 * fog);',
	'		vec3 body = mix(u_body, u_haze, haze * mix(0.6, 0.15, u_dark));',
	'		float rise = mix(smoothstep(-0.02, 0.16 + 0.08 * fog, ly), 1.0, depth * 0.55);',
	'		float ba = mix(mix(0.22, 0.80, depth), mix(0.10, 0.38, depth), 1.0 - u_dark) * inB * calm * mix(0.35, 1.0, rise);',
	'		float we = emit * inB * calm * calm * mix(1.0 - haze * 0.6, 1.0, depth);',
	'		acc = over(vec4(body * ba + wc * we, max(ba, we)), acc);',
	'		if (i == 2) {',
	'			float mist = fbm(vec2(p.x * 2.4 - u_time * 0.04, p.y * 3.2 + u_time * 0.015));',
	'			float ma = smoothstep(0.35, 0.8, mist) * exp(-abs(p.y - H - 0.06) * 6.0) * 0.45 * fog * mix(0.4, 1.0, calm) * step(H, p.y);',
	'			ma *= mix(0.55, 1.0, u_dark);',
	'			acc = over(vec4(u_haze * ma, ma), acc);',
	'		}',
	'	}',
	'	return acc;',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	vec2 p = px / res.y;',
	'	p.y += u_look.y * 0.02;',
	'	float fog = ' + FOG_DENSITY.toFixed(3) + ';',
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float near = 1.0 - smoothstep(0.5, 1.3, band);',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * near;',
	'	vec4 col;',
	'	if (p.y >= H) {',
	'		col = city(p, calm, fog);',
	'	} else {',
	'		float d = H - p.y;',
	'		vec2 rp = vec2(p.x + sin(p.y * 42.0 + u_time * 1.6) * 0.004 * (1.0 + d * 3.0) + sin(p.y * 11.0 - u_time * 0.7) * 0.01 * d, H + d * 1.1);',
	'		float glint = smoothstep(0.45, 0.9, noise(vec2(p.x * 40.0, p.y * 150.0 - u_time * 1.2)));',
	'		vec4 refl = city(rp, calm, fog) * exp(-d * 5.0) * mix(0.5, 0.7, u_dark) * (0.6 + 0.8 * glint);',
	'		float wa = mix(0.06, 0.32, u_dark) * smoothstep(0.0, 0.05, d) * mix(0.35, 1.0, calm) * smoothstep(0.0, 0.18, p.y + 0.06);',
	'		col = over(refl, vec4(u_body * wa, wa));',
	'	}',
	'	col.a = clamp(col.a, 0.0, 1.0);',
	'	gl_FragColor = vec4(min(col.rgb, vec3(col.a)), col.a);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
const loc = {};
let w = 0, h = 0, dpr = 1;
let last = 0, time = 0, reduced = false, column = null;
const pans = new Float32Array(5);
const mouse = { x: -10000, y: -10000, amount: 0, target: 0, lx: 0, ly: 0 };
const colors = { c1: hexToRgb(COLOR_AMBER), c2: hexToRgb(COLOR_CYAN), c3: hexToRgb(COLOR_MAGENTA), haze: hexToRgb(COLOR_HAZE), body: [0.02, 0.02, 0.035], dark: 1 };

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function mix3(a, b, k) { return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]; }

// Windows in the accents, towers in the theme's structure color, fog between muted and accent2
function applyTheme(t) {
	if (t) colors.dark = t.dark === false ? 0 : 1;
	const own = !FOLLOW_THEME || !t || !t.rgb;
	if (own) {
		colors.c1 = hexToRgb(COLOR_AMBER);
		colors.c2 = hexToRgb(COLOR_CYAN);
		colors.c3 = hexToRgb(COLOR_MAGENTA);
		colors.haze = colors.dark ? hexToRgb(COLOR_HAZE) : [0.96, 0.95, 0.96];
		colors.body = colors.dark ? [0.02, 0.02, 0.035] : [0.36, 0.38, 0.44];
		return;
	}
	colors.c1 = t.rgb.accent;
	colors.c2 = t.rgb.accent3;
	colors.c3 = t.rgb.accent2;
	colors.haze = colors.dark ? mix3(t.rgb.muted, t.rgb.accent2, 0.35) : mix3(t.rgb.background, [1, 1, 1], 0.5);
	colors.body = colors.dark ? mix3(t.rgb.background, [0, 0, 0], 0.75) : t.rgb.muted;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_pan', 'u_look', 'u_c1', 'u_c2', 'u_c3', 'u_haze', 'u_body', 'u_dark', 'u_col'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

// Window grids are line art, so the scene follows the pixel ratio up to 2
function size() {
	const s = RENDER_SCALE * Math.min(dpr, 2);
	canvas.width = Math.max(1, Math.round(w * s));
	canvas.height = Math.max(1, Math.round(h * s));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const k = reduced ? REDUCED_SPEED : 1;
	time = (time + dt * MOTION * k) % 3000;
	for (let i = 0; i < 5; i++) pans[i] = (pans[i] + dt * PAN_SPEED * k * (0.015 + i * 0.02)) % 1024;
	// The head turn eases toward the cursor, then drifts back once it rests
	mouse.target = Math.max(0, mouse.target - dt * 0.35);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 2);
	const tx = w ? (mouse.x / w - 0.5) * mouse.amount * LOOK_AROUND : 0;
	const ty = h ? (0.5 - mouse.y / h) * mouse.amount * LOOK_AROUND : 0;
	const ease = Math.min(1, dt * (reduced ? 0.6 : 2.5));
	mouse.lx += (tx - mouse.lx) * ease;
	mouse.ly += (ty - mouse.ly) * ease;
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform1fv(loc.u_pan, pans);
	gl.uniform2f(loc.u_look, mouse.lx, mouse.ly);
	gl.uniform3fv(loc.u_c1, colors.c1);
	gl.uniform3fv(loc.u_c2, colors.c2);
	gl.uniform3fv(loc.u_c3, colors.c3);
	gl.uniform3fv(loc.u_haze, colors.haze);
	gl.uniform3fv(loc.u_body, colors.body);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	const opts = { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' };
	gl = canvas.getContext('webgl2', opts) || canvas.getContext('webgl', opts);
	if (!gl) {
		console.warn('Chongqing Fog City: WebGL is not available, so the city is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Chongqing Fog City:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Chongqing Fog City:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			dpr = d.dpr || 1;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			for (let i = 0; i < 5; i++) pans[i] = Math.random() * 1024;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			dpr = d.dpr || dpr;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

her.customCSS:
:root {
	--fog-glass: color-mix(in oklab, var(--color-gray-50) 64%, transparent);
	--fog-sidebar: color-mix(in oklab, var(--color-gray-50) 70%, transparent);
	--fog-bubble: color-mix(in oklab, var(--tdp-accent-3) 8%, var(--color-gray-100) 56%);
	--fog-selected: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--fog-line: color-mix(in oklab, var(--color-gray-500) 26%, transparent);
	--fog-shade: color-mix(in oklab, var(--color-gray-600) 26%, transparent);
	--fog-glow: color-mix(in oklab, var(--tdp-accent-3) 50%, transparent);
	--fog-ring: color-mix(in oklab, var(--tdp-accent-3) 18%, transparent);
	--fog-sign: var(--tdp-accent-2);
	--fog-link: var(--tdp-accent-3);
	--fog-strong: color-mix(in oklab, var(--tdp-accent) 25%, var(--color-gray-900));
	--fog-pill-shadow: 0 14px 40px -18px var(--fog-shade);
}

/* Rain-wet glass over the river city: Open WebUI's own shapes, a neon
   sign stripe on the open chat. !important only where Canvas FX clears a background. */
#message-input-container {
	background-color: var(--fog-glass) !important;
	border-color: var(--fog-line) !important;
	backdrop-filter: blur(16px) saturate(1.25);
	box-shadow: var(--fog-pill-shadow);
	transition: border-color 0.3s ease, box-shadow 0.3s ease;
}
#message-input-container:focus-within {
	border-color: var(--fog-glow) !important;
	box-shadow: 0 0 0 3px var(--fog-ring), var(--fog-pill-shadow);
}
.chat-user .rounded-3xl {
	background-color: var(--fog-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--fog-line);
}
#sidebar {
	background-color: var(--fog-sidebar) !important;
	backdrop-filter: blur(22px) saturate(1.2);
	border-inline-end: 1px solid var(--fog-line);
}
#sidebar-chat-item.selected { background-color: var(--fog-selected); box-shadow: inset 2px 0 0 var(--fog-sign); }
.markdown-prose a { color: var(--fog-link); text-decoration-color: var(--fog-glow); }
.markdown-prose strong { color: var(--fog-strong); }
.markdown-prose blockquote { border-inline-start-color: var(--fog-sign); }
.markdown-prose hr { border-color: var(--fog-line); }
html { scrollbar-color: var(--fog-line) transparent; }
::selection { background-color: var(--fog-ring); }

her.canvasScript:
/**
 * Title: Chongqing Fog City (WebGL)
 * Description: Layered neon towers of a river city drift past in river mist and mirror onto rippling water, dipping and dimming behind the chat while the cursor turns your head.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const PAN_SPEED       = 1;     // how fast the skyline drifts sideways; 0 holds it still (0-3)
const MOTION          = 1;     // speed of the mist, ripples and window flicker (0-2)
const REDUCED_SPEED   = 0.15;  // share of the motion kept when the viewer asks to reduce motion (0-1)
const FOG_DENSITY     = 1;     // river-mist thickness (0-2)
const NEON_BRIGHTNESS = 1.4;     // glow of the lit windows and signs (0-2)
const WINDOW_DENSITY  = 0.45;  // share of windows that are lit (0-1)
const CITY_HEIGHT     = 1;     // how tall the towers climb (0.5-1.5)
const WATERLINE       = 0.22;  // height of the river's edge, as a share of the screen (0.1-0.4)
const LOOK_AROUND     = 1;     // how far the layers shift as the cursor moves (0-2)
const CENTER_CALM     = 0.8;   // how much the city dips and dims behind the chat column (0-1)
const BAND_WIDTH      = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const RENDER_SCALE    = 0.75;  // resolution of the scene; windows stay crisp at 0.75 (0.35-1)
const MAX_FPS         = 30;    // frame cap; the city moves slowly (15-60)
const FOLLOW_THEME    = true;  // take the colors from the theme's palette
const COLOR_AMBER     = '#ffb857';  // main window color when not following the theme
const COLOR_CYAN      = '#40e6ff';  // second window color
const COLOR_MAGENTA   = '#ff3d80';  // sign and lantern color
const COLOR_HAZE      = '#8a4a6a';  // fog color, where the neon bleeds into the mist
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform float u_pan[5];',
	'uniform vec2 u_look;',
	'uniform vec3 u_c1;',
	'uniform vec3 u_c2;',
	'uniform vec3 u_c3;',
	'uniform vec3 u_haze;',
	'uniform vec3 u_body;',
	'uniform float u_dark;',
	'uniform vec2 u_col;',
	'const float H = ' + WATERLINE.toFixed(3) + ';',
	'float h11(float n) { return fract(sin(mod(n, 1024.0) * 12.9898) * 43758.5453); }',
	'float h21(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }',
	'float noise(vec2 p) {',
	'	vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);',
	'	return mix(mix(h21(i), h21(i + vec2(1.0, 0.0)), u.x), mix(h21(i + vec2(0.0, 1.0)), h21(i + vec2(1.0, 1.0)), u.x), u.y);',
	'}',
	'float fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 4; i++) { v += a * noise(p); p *= 2.03; a *= 0.5; } return v; }',
	'vec3 winColor(float k) { return k < 0.5 ? u_c1 : (k < 0.75 ? u_c2 : (k < 0.92 ? u_c3 : mix(u_c2, vec3(1.0), 0.4))); }',
	'vec4 over(vec4 top, vec4 under) { return top + under * (1.0 - top.a); }',
	// The skyline at point p (in screen heights), premultiplied; calm dims it, dip lowers it
	'vec4 city(vec2 p, float calm, float fog) {',
	'	vec2 colH = u_col / (u_res.y / u_scale);',
	'	float sy = max(p.y - H, 0.0);',
	'	float g = exp(-sy * 3.5) * (0.14 + 0.10 * fog) * mix(0.55, 1.0, calm) * mix(0.6, 1.0, u_dark);',
	'	vec4 acc = vec4(u_haze * g, g) * step(H, p.y);',
	'	for (int i = 0; i < 5; i++) {',
	'		float fi = float(i), depth = fi / 4.0;',
	'		float scale = mix(6.5, 2.3, depth);',
	'		float off = u_pan[i] + u_look.x * (0.4 + depth * 1.4) + fi * 17.0;',
	'		float wx = p.x * scale + off;',
	'		float ci = floor(wx), f = fract(wx);',
	'		float rnd = h11(ci + fi * 57.0), rw = h11(ci * 1.73 + fi * 23.0);',
	'		float bandB = abs((ci + 0.5 - off) / scale - colH.x) / colH.y;',
	'		float dip = 1.0 - 0.5 * ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.4, 1.2, bandB));',
	'		float topH = (mix(0.20, 0.30, depth) + rnd * mix(0.12, 0.34, depth)) * ' + CITY_HEIGHT.toFixed(3) + ' * dip;',
	'		float wB = 0.70 + rw * 0.22, edge = (1.0 - wB) * 0.5;',
	'		float aa = scale / (u_res.y / u_scale);',
	'		float inB = smoothstep(edge - aa, edge, f) * smoothstep(1.0 - edge + aa, 1.0 - edge, f) * step(H, p.y) * smoothstep(H + topH + 0.002, H + topH, p.y);',
	'		float lx = (f - edge) / wB, ly = p.y - H;',
	'		float wCols = floor(5.0 + rw * 6.0), rowH = mix(0.011, 0.016, depth);',
	'		vec2 cell = vec2(floor(lx * wCols), floor(ly / rowH));',
	'		vec2 wf = vec2(fract(lx * wCols), fract(ly / rowH));',
	'		float frame = step(0.22, wf.x) * step(wf.x, 0.78) * step(0.3, wf.y) * step(wf.y, 0.78) * step(ly, topH - 0.012);',
	'		float seed = h21(cell + vec2(mod(ci, 1024.0) * 7.0, fi * 11.0));',
	'		float lit = step(mix(0.80, 0.25, ' + WINDOW_DENSITY.toFixed(3) + '), seed);',
	'		float flick = 0.78 + 0.22 * step(0.5, h21(cell + floor(u_time * (0.12 + seed * 0.3))));',
	'		float emit = lit * frame * flick * (0.45 + 0.55 * h21(cell + 3.7)) * (0.35 + depth * 0.65) * ' + NEON_BRIGHTNESS.toFixed(3) + ' * mix(0.75, 1.0, u_dark);',
	'		float sg = step(0.62, rnd) * step(0.5, depth) * step(0.06, lx) * step(lx, 0.12) * step(0.08, ly) * step(ly, topH * 0.7);',
	'		emit = max(emit, sg * (0.55 + 0.35 * sin(u_time * 0.8 + rnd * 20.0)) * ' + NEON_BRIGHTNESS.toFixed(3) + ');',
	'		vec3 wc = sg > 0.5 ? mix(u_c2, u_c3, step(0.8, rnd)) : winColor(h11(cell.x + cell.y * 3.1 + ci));',
	'		float haze = (1.0 - depth) * (0.35 + 0.3 * fog);',
	'		vec3 body = mix(u_body, u_haze, haze * mix(0.6, 0.15, u_dark));',
	'		float rise = mix(smoothstep(-0.02, 0.16 + 0.08 * fog, ly), 1.0, depth * 0.55);',
	'		float ba = mix(mix(0.22, 0.80, depth), mix(0.10, 0.38, depth), 1.0 - u_dark) * inB * calm * mix(0.35, 1.0, rise);',
	'		float we = emit * inB * calm * calm * mix(1.0 - haze * 0.6, 1.0, depth);',
	'		acc = over(vec4(body * ba + wc * we, max(ba, we)), acc);',
	'		if (i == 2) {',
	'			float mist = fbm(vec2(p.x * 2.4 - u_time * 0.04, p.y * 3.2 + u_time * 0.015));',
	'			float ma = smoothstep(0.35, 0.8, mist) * exp(-abs(p.y - H - 0.06) * 6.0) * 0.45 * fog * mix(0.4, 1.0, calm) * step(H, p.y);',
	'			ma *= mix(0.55, 1.0, u_dark);',
	'			acc = over(vec4(u_haze * ma, ma), acc);',
	'		}',
	'	}',
	'	return acc;',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	vec2 p = px / res.y;',
	'	p.y += u_look.y * 0.02;',
	'	float fog = ' + FOG_DENSITY.toFixed(3) + ';',
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float near = 1.0 - smoothstep(0.5, 1.3, band);',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * near;',
	'	vec4 col;',
	'	if (p.y >= H) {',
	'		col = city(p, calm, fog);',
	'	} else {',
	'		float d = H - p.y;',
	'		vec2 rp = vec2(p.x + sin(p.y * 42.0 + u_time * 1.6) * 0.004 * (1.0 + d * 3.0) + sin(p.y * 11.0 - u_time * 0.7) * 0.01 * d, H + d * 1.1);',
	'		float glint = smoothstep(0.45, 0.9, noise(vec2(p.x * 40.0, p.y * 150.0 - u_time * 1.2)));',
	'		vec4 refl = city(rp, calm, fog) * exp(-d * 5.0) * mix(0.5, 0.7, u_dark) * (0.6 + 0.8 * glint);',
	'		float wa = mix(0.06, 0.32, u_dark) * smoothstep(0.0, 0.05, d) * mix(0.35, 1.0, calm) * smoothstep(0.0, 0.18, p.y + 0.06);',
	'		col = over(refl, vec4(u_body * wa, wa));',
	'	}',
	'	col.a = clamp(col.a, 0.0, 1.0);',
	'	gl_FragColor = vec4(min(col.rgb, vec3(col.a)), col.a);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
const loc = {};
let w = 0, h = 0, dpr = 1;
let last = 0, time = 0, reduced = false, column = null;
const pans = new Float32Array(5);
const mouse = { x: -10000, y: -10000, amount: 0, target: 0, lx: 0, ly: 0 };
const colors = { c1: hexToRgb(COLOR_AMBER), c2: hexToRgb(COLOR_CYAN), c3: hexToRgb(COLOR_MAGENTA), haze: hexToRgb(COLOR_HAZE), body: [0.02, 0.02, 0.035], dark: 1 };

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function mix3(a, b, k) { return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]; }

// Windows in the accents, towers in the theme's structure color, fog between muted and accent2
function applyTheme(t) {
	if (t) colors.dark = t.dark === false ? 0 : 1;
	const own = !FOLLOW_THEME || !t || !t.rgb;
	if (own) {
		colors.c1 = hexToRgb(COLOR_AMBER);
		colors.c2 = hexToRgb(COLOR_CYAN);
		colors.c3 = hexToRgb(COLOR_MAGENTA);
		colors.haze = colors.dark ? hexToRgb(COLOR_HAZE) : [0.96, 0.95, 0.96];
		colors.body = colors.dark ? [0.02, 0.02, 0.035] : [0.36, 0.38, 0.44];
		return;
	}
	colors.c1 = t.rgb.accent;
	colors.c2 = t.rgb.accent3;
	colors.c3 = t.rgb.accent2;
	colors.haze = colors.dark ? mix3(t.rgb.muted, t.rgb.accent2, 0.35) : mix3(t.rgb.background, [1, 1, 1], 0.5);
	colors.body = colors.dark ? mix3(t.rgb.background, [0, 0, 0], 0.75) : t.rgb.muted;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_pan', 'u_look', 'u_c1', 'u_c2', 'u_c3', 'u_haze', 'u_body', 'u_dark', 'u_col'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

// Window grids are line art, so the scene follows the pixel ratio up to 2
function size() {
	const s = RENDER_SCALE * Math.min(dpr, 2);
	canvas.width = Math.max(1, Math.round(w * s));
	canvas.height = Math.max(1, Math.round(h * s));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const k = reduced ? REDUCED_SPEED : 1;
	time = (time + dt * MOTION * k) % 3000;
	for (let i = 0; i < 5; i++) pans[i] = (pans[i] + dt * PAN_SPEED * k * (0.015 + i * 0.02)) % 1024;
	// The head turn eases toward the cursor, then drifts back once it rests
	mouse.target = Math.max(0, mouse.target - dt * 0.35);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 2);
	const tx = w ? (mouse.x / w - 0.5) * mouse.amount * LOOK_AROUND : 0;
	const ty = h ? (0.5 - mouse.y / h) * mouse.amount * LOOK_AROUND : 0;
	const ease = Math.min(1, dt * (reduced ? 0.6 : 2.5));
	mouse.lx += (tx - mouse.lx) * ease;
	mouse.ly += (ty - mouse.ly) * ease;
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform1fv(loc.u_pan, pans);
	gl.uniform2f(loc.u_look, mouse.lx, mouse.ly);
	gl.uniform3fv(loc.u_c1, colors.c1);
	gl.uniform3fv(loc.u_c2, colors.c2);
	gl.uniform3fv(loc.u_c3, colors.c3);
	gl.uniform3fv(loc.u_haze, colors.haze);
	gl.uniform3fv(loc.u_body, colors.body);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	const opts = { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' };
	gl = canvas.getContext('webgl2', opts) || canvas.getContext('webgl', opts);
	if (!gl) {
		console.warn('Chongqing Fog City: WebGL is not available, so the city is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Chongqing Fog City:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Chongqing Fog City:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			dpr = d.dpr || 1;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			for (let i = 0; i < 5; i++) pans[i] = Math.random() * 1024;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			dpr = d.dpr || dpr;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

