	'	cx = cx > u_col.x ? min(max(cx, u_col.x + u_col.y * 0.85), u_area.y - reach * 0.3) : max(min(cx, u_col.x - u_col.y * 0.85), u_area.x + reach * 0.3);',
	'	vec2 c = vec2(cx, (1.0 - ' + CORE_Y.toFixed(3) + ') * res.y);',
	'	vec2 rel = (px - c) / reach;',
	'	float d = length(rel);',
