	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--ms-line);
}
#sidebar-chat-item.selected { background-color: var(--ms-selected); }
.markdown-prose a { color: var(--ms-accent); text-decoration-color: var(--ms-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--ms-glow); }
.markdown-prose :is(h1, h2) { color: var(--ms-accent); }
.markdown-prose hr { border-color: var(--ms-glow); }
html { scrollbar-color: var(--ms-line) transparent; }
::selection { background-color: var(--ms-ring); }

her.canvasScript:
/**
 * Title: Ember Dream
 * Description: Campfire embers rise from the bottom of the screen in your theme's colors, cool as they climb, thin out behind the chat, scatter when the cursor sweeps past and burst from a tap.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const EMBER_COUNT   = 150;   // embers in the air at once (30-400)
const RISE_SPEED    = 42;    // average climb, in px per second (10-120)
const RISE_HEIGHT   = 0.55;  // how far up the screen embers climb before burning out (0.2-1)
const SWAY          = 18;    // side-to-side drift, in px per second (0-60)
const EMBER_SIZE    = 1;     // size of each ember and its glow (0.5-2)
const WISPS         = 5;     // faint flame wisps along the bottom edge (0-12)
const GLOW_POOLS    = 3;     // warm pools of firelight along the bottom (0-6)
const WIND          = 1;     // how hard a moving cursor scatters embers (0-3)
const BURST_SIZE    = 24;    // embers thrown by a tap; 0 turns taps off (0-60)
const MOTION        = 1;     // overall speed (0.2-2)
const REDUCED_SPEED = 0.25;  // speed kept when the viewer asks to reduce motion (0-1)
const CENTER_CALM   = 0.8;   // how much the embers thin out behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const COLOR_HOT     = '#ffd98a';  // fresh ember color when not following the theme
const COLOR_WARM    = '#ff8c3a';  // ember color halfway up
const COLOR_COOL    = '#d4442a';  // dying ember and wisp color
const FIRE_WARMTH   = 0.5;   // how far theme colors lean toward firelight (0-1)
/* ──────────────────────────────────────────── */

const MAX_BURST = 150, ES = 32, GS = 128;
let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, time = 0, reduced = false, dark = true, column = null;
let calmLut = new Float32Array(1), hexes = [COLOR_HOT, COLOR_WARM, COLOR_COOL];
const emberSprites = [], mouse = { x: -10000, y: -10000, energy: 0 };
let glowSprite = null, wispSprite = null;

// Ember pool
const ex = new Float32Array(EMBER_COUNT), ey = new Float32Array(EMBER_COUNT), evx = new Float32Array(EMBER_COUNT);
const ey0 = new Float32Array(EMBER_COUNT), erise = new Float32Array(EMBER_COUNT), espd = new Float32Array(EMBER_COUNT);
const esz = new Float32Array(EMBER_COUNT), eph = new Float32Array(EMBER_COUNT), eage = new Float32Array(EMBER_COUNT);
// Burst pool
const bx = new Float32Array(MAX_BURST), by = new Float32Array(MAX_BURST), bvx = new Float32Array(MAX_BURST), bvy = new Float32Array(MAX_BURST);
const blife = new Float32Array(MAX_BURST), bsz = new Float32Array(MAX_BURST);
let bcount = 0;
// Wisps and pools
const wx = new Float32Array(12), wy = new Float32Array(12), wage = new Float32Array(12), wspan = new Float32Array(12), wsc = new Float32Array(12), wph = new Float32Array(12);
const px = new Float32Array(6), pph = new Float32Array(6);

function rgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function rgba(c, a, lift) {
	return 'rgba(' + Math.round(c[0] + (255 - c[0]) * lift) + ',' + Math.round(c[1] + (255 - c[1]) * lift) + ',' + Math.round(c[2] + (255 - c[2]) * lift) + ',' + a + ')';
}
// Leans a theme color toward its firelight default, so embers still read as embers
function mix(a, b) {
	const x = rgb(a), y = rgb(b), k = FIRE_WARMTH;
	return '#' + ((1 << 24) | (Math.round(x[0] + (y[0] - x[0]) * k) << 16) | (Math.round(x[1] + (y[1] - x[1]) * k) << 8) | Math.round(x[2] + (y[2] - x[2]) * k)).toString(16).slice(1);
}
function radial(size, stops) {
	const s = new OffscreenCanvas(size, size), g = s.getContext('2d'), r = size / 2;
	const grad = g.createRadialGradient(r, r, 0, r, r, r);
	for (let i = 0; i < stops.length; i += 2) grad.addColorStop(stops[i], stops[i + 1]);
	g.fillStyle = grad;
	g.fillRect(0, 0, size, size);
	return s;
}

// Sprites: one glowing ember per heat stage, a pool of firelight and a soft flame tongue
function buildSprites() {
	for (let i = 0; i < 3; i++) {
		const c = rgb(hexes[i]);
		emberSprites[i] = dark
			? radial(ES, [0, rgba(c, 1, 0.75 - i * 0.25), 0.07, rgba(c, 1, 0.35 - i * 0.12), 0.18, rgba(c, 0.7, 0), 0.4, rgba(c, 0.22, 0), 0.7, rgba(c, 0.05, 0), 1, rgba(c, 0, 0)])
			: radial(ES, [0, rgba(c, 1, 0), 0.16, rgba(c, 0.95, 0), 0.3, rgba(c, 0.35, 0), 0.6, rgba(c, 0.06, 0), 1, rgba(c, 0, 0)]);
	}
	const warm = rgb(hexes[1]), cool = rgb(hexes[2]);
	glowSprite = radial(GS, [0, rgba(warm, 1, 0), 0.4, rgba(warm, 0.45, 0), 1, rgba(warm, 0, 0)]);
	wispSprite = new OffscreenCanvas(64, 192);
	const g = wispSprite.getContext('2d');
	const grad = g.createLinearGradient(0, 192, 0, 0);
	grad.addColorStop(0, rgba(cool, 1, 0));
	grad.addColorStop(0.45, rgba(warm, 0.8, 0));
	grad.addColorStop(1, rgba(rgb(hexes[0]), 0, 0));
	g.fillStyle = grad;
	g.globalAlpha = 0.12;
	for (let k = 0; k < 9; k++) {
		const s = 1 - k * 0.08;
		g.beginPath();
		g.moveTo(32 - 30 * s, 192);
		g.bezierCurveTo(32 - 32 * s, 120, 32 - 6 * s, 80, 32 + 4 * s, 192 - 188 * s);
		g.bezierCurveTo(32 + 14 * s, 90, 32 + 32 * s, 130, 32 + 30 * s, 192);
		g.fill();
	}
}

function applyTheme(t) {
	if (!t) return;
	dark = t.dark !== false;
	if (FOLLOW_THEME && t.colors) hexes = [mix(t.colors.accent, COLOR_HOT), mix(t.colors.accent2, COLOR_WARM), mix(t.colors.accent3, COLOR_COOL)];
	if (ctx) buildSprites();
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

// Density and alpha factor across the screen, rebuilt on resize and layout
function buildCalm() {
	calmLut = new Float32Array((w >> 2) + 2);
	const cx = colX(), half = colHalf();
	for (let i = 0; i < calmLut.length; i++) {
		const t = Math.min(1, Math.max(0, (Math.abs(i * 4 - cx) / half - 0.55) / 0.7));
		calmLut[i] = 1 - CENTER_CALM * (1 - t * t * (3 - 2 * t));
	}
}

function calm(x) {
	const i = x >> 2;
	return calmLut[i < 0 ? 0 : i >= calmLut.length ? calmLut.length - 1 : i];
}

// Spawn in the bottom fifth, less often behind the chat column
function spawn(i, scatter) {
	let x = Math.random() * w;
	for (let k = 0; k < 3 && Math.random() > calm(x); k++) x = Math.random() * w;
	ex[i] = x;
	ey0[i] = h * (0.82 + Math.random() * 0.2);
	erise[i] = h * RISE_HEIGHT * (0.35 + Math.random() * 0.65);
	ey[i] = scatter ? ey0[i] - erise[i] * Math.random() : ey0[i];
	evx[i] = 0;
	espd[i] = RISE_SPEED * (0.6 + Math.random() * 0.8);
	esz[i] = (22 + Math.random() * 24) * EMBER_SIZE;
	eph[i] = Math.random() * 6.283;
	eage[i] = scatter ? 2 : 0;
}

function size(oldW, oldH) {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	buildCalm();
	if (oldW) {
		const sx = w / oldW, sy = h / oldH;
		for (let i = 0; i < EMBER_COUNT; i++) { ex[i] *= sx; ey[i] *= sy; ey0[i] *= sy; erise[i] *= sy; }
		for (let i = 0; i < bcount; i++) { bx[i] *= sx; by[i] *= sy; }
	} else {
		for (let i = 0; i < EMBER_COUNT; i++) spawn(i, true);
	}
	for (let i = 0; i < 12; i++) resetWisp(i, true);
	for (let i = 0; i < 6; i++) { const side = i % 2; px[i] = side ? w * (0.86 + Math.random() * 0.12) : w * (0.02 + Math.random() * 0.12); pph[i] = Math.random() * 6.283; }
}

// Wisps rise beside the chat column, on either side by the room each has
function resetWisp(i, scatter) {
	// Measured from the chat area's edges, which leave out the sidebar
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const pad = w * 0.03, left = Math.max(0, colX() - colHalf() * 0.6 - pad - lo), right = Math.max(0, hi - pad - colX() - colHalf() * 0.6);
	const r = Math.random() * (left + right);
	wx[i] = left + right < 40 ? lo + Math.random() * (hi - lo) : r < left ? lo + pad + r : hi - pad - (r - left);
	wy[i] = h + 30 + Math.random() * 40;
	wspan[i] = 5 + Math.random() * 5;
	wage[i] = scatter ? Math.random() * wspan[i] : 0;
	wsc[i] = 0.6 + Math.random() * 0.7;
	wph[i] = Math.random() * 6.283;
}

function burst(x, y) {
	const n = Math.round(BURST_SIZE * Math.max(0.3, calm(x)));
	for (let k = 0; k < n && bcount < MAX_BURST; k++) {
		const i = bcount++, a = Math.random() * 6.283, v = 40 + Math.random() * 110;
		bx[i] = x; by[i] = y;
		bvx[i] = Math.cos(a) * v; bvy[i] = Math.sin(a) * v - 50;
		blife[i] = 1.2 + Math.random() * 1.2;
		bsz[i] = (20 + Math.random() * 16) * EMBER_SIZE;
	}
}

function frame(now) {
	requestAnimationFrame(frame);
	const real = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const dt = real * MOTION * (reduced ? REDUCED_SPEED : 1);
	time += dt;
	mouse.energy *= Math.exp(-real * 2.5);
	ctx.clearRect(0, 0, w, h);
	const lit = dark ? 1 : 0.9;

	// Firelight pools and wisps along the bottom
	ctx.globalCompositeOperation = dark ? 'lighter' : 'source-over';
	for (let i = 0; i < GLOW_POOLS; i++) {
		const d = 420 + 60 * Math.sin(time * 0.4 + pph[i]);
		ctx.globalAlpha = (dark ? 0.13 : 0.05) * (0.75 + 0.25 * Math.sin(time * 0.9 + pph[i] * 3));
		ctx.drawImage(glowSprite, px[i] - d / 2, h - d * 0.32, d, d);
	}
	for (let i = 0; i < WISPS; i++) {
		wage[i] += dt;
		if (wage[i] > wspan[i]) resetWisp(i, false);
		const f = wage[i] / wspan[i], s = wsc[i];
		ctx.globalAlpha = (dark ? 0.15 : 0.06) * Math.sin(f * 3.1416) * calm(wx[i]);
		const fl = 1 + 0.12 * Math.sin(time * 5 + wph[i]), sk = 0.18 * Math.sin(time * 0.7 + wph[i]);
		ctx.setTransform(dpr * s * fl, 0, dpr * sk * s, dpr * s * (1 - f * 0.3), dpr * wx[i], dpr * (wy[i] - f * 90));
		ctx.drawImage(wispSprite, -32, -192);
	}
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

	// Embers: climb, sway, cool through three colors and burn out
	const drag = Math.exp(-1.6 * dt), wind = WIND * mouse.energy * 900;
	for (let i = 0; i < EMBER_COUNT; i++) {
		eage[i] += dt;
		ey[i] -= espd[i] * dt;
		const r = (ey0[i] - ey[i]) / erise[i];
		if (r >= 1) { spawn(i, false); continue; }
		if (wind > 1) {
			const dx = ex[i] - mouse.x, dy = ey[i] - mouse.y, dd = dx * dx + dy * dy;
			if (dd < 32400 && dd > 1) {
				const dist = Math.sqrt(dd);
				evx[i] += (dx / dist) * (1 - dist / 180) * wind * dt;
				ey[i] -= (1 - dist / 180) * wind * 0.15 * dt;
			}
		}
		evx[i] *= drag;
		ex[i] += (evx[i] + Math.sin(time * 0.8 + eph[i]) * SWAY) * dt;
		if (ex[i] < -20) ex[i] += w + 40; else if (ex[i] > w + 20) ex[i] -= w + 40;
		const a = Math.min(1, eage[i] / 0.8) * (1 - r * r) * (0.7 + 0.3 * Math.sin(time * 3 + eph[i] * 5)) * calm(ex[i]) * lit;
		if (a < 0.02) continue;
		const d = esz[i] * (1 - r * 0.5);
		ctx.globalAlpha = a;
		ctx.drawImage(emberSprites[r < 0.3 ? 0 : r < 0.65 ? 1 : 2], ex[i] - d / 2, ey[i] - d / 2, d, d);
	}

	// Tap bursts
	const grav = 60 * dt;
	for (let i = 0; i < bcount; i++) {
		blife[i] -= dt;
		if (blife[i] <= 0) {
			const j = --bcount;
			bx[i] = bx[j]; by[i] = by[j]; bvx[i] = bvx[j]; bvy[i] = bvy[j]; blife[i] = blife[j]; bsz[i] = bsz[j];
			i--;
			continue;
		}
		bvx[i] *= drag; bvy[i] = bvy[i] * drag + grav;
		bx[i] += bvx[i] * dt; by[i] += bvy[i] * dt;
		const f = Math.min(1, blife[i] / 1.2);
		ctx.globalAlpha = f * lit * Math.max(0.35, calm(bx[i]));
		const d = bsz[i] * (0.6 + 0.4 * f);
		ctx.drawImage(emberSprites[f > 0.6 ? 0 : 1], bx[i] - d / 2, by[i] - d / 2, d, d);
	}
	ctx.globalAlpha = 1;
	ctx.globalCompositeOperation = 'source-over';
}

function move(x, y) {
	if (mouse.x > -9000) mouse.energy = Math.min(1, mouse.energy + Math.hypot(x - mouse.x, y - mouse.y) / 60);
	mouse.x = x; mouse.y = y;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 1);
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			buildSprites();
			size(0, 0);
			requestAnimationFrame(frame);
			break;
		case 'resize': {
			const ow = w, oh = h;
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 1);
			if (canvas) size(ow, oh);
			break;
		}
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas) buildCalm();
			break;
		case 'mousemove':
			move(d.x, d.y);
			break;
		case 'touchmove':
			if (d.touches && d.touches.length) move(d.touches[0].x, d.touches[0].y);
			break;
		case 'mousedown':
			if (!reduced && BURST_SIZE > 0) burst(d.x, d.y);
			break;
	}
};

dark.customCSS:
:root {
	--forge-glass: color-mix(in oklab, var(--color-gray-900) 58%, transparent);
	--forge-sidebar: color-mix(in oklab, var(--color-gray-950) 72%, transparent);
	--forge-bubble: color-mix(in oklab, var(--tdp-accent-2) 10%, var(--color-gray-800) 50%);
	--forge-selected: color-mix(in oklab, var(--color-gray-500) 20%, transparent);
	--forge-line: color-mix(in oklab, var(--color-gray-400) 20%, transparent);
	--forge-shade: color-mix(in oklab, var(--color-gray-950) 70%, transparent);
	--forge-glow: color-mix(in oklab, var(--tdp-accent) 55%, transparent);
	--forge-ring: color-mix(in oklab, var(--tdp-accent) 18%, transparent);
	--forge-link: var(--tdp-accent-3);
	--forge-strong: color-mix(in oklab, var(--tdp-accent-3) 35%, var(--color-gray-100));
	--forge-pill-shadow: 0 14px 40px -18px var(--forge-shade), 0 12px 34px -20px color-mix(in oklab, var(--tdp-accent) 60%, transparent);
}

/* Smoked glass over the forge: Open WebUI's own shapes, an ember glow
   under the input. !important only where Canvas FX clears a background. */
#message-input-container {
	background-color: var(--forge-glass) !important;
	border-color: var(--forge-line) !important;
	backdrop-filter: blur(16px) saturate(1.2);
	box-shadow: var(--forge-pill-shadow);
	transition: border-color 0.3s ease, box-shadow 0.3s ease;
}
#message-input-container:focus-within {
	border-color: var(--forge-glow) !important;
	box-shadow: 0 0 0 3px var(--forge-ring), var(--forge-pill-shadow);
}
.chat-user .rounded-3xl {
	background-color: var(--forge-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--forge-line);
}
#sidebar {
	background-color: var(--forge-sidebar) !important;
	backdrop-filter: blur(22px) saturate(1.2);
	border-inline-end: 1px solid var(--forge-line);
}
#sidebar-chat-item.selected { background-color: var(--forge-selected); box-shadow: inset 2px 0 0 var(--forge-glow); }
.markdown-prose a { color: var(--forge-link); text-decoration-color: var(--forge-glow); }
.markdown-prose strong { color: var(--forge-strong); }
.markdown-prose blockquote { border-inline-start-color: var(--forge-glow); }
.markdown-prose hr { border-color: var(--forge-line); }
html { scrollbar-color: var(--forge-line) transparent; }
::selection { background-color: var(--forge-ring); }

dark.canvasScript:
/**
 * Title: Molten Forge (WebGL)
 * Description: Domain-warped lava rivers glow through cracked crust along the screen's sides and floor with rising embers, cooling to faint cracks behind the chat while the cursor stokes the heat and leans the flow.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const FLOW_SPEED    = 1;     // how fast the lava churns; 0 holds it still (0-3)
const REDUCED_SPEED = 0.15;  // share of the flow kept when the viewer asks to reduce motion (0-1)
const NOISE_SCALE   = 2.4;   // lava structure frequency; higher is finer (1-5)
const HEAT          = 1.3;     // how brightly the lava glows (0-2)
const FORGE_HEIGHT  = 0.3;   // how far the hot floor reaches up the screen, as a share (0-0.6)
const EMBER_AMOUNT  = 1.3;     // brightness of the rising embers; 0 turns them off (0-2)
const SHIMMER       = 1;     // heat-haze distortion strength (0-2)
const CURSOR_HEAT   = 1;     // how much the cursor stokes and steers the lava (0-2)
const CENTER_CALM   = 0.85;  // how much the lava cools behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const RENDER_SCALE  = 0.5;   // resolution of the lava; it is soft, so half is plenty (0.25-1)
const MAX_FPS       = 30;    // frame cap; lava moves slowly (15-60)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const COLOR_DEEP    = '#7a1600';  // cooling lava when not following the theme
const COLOR_HOT     = '#ff7a0a';  // running lava and cracks
const COLOR_CORE    = '#ffd890';  // white-hot core and embers
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform float u_drift;',
	'uniform vec3 u_mouse;',
	'uniform vec3 u_deep;',
	'uniform vec3 u_hot;',
	'uniform vec3 u_core;',
	'uniform vec3 u_rock;',
	'uniform float u_dark;',
	'uniform vec2 u_col;',
	'float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }',
	'vec2 hash2(vec2 p) { return vec2(hash(p), hash(p + 17.31)); }',
	'float noise(vec2 p) {',
	'	vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);',
	'	return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);',
	'}',
	'float fbm(vec2 p) {',
	'	float v = 0.0, a = 0.5;',
	'	mat2 m = mat2(1.6, 1.2, -1.2, 1.6);',
	'	for (int i = 0; i < 5; i++) { v += a * noise(p); p = m * p; a *= 0.5; }',
	'	return v;',
	'}',
	// Two layers of embers rising through cells, each lit cell holding one spark
	'float embers(vec2 p, float t) {',
	'	float acc = 0.0;',
	'	for (int i = 0; i < 2; i++) {',
	'		float fi = float(i);',
	'		vec2 ep = vec2(p.x * (14.0 + fi * 8.0) + sin(t * 0.4 + fi * 2.0 + p.y * 3.0) * 0.4, p.y * 9.0 - t * (0.9 + fi * 0.5));',
	'		vec2 id = floor(ep), f = fract(ep);',
	'		float d = length(f - (0.2 + 0.6 * hash2(id)));',
	'		float tw = 0.6 + 0.4 * sin(t * 1.6 + hash(id) * 40.0);',
	'		acc += smoothstep(0.11, 0.0, d) * tw * step(0.82, hash(id + 2.7)) * (1.2 - fi * 0.4);',
	'	}',
	'	return acc;',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	vec2 p0 = px / res.y;',
	'	float t = u_time;',
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.55, 1.25, band));',
	'	float side = smoothstep(0.75, 1.6, band);',
	'	float floorHeat = 1.0 - smoothstep(0.0, ' + Math.max(0.05, FORGE_HEIGHT).toFixed(3) + ', px.y / res.y);',
	'	vec2 m = vec2(u_mouse.x, res.y - u_mouse.y);',
	'	float stoke = exp(-length(px - m) / 200.0) * u_mouse.z * ' + CURSOR_HEAT.toFixed(3) + ';',
	'	float mask = clamp(max(side, floorHeat * 0.9) + stoke * 0.7, 0.0, 1.0);',
	'	vec2 p = p0 + (vec2(noise(p0 * 24.0 + t * 2.2), noise(p0 * 24.0 + 9.1 + t * 2.0)) - 0.5) * 0.006 * ' + SHIMMER.toFixed(3) + ' * (0.3 + mask);',
	'	float K = ' + NOISE_SCALE.toFixed(3) + ';',
	'	float q1 = fbm(p * K * 1.15 + vec2(u_drift, -t * 0.02));',
	'	float q2 = fbm(p * K * 1.15 + vec2(4.4, 1.3) - vec2(u_drift * 0.6, 0.0));',
	'	float hgt = fbm(p * K + 2.3 * vec2(q1, q2));',
	'	float channel = 1.0 - smoothstep(0.0, mix(0.018, 0.06, mask), abs(hgt - 0.47 + 0.03 * q1));',
	'	float lake = mix(0.10, 0.30, mask);',
	'	float skin = smoothstep(0.25, 0.75, noise(p * 9.0 + vec2(q1, q2) * 3.0 + t * 0.05));',
	'	float pool = (1.0 - smoothstep(lake - 0.07, lake, hgt)) * mix(0.35, 1.0, skin);',
	'	float heat = max(channel * mix(0.45, 1.0, mask), pool * mask);',
	'	float pulse = 0.85 + 0.15 * sin(t * 0.9 + q1 * 6.0);',
	'	float ridged = 1.0 - abs(2.0 * noise(p * 7.0 + vec2(q2, q1) * 2.0) - 1.0);',
	'	float cracks = pow(ridged, 9.0) * (1.0 - heat) * mix(0.08, 1.0, mask);',
	'	float hm = ' + HEAT.toFixed(3) + ' * (1.0 + stoke * 0.5) * mix(0.8, 1.0, u_dark);',
	'	vec3 lava = mix(mix(u_deep, u_hot, pow(heat, 1.4)), u_core, pow(heat, 6.0) * pulse * 0.55 * u_dark);',
	'	float la = smoothstep(0.0, 0.6, heat) * mix(0.18, 1.0, mask) * calm * min(1.0, hm * pulse) * mix(0.7, 0.92, u_dark);',
	'	float ra = (1.0 - heat) * mask * calm * (0.55 + 0.5 * noise(p * 11.0)) * mix(0.10, 0.30, u_dark);',
	'	float ca = cracks * calm * min(1.0, 0.9 * hm * pulse) * mix(0.7, 1.0, u_dark);',
	'	float ga = heat * mask * calm * 0.25 * hm;',
	'	float ea = embers(p0, t) * max(side, floorHeat * 0.6) * calm * calm * ' + EMBER_AMOUNT.toFixed(3) + ' * smoothstep(1.0, 0.7, px.y / res.y) * mix(0.7, 1.0, u_dark);',
	'	vec4 o = vec4(u_rock * ra, ra);',
	'	o = vec4(u_hot * ga, ga) + o * (1.0 - ga);',
	'	o = vec4(min(lava, vec3(1.0)) * la, la) + o * (1.0 - la);',
	'	o = vec4(u_hot * ca, ca) + o * (1.0 - ca);',
	'	o = vec4(mix(u_hot, u_core, 0.6) * ea, ea) + o * (1.0 - ea);',
	'	o = clamp(o, 0.0, 1.0);',
	'	gl_FragColor = vec4(min(o.rgb, vec3(o.a)), o.a);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
const loc = {};
let w = 0, h = 0;
let last = 0, time = 0, drift = 0, reduced = false, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0, sx: -10000, sy: -10000, lean: 0 };
const colors = { deep: hexToRgb(COLOR_DEEP), hot: hexToRgb(COLOR_HOT), core: hexToRgb(COLOR_CORE), rock: [0, 0, 0], dark: 1 };

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function mix3(a, b, k) { return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]; }

// Running lava takes accent, cooling lava accent2, the core leans toward white on dark themes
function applyTheme(t) {
	if (t) colors.dark = t.dark === false ? 0 : 1;
	const dark = colors.dark === 1;
	if (!FOLLOW_THEME || !t || !t.rgb) {
		colors.deep = hexToRgb(COLOR_DEEP);
		colors.hot = dark ? hexToRgb(COLOR_HOT) : mix3(hexToRgb(COLOR_HOT), hexToRgb(COLOR_DEEP), 0.25);
		colors.core = hexToRgb(COLOR_CORE);
		colors.rock = dark ? [0, 0, 0] : [0.35, 0.3, 0.28];
		return;
	}
	colors.deep = dark ? mix3(t.rgb.accent2, [0, 0, 0], 0.4) : t.rgb.accent2;
	colors.hot = t.rgb.accent;
	colors.core = dark ? mix3(t.rgb.accent, [1, 1, 1], 0.6) : t.rgb.accent3;
	colors.rock = dark ? mix3(t.rgb.background, [0, 0, 0], 0.7) : t.rgb.muted;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_drift', 'u_mouse', 'u_deep', 'u_hot', 'u_core', 'u_rock', 'u_dark', 'u_col'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

function size() {
	canvas.width = Math.max(1, Math.round(w * RENDER_SCALE));
	canvas.height = Math.max(1, Math.round(h * RENDER_SCALE));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const k = dt * FLOW_SPEED * (reduced ? REDUCED_SPEED : 1);
	time = (time + k) % 2000;
	// The cursor leans the flow toward its side of the screen, easing back once it rests
	mouse.target = Math.max(0, mouse.target - dt * 0.4);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 2);
	const want = w ? (mouse.x / w - 0.5) * 2 * mouse.amount * CURSOR_HEAT : 0;
	mouse.lean += (want - mouse.lean) * Math.min(1, dt * 0.8);
	drift = (drift + k * (0.02 + mouse.lean * 0.06)) % 1000;
	const ease = Math.min(1, dt * 4);
	mouse.sx += (mouse.x - mouse.sx) * ease;
	mouse.sy += (mouse.y - mouse.sy) * ease;
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform1f(loc.u_drift, drift);
	gl.uniform3f(loc.u_mouse, mouse.sx, mouse.sy, mouse.amount);
	gl.uniform3fv(loc.u_deep, colors.deep);
	gl.uniform3fv(loc.u_hot, colors.hot);
	gl.uniform3fv(loc.u_core, colors.core);
	gl.uniform3fv(loc.u_rock, colors.rock);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	const opts = { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' };
	gl = canvas.getContext('webgl2', opts) || canvas.getContext('webgl', opts);
	if (!gl) {
		console.warn('Molten Forge: WebGL is not available, so the lava is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Molten Forge:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Molten Forge:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			time = Math.random() * 200;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			if (mouse.amount < 0.02) { mouse.sx = d.x; mouse.sy = d.y; }
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

light.customCSS:
:root {
	--forge-glass: color-mix(in oklab, var(--color-gray-50) 66%, transparent);
	--forge-sidebar: color-mix(in oklab, var(--color-gray-50) 72%, transparent);
	--forge-bubble: color-mix(in oklab, var(--tdp-accent) 8%, var(--color-gray-100) 56%);
	--forge-selected: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--forge-line: color-mix(in oklab, var(--color-gray-500) 26%, transparent);
	--forge-shade: color-mix(in oklab, var(--color-gray-600) 26%, transparent);
	--forge-glow: color-mix(in oklab, var(--tdp-accent) 55%, transparent);
	--forge-ring: color-mix(in oklab, var(--tdp-accent) 18%, transparent);
	--forge-link: var(--tdp-accent-2);
	--forge-strong: color-mix(in oklab, var(--tdp-accent-2) 30%, var(--color-gray-900));
	--forge-pill-shadow: 0 14px 40px -18px var(--forge-shade), 0 12px 30px -22px color-mix(in oklab, var(--tdp-accent) 45%, transparent);
}

/* Smoked glass over the forge: Open WebUI's own shapes, an ember glow
   under the input. !important only where Canvas FX clears a background. */
#message-input-container {
	background-color: var(--forge-glass) !important;
	border-color: var(--forge-line) !important;
	backdrop-filter: blur(16px) saturate(1.2);
	box-shadow: var(--forge-pill-shadow);
	transition: border-color 0.3s ease, box-shadow 0.3s ease;
}
#message-input-container:focus-within {
	border-color: var(--forge-glow) !important;
	box-shadow: 0 0 0 3px var(--forge-ring), var(--forge-pill-shadow);
}
.chat-user .rounded-3xl {
	background-color: var(--forge-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--forge-line);
}
#sidebar {
	background-color: var(--forge-sidebar) !important;
	backdrop-filter: blur(22px) saturate(1.2);
	border-inline-end: 1px solid var(--forge-line);
}
#sidebar-chat-item.selected { background-color: var(--forge-selected); box-shadow: inset 2px 0 0 var(--forge-glow); }
.markdown-prose a { color: var(--forge-link); text-decoration-color: var(--forge-glow); }
.markdown-prose strong { color: var(--forge-strong); }
.markdown-prose blockquote { border-inline-start-color: var(--forge-glow); }
.markdown-prose hr { border-color: var(--forge-line); }
html { scrollbar-color: var(--forge-line) transparent; }
::selection { background-color: var(--forge-ring); }

light.canvasScript:
/**
 * Title: Molten Forge (WebGL)
 * Description: Domain-warped lava rivers glow through cracked crust along the screen's sides and floor with rising embers, cooling to faint cracks behind the chat while the cursor stokes the heat and leans the flow.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const FLOW_SPEED    = 1;     // how fast the lava churns; 0 holds it still (0-3)
const REDUCED_SPEED = 0.15;  // share of the flow kept when the viewer asks to reduce motion (0-1)
const NOISE_SCALE   = 2.4;   // lava structure frequency; higher is finer (1-5)
const HEAT          = 1.7;     // how brightly the lava glows (0-2)
const FORGE_HEIGHT  = 0.3;   // how far the hot floor reaches up the screen, as a share (0-0.6)
const EMBER_AMOUNT  = 1;     // brightness of the rising embers; 0 turns them off (0-2)
const SHIMMER       = 1;     // heat-haze distortion strength (0-2)
const CURSOR_HEAT   = 1;     // how much the cursor stokes and steers the lava (0-2)
const CENTER_CALM   = 0.85;  // how much the lava cools behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const RENDER_SCALE  = 0.5;   // resolution of the lava; it is soft, so half is plenty (0.25-1)
const MAX_FPS       = 30;    // frame cap; lava moves slowly (15-60)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const COLOR_DEEP    = '#7a1600';  // cooling lava when not following the theme
const COLOR_HOT     = '#ff7a0a';  // running lava and cracks
const COLOR_CORE    = '#ffd890';  // white-hot core and embers
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform float u_drift;',
	'uniform vec3 u_mouse;',
	'uniform vec3 u_deep;',
	'uniform vec3 u_hot;',
	'uniform vec3 u_core;',
	'uniform vec3 u_rock;',
	'uniform float u_dark;',
	'uniform vec2 u_col;',
	'float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }',
	'vec2 hash2(vec2 p) { return vec2(hash(p), hash(p + 17.31)); }',
	'float noise(vec2 p) {',
	'	vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);',
	'	return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);',
	'}',
	'float fbm(vec2 p) {',
	'	float v = 0.0, a = 0.5;',
	'	mat2 m = mat2(1.6, 1.2, -1.2, 1.6);',
	'	for (int i = 0; i < 5; i++) { v += a * noise(p); p = m * p; a *= 0.5; }',
	'	return v;',
	'}',
	// Two layers of embers rising through cells, each lit cell holding one spark
	'float embers(vec2 p, float t) {',
	'	float acc = 0.0;',
	'	for (int i = 0; i < 2; i++) {',
	'		float fi = float(i);',
	'		vec2 ep = vec2(p.x * (14.0 + fi * 8.0) + sin(t * 0.4 + fi * 2.0 + p.y * 3.0) * 0.4, p.y * 9.0 - t * (0.9 + fi * 0.5));',
	'		vec2 id = floor(ep), f = fract(ep);',
	'		float d = length(f - (0.2 + 0.6 * hash2(id)));',
	'		float tw = 0.6 + 0.4 * sin(t * 1.6 + hash(id) * 40.0);',
	'		acc += smoothstep(0.11, 0.0, d) * tw * step(0.82, hash(id + 2.7)) * (1.2 - fi * 0.4);',
	'	}',
	'	return acc;',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	vec2 p0 = px / res.y;',
	'	float t = u_time;',
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.55, 1.25, band));',
	'	float side = smoothstep(0.75, 1.6, band);',
	'	float floorHeat = 1.0 - smoothstep(0.0, ' + Math.max(0.05, FORGE_HEIGHT).toFixed(3) + ', px.y / res.y);',
	'	vec2 m = vec2(u_mouse.x, res.y - u_mouse.y);',
	'	float stoke = exp(-length(px - m) / 200.0) * u_mouse.z * ' + CURSOR_HEAT.toFixed(3) + ';',
	'	float mask = clamp(max(side, floorHeat * 0.9) + stoke * 0.7, 0.0, 1.0);',
	'	vec2 p = p0 + (vec2(noise(p0 * 24.0 + t * 2.2), noise(p0 * 24.0 + 9.1 + t * 2.0)) - 0.5) * 0.006 * ' + SHIMMER.toFixed(3) + ' * (0.3 + mask);',
	'	float K = ' + NOISE_SCALE.toFixed(3) + ';',
	'	float q1 = fbm(p * K * 1.15 + vec2(u_drift, -t * 0.02));',
	'	float q2 = fbm(p * K * 1.15 + vec2(4.4, 1.3) - vec2(u_drift * 0.6, 0.0));',
	'	float hgt = fbm(p * K + 2.3 * vec2(q1, q2));',
	'	float channel = 1.0 - smoothstep(0.0, mix(0.018, 0.06, mask), abs(hgt - 0.47 + 0.03 * q1));',
	'	float lake = mix(0.10, 0.30, mask);',
	'	float skin = smoothstep(0.25, 0.75, noise(p * 9.0 + vec2(q1, q2) * 3.0 + t * 0.05));',
	'	float pool = (1.0 - smoothstep(lake - 0.07, lake, hgt)) * mix(0.35, 1.0, skin);',
	'	float heat = max(channel * mix(0.45, 1.0, mask), pool * mask);',
	'	float pulse = 0.85 + 0.15 * sin(t * 0.9 + q1 * 6.0);',
	'	float ridged = 1.0 - abs(2.0 * noise(p * 7.0 + vec2(q2, q1) * 2.0) - 1.0);',
	'	float cracks = pow(ridged, 9.0) * (1.0 - heat) * mix(0.08, 1.0, mask);',
	'	float hm = ' + HEAT.toFixed(3) + ' * (1.0 + stoke * 0.5) * mix(0.8, 1.0, u_dark);',
	'	vec3 lava = mix(mix(u_deep, u_hot, pow(heat, 1.4)), u_core, pow(heat, 6.0) * pulse * 0.55 * u_dark);',
	'	float la = smoothstep(0.0, 0.6, heat) * mix(0.18, 1.0, mask) * calm * min(1.0, hm * pulse) * mix(0.7, 0.92, u_dark);',
	'	float ra = (1.0 - heat) * mask * calm * (0.55 + 0.5 * noise(p * 11.0)) * mix(0.10, 0.30, u_dark);',
	'	float ca = cracks * calm * min(1.0, 0.9 * hm * pulse) * mix(0.7, 1.0, u_dark);',
	'	float ga = heat * mask * calm * 0.25 * hm;',
	'	float ea = embers(p0, t) * max(side, floorHeat * 0.6) * calm * calm * ' + EMBER_AMOUNT.toFixed(3) + ' * smoothstep(1.0, 0.7, px.y / res.y) * mix(0.7, 1.0, u_dark);',
	'	vec4 o = vec4(u_rock * ra, ra);',
	'	o = vec4(u_hot * ga, ga) + o * (1.0 - ga);',
	'	o = vec4(min(lava, vec3(1.0)) * la, la) + o * (1.0 - la);',
	'	o = vec4(u_hot * ca, ca) + o * (1.0 - ca);',
	'	o = vec4(mix(u_hot, u_core, 0.6) * ea, ea) + o * (1.0 - ea);',
	'	o = clamp(o, 0.0, 1.0);',
	'	gl_FragColor = vec4(min(o.rgb, vec3(o.a)), o.a);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
const loc = {};
let w = 0, h = 0;
let last = 0, time = 0, drift = 0, reduced = false, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0, sx: -10000, sy: -10000, lean: 0 };
const colors = { deep: hexToRgb(COLOR_DEEP), hot: hexToRgb(COLOR_HOT), core: hexToRgb(COLOR_CORE), rock: [0, 0, 0], dark: 1 };

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function mix3(a, b, k) { return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]; }

// Running lava takes accent, cooling lava accent2, the core leans toward white on dark themes
function applyTheme(t) {
	if (t) colors.dark = t.dark === false ? 0 : 1;
	const dark = colors.dark === 1;
	if (!FOLLOW_THEME || !t || !t.rgb) {
		colors.deep = hexToRgb(COLOR_DEEP);
		colors.hot = dark ? hexToRgb(COLOR_HOT) : mix3(hexToRgb(COLOR_HOT), hexToRgb(COLOR_DEEP), 0.25);
		colors.core = hexToRgb(COLOR_CORE);
		colors.rock = dark ? [0, 0, 0] : [0.35, 0.3, 0.28];
		return;
	}
	colors.deep = dark ? mix3(t.rgb.accent2, [0, 0, 0], 0.4) : t.rgb.accent2;
	colors.hot = t.rgb.accent;
	colors.core = dark ? mix3(t.rgb.accent, [1, 1, 1], 0.6) : t.rgb.accent3;
	colors.rock = dark ? mix3(t.rgb.background, [0, 0, 0], 0.7) : t.rgb.muted;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
