oled.customCSS:
:root {
	--pink-glass: color-mix(in oklab, var(--color-gray-950) 62%, transparent);
	--pink-sidebar: color-mix(in oklab, var(--color-gray-950) 76%, transparent);
	--pink-bubble: color-mix(in oklab, var(--pink-accent) 20%, var(--color-gray-800) 50%);
	--pink-selected: color-mix(in oklab, var(--color-gray-500) 20%, transparent);
	--pink-line: color-mix(in oklab, var(--color-gray-400) 20%, transparent);
	--pink-glow: color-mix(in oklab, var(--pink-accent) 45%, transparent);
	--pink-ring: color-mix(in oklab, var(--pink-accent) 16%, transparent);
	--pink-shade: color-mix(in oklab, var(--color-gray-950) 70%, transparent);
	--pink-accent: oklch(0.8 0.11 356);
}

/* Soft pink glass in Open WebUI's own shapes, colored by the palette. !important only where Canvas FX transparency clears a background. */
#message-input-container {
	background-color: var(--pink-glass) !important;
	border-color: var(--pink-line) !important;
	backdrop-filter: blur(22px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--pink-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--pink-glow) !important;
	box-shadow: 0 0 0 3px var(--pink-ring), 0 12px 40px -16px var(--pink-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--pink-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--pink-line);
}
#sidebar {
	background-color: var(--pink-sidebar) !important;
	backdrop-filter: blur(26px) saturate(1.2);
	border-inline-end: 1px solid var(--pink-line);
}
#sidebar-chat-item.selected { background-color: var(--pink-selected); }
.markdown-prose a { color: var(--pink-accent); text-decoration-color: var(--pink-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--pink-glow); }
.markdown-prose hr { border-color: var(--pink-glow); }
html { scrollbar-color: var(--pink-line) transparent; }
::selection { background-color: var(--pink-ring); }

